window.SHICI_SONG=[{"id":"S00001","t":"水龙吟","a":"苏轼","c":["古来云海茫茫，道山绛阙知何处。","人间自有，赤城居士，龙蟠凤举。","清净无为，坐忘遗照，八篇奇语。","向玉霄东望，蓬莱暗霭，有云驾、骖风驭。","行尽九州四海，笑纷纷、落花飞絮。","临江一见，谪仙风采，无言心许。","八表神游，浩然相对，酒酣箕踞。","待垂天赋就，骑鲸路稳，约相将去。"],"p":"水龙吟"},{"id":"S00002","t":"水龙吟","a":"苏轼","c":["楚山修竹如云，异材秀出千林表。","龙须半翦，凤膺微涨，玉肌匀绕。","木落淮南，雨晴云梦，月明风袅。","自中郎不见，桓伊去后，知孤负、秋多少。","闻道岭南太守，后堂深、绿珠娇小。","绮窗学弄，梁州初遍，霓裳未了。","嚼征含宫，泛商流羽，一声云杪。","为使君洗尽，蛮风瘴雨，作霜天晓。"],"p":"水龙吟"},{"id":"S00003","t":"水龙吟","a":"苏轼","c":["似花还似非花，也无人惜从教坠。","抛家傍路，思量却是，无情有思。","萦损柔肠，困酣娇眼，欲开还闭。","梦随风万里，寻郎去处，又还被、莺呼起。","不恨此花飞尽，恨西园、落红难缀。","晓来雨过，遗踪何在，一池萍碎。","春色三分，二分尘土，一分流水。","细看来，不是杨花点点，是离人泪。"],"p":"水龙吟"},{"id":"S00004","t":"水龙吟","a":"苏轼","c":["小舟横截春江，卧看翠壁红楼起。","云间笑语，使君高会，佳人半醉。","危柱哀弦，艳歌馀响，绕云萦水。","念故人老大，风流未减，独回首、烟波里。","推枕惘然不见，但空江、月明千里。","五湖闻道，扁舟归去，仍携西子。","云梦南州，武昌南岸，昔游应记。","料多情梦里，端来见我，也参差是。"],"p":"水龙吟"},{"id":"S00005","t":"满庭芳","a":"苏轼","c":["归去来兮，吾归何处，万里家在岷峨。","百年强半，来日苦无多。","坐见黄州再闰，儿童尽、楚语吴歌。","山中友，鸡豚社酒，相劝老东坡。","云何。","当此去，人生底事，来往如梭。","待闲看，秋风洛水清波。","好在堂前细柳，应念我、莫翦柔柯。","仍传语，江南父老，时与晒渔蓑。"],"p":"满庭芳"},{"id":"S00006","t":"满庭芳","a":"苏轼","c":["香叆雕盘，寒生冰箸，画堂别是风光。","主人情重，开宴出红妆。","腻玉圆搓素颈，藕丝嫩、新织仙裳。","双歌罢，虚檐转月，馀韵尚悠扬。","人间，何处有，司空见惯，应谓寻常。","坐中有狂客，恼乱愁肠。","报道金钗坠也，十指露、春笋纤长。","亲曾见，全胜宋玉，想像赋高唐。"],"p":"满庭芳"},{"id":"S00007","t":"满庭芳","a":"苏轼","c":["蜗角虚名，蝇头微利，算来著甚干忙。","事皆前定，谁弱又谁强。","且趁闲身未老，尽放我、些子疏狂。","百年里，浑教是醉，三万六千场。","思量。","能几许，忧愁风雨，一半相妨。","又何须，抵死说短论长。","幸对清风皓月，苔茵展、云幕高张。","江南好，千锺美酒，一曲《满庭芳》。"],"p":"满庭芳"},{"id":"S00008","t":"满庭芳","a":"苏轼","c":["三十三年，今谁存者，算只君与长江。","凛然苍桧，霜干苦难双。","闻道司州古县，云溪上、竹坞松窗。","江南岸，不因送子，宁肯过吾邦。","𪭢𪭢。","疏雨过，风林舞破，烟盖云幢。","愿持此邀君，一饮空缸。","居士先生老矣，真梦里、相对残釭。","歌舞断，行人未起，船鼓已逄逄。"],"p":"满庭芳"},{"id":"S00009","t":"满庭芳","a":"苏轼","c":["三十三年，飘流江海，万里烟浪云帆。","故人惊怪，憔悴老青衫。","我自疏狂异趣，君何事、奔走尘凡。","流年尽，穷途坐守，船尾冻相衔。","巉巉。","淮浦外，层楼翠壁，古寺空岩。","步携手林间，笑挽ホホ。","莫上孤峰尽处，萦望眼、云海相搀。","家何在，因君问我，归梦绕松杉。"],"p":"满庭芳"},{"id":"S00010","t":"水调歌头","a":"苏轼","c":["落日绣帘卷，亭下水连空。","知君为我，新作窗户湿青红。","长记平山堂上，敧枕江南烟雨，渺渺没孤鸿。","认得醉翁语，山色有无中。","一千顷，都镜净，倒碧峰。","忽然浪起，掀舞一叶白头翁。","堪笑兰台公子，未解庄生天籁，刚道有雌雄。","一点浩然气，千里快哉风。"],"p":"水调歌头"},{"id":"S00011","t":"水调歌头","a":"苏轼","c":["安石在东海，从事鬓惊秋。","中年亲友难别，丝竹缓离愁。","一旦功成名遂，准拟东还海道，扶病入西州。","雅志困轩冕，遗恨寄沧洲。","岁云暮，须早计，要褐裘。","故乡归去千里，佳处辄迟留。","我醉歌时君和，醉倒须君扶我，惟酒可忘忧。","一任刘玄德，相对卧高楼。"],"p":"水调歌头"},{"id":"S00012","t":"水调歌头","a":"苏轼","c":["明月几时有，把酒问青天。","不知天上宫阙，今夕是何年。","我欲乘风归去，又恐琼楼玉宇，高处不胜寒。","起舞弄清影，何似在人间。","转朱阁，低绮户，照无眠。","不应有恨，何事长向别时圆。","人有悲欢离合，月有阴晴圆缺，此事古难全。","但愿人长久，千里共婵娟。"],"p":"水调歌头"},{"id":"S00013","t":"水调歌头","a":"苏轼","c":["昵昵儿女语，灯火夜微明。","恩冤尔汝来去，弹指泪和声。","忽变轩昂勇士，一鼓填然作气，千里不留行。","回首暮云远，飞絮搅青冥。","众禽里，真彩凤，独不鸣。","跻攀寸步千险，一落百寻轻。","烦子指间风雨，置我肠中冰炭，起坐不能平。","推手从归去，无泪与君倾。"],"p":"水调歌头"},{"id":"S00014","t":"满江红","a":"苏轼","c":["忧喜相寻，风雨过、一江春绿。","巫峡梦、至今空有，乱山屏簇。","何似伯鸾携德耀，箪瓢未足清欢足。","渐粲然、光彩照阶庭，生兰玉。","幽梦里，传心曲。","肠断处，凭他续。","文君婿知否，笑君卑辱。","君不见周南歌汉广，天教夫子休乔木。","便相将、左手抱琴书，云间宿。"],"p":"满江红"},{"id":"S00015","t":"满江红","a":"苏轼","c":["江汉西来，高楼下、蒲萄深碧。","犹自带、岷峨云浪，锦江春色。","君是南山遗爱守，我为剑外思归客。","对此间、风物岂无情，殷勤说。","江表传，君休读。","狂处士，真堪惜。","空洲对鹦鹉，苇花萧瑟。","不独笑书生争底事，曹公黄祖俱飘忽。","愿使君、还赋谪仙诗，追黄鹤。"],"p":"满江红"},{"id":"S00016","t":"满江红","a":"苏轼","c":["东武南城，新堤固、涟漪初溢。","隐隐遍、长林高阜，卧红堆碧。","枝上残花吹尽也，与君更向江头觅。","问向前、犹有几多春，三之一。","官里事，何时毕。","风雨外，无多日。","相将泛曲水，满城争出。","君不见兰亭修禊事，当时坐上皆豪逸。","到如今、修竹满山阴，空陈迹。"],"p":"满江红"},{"id":"S00017","t":"满江红","a":"苏轼","c":["清颖东流，愁目断、孤帆明灭。","宦游处、青山白浪，万重千叠。","孤负当年林下意，对床夜雨听萧瑟。","恨此生、长向别离中，添华发。","一尊酒，黄河侧。","无限事，从头说。","相看恍如昨，许多年月。","衣上旧痕馀苦泪，眉间喜气添黄色。","便与君、池上觅残春，花如雪。"],"p":"满江红"},{"id":"S00018","t":"满江红","a":"苏轼","c":["天岂无情，天也解、多情留客。","春向暖、朝来底事，尚飘轻雪。","君过春来纡组绶，我应归去耽泉石。","恐异时、杯酒忽相思，云山隔。","浮世事，俱难必。","人纵健，头应白。","何辞更一醉，此欢难觅。","欲向佳人诉离恨，泪珠先已凝双睫。","但莫遣、新燕却来时，音书绝。"],"p":"满江红"},{"id":"S00019","t":"归朝欢","a":"苏轼","c":["我梦扁舟浮震泽。","雪浪摇空千顷白。","觉来满眼是庐山，倚天无数开青壁。","此生长接淅。","与君同是江南客。","梦中游，觉来清赏，同作飞梭掷。","明日西风还挂席。","唱我新词泪沾臆。","灵均去后楚山空，澧阳兰芷无颜色。","君才如梦得。","武陵更在西南极。","竹枝词，莫摇新唱，谁谓古今隔。"],"p":"归朝欢"},{"id":"S00020","t":"念奴娇","a":"苏轼","c":["大江东去，浪淘尽、千古风流人物。","故垒西边人道是，三国周郎赤壁。","乱石穿空，惊涛拍岸，卷起千堆雪。","江山如画，一时多少豪杰。","遥想公瑾当年，小乔初嫁了，雄姿英发。","羽扇纶巾谈笑间，强虏灰飞烟灭。","故国神游，多情应笑，我早生华发。","人间如梦，一尊还酹江月。"],"p":"念奴娇"},{"id":"S00021","t":"雨中花・夜行船","a":"苏轼","c":["今岁花时深院，尽日东风，荡扬茶烟。","但有绿苔芳草，柳絮榆钱。","闻道城西，长廊古寺，甲第名园。","有国艳带酒，天香染袂，为我留连。","清明过了，残红无处，对此泪洒尊前。","秋向晚，一枝何事，向我依然。","高会聊追短景，清商不暇馀妍。","不如留取，十分春态，付与明年。"],"p":"雨中花・夜行船"},{"id":"S00022","t":"沁园春","a":"苏轼","c":["孤馆灯青，野店鸡号，旅枕梦残。","渐月华收练，晨霜耿耿，云山摛锦，朝露清清。","世路无穷，劳生有限，似此区区长鲜欢。","微吟罢，凭征鞍无语，往事千端。","当时共客长安。","似二陆初来俱少年。","有笔头千字，胸中万卷，致君尧舜，此事何难。","用舍由时，行藏在我，袖手何妨闲处看。","身长健，但优游卒岁，且斗尊前。"],"p":"沁园春"},{"id":"S00023","t":"劝金船","a":"苏轼","c":["无情流水多情客。","劝我如曾识。","杯行到手休辞却。","这公道难得。","曲水池上，小字更书年月。","还对茂林修竹，似永和节。","纤纤素手如霜雪。","笑把秋花插。","尊前莫怪歌声咽。","又还是轻别。","此去翱翔，遍赏玉堂金阙。","欲问再来何岁，应有华发。"],"p":"劝金船"},{"id":"S00024","t":"一丛花","a":"苏轼","c":["今年春浅腊侵年。","冰雪破春妍。","东风有信无人见，露微意、柳际花边。","寒夜纵长，孤衾易暖，钟鼓渐清圆。","朝来初日半含山。","楼阁淡疏烟。","游人便作寻芳计，小桃杏、应已争先。","衰病少情，疏慵自放，惟爱日高眠。"],"p":"一丛花"},{"id":"S00025","t":"木兰花令","a":"苏轼","c":["霜馀已失长淮阔。","空听潺潺清颍咽。","佳人犹唱醉翁词，四十三年如电抹。","草头秋露流珠滑。","三五盈盈还二八。","与余同是识翁人，惟有西湖波底月。"],"p":"木兰花令"},{"id":"S00026","t":"木兰花令","a":"苏轼","c":["知君仙骨无寒暑。","千载相逢犹旦暮。","故将别语恼佳人，要看梨花枝上雨。","落花已逐回风去。","花本无心莺自诉。","明朝归路下塘西，不见莺啼花落处。"],"p":"木兰花令"},{"id":"S00027","t":"木兰花令","a":"苏轼","c":["梧桐叶上三更雨。","惊破梦魂无觅处。","夜凉枕簟已知秋，更听寒蛩促机杼。","梦中历历来时路。","犹在江亭醉歌舞。","尊前必有问君人，为道别来心与绪。"],"p":"木兰花令"},{"id":"S00028","t":"西江月","a":"苏轼","c":["公子眼花乱发，老夫鼻观先通。","领巾飘下瑞香风。","惊起谪仙春梦。","后土祠中玉蕊，蓬莱殿后鞓红。","此花清绝更纤秾。","把酒何人心动。"],"p":"西江月"},{"id":"S00029","t":"西江月","a":"苏轼","c":["小院朱阑几曲，重城画鼓三通。","更看微月转光风。","归去香云入梦。","翠袖争浮大白，皂罗半插斜红。","灯花零落酒花秾。","妙语一时飞动。"],"p":"西江月"},{"id":"S00030","t":"西江月","a":"苏轼","c":["怪此花枝怨泣，托君诗句名通。","凭将草木记吴风。","继取相如云梦。","点笔袖沾醉墨，谤花面有惭红。","知君却是为情秾。","怕见此花撩动。"],"p":"西江月"},{"id":"S00031","t":"西江月","a":"辛弃疾","c":["一柱中擎远碧，两峰旁依高寒。","横陈削就短长山。","莫把一分增减。","我望云烟目断，人言风景天悭。","被公诗笔尽追还。","更上层楼一览。"],"p":"西江月"},{"id":"S00032","t":"西江月","a":"辛弃疾","c":["堂上谋臣帷幄，边头猛将干戈。","天时地利与人和。","燕可伐与曰可。","此日楼台鼎鼐，他时剑履山河。","都人齐和大风歌。","管领群臣来贺。"],"p":"西江月"},{"id":"S00033","t":"生查子","a":"辛弃疾","c":["青山招不来，偃蹇谁怜汝。","岁晚太寒生，唤我溪边住。","山头明月来，本在高高处。","夜夜入清溪，听读《离骚》去。"],"p":"生查子"},{"id":"S00034","t":"生查子","a":"辛弃疾","c":["高人千丈崖，千古储冰雪。","六月火云时，一见森毛发。","俗人如盗泉，照眼多昏浊。","高处挂吾瓢，不饮吾宁渴。"],"p":"生查子"},{"id":"S00035","t":"卜算子","a":"辛弃疾","c":["盗跖傥名丘，孔子还名跖。","跖圣丘愚直至今，美恶无真实。","简册写虚名，蝼蚁侵枯骨。","千古光阴一霎时，且进杯中物。"],"p":"卜算子"},{"id":"S00036","t":"卜算子","a":"辛弃疾","c":["一个去学仙，一个去学佛。","仙饮千杯醉似泥，皮骨如金石。","不饮便康强，佛寿须千百。","八十馀年入涅槃，且进杯中物。"],"p":"卜算子"},{"id":"S00037","t":"卜算子","a":"辛弃疾","c":["一饮动连宵，一醉长三日。","废尽寒暄不写书，富贵何由得。","请看冢中人，冢似当时笔。","万札千书只恁休，且进杯中物。"],"p":"卜算子"},{"id":"S00038","t":"卜算子","a":"辛弃疾","c":["刚者不坚牢，柔者难摧挫。","不信张开口了看，舌在牙先堕。","已阙两边厢，又豁中间个。","说与儿曹莫笑翁，狗窦从君过。"],"p":"卜算子"},{"id":"S00039","t":"卜算子","a":"辛弃疾","c":["一以我为牛，一以吾为马。","人与之名受不辞，善学庄周者。","江海任虚舟，风雨从飘瓦。","醉者乘车坠不伤，全得于天也。"],"p":"卜算子"},{"id":"S00040","t":"卜算子","a":"辛弃疾","c":["夜雨醉瓜庐，春水行秧马。","点检田间快活人，未有如翁者。","秃尽兔豪锥，磨透铜台瓦。","谁伴扬雄作解嘲，乌有先生也。"],"p":"卜算子"},{"id":"S00041","t":"卜算子","a":"辛弃疾","c":["珠玉作泥沙，山谷量牛马。","试上累累丘垅看，谁是强梁者。","水浸浅深檐，山压高低瓦。","山水朝来笑问人，翁早归来也。"],"p":"卜算子"},{"id":"S00042","t":"卜算子","a":"辛弃疾","c":["千古李将军，夺得胡儿马。","李蔡为人在下中，却是封侯者。","芸草去阵根，笕竹添新瓦。","万一朝家举力田，舍我其谁也。"],"p":"卜算子"},{"id":"S00043","t":"哨遍","a":"辛弃疾","c":["池上主人，人适忘鱼，鱼适还忘水。","洋洋乎，翠藻青萍里。","想鱼兮、无便于此。","尝试思，庄周正谈两事。","一明豕虱一羊蚁。","说蚁慕于膻，于蚁弃知，又说于羊弃意。","甚虱焚于豕独忘之。","却骤说于鱼为得计。","千古遗文，我不知言，以我非子。","子固非鱼，噫。","鱼之为计子焉知。","河水深且广，风涛万倾堪依。","有网罟如云，鹈鹕成阵，过而留泣计应非。","其外海茫茫，下有龙伯，饥时一啖千里。","更任公五十犗为饵。","使海上人人厌腥味。","似鲲鹏、变化能几。","东游入海，此计直以命为嬉。","古来谬算狂图，五鼎烹死，指为平地。","嗟鱼欲事远游时。","请三思而行可矣。"],"p":"哨遍"},{"id":"S00044","t":"兰陵王","a":"辛弃疾","c":["恨之极。","恨极销磨不得。","苌弘事，人道后来，其血三年化为碧。","郑人缓也泣。","吾父攻儒助墨。","十年梦，沈痛化余，秋柏之间既为实。","相思重相忆。","被怨结中肠，潜动精魄。","望夫江上岩岩立。","嗟一念中变，后期长绝。","君看启母愤所激。","又俄倾为石。","难敌。","最多力。","甚一忿沈渊，精气为物。","依然困斗牛磨角。","便影入山骨，至今雕琢。","寻思人间，只合化，梦中蝶。"],"p":"兰陵王"},{"id":"S00045","t":"贺新郎","a":"辛弃疾","c":["著厌霓裳素。","染胭脂、苎罗山下，浣沙溪渡。","谁与流霞千古酝，引得东风相误。","从臾入、吴宫深处。","鬓乱钗横浑不醒，转越江、刬地迷归路。","烟艇小，五湖去。","当时倩得春留住。","就锦屏一曲，种种断肠风度。","才是清明三月近，须要诗人妙句。","笑援笔、殷勤为赋。","十样蛮笺纹错绮，粲珠玑、渊掷惊风雨。","重唤酒，共花语。"],"p":"贺新郎"},{"id":"S00046","t":"贺新郎","a":"辛弃疾","c":["碧海成桑野。","笑人间，江翻平陆，水云高下。","自是三山颜色好，更著雨婚烟嫁。","料未必、龙眠能画。","拟向诗人求幼妇，倩诸君、妙手皆谈马。","须进酒，为陶写。","回头鸥鹭瓢泉社。","莫吟诗、莫抛尊酒，是吾盟也。","千骑而今遮白发，忘却沧浪亭榭。","但记得、灞陵呵夜。","我辈从来文字饮，怕壮怀、激烈须歌者。","蝉噪也，绿阴夏。"],"p":"贺新郎"},{"id":"S00047","t":"贺新郎","a":"辛弃疾","c":["鸟倦飞还矣。","笑渊明、瓶中储粟，有无能几。","莲社高人留翁语，我醉宁论许事。","试沽酒、重斟翁喜。","一见箫然音韵古，想东篱、醉卧参差是。","千载下，竟谁似。","元龙百尺高楼里。","把新诗、殷勤问我，停云情味。","北夏门高从拉攞，何事须人料理。","翁曾道、繁华朝起。","尘土人言宁可用，顾青山、与我何如耳。","歌且和，楚狂子。"],"p":"贺新郎"},{"id":"S00048","t":"贺新郎","a":"辛弃疾","c":["肘后俄生柳。","叹人生、不如意事，十常八九。","右手淋浪才有用，闲却持螯左手。","谩赢得、伤今感旧。","投阁先生惟寂寞，笑是非、不了身前后。","持此语，问乌有。","青山幸自重重秀。","问新来、萧萧木落，颇堪秋否。","总被西风都瘦损，依旧千岩万岫。","把万事、无言搔首。","翁比渠侬人谁好，是我常、与我周旋久。","宁作我，一杯酒。"],"p":"贺新郎"},{"id":"S00049","t":"念奴娇","a":"辛弃疾","c":["风狂雨横，是邀勒园林，几多桃李。","待上层楼无气力，尘满栏干谁倚。","就火添衣，移香傍枕，莫卷朱帘起。","元宵过也，春寒犹自如此。","为问几日新晴，鸠鸣屋上，鹊报檐前喜。","揩试老来诗句眼，要看拍堤春水。","月下凭肩，花边系马，此兴今休矣。","溪南酒贱，光阴只在弹指。"],"p":"念奴娇"},{"id":"S00050","t":"念奴娇","a":"辛弃疾","c":["洞庭春晚，旧传恐是，人间尤物。","收拾瑶池倾国艳，来向朱栏一壁。","透户龙香，隔帘莺语，料得肌如血。","月妖真态，是谁教避人杰。","酒罢归对寒窗，相留昨夜，应是梅花发。","赋了高唐犹想像，不管孤灯明灭。","半面难期，多情易感，愁点星星发。","绕梁声在，为伊忘味三月。"],"p":"念奴娇"},{"id":"S00051","t":"念奴娇","a":"辛弃疾","c":["是谁调护，岁寒枝、都把苍苔封了。","茅舍疏篱江上路，清夜月高山小。","摸索应知，曹刘沈谢，何况霜天晓。","芬芳一世，料君长被花恼。","惆怅立马行人，一枝最爱，竹外横斜好。","我向东邻曾醉里，唤起诗家二老。","拄杖而今，婆娑雪里，又识商山皓。","请君置酒，看渠与我倾倒。"],"p":"念奴娇"},{"id":"S00052","t":"沁园春","a":"辛弃疾","c":["老子平生，笑尽人间，儿女怨恩。","况白头能几，定应独往，青云得意，见说长存。","抖擞衣冠，怜渠无恙，合挂当年神武门。","都如梦，算能争几许，鸡晓钟昏。","此心无有新冤。","况抱瓮年来自灌园。","但凄凉顾影，频悲往事，殷勤对佛，欲问前因。","却怕青山，也妨贤路，休斗尊前见在身。","山中友，试高吟楚些，重与招魂。"],"p":"沁园春"},{"id":"S00053","t":"沁园春","a":"辛弃疾","c":["有美人兮，玉佩琼踞，吾梦见之。","问斜阳犹照，渔樵故里，长桥谁记，今故期思。","物化苍茫，神游仿佛，春与猿吟秋鹤飞。","还惊笑，向晴波忽见，千丈虹霓。","觉来西望崔嵬。","更上有青枫下有溪。","待空山自荐，寒泉秋菊，中流却送，桂棹兰旗。","万事长嗟，百年双鬓，吾非斯人谁与归。","凭阑久，正清愁未了，醉墨休题。"],"p":"沁园春"},{"id":"S00054","t":"沁园春","a":"辛弃疾","c":["我试评君，君定何如，玉川似之。","记李花初发，乘云共语，梅花开后，对月相思。","白发重来，画桥一望，秋水长天孤鹜飞。","同吟处，看佩摇明月，衣卷青霓。","相君高节崔嵬。","是此处耕岩与钓溪。","被西风吹尽，村箫社鼓，青山留得，松盖云旗。","吊古愁浓，怀人日暮，一片心从天外归。","新词好，似凄凉楚些，字字堪题。"],"p":"沁园春"},{"id":"S00055","t":"沁园春","a":"辛弃疾","c":["我醉狂吟，君作新声，倚歌和之。","算芬芳定向，梅间得意，轻清多是，雪里寻思。","朱雀桥边，何人会道，野草斜阳春燕飞。","都休问，甚元无霁雨，却有晴霓。","诗坛千丈崔嵬。","更有笔如山墨作溪。","看君才未数，曹刘敌手，风骚合受，屈宋降旗。","谁识相如，平生自许，慷慨须乘驷马归。","长安路，问垂虹千柱，何处曾题。"],"p":"沁园春"},{"id":"S00056","t":"水调歌头","a":"辛弃疾","c":["落日古城角，把酒劝君留。","长安路远，何事风雪敝貂裘。","散尽黄金身世，不管秦楼人怨，归计狎沙鸥。","明夜扁舟去，和月载离愁。","功名事，身未老，几时休。","诗书万卷，致身须到古伊周。","莫学班超投笔，纵得封侯万里，憔悴老边州。","何处依刘客，寂寞赋《登楼》。"],"p":"水调歌头"},{"id":"S00057","t":"水调歌头","a":"辛弃疾","c":["官事未易了，且向酒边来。","君如无我，问君怀抱向谁开。","但放平生丘壑，莫管旁人嘲骂，深蛰要惊雷。","白发还自笑，何地置衰颓。","五车书，千古饮，百篇才。","新词未到，琼瑰先梦满吾怀。","已过西风重九，且要黄花入手，诗兴未关梅。","君要花满县，桃李趁时栽。"],"p":"水调歌头"},{"id":"S00058","t":"水调歌头","a":"辛弃疾","c":["千里渥洼种，名动帝王家。","金銮当日奏草，落笔万龙蛇。","带得无边春下，等待江山都老，教看鬓方鸦。","莫管钱流地，且拟醉黄花。","唤双成，歌弄玉，舞绿华。","一觞为饮千岁，江海吸流霞。","闻道清都帝所，要挽银河仙浪，西北洗胡沙。","回首日边去，云里认飞车。"],"p":"水调歌头"},{"id":"S00059","t":"水调歌头","a":"辛弃疾","c":["千古老蟾口，云洞插天开。","涨痕当日何事，汹涌到崔嵬。","攫土抟沙儿戏，翠谷苍崖几变，风雨化人来。","万里须臾耳，野马骤空埃。","笑年来，蕉鹿梦，画蛇杯。","黄花憔悴风露，野碧涨荒莱。","此会明年谁健，后日犹今视昔，歌舞只空台。","爱酒陶元亮，无酒正徘徊。"],"p":"水调歌头"},{"id":"S00060","t":"水调歌头","a":"辛弃疾","c":["文字觑天巧，亭榭定风流。","平生丘壑，岁晚也作稻粱谋。","五亩园中秀野，一水田将绿绕，𫁂䅉不胜秋。","饭饱对花竹，可是便忘忧。","吾老矣，探禹穴，欠东游。","君家风月几许，白鸟去悠悠。","插架牙签万轴，射虎南山一骑，容我揽须不。","更欲劝君酒，百尺卧高楼。"],"p":"水调歌头"},{"id":"S00061","t":"黄莺儿","a":"柳永","c":["园林晴昼春谁主。","暖律潜催，幽谷暄和，黄鹂翩翩，乍迁芳树。","观露湿缕金衣，叶映如簧语。","晓来枝上绵蛮，似把芳心、深意低诉。","无据。","乍出暖烟来，又趁游蜂去。","恣狂踪迹，两两相呼，终朝雾吟风舞。","当上苑柳秾时，别馆花深处。","此际海燕偏饶，都把韶光与。"],"p":"黄莺儿"},{"id":"S00062","t":"玉女摇仙佩","a":"柳永","c":["飞琼伴侣，偶别珠宫，未返神仙行缀。","取次梳妆，寻常言语，有得几多姝丽。","拟把名花比。","恐旁人笑我，谈何容易。","细思算、奇葩艳卉，惟是深红浅白而已。","争如这多情，占得人间，千娇百媚。","须信画堂绣阁，皓月清风，忍把光阴轻弃。","自古及今、佳人才子，少得当年双美。","且恁相偎依。","未消得、怜我多才多艺。","愿妳妳、兰心蕙性，枕前言下，表余深意。","为盟誓。","今生断不孤鸳被。"],"p":"玉女摇仙佩"},{"id":"S00063","t":"雪梅香","a":"柳永","c":["景萧索，危楼独立面晴空。","动悲秋情绪，当时宋玉应同。","渔市孤烟袅寒碧，水村残叶舞愁红。","楚天阔，浪浸斜阳，千里溶溶。","临风。","想佳丽，别后愁颜，镇敛眉峰。","可惜当年，顿乖雨迹云踪。","雅态妍姿正欢洽，落花流水忽西东。","无憀恨、相思意，尽分付征鸿。"],"p":"雪梅香"},{"id":"S00064","t":"尾犯","a":"柳永","c":["夜雨滴空阶，孤馆梦回，情绪萧索。","一片闲愁，想丹青难貌。","秋渐老、蛩声正苦，夜将阑、灯花旋落。","最无端处，总把良宵，祗恁孤眠却。","佳人应怪我，别后寡信轻诺。","记得当初，翦香云为约。","甚时向、幽闺深处，按新词、流霞共酌。","再同欢笑，肯把金玉珠珍博。"],"p":"尾犯"},{"id":"S00065","t":"早梅芳・喜迁莺","a":"柳永","c":["海霞红，山烟翠。","故都风景繁华地。","谯门画戟，下临万井，金碧楼台相倚。","芰荷浦溆，杨柳汀洲，映虹桥倒影，兰舟飞棹，游人聚散，一片湖光里。","汉元侯，自从破虏征蛮，峻陟枢庭贵。","筹帷厌久，盛年昼锦，归来吾乡我里。","铃斋少讼，宴馆多欢，未周星，便恐皇家，图任勋贤，又作登庸计。"],"p":"早梅芳・喜迁莺"},{"id":"S00066","t":"斗百花","a":"柳永","c":["飒飒霜飘鸳瓦，翠幕轻寒微透，长门深锁悄悄，满庭秋色将晚。","眼看菊蕊，重阳泪落如珠，长是淹残粉面。","鸾辂音尘远。","无险幽恨，寄情空𣨼纨扇。","应是帝王，当初怪妾辞辇。","陡顿今来，宫中第一妖娆，却道昭阳飞燕。"],"p":"斗百花"},{"id":"S00067","t":"斗百花","a":"柳永","c":["煦色韶光明媚。","轻霭低笼芳树。","池塘浅蘸烟芜，帘幕闲垂风絮。","春困厌厌，抛掷斗草工夫，冷落踏青心绪。","终日卮朱户。","远恨绵绵，淑景迟迟难度。","年少傅粉，依前醉眠何处。","深院无人，黄昏乍拆秋千，空锁满庭花雨。"],"p":"斗百花"},{"id":"S00068","t":"斗百花","a":"柳永","c":["满搦宫腰纤细。","年纪方当笄岁。","刚被风流沾惹，与合垂杨双髻。","初学严妆，如描似削身材，怯雨羞云情意。","举措多娇媚。","争奈心性，未会先怜佳婿。","长是夜深，不肯便入鸳被。","与解罗裳，盈盈背立银釭，却道你但先睡。"],"p":"斗百花"},{"id":"S00069","t":"甘草子","a":"柳永","c":["秋暮。","乱洒衰荷，颗颗真珠雨。","雨过月华生，冷彻鸳鸯浦。","池长凭阑愁无侣。","奈此个、单栖情绪。","却傍金笼共鹦鹉。","念粉郎言语。"],"p":"甘草子"},{"id":"S00070","t":"甘草子","a":"柳永","c":["秋尽。","叶翦红绡，砌菊遗金粉。","雁字一行来，还有边庭信。","飘散露华清风紧。","动翠幕、晓寒犹嫩。","中酒残妆慵整顿。","聚两眉离恨。"],"p":"甘草子"},{"id":"S00071","t":"送征衣","a":"柳永","c":["过韶阳。","璇枢电绕，华渚虹流，运应千载会昌。","罄寰宇、荐殊祥。","吾皇。","诞弥月，瑶图缵庆，玉叶腾芳。","并景贶、三灵眷祐，挺英哲、掩前王。","迂年年、嘉节清和，颁率土称觞。","无间要荒华夏，尽万里、走梯航。","彤庭舜张大乐，禹会群方。","鹓行。","望上国，山呼鳌抃，遥𦶟炉香。","竟就日、瞻云献寿，指南山、等无疆。","愿巍巍、宝历鸿基，齐天地遥长。"],"p":"送征衣"},{"id":"S00072","t":"昼夜乐","a":"柳永","c":["洞房记得初相遇。","便只合、长相聚。","何期小会幽欢，变作离情别绪。","况值阑珊春色暮。","对满目、乱花狂絮。","直恐好风光，尽随伊归去。","一场寂寞凭谁诉。","算前言、总轻负。","早知恁地难拼，悔不当时留住。","其奈风流端正外，更别有、系人心处。","一日不思量，也攒眉千度。"],"p":"昼夜乐"},{"id":"S00073","t":"昼夜乐","a":"柳永","c":["秀香家住桃花径。","算神仙、才堪并。","层波细翦明眸，腻玉圆搓素颈。","爱把歌喉当筵逞。","遏天边，乱云愁凝。","言语似娇莺，一声声堪听。","洞房饮散帘帏静。","拥香衾、欢心称。","金炉麝袅青烟，凤帐烛摇红影。","无限狂心乘酒兴。","这欢娱、渐入嘉景。","犹自怨邻鸡，道秋宵不永。"],"p":"昼夜乐"},{"id":"S00074","t":"柳腰轻","a":"柳永","c":["英英妙舞腰肢软。","章台柳、昭阳燕。","锦衣冠盖，绮堂筵会，是处千金争选。","顾香砌、丝管初调，倚轻风、佩环微颤。","乍入霓裳促遍。","逞盈盈、渐催檀板。","慢垂霞袖，急趋莲步，进退奇容千变。","算何止、倾国倾城，暂回眸、万人肠断。"],"p":"柳腰轻"},{"id":"S00075","t":"西江月","a":"柳永","c":["凤额绣帘高卷，兽环朱户频摇。","两竿红日上花梢。","春睡厌厌难觉。","好梦狂随飞絮，闲愁浓胜香醪。","不成雨暮与云朝。","又是韶光过了。"],"p":"西江月"},{"id":"S00076","t":"倾杯乐","a":"柳永","c":["禁漏花深，绣工日永，蕙风布暖。","变韶景、都门十二，元宵三五，银蟾光满。","连云复道凌飞观。","耸皇居丽，嘉气瑞烟葱蒨。","翠华宵幸，是处层城阆苑。","龙凤烛、交光星汉。","对咫尺鳌山开羽扇。","会乐府两籍神仙，梨园四部弦管。","向晓色、都人未散。","盈万井、山呼鳌抃。","愿岁岁，天仗里、长瞻凤辇。"],"p":"倾杯乐"},{"id":"S00077","t":"笛家弄・笛家","a":"柳永","c":["花发西园，草薰南陌，韶光明媚，乍晴轻暖清明后。","水嬉舟动，禊饮筵开，银塘似染，金堤如绣。","是处王孙，几多游妓，往往携纤手。","遣离人、对嘉景，触目伤怀，尽成感旧。","别久。","帝城当日，兰堂夜烛，百万呼卢，画阁春风，十千沽酒。","未省、宴处能忘管弦，醉里不寻花柳。","岂知秦楼，玉箫声断，前事难重偶。","空遗恨，望仙乡，一饷消凝，泪沾襟袖。"],"p":"笛家弄・笛家"},{"id":"S00078","t":"倾杯乐","a":"柳永","c":["皓月初圆，暮云飘散，分明夜色如晴昼。","渐消尽、醺醺残酒。","危阁迥、凉生襟袖。","追旧事、一饷凭阑久。","如何媚容艳态，抵死孤欢偶。","朝思暮想，自家空恁添清瘦。","算到头、谁与伸剖。","向道我别来，为伊牵系，度岁经年，偷眼觑、也不忍觑花柳。","可惜恁、好景良宵，未曾略展双眉暂开口。","问甚时与你，深怜痛惜还依旧。"],"p":"倾杯乐"},{"id":"S00079","t":"迎新春","a":"柳永","c":["嶰管变青律，帝里阳和新布。","晴景回轻煦。","庆嘉节、当三五。","列华灯、千门万户。","遍九陌、罗绮香风微度。","十里然绛树。","鳌山耸、喧天潇鼓。","渐天如水，素月当午。","香径里、绝缨掷果无数。","更阑烛影花阴下，少年人、往往奇遇。","太平时、朝野多欢民康阜。","随分良聚。","堪对此景，争忍独醒归去。"],"p":"迎新春"},{"id":"S00080","t":"曲玉管","a":"柳永","c":["陇首云飞，江边日晚，烟波满目凭阑久。","立望关河萧索，千里清秋。","忍凝眸。","杳杳神京，盈盈仙子，别来锦字终难偶。","断雁无凭，冉冉飞下汀洲。","思悠悠。","暗想当初，有多少、幽欢佳会，岂知聚散难期，翻成雨恨云愁。","阻追游。","每登山临水，惹起平生心事，一场消黯，永日无言，却下层楼。"],"p":"曲玉管"},{"id":"S00081","t":"满朝欢","a":"柳永","c":["花隔铜壶，露晞金掌，都门十二清晓。","帝里风光烂漫，偏爱春杪。","烟轻昼永，引莺啭上林，鱼游灵沼。","巷陌乍晴，香尘染惹，垂杨芳草。","因念秦楼彩凤，楚观朝云，往惜曾迷歌笑。","别来岁久，偶忆欢盟重到。","人面桃花，未知何处，但掩朱扉悄悄。","尽日伫立无言，赢得凄凉怀抱。"],"p":"满朝欢"},{"id":"S00082","t":"梦还京","a":"柳永","c":["夜来匆匆饮散，敧枕背灯睡。","酒力全轻，醉魂易醒，风揭帘栊，梦断披衣重起。","悄无寐。","追悔当初，绣阁话别太容易。","日许时、犹阻归计。","甚况味。","旅馆虚度残岁。","想娇媚。","那里独守鸳帏静，永漏迢迢，也应暗同此意。"],"p":"梦还京"},{"id":"S00083","t":"凤衔杯","a":"柳永","c":["有美瑶卿能染翰。","千里寄、小诗长简。","想初襞苔笺，旋挥翠管红窗畔。","渐玉箸、银钩满。","锦囊收，犀轴卷。","常珍重、小斋吟玩。","更宝若珠玑，置之怀袖时时看。","似频见、千娇面。"],"p":"凤衔杯"},{"id":"S00084","t":"凤衔杯","a":"柳永","c":["追悔当初孤深愿。","经年价、两成幽怨。","任越水吴山，似屏如障堪游玩。","奈独自、慵抬眼。","赏烟花，听弦管。","图欢笑、转加肠断。","更时展丹青，强拈书信频频看。","又争似、亲相见。"],"p":"凤衔杯"},{"id":"S00085","t":"鹤冲天","a":"柳永","c":["闲窗漏永，月冷霜华堕。","悄悄下帘幕，残灯火。","再三追往事，离魂乱、愁肠锁。","无语沉吟坐。","好天好景，未省展眉则个。","从前早是多成破。","何况经岁月，相抛亸。","假使重相见，还得似、旧时么。","悔恨无计那。","迢迢良夜，自家只恁摧挫。"],"p":"鹤冲天"},{"id":"S00086","t":"受恩深","a":"柳永","c":["雅致装庭宇。","黄花开淡泞。","细香明艳尽天与。","助秀色堪餐，向晓自有真珠露。","刚被金钱妒。","拟买断秋天，容易独步。","粉蝶无情蜂已去。","要上金尊，惟有诗人曾许。","待宴赏重阳，恁时尽把芳心吐。","陶令轻回顾。","免憔悴东篱，冷烟寒雨。"],"p":"受恩深"},{"id":"S00087","t":"看花回","a":"柳永","c":["屈指劳生百岁期。","荣瘁相随。","利牵名惹逡巡过，奈两轮、玉走金飞。","红颜成白发，极品何为。","尘事常多雅会稀。","忍不开眉。","画堂歌管深深处，难忘酒盏花枝。","醉乡风景好，携手同归。"],"p":"看花回"},{"id":"S00088","t":"看花回","a":"柳永","c":["玉墄金阶舞舜干。","朝野多欢。","九衢三市风光丽，正万家、急管繁弦。","凤楼临绮陌，嘉气非烟。","雅俗熙熙物态妍。","忍负芳年。","笑筵歌席连昏昼，任旗亭、斗酒十千。","赏心何处好，惟有尊前。"],"p":"看花回"},{"id":"S00089","t":"柳初新","a":"柳永","c":["东郊向晓星杓亚。","报帝里、春来也。","柳抬烟眼，花匀露脸，渐觉绿娇红姹。","妆点层台芳榭。","运神功、丹青无价。","别有尧阶试罢。","新郎君、成行如画。","杏园风细，桃花浪暖，竞喜羽迁鳞化。","遍九陌、相将游冶。","骤香尘、宝鞍骄马。"],"p":"柳初新"},{"id":"S00090","t":"两同心","a":"柳永","c":["嫩脸修蛾，淡匀轻扫。","最爱学、宫体梳妆，偏能做、文人谈笑。","绮筵前、舞燕歌云，别有轻妙。","饮散玉炉烟袅。","洞房悄悄。","锦帐里、低语偏浓，银烛下、细看俱好。","那人人，昨夜分明，许伊偕老。"],"p":"两同心"},{"id":"S00091","t":"孤雁儿・御街行","a":"李清照","c":["藤床纸帐朝眠起。","说不尽、无佳思。","沈香断续玉炉寒，伴我情怀如水。","笛里三弄，梅心惊破，多少春情意。","小风疏雨萧萧地。","又催下、千行泪。","吹箫人去玉楼空，肠断与谁同倚。","一枝折得，人间天上，没个人堪寄。"],"p":"孤雁儿・御街行"},{"id":"S00092","t":"满庭霜・满庭芳","a":"李清照","c":["小阁藏春，闲窗锁昼，画堂无限深幽。","篆香烧尽，日影下帘钩。","手种江梅更好，又何必、临水登楼。","无人到，寂寥浑似，何逊在扬州。","从来，知韵胜，难堪雨籍，不耐风柔。","更谁家横笛，吹动浓愁。","莫恨香消雪减，须信道、扫迹情留。","难言处，良宵淡月，疏影尚风流。"],"p":"满庭霜・满庭芳"},{"id":"S00093","t":"玉楼春","a":"李清照","c":["红酥肯放琼苞碎。","探著南枝开遍未。","不知酝藉几多香，但见包藏无限意。","道人憔悴春窗底。","闷损阑干愁不倚。","要来小酌便来休，未必明朝风不起。"],"p":"玉楼春"},{"id":"S00094","t":"渔家傲","a":"李清照","c":["雪里已知春信至。","寒梅点缀琼枝腻。","香脸半开娇旖旎。","当庭际。","玉人浴出新妆洗。","造化可能偏有意。","故教明月玲珑地。","共赏金尊沈绿蚁。","莫辞醉。","此花不与群花比。"],"p":"渔家傲"},{"id":"S00095","t":"清平乐","a":"李清照","c":["年年雪里。","常插梅花醉。","挼尽梅花无好意。","赢得满衣清泪。","今年海角天涯。","萧萧两鬓生华。","看取晚来风势，故应难看梅花。"],"p":"清平乐"},{"id":"S00096","t":"南歌子","a":"李清照","c":["天上星河转，人间帘幕垂。","凉生枕簟泪痕滋。","起解罗衣、聊问夜何其。","翠贴莲蓬小，金销藕叶稀。","旧时天气旧时衣。","只有情怀、不似旧家时。"],"p":"南歌子"},{"id":"S00097","t":"转调满庭芳・满庭芳","a":"李清照","c":["芳草池塘，绿阴庭院，晚晴寒透窗纱。","□□金锁，管是客来唦。","寂寞尊前席上，惟□、海角天涯。","能留否，酴醿落尽，犹赖有□□。","当年，曾胜赏，生香薰袖，活火分茶。","□□□龙骄马，流水轻车。","不怕风狂雨骤，恰才称、煮酒残花。","如今也，不成怀抱，得似旧时那。"],"p":"转调满庭芳・满庭芳"},{"id":"S00098","t":"渔家傲","a":"李清照","c":["天接云涛连晓雾。","星河欲转千帆舞。","彷佛梦魂归帝所。","闻天语。","殷勤问我归何处。","我报路长嗟日暮。","学诗谩有惊人句。","九万里风鹏正举。","风休住。","蓬舟吹取三山去。"],"p":"渔家傲"},{"id":"S00099","t":"如梦令","a":"李清照","c":["常记溪亭日暮。","沈醉不知归路。","兴尽晚回舟，误入藕花深处。","争渡。","争渡。","惊起一滩鸥鹭。"],"p":"如梦令"},{"id":"S00100","t":"如梦令","a":"李清照","c":["昨夜雨疏风骤。","浓睡不消残酒。","试问卷帘人，却道海棠依旧。","知否。","知否。","应是绿肥红瘦。"],"p":"如梦令"},{"id":"S00101","t":"多丽","a":"李清照","c":["小楼寒，夜长帘幕低垂。","恨萧萧、无情风雨，夜来揉损琼肌。","也不似、贵妃醉脸，也不似、孙寿愁眉。","韩令偷香，徐娘傅粉，莫将比拟未新奇。","细看取、屈平陶令，风韵正相宜。","微风起，清芬酝籍，不减酴醿。","渐秋阑、雪清玉瘦，向人无限依依。","似愁凝、汉皋解佩，似泪洒、纨扇题诗。","朗月清风，浓烟暗雨，天教憔悴度芳姿。","纵爱惜、不知从此，留得几多时。","人情好，何须更忆，泽畔东篱。"],"p":"多丽"},{"id":"S00102","t":"菩萨蛮","a":"李清照","c":["风柔日薄春犹早。","夹衫乍著心情好。","睡起觉微寒。","梅花鬓上残。","故乡何处是。","忘了除非醉。","沈水卧时烧。","香消酒未消。"],"p":"菩萨蛮"},{"id":"S00103","t":"菩萨蛮","a":"李清照","c":["归鸿声断残云碧。","背窗雪落炉烟直。","烛底凤钗明。","钗头人胜轻。","角声催晓漏。","曙色回牛斗。","春意看花难。","西风留旧寒。"],"p":"菩萨蛮"},{"id":"S00104","t":"浣溪沙","a":"李清照","c":["莫许杯深琥珀浓。","未成沈醉意先融。","□□已应晚来风。","瑞脑香消魂梦断，辟寒金小髻鬟松。","醒时空对烛花红。"],"p":"浣溪沙"},{"id":"S00105","t":"浣溪沙","a":"李清照","c":["小院闲窗春色深。","重帘未卷影沈沈。","倚楼无语理瑶琴。","远岫出山催薄暮，细风吹雨弄轻阴。","梨花欲谢恐难禁。"],"p":"浣溪沙"},{"id":"S00106","t":"浣溪沙","a":"李清照","c":["淡荡春光寒食天。","玉炉沈水袅残烟。","梦回山枕隐花钿。","海燕未来人斗草，江海已过柳生绵。","黄昏疏雨湿秋千。"],"p":"浣溪沙"},{"id":"S00107","t":"凤凰台上忆吹箫","a":"李清照","c":["香冷金猊，被翻红浪，起来人未梳头。","任宝奁闲掩，日上帘钩。","生怕闲愁暗恨，多少事、欲说还休。","今年瘦，非干病酒，不是悲秋。","明朝，这回去也，千万遍阳关，也即难留。","念武陵春晚，云锁重楼。","记取楼前绿水，应念我、终日凝眸。","凝眸处，从今更数，几段新愁。"],"p":"凤凰台上忆吹箫"},{"id":"S00108","t":"一剪梅・一翦梅","a":"李清照","c":["红藕香残玉簟秋。","轻解罗裳，独上兰舟。","雪中谁寄锦书来，雁字回时，月满西楼。","花自飘零水自流。","一种相思，两处闲愁。","此情无计可消除，才下眉头，却上心头。"],"p":"一剪梅・一翦梅"},{"id":"S00109","t":"蝶恋花","a":"李清照","c":["泪湿罗衣脂粉满。","四叠阳关，唱到千千遍。","人道山长山又断。","萧萧微雨闻孤馆。","惜别伤离方寸乱。","忘了临行，酒盏深和浅。","好把音书凭过雁。","东来不似蓬莱远。"],"p":"蝶恋花"},{"id":"S00110","t":"蝶恋花","a":"李清照","c":["暖日晴风初破冻。","柳眼眉腮，已觉春心动。","酒意诗情谁与共。","泪融残粉花钿重。","乍试夹衫金缕缝。","山枕斜敧，枕损钗头凤。","独抱浓愁无好梦。","夜阑犹剪灯花弄。"],"p":"蝶恋花"},{"id":"S00111","t":"鹧鸪天","a":"李清照","c":["寒日萧萧上锁窗。","梧桐应恨夜来霜。","酒阑更喜团茶苦，梦断偏宜瑞脑香。","秋已尽，日犹长。","仲宣怀远更凄凉。","不如随分尊前醉，莫负东篱菊蕊黄。"],"p":"鹧鸪天"},{"id":"S00112","t":"小重山","a":"李清照","c":["春到长门春草青。","江梅些子破，未开匀。","碧云笼碾玉成尘。","留晓梦，惊破一瓯春。","花影压重门。","疏帘铺淡月，好黄昏。","二年三度负东君。","归来也，著意过今春。"],"p":"小重山"},{"id":"S00113","t":"怨王孙・忆王孙","a":"李清照","c":["湖上风来波浩渺。","秋已暮、红稀香少。","水光山色与人亲，说不尽、无穷好。","莲子已成荷叶老。","青露洗、苹花汀草。","眠沙鸥鹭不回头，似也恨、人归早。"],"p":"怨王孙・忆王孙"},{"id":"S00114","t":"临江仙","a":"李清照","c":["庭院深深深几许，云窗雾阁常扃。","柳梢梅萼渐分明。","春归秣陵树，人客远安城。","感月吟风多少事，如今老去无成。","谁怜憔悴更凋零。","试灯无意思，踏雪没心情。"],"p":"临江仙"},{"id":"S00115","t":"醉花阴","a":"李清照","c":["薄雾浓云愁永昼。","瑞脑消金兽。","佳节又重阳，玉枕纱厨，半夜凉初透。","东篱把洒黄昏后，有暗香盈袖。","莫道不消魂，帘卷西风，人似黄花瘦。"],"p":"醉花阴"},{"id":"S00116","t":"好事近","a":"李清照","c":["风定落花深，帘外拥红堆雪。","长记海棠开后，正是伤春时节。","酒阑歌罢玉尊空，青缸暗明灭。","魂梦不堪幽怨，更一声啼鴂。"],"p":"好事近"},{"id":"S00117","t":"诉衷情","a":"李清照","c":["夜来沈醉卸妆迟。","梅萼插残枝。","酒醒熏破春睡，梦远不成归。","人悄悄，月依依。","翠帘垂。","更挼残芯，更拈馀香，更得些时。"],"p":"诉衷情"},{"id":"S00118","t":"行香子","a":"李清照","c":["草际鸣蛩。","惊落梧桐。","正人间、天上愁浓。","云阶月地，关锁千重。","纵浮槎来，浮槎去，不相逢。","星桥鹊驾，经年才见，想离情、别恨难穷。","牵牛织女，莫是离中。","甚霎儿晴，霎儿雨，霎儿风。"],"p":"行香子"},{"id":"S00119","t":"失调名","a":"李清照","c":["犹将歌扇向人遮。","水晶山枕象牙床。","彩云易散月长亏。","几多深恨断人肠。","罗衣消尽恁时香。","闲愁也似月明多。","直送凄凉到画屏。"],"p":"失调名"},{"id":"S00120","t":"鹧鸪天","a":"李清照","c":["暗淡轻黄体性柔。","情疏迹远只香留。","何须浅碧深红色，自是花中第一流。","梅定妒，菊应羞。","画阑开处冠中秋。","骚人可煞无情思，何事当年不见收。"],"p":"鹧鸪天"},{"id":"S00121","t":"西湖念语","a":"欧阳修","c":["昔者王子猷之爱竹，造门不问于主人，陶渊明之卧舆，遇酒便留于道士。","况西湖之胜概，擅东颍之佳名。","虽美景良辰，固多于高会。","而清风明月，幸属于闲人。","并游或结于良朋，乘兴有时而独往。","鸣蛙暂听，安问属官而属私。","曲水临流，自可一觞而一咏。","至欢然而会意，亦傍若于无人。","乃知偶来常胜于特来，前言可信。","所有虽非于己有，其得已多。","因翻旧阕之辞，写以新声之调，敢阵薄伎，聊佐清欢。"],"p":"西湖念语"},{"id":"S00122","t":"采桑子","a":"欧阳修","c":["轻舟短棹西湖好，绿水逶迤。","芳草长堤。","隐隐笙歌处处随。","无风水面琉璃滑，不觉船移。","微动涟漪。","惊起沙禽掠岸飞。"],"p":"采桑子"},{"id":"S00123","t":"采桑子","a":"欧阳修","c":["春深雨过西湖好，百卉争妍。","蝶乱蜂喧。","晴日催花暖欲然。","兰桡画舸悠悠去，疑是神仙。","返照波间。","水阔风高扬管弦。"],"p":"采桑子"},{"id":"S00124","t":"采桑子","a":"欧阳修","c":["画船载酒西湖好，急管繁弦。","玉盏催传。","稳泛平波任醉眠。","行云却在行舟下，空水澄鲜。","俯仰留连。","疑是湖中别有天。"],"p":"采桑子"},{"id":"S00125","t":"采桑子","a":"欧阳修","c":["群芳过后西湖好，狼籍残红。","飞絮蒙蒙。","垂柳阑干尽日风。","笙歌散尽游人去，始觉春空。","垂下帘栊。","双燕归来细雨中。"],"p":"采桑子"},{"id":"S00126","t":"采桑子","a":"欧阳修","c":["何人解赏西湖好，佳景无时。","飞盖相追。","贪向花间醉玉卮。","谁知闲凭阑干处，芳草斜晖。","水远烟微。","一点沧洲白鹭飞。"],"p":"采桑子"},{"id":"S00127","t":"采桑子","a":"欧阳修","c":["清明上巳西湖好，满目繁华。","争道谁家。","绿柳朱轮走钿车。","游人日暮相将去，醒醉喧哗。","路转堤斜。","直到城头总是花。"],"p":"采桑子"},{"id":"S00128","t":"采桑子","a":"欧阳修","c":["荷花开后西湖好，载酒来时。","不用旌旗。","前后红幢绿盖随。","画船撑入花深处，香泛金卮。","烟雨微微。","一片笙歌醉里归。"],"p":"采桑子"},{"id":"S00129","t":"采桑子","a":"欧阳修","c":["天容水色西湖好，云物俱鲜。","鸥鹭闲眠。","应惯寻常听管弦。","风清月白偏宜夜，一片琼田。","谁羡骖鸾。","人在舟中便是仙。"],"p":"采桑子"},{"id":"S00130","t":"采桑子","a":"欧阳修","c":["残霞夕照西湖好，花坞苹汀。","十顷波平。","野岸无人舟自横。","西南月上浮云散，轩槛凉生。","莲芰香清。","水面风来酒面醒。"],"p":"采桑子"},{"id":"S00131","t":"采桑子","a":"欧阳修","c":["平生为爱西湖好，来拥朱轮。","富贵浮云。","俯仰流年二十春。","归来恰似辽东鹤，城郭人民。","触目皆新。","谁识当年旧主人。"],"p":"采桑子"},{"id":"S00132","t":"采桑子","a":"欧阳修","c":["画楼钟动君休唱，往事无踪。","聚散匆匆。","今日欢娱几客同。","去年绿鬓今年白，不觉衰容。","明月清风。","把酒何人忆谢公。"],"p":"采桑子"},{"id":"S00133","t":"采桑子","a":"欧阳修","c":["十年一别流光速，白首相逢。","莫话衰翁。","但斗尊前语笑同。","劝君满酌君须醉，尽日从容。","画鹢牵风。","即去朝天沃舜聪。"],"p":"采桑子"},{"id":"S00134","t":"采桑子","a":"欧阳修","c":["十年前是尊前客，月白风清。","忧患凋零。","老去光阴速可惊。","鬓华虽改心无改，试把金觥。","旧曲重听。","犹是当年醉里声。"],"p":"采桑子"},{"id":"S00135","t":"朝中措","a":"欧阳修","c":["平山阑槛倚晴空。","山色有无中。","手种堂前垂柳，别来几度春风。","文章太守，挥毫万字，一饮千锺。","行乐直须年少，尊前看取衰翁。"],"p":"朝中措"},{"id":"S00136","t":"长相思","a":"欧阳修","c":["苹满溪。","柳绕堤。","相送行人溪水西。","回时陇月低。","烟霏霏。","风凄凄。","重倚朱门听马嘶。","寒鸥相对飞。"],"p":"长相思"},{"id":"S00137","t":"长相思","a":"欧阳修","c":["花似伊。","柳似伊。","花柳青春人别离。","低头双泪垂。","长江东。","长江西。","两岸鸳鸯两处飞。","相逢知几时。"],"p":"长相思"},{"id":"S00138","t":"长相思","a":"欧阳修","c":["深花枝。","浅花枝。","深浅花枝相并时。","花枝难似伊。","玉如肌。","柳如眉。","爱著鹅黄金缕衣。","啼妆更为谁。"],"p":"长相思"},{"id":"S00139","t":"诉衷情","a":"欧阳修","c":["清晨帘幕卷轻霜。","呵手试梅妆。","都缘自有离恨，故画作远山长。","思往事，惜流芳。","易成伤。","拟歌先敛，欲笑还颦，最断人肠。"],"p":"诉衷情"},{"id":"S00140","t":"踏莎行","a":"欧阳修","c":["候馆梅残，溪桥柳细。","草熏风暖摇征辔。","离愁渐远渐无穷，迢迢不断如春水。","寸寸柔肠，盈盈粉泪。","楼高莫近危阑倚。","平芜尽处是春山，行人更在春山外。"],"p":"踏莎行"},{"id":"S00141","t":"踏莎行","a":"欧阳修","c":["雨霁风光，春分天气。","千花百卉争明媚。","画梁新燕一双双，玉笼鹦鹉愁孤睡。","薜荔依墙，莓苔满地。","青楼几处歌声丽。","蓦然旧事心上来，无言敛皱眉山翠。"],"p":"踏莎行"},{"id":"S00142","t":"望江南・忆江南","a":"欧阳修","c":["江南蝶，斜日一双双。","身似何郎全傅粉，心如韩寿爱偷香。","天赋与轻狂。","微雨后，薄翅腻烟光。","才伴游蜂来小院，又随飞絮过东墙。","长是为花忙。"],"p":"望江南・忆江南"},{"id":"S00143","t":"减字木兰花","a":"欧阳修","c":["留春不住。","燕老莺慵无觅处。","说似残春。","一老应无却少人。","风和月好。","办得黄金须买笑。","爱惜芳时。","莫待无花空折枝。"],"p":"减字木兰花"},{"id":"S00144","t":"减字木兰花","a":"欧阳修","c":["伤怀离抱。","天若有情天亦老。","此意如何。","细似轻丝渺似波。","扁舟岸侧。","枫叶荻花秋索索。","细想前欢。","须著人间比梦间。"],"p":"减字木兰花"},{"id":"S00145","t":"减字木兰花","a":"欧阳修","c":["楼台向晓。","淡月低云天气好。","翠幕风微。","宛转梁州入破时。","香生舞袂。","楚女腰肢天与细。","汗粉重匀。","酒后轻寒不著人。"],"p":"减字木兰花"},{"id":"S00146","t":"减字木兰花","a":"欧阳修","c":["画堂雅宴。","一抹朱弦初入遍。","慢拈轻笼。","玉指纤纤嫩剥葱。","拨头憁利。","怨月愁花无限意。","红粉轻盈。","倚暖香檀曲未成。"],"p":"减字木兰花"},{"id":"S00147","t":"减字木兰花","a":"欧阳修","c":["歌檀敛袂。","缭绕雕梁尘暗起。","柔润清圆。","百琲明珠一线穿。","樱唇玉齿。","天上仙音心下事。","留往行云。","满坐迷魂酒半醺。"],"p":"减字木兰花"},{"id":"S00148","t":"生查子","a":"欧阳修","c":["去年元夜时，花市灯如昼。","月到柳梢头，人约黄昏后。","今年元夜时，月与灯依旧。","不见去年人，泪满春衫袖。"],"p":"生查子"},{"id":"S00149","t":"生查子","a":"欧阳修","c":["含羞整翠鬟，得意频相顾。","雁柱十三弦，一一春莺语。","娇云容易飞，梦断知何处。","深院锁黄昏，阵阵芭蕉雨。"],"p":"生查子"},{"id":"S00150","t":"清商怨","a":"欧阳修","c":["关河愁思望处满。","渐素秋向晚。","雁过南云，行人回泪眼。","双鸾衾裯悔展。","夜又永、枕孤人远。","梦未成归，梅花闻塞管。"],"p":"清商怨"},{"id":"S00151","t":"望海潮","a":"秦观","c":["星分牛斗，疆连淮海，扬州万井提封。","花发路香，莺啼人起，珠帘十里东风。","豪俊气如虹。","曳照春金紫，飞盖相从。","巷入垂杨，画桥南北翠烟中。","追思故国繁雄。","有迷楼挂斗，月观横空。","纹锦制帆，明珠溅雨，宁论爵马鱼龙。","往事逐孤鸿。","但乱云流水，萦带离宫。","最好挥毫万字，一饮拼千锺。"],"p":"望海潮"},{"id":"S00152","t":"望海潮","a":"秦观","c":["秦峰苍翠，耶溪潇洒，千岩万壑争流。","鸳瓦雉城，谯门画戟，蓬莱燕阁三休。","天际识归舟。","泛五湖烟月，西子同游。","茂草台荒，苎萝村冷起闲愁。","何人览古凝眸。","怅朱颜易失，翠被难留。","梅市旧书，兰亭古墨，依稀风韵生秋。","狂客鉴湖头。","有百年台沼，终日夷犹。","最好金龟换酒，相与醉沧洲。"],"p":"望海潮"},{"id":"S00153","t":"望海潮","a":"秦观","c":["梅英疏淡，冰澌溶泄，东风暗换年华。","金谷俊游，铜驼巷陌，新晴细履平沙。","长记误随车。","正絮翻蝶舞，芳思交加。","柳下桃蹊，乱分春色到人家。","西园夜饮鸣笳。","有华灯碍月，飞盖妨花。","兰苑未空，行人渐老，重来是事堪嗟。","烟暝酒旗斜。","但倚楼极目，时见栖鸦。","无奈归心。","暗随流水到天涯。"],"p":"望海潮"},{"id":"S00154","t":"望海潮","a":"秦观","c":["奴如飞絮，郎如流水，相沾便肯相随。","微月户庭，残灯帘幕，匆匆共惜佳期。","才话暂分携。","早抱人娇咽，双泪红垂。","画舸难停，翠帷轻别两依依。","别来怎表相思。","有分香帕子，合数松儿。","红粉脆痕，青笺嫩约，丁宁莫遣人知。","成病也因谁。","更自言秋杪，亲去无疑。","但恐生时注著，合有分于飞。"],"p":"望海潮"},{"id":"S00155","t":"沁园春","a":"秦观","c":["宿霭迷空，腻云笼日，昼景渐长。","正兰皋泥润，谁家燕喜，蜜脾香少，触处蜂忙。","尽日无人帘幕挂，更风递游丝时过墙。","微雨后，有桃愁杏怨，红泪淋浪。","风流寸心易感，但依依伫立，回尽柔肠。","念小奁瑶鉴，重匀绛蜡，玉笼金斗，时熨沈香。","柳下相将游冶处，便回首青楼成异乡。","相忆事，纵蛮笺万叠，难写微茫。"],"p":"沁园春"},{"id":"S00156","t":"水龙吟","a":"秦观","c":["小楼连远横空，下窥绣毂雕鞍骤。","朱帘半卷，单衣初试，清明时候。","破暖轻风，弄晴微雨，欲无还有。","卖花声过尽，斜阳院落，红成阵、飞鸳甃。","玉佩丁东别后。","怅佳期、参差难又。","名缰利锁，天还知道，和天也瘦。","花下重门，柳边深巷，不堪回首。","念多情但有，当时皓月，向人依旧。"],"p":"水龙吟"},{"id":"S00157","t":"八六子","a":"秦观","c":["倚危亭。","恨如芳草，萋萋刬尽还生。","念柳外青骢别后，水边红袂分时，怆然暗惊。","无端天与娉婷。","夜月一帘幽梦，春风十里柔情。","怎奈向、欢娱渐随流水，素弦声断，翠绡香减，那堪片片飞花弄晚，蒙蒙残雨笼晴。","正销凝。","黄鹂又啼数声。"],"p":"八六子"},{"id":"S00158","t":"风流子","a":"秦观","c":["东风吹碧草，年华换、行客老沧洲。","见梅吐旧英，柳摇新绿，恼人春色，还上枝头。","寸心乱，北随云黯黯，东逐水悠悠。","斜日半山，暝烟两岸，数声横笛，一叶扁舟。","青门同携手，前欢记、浑似梦里扬州。","谁念断肠南陌，回首西楼。","算天长地久，有时有尽，奈何绵绵，此恨难休。","拟待倩人说与，生怕人愁。"],"p":"风流子"},{"id":"S00159","t":"梦扬州","a":"秦观","c":["晚云收。","正柳塘、烟雨初休。","燕子未归，恻恻清寒如秋。","小阑外、东风软，透绣帷、花蜜香稠。","江南远，人何处，鹧鸪啼破春愁。","长记曾陪燕游。","酬妙舞清歌，丽锦缠头。","𣨼酒为花，十载因谁淹留。","醉鞭拂面归来晚，望翠楼、帘卷金钩。","佳会阻，离情正乱，频梦扬州。"],"p":"梦扬州"},{"id":"S00160","t":"雨中花・夜行船","a":"秦观","c":["指点虚无征路，醉乘斑虬，远访西极。","正天风吹落，满空寒白。","玉女明星迎笑，何苦自淹尘域。","正火轮飞上，雾卷烟开，洞观金碧。","重重观阁，横枕鳌峰，水面倒衔苍石。","随处有、奇香幽火，杳然难测。","好是蟠桃熟后，阿环偷报消息。","在青天碧海，一枝难遇，占取春色。"],"p":"雨中花・夜行船"},{"id":"S00161","t":"一丛花","a":"秦观","c":["年时今夜见师师。","双颊酒红滋。","疏帘半卷微灯外，露华上、烟袅凉风。","簪髻乱抛，偎人不起，弹泪唱新词。","佳期。","谁料久参差。","愁绪暗萦丝。","想应妙舞清歌罢，又还对、秋色嗟咨。","惟有画楼，当时明月，两处照相思。"],"p":"一丛花"},{"id":"S00162","t":"鼓笛慢・水龙吟","a":"秦观","c":["乱花丛里曾携手，穷艳景，迷欢赏。","到如今谁把，雕鞍锁定，阻游人来往。","好梦随春远，从前事、不堪思想。","念香闺正杳，佳欢未偶，难留恋、空惆怅。","永夜婵娟未满，叹玉楼，几时重上。","那堪万里，却寻归路，指阳关孤唱。","苦恨东流水，桃源路、欲回双桨。","仗何人，细与丁宁问呵，我如今怎向。"],"p":"鼓笛慢・水龙吟"},{"id":"S00163","t":"促拍满路花","a":"秦观","c":["露颗添花色。","月彩投窗隙。","春思如中酒，恨无力。","洞房咫尺，曾寄情鸾翼。","云散无踪迹。","罗帐薰残，梦回无处寻觅。","轻红腻白。","步步熏兰泽。","约腕金环重，宜妆饰。","未知安否，一向无消息。","不似寻常忆。","忆后教人，片时存济不得。"],"p":"促拍满路花"},{"id":"S00164","t":"长相思","a":"秦观","c":["铁瓮城高，蒜山渡阔，干云十二层楼。","开尊待月，掩箔披风，依然灯火扬州。","绮陌南头。","记歌名宛转，乡号温柔。","曲槛俯清流。","想花阴、谁系兰舟。","念凄绝秦弦，感深荆赋，相望几许凝愁。","勤勤裁尺素，奈双鱼、难渡瓜洲。","晓鉴堪羞。","潘鬓点、吴霜渐稠。","幸于飞、鸳鸯未老，不应同是悲秋。"],"p":"长相思"},{"id":"S00165","t":"满庭芳","a":"秦观","c":["山抹微云，天连衰草，画角声断谯门。","暂停征棹，聊共引离尊。","多少蓬莱旧事，空回首、烟霭纷纷。","斜阳外，寒鸦万点，流水绕孤村。","销魂。","当此际，香囊暗解，罗带轻分。","谩赢得、青楼薄幸名存。","此去何时见也，襟袖上、空惹啼痕。","伤情处，高城望断，灯火已黄昏。"],"p":"满庭芳"},{"id":"S00166","t":"满庭芳","a":"秦观","c":["红蓼花繁，黄芦叶乱，夜深玉露初零。","霁天空阔，云淡楚江清。","独棹孤篷小艇，悠悠过、烟渚沙汀。","金钩细，丝纶慢卷，牵动一潭星。","时时，横短笛，清风浩月，相与忘形。","任人笑生涯，泛梗飘萍。","饮罢不妨醉卧，尘劳事、有耳谁听。","江风静，日高未起，枕上酒微醒。"],"p":"满庭芳"},{"id":"S00167","t":"满庭芳","a":"秦观","c":["碧水惊秋，黄云凝暮，败叶零乱空阶。","洞房人静，斜月照徘徊。","又是重阳近也，几处处，砧杵声催。","西窗下，风摇翠竹，疑是故人来。","伤怀。","增怅望，新欢易失，往事难猜。","问篱边黄菊，知为谁开。","谩道愁须𣨼酒，酒未醒、愁已先回。","凭阑久，金波渐转，白露点苍苔。"],"p":"满庭芳"},{"id":"S00168","t":"江城子","a":"秦观","c":["西城杨柳弄春柔。","动离忧。","泪难收。","犹记多情，曾为系归舟。","碧野朱桥当日事，人不见，水空流。","韶华不为少年留。","恨悠悠。","几时休。","飞絮落花时候、一登楼。","便做春江都是泪，流不尽，许多愁。"],"p":"江城子"},{"id":"S00169","t":"江城子","a":"秦观","c":["南来飞燕北归鸿。","偶相逢。","惨愁容。","绿鬓朱颜，重见两衰翁。","别后悠悠君莫问，无限事，不言中。","小槽春酒滴珠红。","莫匆匆。","满金锺。","饮散落花流水、各西东。","后会不知何处是，烟浪远，暮云重。"],"p":"江城子"},{"id":"S00170","t":"江城子","a":"秦观","c":["枣花金钏约柔荑。","昔曾携。","事难期。","咫尺玉颜，和泪锁春闺。","恰似小园桃与李，虽同处，不同枝。","玉笙初度颤鸾篦。","落花飞。","为谁吹。","月冷风高，此恨只天知。","任是行人无定处，重相见，是何时。"],"p":"江城子"},{"id":"S00171","t":"满园花・促拍满路花","a":"秦观","c":["一向沈吟久。","泪珠盈襟袖。","我当初不和、苦撋就。","惯纵得软顽，见底心先有。","行待痴心守。","甚捻著脉子，倒把人来僝僽。","近日来、非常罗皂丑。","佛也须眉皱。","怎掩得众人口。","待收了孛罗，罢了从来斗。","从今后。","休道共我，梦见也、不能得句。"],"p":"满园花・促拍满路花"},{"id":"S00172","t":"迎春乐","a":"秦观","c":["菖蒲叶叶知多少。","惟有个、蜂儿妙。","雨晴红粉齐开了。","露一点、娇黄小。","早是被、晓风力暴。","更春共、斜阳俱老。","怎得香香深处，作个蜂儿抱。"],"p":"迎春乐"},{"id":"S00173","t":"鹊桥仙","a":"秦观","c":["纤云弄巧，飞星传恨，银汉迢迢暗度。","金风玉露一相逢，便胜却、人间无数。","柔情似水，佳期如梦，忍顾鹊桥归路。","两情若是长久时，又岂在、朝朝暮暮。"],"p":"鹊桥仙"},{"id":"S00174","t":"菩萨蛮","a":"秦观","c":["虫声泣露惊秋枕。","罗帏泪湿鸳鸯锦。","独卧玉肌凉。","残更与恨长。","阴风翻翠幔。","雨涩灯花暗。","毕竟不成眠。","鸦啼金井寒。"],"p":"菩萨蛮"},{"id":"S00175","t":"减字木兰花","a":"秦观","c":["天涯旧恨。","独自凄凉人不问。","欲见回肠。","断尽金炉小篆香。","黛峨长敛。","任是春风吹不展。","困倚危楼。","过尽飞鸿字字愁。"],"p":"减字木兰花"},{"id":"S00176","t":"木兰花・玉楼春","a":"秦观","c":["秋容老尽芙蓉院。","草上霜花匀似翦。","西楼促坐酒杯深，风压绣帘香不卷。","玉纤慵整银筝雁。","红袖时笼金鸭暖。","岁华一任委西风，独有春红留醉脸。"],"p":"木兰花・玉楼春"},{"id":"S00177","t":"画堂春","a":"秦观","c":["落红铺尽水平池。","弄晴小雨霏霏。","杏园憔悴杜鹃啼。","无奈春归。","柳外画楼独上，凭阑手拈花枝。","放花无语对斜晖。","此恨谁知。"],"p":"画堂春"},{"id":"S00178","t":"千秋岁","a":"秦观","c":["水边沙外。","城郭春寒退。","花影乱，莺声碎。","飘零疏酒盏，离别宽衣带。","人不见，碧云暮合空相对。","忆昔西池会。","鹓鹭同飞盖。","携手处，今谁在。","日边清梦断，镜里朱颜改。","春去也，飞红万点愁如海。"],"p":"千秋岁"},{"id":"S00179","t":"踏莎行","a":"秦观","c":["雾失楼台，月迷津渡。","桃源望断无寻处。","可堪孤馆闭春寒，杜鹃声里斜阳暮。","驿寄梅花，鱼传尺素。","砌成此恨无重数。","郴江幸自绕郴山，为谁流下潇湘去。"],"p":"踏莎行"},{"id":"S00180","t":"蝶恋花","a":"秦观","c":["晓日窥轩双燕语。","似与佳人，共惜春将暮。","屈指艳阳都几许。","可无时霎闲风雨。","流水落花无问处。","只有飞云，冉冉来还去。","持酒劝云云且住。","凭君碍断春归路。"],"p":"蝶恋花"},{"id":"S00181","t":"赤壁词・念奴娇","a":"陆游","c":["禁门锺晓，忆君来朝路，初翔鸾鹄。","西府中台推独步，行对金莲宫烛。","蹙绣华鞯，仙葩宝带，看即飞腾速。","人生难料，一尊此地相属。","回首紫陌青门，西湖闲院，锁千梢修竹。","素壁栖鸦应好在，残梦不堪重续。","岁月惊心，功名看镜，短鬓无多绿。","一欢休惜，与君同醉浮玉。"],"p":"赤壁词・念奴娇"},{"id":"S00182","t":"浣溪沙","a":"陆游","c":["懒向沙头醉玉瓶。","唤君同赏小窗明。","夕阳吹角最关情。","忙日苦多闲日少，新愁常续旧愁生。","客中无伴怕君行。"],"p":"浣溪沙"},{"id":"S00183","t":"浣溪沙","a":"陆游","c":["浴罢华清第二汤。","红绵扑粉玉肌凉。","娉婷初试藕丝裳。","凤尺裁成猩血色，螭奁熏透麝脐香。","水亭幽处捧霞觞。"],"p":"浣溪沙"},{"id":"S00184","t":"青玉案","a":"陆游","c":["西风挟雨声翻浪。","恰洗尽、黄茅瘴。","老惯人间齐得丧。","千岩高卧，五湖归棹，替却凌烟像。","故人小驻平戎帐。","白羽腰间气何壮。","我老渔樵君将相。","小槽红酒，晚香丹荔，记取蛮江上。"],"p":"青玉案"},{"id":"S00185","t":"水调歌头","a":"陆游","c":["江左占形胜，最数古徐州。","连山如画，佳处缥渺著危楼。","鼓角临风悲壮，烽火连空明灭，往事忆孙刘。","千里曜戈甲，万灶宿貔貅。","露沾草，风落木，岁方秋。","使君宏放，谈笑洗尽古今愁。","不见襄阳登览，磨灭游人无数，遗恨黯难收。","叔子独千载，名与汉江流。"],"p":"水调歌头"},{"id":"S00186","t":"浪淘沙","a":"陆游","c":["绿树暗长亭。","几把离尊。","阳关常恨不堪闻。","何况今朝秋色里，身是行人。","清泪浥罗巾。","各自消魂。","一江离恨恰平分。","安得千寻横铁锁，截断烟津。"],"p":"浪淘沙"},{"id":"S00187","t":"定风波","a":"陆游","c":["敧帽垂鞭送客回。","小桥流水一枝梅。","衰病逢春都不记。","谁谓。","幽香却解逐人来。","安得身闲频置酒。","携手。","与君看到十分开。","少壮相从今雪鬓。","因甚。","流年羁恨两相催。"],"p":"定风波"},{"id":"S00188","t":"南乡子","a":"陆游","c":["归梦寄吴樯。","水驿江程去路长。","想见芳洲初系缆，斜阳。","烟树参差认武昌。","愁鬓点新霜。","曾是朝衣染御香。","重到故乡交旧少，凄凉。","却恐它乡胜故乡。"],"p":"南乡子"},{"id":"S00189","t":"南乡子","a":"陆游","c":["早岁入皇州。","尊酒相逢尽胜流。","三十年来真一梦，堪愁。","客路萧萧两鬓秋。","蓬峤偶重游。","不待人嘲我自羞。","看镜倚楼俱已矣，扁舟。","月笛烟蓑万事休。"],"p":"南乡子"},{"id":"S00190","t":"满江红","a":"陆游","c":["危堞朱栏，登览处、一江秋色。","人正似、征鸿社燕，几番轻别。","缱绻难忘当日语，凄凉又作它乡客。","问鬓边、都有几多丝，真堪织。","杨柳院，秋千陌。","无限事，成虚掷。","如今何处也，梦魂难觅。","金鸭微温香缥渺，锦茵初展情萧瑟。","料也应、红泪伴秋霖，灯前滴。"],"p":"满江红"},{"id":"S00191","t":"满江红","a":"陆游","c":["疏蕊幽香，禁不过、晚寒愁绝。","那更是、巴东江上，楚山千叠。","敧帽闲寻西瀼路，亸鞭笑向南枝说。","恐使君、归去上銮坡，孤风月。","清镜里，悲华发。","山驿外，溪桥侧。","凄然回首处，凤凰城阙。","憔悴如今谁领略，飘零已是无颜色。","问行厨、何日唤宾僚，犹堪折。"],"p":"满江红"},{"id":"S00192","t":"感皇恩","a":"陆游","c":["春色到人间，彩旛初戴。","正好春盘细生菜。","一般日月，只有仙家偏耐。","雪霜从点鬓，朱颜在。","温诏鼎来，延英催对。","凤阁鸾台看除拜。","对衣裁稳，恰称球纹新带。","个时方旋了、功名债。"],"p":"感皇恩"},{"id":"S00193","t":"感皇恩","a":"陆游","c":["小阁倚秋空，下临江渚。","漠漠孤云未成雨。","数声新雁，回首杜陵何处。","壮心空万里，人谁许。","黄阁紫枢，筑坛开府。","莫怕功名欠人做。","如今熟计，只有故乡归路。","石帆山脚下，菱三亩。"],"p":"感皇恩"},{"id":"S00194","t":"好事近","a":"陆游","c":["羁雁未成归，肠断宝筝零落。","那更冻醪无力，似故人情薄。","瘴云蛮雨暗孤城，身在楚山角。","烦问剑南消息，怕还成疏索。"],"p":"好事近"},{"id":"S00195","t":"好事近","a":"陆游","c":["风露九霄寒，侍宴玉华宫阙。","亲向紫皇香案，见金芝千叶。","碧壶仙露酝初成，香味两奇绝。","醉后却骑丹凤，看蓬莱春色。"],"p":"好事近"},{"id":"S00196","t":"好事近","a":"陆游","c":["客路苦思归，愁似茧丝千绪。","梦里镜湖烟雨，看山无重数。","尊前消尽少年狂，慵著送春语。","花落燕飞庭户，叹年光如许。"],"p":"好事近"},{"id":"S00197","t":"好事近","a":"陆游","c":["岁晚喜东归，扫尽市朝陈迹。","拣得乱山环处，钓一潭澄碧。","卖鱼沽酒醉还醒，心事付横笛。","家在万重云外，有沙鸥相识。"],"p":"好事近"},{"id":"S00198","t":"好事近","a":"陆游","c":["华表又千年，谁记驾云孤鹤。","回首旧曾游处，但山川城郭。","纷纷车马满人间，尘土污芒𪨗。","且访葛仙丹井，看岩花开落。"],"p":"好事近"},{"id":"S00199","t":"好事近","a":"陆游","c":["挥袖别人间，飞蹑峭崖苍壁。","寻见古仙丹灶，有白云成积。","心如潭水静无风，一坐数千息。","夜半忽惊奇事，看鲸波暾日。"],"p":"好事近"},{"id":"S00200","t":"好事近","a":"陆游","c":["湓口放船归，薄暮散花洲宿。","两岸白苹红蓼，映一蓑新绿。","有沽酒处便为家，菱芡四时足。","明日又乘风去，任江南江北。"],"p":"好事近"},{"id":"S00201","t":"好事近","a":"陆游","c":["挥袖上西峰，孤绝去天无尺。","拄杖下临鲸海，数烟帆历历。","贪看云气舞青鸾，归路已将夕。","多谢半山松吹，解殷勤留客。"],"p":"好事近"},{"id":"S00202","t":"好事近","a":"陆游","c":["小倦带馀酲，澹澹数櫺斜日。","驱退睡魔十万，有双龙苍璧。","少年莫笑老人衰，风味似平昔。","扶杖冻云深处，探溪梅消息。"],"p":"好事近"},{"id":"S00203","t":"好事近","a":"陆游","c":["觅个有缘人，分付玉壶灵药。","谁向市尘深处，识辽天孤鹤。","月中吹笛下巴陵，条华赴前约。","今古废兴何限，叹山川如昨。"],"p":"好事近"},{"id":"S00204","t":"好事近","a":"陆游","c":["平旦出秦关，雪色驾车双鹿。","借问此行安往，赏清伊修竹。","汉家宫殿劫灰中，春草几回绿。","君看变迁如许，况纷纷荣辱。"],"p":"好事近"},{"id":"S00205","t":"好事近","a":"陆游","c":["秋晓上莲峰，高蹑倚天青壁。","谁与放翁为伴，有天坛轻策。","铿然忽变赤龙飞，雷雨四山黑。","谈笑做成丰岁，笑禅龛楖栗。"],"p":"好事近"},{"id":"S00206","t":"鹧鸪天","a":"陆游","c":["家住东吴近帝乡。","平生豪举少年场。","十千沽酒青楼上，百万呼卢锦瑟傍。","身易老，恨难忘。","尊前赢得是凄凉。","君归为报京华旧，一事无成两鬓霜。"],"p":"鹧鸪天"},{"id":"S00207","t":"鹧鸪天","a":"陆游","c":["看尽巴山看蜀山。","子规江上过春残。","惯眠古驿常安枕，熟听《阳关》不惨颜。","慵服气，懒烧丹。","不妨青鬓戏人间。","秘传一字神仙诀，说与君知只是顽。"],"p":"鹧鸪天"},{"id":"S00208","t":"鹧鸪天","a":"陆游","c":["梳发金盘剩一窝。","画眉鸾镜晕双蛾。","人间何处无春到，只有伊家独占多。","微步处，奈娇何。","春衫初换曲尘罗。","东邻斗草归来晚，忘却新传子夜歌。"],"p":"鹧鸪天"},{"id":"S00209","t":"鹧鸪天","a":"陆游","c":["家住苍烟落照间。","丝毫尘事不相关。","斟残玉瀣行穿竹，卷罢《黄庭》卧看山。","贪啸傲，任衰残。","不妨随处一开颜。","元知造物心肠别，老却英雄似等闲。"],"p":"鹧鸪天"},{"id":"S00210","t":"鹧鸪天","a":"陆游","c":["插脚红尘已是颠。","更求平地上青天。","新来有个生涯别，买断烟波不用钱。","沽酒市，采菱船。","醉听风雨拥蓑眠。","三山老子真堪笑，见事迟来四十年。"],"p":"鹧鸪天"},{"id":"S00211","t":"念奴娇","a":"黄庭坚","c":["断虹霁雨，净秋空，山染修眉新绿。","桂影扶疏，谁便道，今夕清辉不足。","万里青天，姮娥何处，驾此一轮玉。","寒光零乱，为谁遍照醽醁。","年少从我追游，晚凉幽径，绕张园森木。","共倒金荷家万里，难得尊前相属。","老子平生，江南江北，最爱临风曲。","孙郎微笑，坐来声喷霜竹。"],"p":"念奴娇"},{"id":"S00212","t":"水调歌头","a":"黄庭坚","c":["瑶草一何碧，春入武陵溪。","溪上桃花无数，花上有黄鹂。","我欲穿花寻路，直入白云深处，浩气展红霓。","只恐花深里，红露湿人衣。","坐玉石，敧玉枕，拂金徽。","谪仙何处，无人伴我白螺杯。","我为灵芝仙草，不为朱唇丹脸，长啸亦何为。","醉舞下山去，明月逐人归。"],"p":"水调歌头"},{"id":"S00213","t":"水调歌头","a":"黄庭坚","c":["落日塞垣路，风劲戛貂裘。","翩翩数骑闲猎，深入黑山头。","极目平沙千里，惟见雕弓白羽，铁面骏骅骝。","隐隐望青冢，特地起闲愁。","汉天子，方鼎盛，四百州。","玉颜皓齿，深锁三十六宫秋。","堂有经纶贤相，边有纵横谋将，不减翠娥羞。","戎虏和乐也，圣主永无忧。"],"p":"水调歌头"},{"id":"S00214","t":"满庭芳","a":"黄庭坚","c":["初绾云鬟，才胜罗绮，便嫌柳陌花街。","占春才子，容易托行媒。","其奈风情债负，烟花部、不免差排。","刘郎恨，桃花片片，随水染尘埃。","风流，贤太守，能笼翠羽，宜醉金钗。","且留取垂杨，掩映厅阶。","直待朱轓去后，从伊便、窄袜弓鞋。","知恩否，朝云暮雨，还向梦中来。"],"p":"满庭芳"},{"id":"S00215","t":"满庭芳","a":"黄庭坚","c":["北苑春风，方圭圆璧，万里名动京关。","碎身粉骨，功合上凌烟。","尊俎风流战胜，降春睡、开拓愁边。","纤纤捧，研膏溅乳，金缕鹧鸪斑。","相如，虽病渴，一觞一咏，宾有群贤。","为扶起灯前，醉玉颓山。","搜搅心中万卷，还倾动、三峡词源。","归来晚，文君未寝，相对小窗前。"],"p":"满庭芳"},{"id":"S00216","t":"鼓笛慢・水龙吟","a":"黄庭坚","c":["早秋明月新圆，汉家戚里生飞将。","青骢宝勒，绿沈金锁，曾瞻天仗。","种德江南，宣威西夏，合宫陪享。","况当年定计，昭陵与子，勋劳在、诸公上。","千骑风流年少，暂淹留、莫辜清赏。","平坡驻马，虚弦落雁，思临虏帐。","遍舞摩围，递歌彭水，拂云惊浪。","看朱颜绿鬓，封侯万里，写凌烟像。"],"p":"鼓笛慢・水龙吟"},{"id":"S00217","t":"洞仙歌","a":"黄庭坚","c":["月中丹桂，自风霜难老。","阅尽人间盛衰草。","望中秋、才有几日，十分圆，霾风雨，云表常如永昼。","不得文章力，白首防秋，谁念云中上功守。","正注意，得人雄，静扫河山，应难纵、五湖归棹。","问持节冯唐几时来，看再策勋名，印窠如斗。"],"p":"洞仙歌"},{"id":"S00218","t":"雨中花・夜行船","a":"黄庭坚","c":["政乐中和，夷夏宴喜，官梅乍传消息。","待作新年欢计，断送春色。","桃李成阴，甘棠少讼，又移旌戟。","念画楼朱阁，风流高会，顿冷谈席。","西州纵有，舞裙歌板，谁共茗邀棋敌。","归来未得，先沾离袖，管弦催滴。","乐事赏心易散，良辰美景难得。","会须醉倒，玉山扶起，更倾春碧。"],"p":"雨中花・夜行船"},{"id":"S00219","t":"忆帝京","a":"黄庭坚","c":["鸣鸠乳燕春闲暇。","化作绿阴槐夏。","寿酒舞红裳，睡鸭飘香麝。","醉此洛阳人，佐郡深儒雅。","况坐上、玉麟金马。","更莫问、莺老花谢。","万里相依，千金为寿，未厌玉烛传清夜。","不醉欲言归，笑杀高阳社。"],"p":"忆帝京"},{"id":"S00220","t":"醉蓬莱","a":"黄庭坚","c":["对朝云叆叇，暮雨霏微，乱峰相倚。","巫峡高唐，锁楚宫朱翠。","画戟移春，靓妆迎马，向一川都会。","万里投荒，一身吊影，成何欢意。","尽道黔南，去天尺五，望极神州，万里烟水。","尊酒公堂，有中朝佳士。","荔颊红深，麝脐香满，醉舞裀歌袂。","杜宇声声，催人到晓，不如归是。"],"p":"醉蓬莱"},{"id":"S00221","t":"南歌子","a":"黄庭坚","c":["诗有渊明语，歌无子夜声。","论文思见老弥明。","坐想罗浮山下、羽衣轻。","何处黔中郡，遥知隔晚晴。","雨馀风急断虹横。","应梦池塘春草、若为情。"],"p":"南歌子"},{"id":"S00222","t":"蓦山溪","a":"黄庭坚","c":["鸳鸯翡翠，小小思珍偶。","眉黛敛秋波，尽湖南、山明水秀。","娉娉袅袅，恰近十三馀，春未透。","花枝瘦。","正是愁时候。","寻花载酒。","肯落谁人后。","只恐远归来，绿成阴、青梅如豆。","心期得处，每自不由人，长亭柳。","君知否。","千里犹回首。"],"p":"蓦山溪"},{"id":"S00223","t":"转调丑奴儿・采桑子","a":"黄庭坚","c":["得意许多时。","长醉赏、月影花枝。","暴风狂雨年年有，金笼锁定，莺雏燕友，不被鸡期。","红旆转逶迤。","悔无计、千里追随。","再来应绾泸南印，而今目下，凄惶怎向，日永春迟。"],"p":"转调丑奴儿・采桑子"},{"id":"S00224","t":"品令","a":"黄庭坚","c":["败叶霜天晓。","渐鼓吹、催行棹。","栽成桃李未开，便解银章归报。","去取麒麟图画，要及年少。","劝公醉倒。","别语怎向醒时道。","楚山千里暮云，正锁离人情抱。","记取江州司马，坐中最老。"],"p":"品令"},{"id":"S00225","t":"踏莎行","a":"黄庭坚","c":["画鼓催春，蛮歌走饷。","雨前一焙谁争长。","低株摘尽到高株，株株别是闽溪样。","碾破春风，香凝午帐。","银瓶雪滚翻成浪。","今宵无睡酒醒时，摩围影在秋江上。"],"p":"踏莎行"},{"id":"S00226","t":"踏莎行","a":"黄庭坚","c":["临水夭桃，倚墙繁李。","长杨风掉青骢尾。","尊中有酒且酬春，更寻何处无愁地。","明日重来，落花如绮。","芭蕉渐展山公启。","欲笺心事寄天公，教人长对花前醉。"],"p":"踏莎行"},{"id":"S00227","t":"定风波","a":"黄庭坚","c":["自断此生休问天。","白头波上泛孤船。","老去文章无气味。","憔悴。","不堪驱使菊花前。","闻道使君携将吏。","高会。","参军吹帽晚风颠。","千骑插花秋色暮。","归去。","翠娥扶入醉时肩。"],"p":"定风波"},{"id":"S00228","t":"定风波","a":"黄庭坚","c":["万里黔中一漏天。","屋居终日似乘船。","及至重阳天也霁。","催醉。","鬼门关外蜀江前。","莫笑老翁犹气岸。","君看。","几人黄菊上华颠。","戏马台南追两谢。","驰射。","风流犹拍古人肩。"],"p":"定风波"},{"id":"S00229","t":"定风波","a":"黄庭坚","c":["晚岁监州闻荔枝。","赤英垂坠压阑枝。","万里来逢芳意歇。","愁绝。","满盘空忆去年时。","涧草山花光照坐。","春过。","等闲桃李又累累。","辜负寒泉浸红皱。","消瘦。","有人花病损香肌。"],"p":"定风波"},{"id":"S00230","t":"定风波","a":"黄庭坚","c":["准拟阶前摘荔枝。","今年歇尽去年枝。","莫是春光厮料理。","无比。","譬如痎疟有休时。","碧甃朱阑情不浅。","何晚。","来年枝上报累累。","雨后园林坐清影。","苏醒。","红裳剥尽看香肌。"],"p":"定风波"},{"id":"S00231","t":"鹊桥仙","a":"黄庭坚","c":["八年不见，清都绛阙，望河汉、溶溶漾漾。","年年牛女恨风波，拼此事、人间天上。","野麋丰草，江鸥远水，老去惟便疏放。","百钱端欲问君平，早晚具、归田小舫。"],"p":"鹊桥仙"},{"id":"S00232","t":"鹊桥仙","a":"黄庭坚","c":["朱楼彩舫，浮瓜沈李，报答风光有处。","一年尊酒暂时同，别泪作、人间晓雨。","鸳鸯机综，能令侬巧，也待乘槎仙去。","若逢海上白头翁，共一访、痴牛呆女。"],"p":"鹊桥仙"},{"id":"S00233","t":"阮郎归","a":"黄庭坚","c":["黔中桃李可寻芳。","摘茶人自忙。","月团犀胯斗圆方。","研膏入焙香。","青箬裹，绛纱囊。","品高闻外江。","酒阑传碗舞红裳。","都濡春味长。"],"p":"阮郎归"},{"id":"S00234","t":"阮郎归","a":"黄庭坚","c":["烹茶留客驻金鞍。","月斜窗外山。","别郎容易见郎难。","有人思远山。","归去后，忆前欢。","画屏金博山。","一杯春露莫留残。","与郎扶玉山。"],"p":"阮郎归"},{"id":"S00235","t":"更漏子","a":"黄庭坚","c":["庵摩勒，西土果。","霜后明珠颗颗。","凭玉兔，捣香尘。","称为席上珍。","号馀甘，争奈苦。","临上马时分付。","管回味，却思量。","忠言君拭尝。"],"p":"更漏子"},{"id":"S00236","t":"绣带子・好女儿","a":"黄庭坚","c":["小院一枝梅。","冲破晓寒开。","晚到芳园游戏，满袖带香回。","玉酒覆银杯。","尽醉去、犹待重来。","东邻何事，惊吹怨笛，雪片成堆。"],"p":"绣带子・好女儿"},{"id":"S00237","t":"撼庭竹","a":"黄庭坚","c":["呜咽南楼吹落梅。","闻鸦树惊栖。","梦中相见不多时。","隔城今夜也应知。","坐久水空碧，山月影沈西。","买个宅儿住著伊。","刚不肯相随。","如今果被天嗔作，永落鸡群被鸡欺。","空恁可怜伊。","风日损花枝。"],"p":"撼庭竹"},{"id":"S00238","t":"减字木兰花","a":"黄庭坚","c":["馀寒争令。","雪共蜡梅相照影。","昨夜东风。","已出耕牛劝岁功。","阴云幂幂。","近觉去天无几尺。","休恨春迟。","桃李梢头次第知。"],"p":"减字木兰花"},{"id":"S00239","t":"减字木兰花","a":"黄庭坚","c":["使君那里。","千骑尘中依约是。","拂我眉头。","无处重寻庾信愁。","山云弥漫。","夹道旌旗联复断。","万事茫茫。","分付澄波与烂肠。"],"p":"减字木兰花"},{"id":"S00240","t":"减字木兰花","a":"黄庭坚","c":["襄王梦里。","草绿烟深何处是。","宋玉台头。","暮雨朝云几许愁。","飞花漫漫。","不管羁人肠欲断。","春水茫茫。","欲度南陵更断肠。"],"p":"减字木兰花"},{"id":"S00241","t":"瑞龙吟","a":"周邦彦","c":["章台路。","还见褪粉梅梢，试花桃树。","愔愔坊陌人家，定巢燕子，归来旧处。","暗凝伫。","因念个人痴小，乍窥门户。","侵晨浅约宫黄，障风映袖，盈盈笑语。","前度刘郎重到，访邻寻里，同时歌舞。","唯有旧家秋娘，声价如故。","吟笺赋笔，犹记燕台句。","知谁伴，名园露饮，东城闲步。","事与孤鸿去。","探春尽是，伤离意绪。","官柳低金缕。","归骑晚，纤纤池塘飞雨。","断肠院落，一帘风絮。"],"p":"瑞龙吟"},{"id":"S00242","t":"锁窗寒・琐寒窗","a":"周邦彦","c":["暗柳啼鸦，单衣伫立，小帘朱户。","桐花半亩，静锁一庭愁雨。","洒空阶，夜阑未休，故人剪烛西窗语。","似楚江暝宿，风灯零乱，少年羁旅。","迟暮。","嬉游处。","正店舍无烟，禁城百五。","旗亭唤酒，付与高阳俦侣。","想东园，桃李自春，小唇秀靥今在否。","到归时，定有残英，待客携尊俎。"],"p":"锁窗寒・琐寒窗"},{"id":"S00243","t":"风流子","a":"周邦彦","c":["新绿小池塘。","风帘动，碎影舞斜阳。","羡金屋去来，旧时巢燕，土花缭绕，前度莓墙。","绣阁凤帏深几许，曾听得理丝簧。","欲说又休，虑乖芳信，未歌先咽，愁近清觞。","遥知新妆了，开朱户，应自待月西厢。","最苦梦魂，今宵不到伊行。","问甚时说与，佳音密耗，寄将秦镜，偷换韩香。","天便教人，霎时厮见何妨。"],"p":"风流子"},{"id":"S00244","t":"渡江云","a":"周邦彦","c":["晴岚低楚甸，暖回雁翼，阵势起平沙。","骤惊春在眼，借问何时，委曲到山家。","涂香晕色，盛粉饰、争作妍华。","千万丝、陌头杨柳，渐渐可藏鸦。","堪嗟。","清江东注，画舸西流，指长安日下。","愁宴阑，风翻旗尾，潮溅乌纱。","今宵正对初弦月，傍水驿，深舣蒹葭。","沈恨处，时时自剔灯花。"],"p":"渡江云"},{"id":"S00245","t":"应天长","a":"周邦彦","c":["条风布暖，霏雾弄晴，池塘遍满春色。","正是夜堂无月，沈沈暗寒食。","梁间燕，前社客。","似笑我、闭门愁寂。","乱花过，隔院芸香，满地狼藉。","长记那回时，邂逅相逢，郊外驻油壁。","又见汉宫传烛，飞烟五候宅。","青青草，迷路陌。","强带酒，细寻前迹。","市桥远，柳下人家，犹自相识。"],"p":"应天长"},{"id":"S00246","t":"荔枝香近・荔枝香","a":"周邦彦","c":["照水残红零乱，风唤去。","尽日测测轻寒，帘底吹香雾。","黄昏客枕无憀，细响当窗雨。","看两两相依燕新乳。","楼下水，渐绿遍、行舟浦。","暮往朝来，心逐片帆轻举。","何日迎门，小槛朱笼报鹦鹉。","共剪西窗蜜炬。"],"p":"荔枝香近・荔枝香"},{"id":"S00247","t":"荔枝香近・荔枝香","a":"周邦彦","c":["夜来寒侵酒席，露微泫。","舄履初会，香泽方熏，无端暗雨催人，但怪灯偏帘卷。","回顾，始觉惊鸿去云远。","大都世间，最苦唯聚散。","到得春残，看即是、开离宴。","细思别后，柳眼花须更谁剪。","此怀何处消遣。"],"p":"荔枝香近・荔枝香"},{"id":"S00248","t":"还京乐","a":"周邦彦","c":["禁烟近，触处、浮香秀色相料理。","正泥花时候，奈何客里，光阴虚费。","望箭波无际。","迎风漾日黄云委。","任去远，中有万点，相思清泪。","到长淮底。","过当时楼下，殷勤为说，春来羁旅况味。","堪嗟误约乖期，向天涯、自看桃李。","想而今、应恨墨盈笺，愁妆照水。","怎得青鸾翼，飞归教见憔悴。"],"p":"还京乐"},{"id":"S00249","t":"扫地花・扫地游","a":"周邦彦","c":["晓阴翳日，正雾霭烟横，远迷平楚。","暗黄万缕。","听鸣禽按曲，小腰欲舞。","细绕回堤，驻马河桥避雨。","信流去。","想一叶怨题，今在何处。","春事能几许。","任占地持杯，扫花寻路。","泪珠溅俎。","叹将愁度日，病伤幽素。","恨入金徽，见说文君更苦。","黯凝伫。","掩重关、遍城锺鼓。"],"p":"扫地花・扫地游"},{"id":"S00250","t":"解连环","a":"周邦彦","c":["怨怀无托。","嗟情人断绝，信音辽邈。","信妙手、能解连环，似风散雨收，雾轻云薄。","燕子楼空，暗尘锁、一床弦索。","想移根换叶。","尽是旧时，手种红药。","汀洲渐生杜若。","料舟依岸曲，人在天角。","谩记得、当日音书，把闲语闲言，待总烧却。","水驿春回，望寄我、江南梅萼。","拚今生，对花对酒，为伊落泪。"],"p":"解连环"},{"id":"S00251","t":"玲珑四犯","a":"周邦彦","c":["秾李夭桃，是旧日潘郎，亲试春艳。","自别河阳，长负露房烟脸。","憔悴鬓点吴霜，念想梦魂飞乱。","叹画阑玉砌都换。","才始有缘重见。","夜深偷展香罗荐。","暗窗前、醉眠葱茜。","浮花浪蕊都相识，谁更曾抬眼。","休问旧色旧香，但认取、芳心一点。","又片时一阵，风雨恶，吹分散。"],"p":"玲珑四犯"},{"id":"S00252","t":"丹凤吟","a":"周邦彦","c":["迤逦春光无赖，翠藻翻池，黄蜂游阁。","朝来风暴，飞絮乱投帘幕。","生憎暮景，倚墙临岸，杏靥夭斜，榆钱轻薄。","昼永惟思傍枕，睡起无憀，残照犹在亭角。","况是别离气味，坐来但觉心绪恶。","痛引浇愁酒，奈愁浓如酒，无计消铄。","那堪昏暝，簌簌半檐花落。","弄粉调朱柔素手，问何时重握。","此时此意，长怕人道著。"],"p":"丹凤吟"},{"id":"S00253","t":"满江红","a":"周邦彦","c":["昼日移阴，揽衣起、春帷睡足。","临宝鉴，绿云撩乱，未忺妆束。","蝶粉蜂黄都褪了，枕痕一线红生肉。","背画栏、脉脉悄无言，寻棋局。","重会面，犹未卜。","无限事，萦心曲。","想秦筝依旧，尚鸣金屋。","芳草连天迷远望，宝香熏被成孤宿。","最苦是、蝴蝶满园飞，无人扑。"],"p":"满江红"},{"id":"S00254","t":"瑞鹤仙","a":"周邦彦","c":["悄郊原带郭。","行路永，客去车尘漠漠。","斜阳映山落。","敛馀红、犹恋孤城栏角。","凌波步弱。","过短亭、何用素约。","有流莺劝我，重解绣鞍，缓引春酌。","不记归时早暮，上马谁扶，醒眠朱阁。","惊飙动幕。","扶残醉，绕红药。","叹西园、已是花深无地，东风何事又恶。","任流光过却。","犹喜洞天自乐。"],"p":"瑞鹤仙"},{"id":"S00255","t":"西平乐","a":"周邦彦","c":["稚柳苏晴，故溪歇雨，川迥未觉春赊。","驼褐寒侵，正怜初日，轻阴抵死须遮。","叹事逐孤鸿尽去，身与塘蒲共晚，争知向此，征途迢递，伫立尘沙。","追念朱颜翠发，曾到处、故地使人嗟。","道连三楚，天低四野，乔木依前，临路敧斜。","重慕想，东陵晦迹，彭泽归来，左右琴书自乐，松菊相依，何况风流鬓未华。","多谢故人，亲驰郑驿，时倒融尊，劝此淹留，共过芳时，翻令倦客思家。"],"p":"西平乐"},{"id":"S00256","t":"浪涛沙・浪淘沙","a":"周邦彦","c":["昼阴重，霜凋岸草，雾隐城堞。","南陌脂车待发。","东门帐饮乍阕。","正拂面垂杨堪缆结。","掩红泪、玉手亲折。","念汉浦离鸿去何许，经时信音绝。","情切。","望中地远天阔。","向露冷风清，无人处、耿耿寒漏咽。","嗟万事难忘，唯是轻别。","翠尊未竭。","凭断云留取，西楼残月。","罗带光销纹衾叠。","连环解、旧香顿歇。","怨歌永、琼壶敲尽缺。","恨春去、不与人期，弄夜色，空馀满地梨花雪。"],"p":"浪涛沙・浪淘沙"},{"id":"S00257","t":"忆旧游","a":"周邦彦","c":["记愁横浅黛，泪洗红铅，门掩秋宵。","坠叶惊离思，听寒蜇夜泣，乱雨潇潇。","凤钗半脱云鬓，窗影烛光摇。","渐暗竹敲凉，疏荧照晚，两地魂销。","迢迢。","问音信，道径底花阴，时认鸣镳。","也拟临朱户，叹因郎憔悴，羞见郎招。","旧巢更有新燕，杨柳拂河桥。","但满目京尘，东风竟日吹露桃。"],"p":"忆旧游"},{"id":"S00258","t":"蓦山溪","a":"周邦彦","c":["湖平春水，菱荇萦船尾。","空翠入衣襟，拊轻桹、游鱼惊避。","晚来潮上，迤逦没沙痕，山四倚。","云渐起。","鸟度屏风里。","周郎逸兴，黄帽侵云水。","落日媚沧洲，泛一棹、夷犹未已。","玉箫金管，不共美人游，因个甚，烟雾底。","独爱莼羹美。"],"p":"蓦山溪"},{"id":"S00259","t":"少年游","a":"周邦彦","c":["南都石黛扫晴山。","衣薄耐朝寒。","一夕东风，海棠花谢，楼上卷帘看。","而今丽日明如洗，南陌暖雕鞍。","旧赏园林，喜无风雨，春鸟报平安。"],"p":"少年游"},{"id":"S00260","t":"少年游","a":"周邦彦","c":["朝云漠漠散轻丝。","楼阁淡春姿。","柳泣花啼，九街泥重，门外燕飞迟。","而今丽日明金屋，春色在桃枝。","不似当时，小桥冲雨，幽恨两人知。"],"p":"少年游"},{"id":"S00261","t":"秋蕊香","a":"周邦彦","c":["乳鸭池塘水暖。","风紧柳花迎面。","午妆粉指印窗眼。","曲里长眉翠浅。","问知社日停针线。","探新燕。","宝钗落枕春梦远。","帘影参差满院。"],"p":"秋蕊香"},{"id":"S00262","t":"渔家傲","a":"周邦彦","c":["灰暖香融销永昼。","蒲萄架上春藤秀。","曲角栏干群雀斗。","清明后。","风梳万缕亭前柳。","日照钗梁光欲溜。","循阶竹粉沾衣袖。","拂拂面红如著酒。","沈吟久。","昨宵正是来时候。"],"p":"渔家傲"},{"id":"S00263","t":"渔家傲","a":"周邦彦","c":["几日轻阴寒测测。","东风急处花成积。","醉踏阳春怀故国。","归未得。","黄鹂久住如相识。","赖有蛾眉能暖客。","长歌屡劝金杯侧。","歌罢月痕来照席。","贪欢适。","帘前重露成涓滴。"],"p":"渔家傲"},{"id":"S00264","t":"南乡子","a":"周邦彦","c":["晨色动妆楼。","短烛荧荧悄未收。","自在开帘风不定，飕飕。","池面冰澌趁水流。","早起怯梳头。","欲绾云鬟又却休。","不会沈吟思底事，凝眸。","两点春山满镜愁。"],"p":"南乡子"},{"id":"S00265","t":"望江南・忆江南","a":"周邦彦","c":["游妓散，独自绕回堤。","芳草怀烟迷水曲，密云衔雨暗城西。","九陌未沾泥。","桃李下，春晚未成蹊。","墙外见花寻路转，柳阴行马过莺啼。","无处不凄凄。"],"p":"望江南・忆江南"},{"id":"S00266","t":"浣溪沙","a":"周邦彦","c":["争挽桐花两鬓垂。","小妆弄影照清池。","出帘踏袜趁蜂儿。","跳脱添金双腕重，琵琶拨尽四弦悲。","夜寒谁肯剪春衣。"],"p":"浣溪沙"},{"id":"S00267","t":"浣溪沙","a":"周邦彦","c":["雨过残红湿未飞。","珠帘一行透斜晖。","游蜂酿蜜窃香归。","金屋无人风竹乱，衣篝尽日水沈微。","一春须有忆人时。"],"p":"浣溪沙"},{"id":"S00268","t":"浣溪沙","a":"周邦彦","c":["楼上晴天碧四垂。","楼前芳草接天涯。","劝君莫上最高梯。","新笋已成堂下竹，落花都上燕巢泥。","忍听林表杜鹃啼。"],"p":"浣溪沙"},{"id":"S00269","t":"迎春乐","a":"周邦彦","c":["清池小圃开云屋。","结春伴、往来熟。","忆年时，纵酒杯行速。","看月上、归禽宿。","墙里修篁森似束。","记名字、曾刊新绿。","见说别来长，沿翠藓、封寒玉。"],"p":"迎春乐"},{"id":"S00270","t":"迎春乐","a":"周邦彦","c":["桃蹊柳曲闲踪迹。","俱曾是、大堤客。","解春衣、贳酒城南陌。","频醉卧、胡姬侧。","鬓点吴霜嗟早白。","更谁念、玉溪消息。","他日水云身，相望处，无南北。"],"p":"迎春乐"},{"id":"S00271","t":"谒金门","a":"晏殊","c":["秋露坠。","滴尽楚兰红泪。","往事旧欢何限意。","思量如梦寐。","人貌老于前岁。","风月宛然无异。","座有嘉宾尊有桂。","莫辞终夕醉。"],"p":"谒金门"},{"id":"S00272","t":"破阵子","a":"晏殊","c":["海上蟠桃易熟，人间好月长圆。","惟有掰钗分钿侣，离别常多会面难。","此情须问天。","蜡烛到明垂泪，熏炉尽日生烟。","一点凄凉愁绝意，谩道秦筝有剩弦。","何曾为细传。"],"p":"破阵子"},{"id":"S00273","t":"破阵子","a":"晏殊","c":["燕子欲归时节，高楼昨夜西风。","求得人间成小会，试把金尊傍菊丛。","歌长粉面红。","斜日更穿帘幕，微凉渐入梧桐。","多少襟怀言不尽，写向蛮笺曲调中。","此情千万重。"],"p":"破阵子"},{"id":"S00274","t":"破阵子","a":"晏殊","c":["忆得去年今日，黄花已满东篱。","曾与玉人临小槛，共折香英泛酒卮。","长条插鬓垂。","人貌不应迁换，珍丛又睹芳菲。","重把一尊寻旧径，所惜光阴去似飞。","风飘露冷时。"],"p":"破阵子"},{"id":"S00275","t":"破阵子","a":"晏殊","c":["湖上西风斜日，荷花落尽红英。","金菊满丛珠颗细，海燕辞巢翅羽轻。","年年岁岁情。","美酒一杯新熟，高歌数阕堪听。","不向尊前同一醉，可奈光阴似水声。","迢迢去未停。"],"p":"破阵子"},{"id":"S00276","t":"浣溪沙","a":"晏殊","c":["阆苑瑶台风露秋。","整鬟凝思捧觥筹。","欲归临别强迟留。","月好谩成孤枕梦，酒阑空得两眉愁。","此时情绪悔风流。"],"p":"浣溪沙"},{"id":"S00277","t":"浣溪沙","a":"晏殊","c":["三月和风满上林。","牡丹妖艳直千金。","恼人天气又春阴。","为我转回红脸面，向谁分付紫檀心。","有情须𣨼酒杯深。"],"p":"浣溪沙"},{"id":"S00278","t":"浣溪沙","a":"晏殊","c":["青杏园林著酒香。","佳人初试薄罗裳。","柳丝无力燕飞忙。","乍雨乍晴花自落，闲愁闲闷日偏长。","为谁消瘦减容光。"],"p":"浣溪沙"},{"id":"S00279","t":"浣溪沙","a":"晏殊","c":["一曲新词酒一杯。","去年天气旧亭台。","夕阳西下几时回。","无可奈何花落去，似曾相识燕归来。","小园香径独徘徊。"],"p":"浣溪沙"},{"id":"S00280","t":"浣溪沙","a":"晏殊","c":["红蓼花香夹岸稠。","绿波春水向东流。","小船轻舫好追游。","渔父酒醒重拨棹，鸳鸯飞去却回头。","一杯销尽两眉愁。"],"p":"浣溪沙"},{"id":"S00281","t":"浣溪沙","a":"晏殊","c":["淡淡梳妆薄薄衣。","天仙模样好容仪。","旧欢前事入颦眉。","闲役梦魂孤烛暗，恨无消息画帘垂。","且留双泪说相思。"],"p":"浣溪沙"},{"id":"S00282","t":"浣溪沙","a":"晏殊","c":["小阁重帘有燕过。","晚花红片落庭莎。","曲阑干影入凉波。","一霎好风生翠幕，几回疏雨滴圆荷。","酒醒人散得愁多。"],"p":"浣溪沙"},{"id":"S00283","t":"浣溪沙","a":"晏殊","c":["宿酒才醒厌玉卮。","水沈香冷懒熏衣。","早梅先绽日边枝。","寒雪寂寥初散后，春风悠扬欲来时。","小屏闲放画帘垂。"],"p":"浣溪沙"},{"id":"S00284","t":"浣溪沙","a":"晏殊","c":["绿叶红花媚晓烟。","黄蜂金蕊欲披莲。","水风深处懒回船。","可惜异香珠箔外，不辞清唱玉尊前。","使星归觐九重天。"],"p":"浣溪沙"},{"id":"S00285","t":"浣溪沙","a":"晏殊","c":["湖上西风急暮蝉。","夜来清露湿红莲。","少留归骑促歌筵。","为别莫辞金盏酒，入朝须近玉炉烟。","不知重会是何年。"],"p":"浣溪沙"},{"id":"S00286","t":"浣溪沙","a":"晏殊","c":["杨柳阴中驻彩旌。","芰荷香里劝金觥。","小词流入管弦声。","只有醉饮宽别恨，不须朝暮促归程。","雨条烟叶系人情。"],"p":"浣溪沙"},{"id":"S00287","t":"浣溪沙","a":"晏殊","c":["一向年光有限身。","等闲离别易消魂。","酒筵歌席莫辞频。","满目山河空念远，落花风雨更伤春。","不如怜取眼前人。"],"p":"浣溪沙"},{"id":"S00288","t":"浣溪沙","a":"晏殊","c":["玉碗冰寒滴露华。","粉融香雪透轻纱。","晚来妆面胜荷花。","鬓亸欲迎眉际月，酒红初上脸边霞。","一场春梦日西斜。"],"p":"浣溪沙"},{"id":"S00289","t":"更漏子","a":"晏殊","c":["蕣华浓，山翠浅。","一寸秋波如剪。","红日永，绮筵开。","暗随仙驭来。","遏云声，回雪袖。","占断晓莺春柳。","才送目，又颦眉。","此情谁得知。"],"p":"更漏子"},{"id":"S00290","t":"更漏子","a":"晏殊","c":["塞鸿高，仙露满。","秋入银河清浅。","逢好客，且开眉。","盛年能几时。","宝筝调，罗袖软。","拍碎画堂檀板。","须尽醉，莫推辞。","人生多别离。"],"p":"更漏子"},{"id":"S00291","t":"更漏子","a":"晏殊","c":["雪藏梅，烟著柳。","依约上春时候。","初送雁，欲问莺。","绿池波浪生。","探花开，留客醉。","忆得去年情味。","金盏酒，玉炉香。","任他红日长。"],"p":"更漏子"},{"id":"S00292","t":"更漏子","a":"晏殊","c":["菊花残，梨叶堕。","可惜良辰虚过。","新酒熟，绮筵开。","不辞红玉杯。","蜀弦高，羌管脆。","慢飐舞娥香袂。","君莫笑，醉乡人。","熙熙长似春。"],"p":"更漏子"},{"id":"S00293","t":"鹊踏枝・蝶恋花","a":"晏殊","c":["槛菊愁烟兰泣露。","罗幕轻寒，燕子双飞去。","明月不谙离恨苦。","斜光到晓穿朱户。","昨夜西风凋碧树。","独上高楼，望尽天涯路。","欲寄彩笺兼尺素。","山长水阔知何处。"],"p":"鹊踏枝・蝶恋花"},{"id":"S00294","t":"鹊踏枝・蝶恋花","a":"晏殊","c":["紫府群仙名籍秘。","五色斑龙，暂降人间世。","海变桑田都不记。","蟠桃一熟三千岁。","露滴彩旌云绕袂。","谁信壶中，别有笙歌地。","门外落花随水逝。","相看莫惜尊前醉。"],"p":"鹊踏枝・蝶恋花"},{"id":"S00295","t":"点绛唇","a":"晏殊","c":["露下风高，井梧宫簟生秋意。","画堂筵启。","一曲呈珠缀。","天外行云，欲去凝香袂。","炉烟起。","断肠声里。","敛尽双蛾翠。"],"p":"点绛唇"},{"id":"S00296","t":"凤衔杯","a":"晏殊","c":["青苹昨夜秋风起。","无限个、露莲相倚。","独凭朱阑、愁望晴天际。","空目断、遥山翠。","彩笺长，锦书细。","谁信道、两情难寄。","可惜良辰好景、欢娱地。","只恁空憔悴。"],"p":"凤衔杯"},{"id":"S00297","t":"凤衔杯","a":"晏殊","c":["留花不住怨花飞。","向南园、情绪依依。","可惜倒红斜白、一枝枝。","经宿雨、又离披。","凭朱槛，把金卮。","对芳丛、惆怅多时。","何况旧欢新恨、阻心期。","空满眼、是相思。"],"p":"凤衔杯"},{"id":"S00298","t":"凤衔杯","a":"晏殊","c":["柳条花颣恼青春。","更那堪、飞絮纷纷。","一曲细丝清脆、倚朱唇。","斟绿酒、掩红巾。","追往事，惜芳辰。","暂时间、留住行云。","端的自家心下、眼中人。","到处里、觉尖新。"],"p":"凤衔杯"},{"id":"S00299","t":"清平乐","a":"晏殊","c":["春花秋草。","只是催人老。","总把千山眉黛扫。","未抵别愁多少。","劝君绿酒金杯。","莫嫌丝管声催。","兔走乌飞不住，人生几度三台。"],"p":"清平乐"},{"id":"S00300","t":"清平乐","a":"晏殊","c":["秋光向晚。","小阁初开宴。","林叶殷红犹未遍。","雨后青苔满院。","萧娘劝我金卮。","殷勤更唱新词。","暮去朝来节老，人生不饮何为。"],"p":"清平乐"},{"id":"S00301","t":"临江仙","a":"晏几道","c":["斗草阶前初见，穿针楼上曾逢。","罗裙香露玉钗风。","靓妆眉沁绿，羞脸粉生红。","流水便随春远，行云终与谁同。","酒醒长恨锦屏空。","相寻梦里路，飞雨落花中。"],"p":"临江仙"},{"id":"S00302","t":"临江仙","a":"晏几道","c":["身外闲愁空满，眼中欢事常稀。","明年应赋送君诗。","细从今夜数，相会几多时。","浅酒欲邀谁劝，深情惟有君知。","东溪春近好同归。","柳垂江上影，梅谢雪中枝。"],"p":"临江仙"},{"id":"S00303","t":"临江仙","a":"晏几道","c":["淡水三年欢意，危弦几夜离情。","晓霜红叶舞归程。","客情今古道，秋梦短长亭。","渌酒尊前清泪，阳关叠里离声。","少陵诗思旧才名。","云鸿相约处，烟雾九重城。"],"p":"临江仙"},{"id":"S00304","t":"临江仙","a":"晏几道","c":["浅浅馀寒春半，雪消蕙草初长。","烟迷柳岸旧池塘。","风吹梅蕊闹，雨细杏花香。","月堕枝头欢意，从前虚梦高唐，觉来何处放思量。","如今不是梦，真个到伊行。"],"p":"临江仙"},{"id":"S00305","t":"临江仙","a":"晏几道","c":["长爱碧阑干影，芙蓉秋水开时。","脸红凝露学娇啼。","霞觞熏冷艳，云髻袅纤枝。","烟雨依前时候，霜丛如旧芳菲。","与谁同醉采香归。","去年花下客，今似蝶分飞。"],"p":"临江仙"},{"id":"S00306","t":"临江仙","a":"晏几道","c":["旖旎仙花解语，轻盈春柳能眠。","玉楼深处绮窗前。","梦回芳草夜，歌罢落梅天。","沈水浓熏绣被，流霞浅酌金船。","绿娇红小正堪怜。","莫如云易散，须似月频圆。"],"p":"临江仙"},{"id":"S00307","t":"临江仙","a":"晏几道","c":["梦后楼台高锁，酒醒帘幕低垂。","去年春恨却来时。","落花人独立，微雨燕双飞。","记得小苹初见，两重心字罗衣。","琵琶弦上说相思。","当时明月在，曾照彩云归。"],"p":"临江仙"},{"id":"S00308","t":"临江仙","a":"晏几道","c":["东野亡来无丽句，于君去后少交亲。","追思往事好沾巾。","白头王建在，犹见咏诗人。","学道深山空自老，留名千载不干身。","酒筵歌席莫辞频。","争如南陌上，占取一年春。"],"p":"临江仙"},{"id":"S00309","t":"蝶恋花","a":"晏几道","c":["卷絮风头寒欲尽。","坠粉飘红，日日香成阵。","新酒又添残酒困。","今春不减前春恨。","蝶去莺飞无处问。","隔水高楼，望断双鱼信。","恼乱层波横一寸。","斜阳只与黄昏近。"],"p":"蝶恋花"},{"id":"S00310","t":"蝶恋花","a":"晏几道","c":["初拈霜纨生怅望。","隔叶莺声，似学秦娥唱。","午睡醒来慵一饷。","双纹翠簟铺寒浪。","雨罢苹风吹碧涨。","脉脉荷花，泪脸红相向。","斜贴绿云新月上。","弯环正是愁眉样。"],"p":"蝶恋花"},{"id":"S00311","t":"蝶恋花","a":"晏几道","c":["庭院碧苔红叶遍。","金菊开时，已近重阳宴。","日日露荷凋绿扇。","粉塘烟水澄如练。","试倚凉风醒酒面。","雁字来时，恰向层楼见。","几点护霜云影转。","谁家芦管吹秋怨。"],"p":"蝶恋花"},{"id":"S00312","t":"蝶恋花","a":"晏几道","c":["喜鹊桥成催凤驾。","天为欢迟，乞与初凉夜。","乞巧双蛾加意画。","玉钩斜傍西南挂。","分钿擘钗凉叶下。","香袖凭肩，谁记当时话。","路隔银河犹可借。","世间离恨何年罢。"],"p":"蝶恋花"},{"id":"S00313","t":"蝶恋花","a":"晏几道","c":["碧草池塘春又晚。","小叶风娇，尚学娥妆浅。","双燕来时还念远。","珠帘绣户杨花满。","绿柱频移弦易断。","细看秦筝，正似人情短。","一曲啼乌心绪乱。","红颜暗与流年换。"],"p":"蝶恋花"},{"id":"S00314","t":"蝶恋花","a":"晏几道","c":["碾玉钗头双凤小。","倒晕工夫，画得宫眉巧。","嫩曲罗裙胜碧草。","鸳鸯绣字春衫好。","三月露桃芳意早。","细看花枝，人面争多少。","水调声长歌未了。","掌中杯尽东池晓。"],"p":"蝶恋花"},{"id":"S00315","t":"蝶恋花","a":"晏几道","c":["醉别西楼醒不记。","春梦秋云，聚散真容易。","斜月半窗还少睡。","画屏闲展吴山翠。","衣上酒痕诗里字。","点点行行，总是凄凉意。","红烛自怜无好计。","夜寒空替人垂泪。"],"p":"蝶恋花"},{"id":"S00316","t":"蝶恋花","a":"晏几道","c":["欲减罗衣寒未去。","不卷珠帘，人在深深处。","残杏枝头花几许。","啼红正恨清明雨。","尽日沈香烟一缕。","宿酒醒迟，恼破春情绪。","远信还因归燕误。","小屏风上西江路。"],"p":"蝶恋花"},{"id":"S00317","t":"蝶恋花","a":"晏几道","c":["千叶早梅夸百媚。","笑面凌寒，内样妆先试。","月脸冰肌香细腻。","风流新称东君意。","一捻年光春有味。","江北江南，更有谁相比。","横玉声中吹满地。","好枝长恨无人寄。"],"p":"蝶恋花"},{"id":"S00318","t":"蝶恋花","a":"晏几道","c":["金翦刀头芳意动。","彩蕊开时，不怕朝寒重。","晴雪半消花䰒䰄。","晓妆呵尽香酥冻。","十二楼中双翠凤。","缥缈歌声，记得江南弄。","醉舞春风谁可共。","秦云已有鸳屏梦。"],"p":"蝶恋花"},{"id":"S00319","t":"蝶恋花","a":"晏几道","c":["笑艳秋莲生绿浦。","红脸青腰，旧识凌波女。","照影弄妆娇欲语。","西风岂是繁华主。","可恨良辰天不与。","才过斜阳，又是黄昏雨。","朝落暮开空自许。","竟无人解知心苦。"],"p":"蝶恋花"},{"id":"S00320","t":"蝶恋花","a":"晏几道","c":["碧落秋风吹玉树。","翠节红旌，晚过银河路。","休笑星机停弄杼。","凤帏已在云深处。","楼上金针穿绣缕。","谁管天边，隔岁分飞苦。","试等夜阑寻别绪。","泪痕千点罗衣露。"],"p":"蝶恋花"},{"id":"S00321","t":"蝶恋花","a":"晏几道","c":["碧玉高楼临水住。","红杏开时，花底曾相遇。","一曲阳春春已暮。","晓莺声断朝云去。","远水来从楼下路。","过尽流波，未得鱼中素。","月细风尖垂柳渡。","梦魂长在分襟处。"],"p":"蝶恋花"},{"id":"S00322","t":"蝶恋花","a":"晏几道","c":["梦入江南烟水路。","行尽江南，不与离人遇。","睡里消魂无说处。","觉来惆怅消魂误。","欲尽此情书尺素。","浮雁沈鱼，终了无凭据。","却倚缓弦歌别绪。","断肠移破秦筝柱。"],"p":"蝶恋花"},{"id":"S00323","t":"蝶恋花","a":"晏几道","c":["黄菊开时伤聚散。","曾记花前，共说深深愿。","重见金英人未见。","相思一夜天涯远。","罗带同心闲结遍。","带易成双，人恨成双晚。","欲写彩笺书别怨。","泪痕早已先书满。"],"p":"蝶恋花"},{"id":"S00324","t":"鹧鸪天","a":"晏几道","c":["彩袖殷勤捧玉锺。","当年拼却醉颜红。","舞低杨柳楼心月，歌尽桃花扇影风。","从别后，忆相逢。","几回魂梦与君同。","今宵剩把银釭照，犹恐相逢是梦中。"],"p":"鹧鸪天"},{"id":"S00325","t":"鹧鸪天","a":"晏几道","c":["一醉醒来春又残。","野棠梨雨泪阑干。","玉笙声里鸾空怨。","罗幕香中燕未还。","终易散，且长闲。","莫教离恨损朱颜。","谁堪共展鸳鸯锦，同过西楼此夜寒。"],"p":"鹧鸪天"},{"id":"S00326","t":"鹧鸪天","a":"晏几道","c":["梅蕊新妆桂叶眉。","小莲风韵出瑶池。","云随绿水歌声转，雪绕红绡舞袖垂。","伤别易，恨欢迟。","惜无红锦为裁诗。","行人莫便消魂去，汉渚星桥尚有期。"],"p":"鹧鸪天"},{"id":"S00327","t":"鹧鸪天","a":"晏几道","c":["守得莲开结伴游。","约开萍叶上兰舟。","来时浦口云随棹，采罢江边月满楼。","花不语，水空流。","年年拼得为花愁。","明朝万一西风动，争向朱颜不耐秋。"],"p":"鹧鸪天"},{"id":"S00328","t":"鹧鸪天","a":"晏几道","c":["斗鸭池南夜不归。","酒阑纨扇有新诗。","云随碧玉歌声转，雪绕红琼舞袖回。","今感旧，欲沾衣。","可怜人似水东西。","回头满眼凄凉事，秋月春风岂得知。"],"p":"鹧鸪天"},{"id":"S00329","t":"鹧鸪天","a":"晏几道","c":["当日佳期鹊误传。","至今犹作断肠仙。","桥成汉渚星波外，人在鸾歌凤舞前。","欢尽夜，别经年。","别多欢少奈何天。","情知此会无长计。","咫尺凉蟾亦未圆。"],"p":"鹧鸪天"},{"id":"S00330","t":"鹧鸪天","a":"晏几道","c":["题破香笺小砑红。","诗篇多寄旧相逢。","西楼酒面垂垂雪，南苑春衫细细风。","花不尽，柳无穷。","别来欢事少人同。","凭谁问取归云信，今在巫山第几峰。"],"p":"鹧鸪天"},{"id":"S00331","t":"醉垂鞭","a":"张先","c":["双蝶绣罗裙。","东池宴。","初相见。","朱粉不深匀。","闲花淡淡春。","细看诸处好。","人人道。","柳腰身。","昨日乱山昏。","来时衣上云。"],"p":"醉垂鞭"},{"id":"S00332","t":"醉垂鞭","a":"张先","c":["朱粉不须施。","花枝小。","春偏好。","娇妙近胜衣。","轻罗红雾垂。","琵琶金画凤。","双条重。","倦眉低。","啄木细声迟。","黄蜂花上飞。"],"p":"醉垂鞭"},{"id":"S00333","t":"南乡子","a":"张先","c":["何处可魂消。","京口终朝两信潮。","不管离心千叠恨，滔滔。","催促行人动去桡。","记得旧江皋。","绿杨轻絮几条条。","春水一篙残照阔，遥遥。","有个多情立画桥。"],"p":"南乡子"},{"id":"S00334","t":"南乡子","a":"张先","c":["潮上水清浑。","棹影轻于水底云。","去意徘徊无奈泪，衣巾。","犹有当时粉黛痕。","海近古城昏。","暮角寒沙雁队分。","今夜相思应看月，无人。","露冷依前独掩门。"],"p":"南乡子"},{"id":"S00335","t":"菩萨蛮","a":"张先","c":["忆郎还上层楼曲。","楼前芳草年年绿。","绿似去时袍。","回头风袖飘。","郎袍应已旧。","颜色非长久。","惜恐镜中春。","不如花草新。"],"p":"菩萨蛮"},{"id":"S00336","t":"菩萨蛮","a":"张先","c":["闻人语著仙卿字。","瞋情恨意还须喜。","何况草长时。","酒前频共伊。","娇香堆宝帐。","月到梨花上。","心事两人知。","掩灯罗幕垂。"],"p":"菩萨蛮"},{"id":"S00337","t":"菩萨蛮","a":"张先","c":["夜深不至春蟾见。","令人更更情飞乱。","翠幕动风亭。","时疑响屉声。","花香闻水榭。","几误飘衣麝。","不忍下朱扉。","绕廊重待伊。"],"p":"菩萨蛮"},{"id":"S00338","t":"菩萨蛮","a":"张先","c":["簟纹衫色娇黄浅。","钗头秋叶玲珑翦。","轻怯瘦腰身。","纱窗病起人。","相思魂欲绝。","莫话新秋别。","何处断离肠。","西风昨夜凉。"],"p":"菩萨蛮"},{"id":"S00339","t":"踏莎行","a":"张先","c":["衾凤犹温，笼鹦尚睡。","宿妆稀淡眉成字。","映花避月上行廊，珠裙折折轻垂地。","翠幕成波，新荷贴水。","纷纷烟柳低还起。","重墙绕院更重门，春风无路通深意。"],"p":"踏莎行"},{"id":"S00340","t":"踏莎行","a":"张先","c":["波湛横眸，霞分腻脸。","盈盈笑动笼香靥。","有情未结凤楼欢，无憀爱把歌眉敛。","密意欲传，娇羞未敢。","斜偎象板还偷盰。","轻轻试问借人么，佯佯不觑云鬟点。"],"p":"踏莎行"},{"id":"S00341","t":"感皇恩","a":"张先","c":["万乘靴袍御紫宸。","挥豪敷丽藻，尽经纶。","第名天陛首平津。","东堂桂，重占一枝春。","殊观耸簪绅。","蓬山仙话重，霈恩新。","暂时趋府冠谈宾。","十年外，身是凤池人。"],"p":"感皇恩"},{"id":"S00342","t":"西江月","a":"张先","c":["体态看来隐约，梳妆好是家常。","檀槽初抱更安详。","立向尊前一行。","小打登钩怕重，尽缠绣带由长。","娇春莺舌巧如簧。","飞在四条弦上。"],"p":"西江月"},{"id":"S00343","t":"庆金枝","a":"张先","c":["青螺添远山。","两娇靥、笑时圆。","抱云勾雪近灯看。","妍处不堪怜。","今生但愿无离别，花月下、绣屏前。","双蚕成茧共缠绵。","更结后生缘。"],"p":"庆金枝"},{"id":"S00344","t":"浣溪沙","a":"张先","c":["轻屉来时不破尘。","石榴花映石榴裙。","有情应得撞腮春。","夜短更难留远梦，日高何计学行云。","树深莺过静无人。"],"p":"浣溪沙"},{"id":"S00345","t":"相思儿令","a":"张先","c":["春去几时还。","问桃李无言。","燕子归栖风紧，梨雪乱西园。","犹有月婵娟。","似人人、难近如天。","愿教清影长相见，更乞取长圆。"],"p":"相思儿令"},{"id":"S00346","t":"师师令","a":"张先","c":["香钿宝珥。","拂菱花如水。","学妆皆道称时宜，粉色有、天然春意。","蜀彩衣长胜未起。","纵乱云垂地。","都城池苑夸桃李。","问东风何似。","不须回扇障清歌，唇一点、小于珠子。","正是残英和月坠。","寄此情千里。"],"p":"师师令"},{"id":"S00347","t":"山亭宴慢・山亭宴","a":"张先","c":["宴亭永昼喧箫鼓。","倚青空、画阑红柱。","玉莹紫微人，蔼和气、春融日煦。","故宫池馆更楼台，约风月、今宵何处。","湖水动鲜衣，竞拾翠、湖边路。","落花荡漾愁空树。","晓山静、数声杜宇。","天意送芳菲，正黯淡、疏烟逗雨。","新欢宁似旧欢长，此会散、几时还聚。","试为挹飞云，问解寄、相思否。"],"p":"山亭宴慢・山亭宴"},{"id":"S00348","t":"谢池春慢","a":"张先","c":["缭墙重院，时闻有、啼莺到。","绣被掩馀寒，画幕明新晓。","朱槛连空阔，飞絮无多少。","径莎平，池水渺。","日长风静，花影闲相照。","尘香拂马，逢谢女、城南道。","秀艳过施粉，多眉生轻笑。","斗色鲜衣薄，碾玉双蝉小。","欢难偶，春过了。","琵琶流怨，都入相思调。"],"p":"谢池春慢"},{"id":"S00349","t":"惜双双・惜分飞","a":"张先","c":["城上层楼天边路。","残照里、平芜绿树。","伤远更惜春暮。","有人还在高高处。","断梦归云经日去。","无计使、哀弦寄语。","相望恨不相遇。","倚桥临水谁家住。"],"p":"惜双双・惜分飞"},{"id":"S00350","t":"江南柳","a":"张先","c":["隋堤远，波急路尘轻。","今古柳桥多送别，见人分袂亦愁生。","何况自关情。","斜照后，新月上西城。","城上楼高重倚望，愿身能似月亭亭。","千里伴君行。"],"p":"江南柳"},{"id":"S00351","t":"八宝装・八宝妆","a":"张先","c":["锦屏罗幌初睡起。","花阴转、重门闭。","正不寒不暖，和风细雨，困人天气。","此时无限伤春意。","凭谁诉、厌厌地。","这浅情薄幸，千山万水，也须来里。"],"p":"八宝装・八宝妆"},{"id":"S00352","t":"一丛花令・一丛花","a":"张先","c":["伤高怀远几时穷。","无物似情浓。","离愁正引千丝乱，更东陌、飞絮蒙蒙。","嘶骑渐遥，征尘不断，何处认郎踪。","双鸳池沼水溶溶。","南北小桡通。","梯横画阁黄昏后，又还是、斜月帘栊。","沈恨细思，不如桃杏，犹解嫁东风。"],"p":"一丛花令・一丛花"},{"id":"S00353","t":"西江月","a":"张先","c":["泛泛春船载乐，溶溶湖水平桥。","高鬟照影翠烟摇。","白纻一声云杪。","倦醉天然玉软，弄妆人惜花娇。","风情遗恨几时消。","不见卢郎年少。"],"p":"西江月"},{"id":"S00354","t":"感皇恩","a":"张先","c":["廊庙当时共代工。","睢陵千里远，约过从。","欲知宾主与谁同。","宗枝内，黄阁旧，有三公。","广乐起云中。","湖山看画轴，两仙翁。","武林嘉语几时穷。","元丰际，德星聚，照江东。"],"p":"感皇恩"},{"id":"S00355","t":"宴春台慢・宴春台","a":"张先","c":["丽日千门，紫烟双阙，琼林又报春回。","殿阁风微，当时去燕还来。","五侯池馆频开。","探芳菲、走马天街。","重帘人语，辚辚绣轩，远近轻雷。","雕觞霞滟，翠幕云飞，楚腰舞柳，宫面妆梅。","金猊夜暖、罗衣暗裛香煤。","洞府人归，放笙歌、灯火楼台。","下蓬莱。","犹有花上月，清影徘徊。"],"p":"宴春台慢・宴春台"},{"id":"S00356","t":"好事近","a":"张先","c":["月色透横枝，短叶小花无力。","北客一声长笛，怨江南先得。","谁教强半腊前开，多情为春忆。","留取大家沈醉，正雨休风息。"],"p":"好事近"},{"id":"S00357","t":"好事近","a":"张先","c":["灯烛上山堂，香雾暖生寒夕。","前夜雪清梅瘦，已不禁轻摘。","双歌声断宝杯空，妆光艳瑶席。","相趁笑声归去，有随人月色。"],"p":"好事近"},{"id":"S00358","t":"清平乐","a":"张先","c":["屏山斜展。","帐卷红绡半。","泥浅曲池飞海燕。","风度杨花满院。","云情雨意空深。","觉来一枕春阴。","陇上梅花落尽，江南消息沈沈。"],"p":"清平乐"},{"id":"S00359","t":"清平乐","a":"张先","c":["清歌逐酒。","腻脸生红透。","樱小杏青寒食后。","衣换缕金轻绣。","画堂新月朱扉。","严城夜鼓声迟。","细看玉人娇面，春光不在花枝。"],"p":"清平乐"},{"id":"S00360","t":"醉桃源・阮郎归","a":"张先","c":["落花浮水树临池。","年前心眼期。","见来无事去还思。","如今花又飞。","浅螺黛，淡胭脂。","开花取次宜。","隔帘灯影闭门时。","此情风月知。"],"p":"醉桃源・阮郎归"},{"id":"S00361","t":"调啸・调笑令","a":"苏辙","c":["渔父。","渔父。","水上微风细雨。","青蓑黄箬裳衣。","红酒白鱼暮归。","暮归、暮归、归暮。","长笛一声何处。"],"p":"调啸・调笑令"},{"id":"S00362","t":"调啸・调笑令","a":"苏辙","c":["归雁。","归雁。","饮啄江南南岸。","将飞却下盘桓。","塞北春来苦寒。","苦寒。","苦寒。","寒苦。","藻荇欲生且住。"],"p":"调啸・调笑令"},{"id":"S00363","t":"水调歌头","a":"苏辙","c":["离别一何久，七度过中秋。","去年东武今夕，明月不胜愁。","岂意彭城山下，同泛清河古汴，船上载凉州。","鼓吹助清赏，鸿雁起汀洲。","坐中客，翠羽帔，紫绮裘。","素娥无赖，西去曾不为人留。","今夜清尊对客，明夜孤帆水驿，依旧照离忧。","但恐同王粲，相对永登楼。"],"p":"水调歌头"},{"id":"S00364","t":"渔家傲","a":"苏辙","c":["七十馀年真一梦。","朝来寿斝儿孙奉。","忧患已空无复痛。","心不动。","此间自有千钧重。","早岁文章供世用。","中年禅味疑天纵。","石塔成时无一缝。","谁与共。","人间天上随他送。"],"p":"渔家傲"},{"id":"S00365","t":"苏幕遮","a":"范仲淹","c":["碧云天，黄叶地。","秋色连波，波上寒烟翠。","山映斜阳天接水。","芳草无情，更在斜阳外。","黯乡魂，追旅思。","夜夜除非，好梦留人睡。","明月楼高休独倚。","酒入愁肠，化作相思泪。"],"p":"苏幕遮"},{"id":"S00366","t":"渔家傲","a":"范仲淹","c":["塞下秋来风景异。","衡阳雁去无留意。","四面边声连角起。","千嶂里。","长烟落日孤城闭。","浊酒一杯家万里。","燕然未勒归无计。","羌管悠悠霜满地。","人不寐。","将军白发征夫泪。"],"p":"渔家傲"},{"id":"S00367","t":"御街行","a":"范仲淹","c":["纷纷堕叶飘香砌。","夜寂静、寒声碎。","真珠帘卷玉楼空，天淡银河垂地。","年年今夜，月华如练，长是人千里。","愁肠已断无由醉。","酒未到、先成泪。","残灯明灭枕头欹。","谙尽孤眠滋味。","都来此事，眉间心上，无计相回避。"],"p":"御街行"},{"id":"S00368","t":"剔银灯","a":"范仲淹","c":["昨夜因看蜀志。","笑曹操、孙权、刘备。","用尽机关，徒劳心力，只得三分天地。","屈指细寻思，争如共、刘伶一醉。","人世都无百岁。","少痴呆、老成尩悴。","只有中间，些子少年，忍把浮名牵系。","一品与千金，问白发、如何回避。"],"p":"剔银灯"},{"id":"S00369","t":"定风波","a":"范仲淹","c":["罗绮满城春欲暮。","百花洲上寻芳去。","浦映□花花映浦。","无尽处。","恍然身入桃源路。","莫怪山翁聊逸豫。","功名得丧归时数。","莺解新声蝶解舞。","天赋与。","争教我辈无欢绪。"],"p":"定风波"},{"id":"S00370","t":"减字浣溪沙・浣溪沙","a":"贺铸","c":["浮动花钗影鬓烟。","浅妆浓笑有馀妍。","酒醺檀点语凭肩。","留不住时分钿镜，旧曾行处失金莲。","碧云芳草恨年年。"],"p":"减字浣溪沙・浣溪沙"},{"id":"S00371","t":"减字浣溪沙・浣溪沙","a":"贺铸","c":["两点春山一寸波。","当筵娇甚不成歌。","动人情态可须多。","金井露寒风下叶，画桥云断月侵河。","厌厌此夜奈愁何。"],"p":"减字浣溪沙・浣溪沙"},{"id":"S00372","t":"减字浣溪沙・浣溪沙","a":"贺铸","c":["清浅陂塘藕叶干。","细风蔬雨鹭鸶寒。","半垂帘幕倚阑干。","惆怅窃香人不见，几回憔悴后庭兰。","行云可是渡江难。"],"p":"减字浣溪沙・浣溪沙"},{"id":"S00373","t":"减字浣溪沙・浣溪沙","a":"贺铸","c":["楼角初销一缕霞。","淡黄杨柳暗栖鸦。","玉人和月摘梅花。","笑拈粉香归洞户，更垂帘幕护窗纱。","东风寒似夜来些。"],"p":"减字浣溪沙・浣溪沙"},{"id":"S00374","t":"相思引","a":"贺铸","c":["团扇单衣杨柳陌。","花似春风□无迹。","赖白玉香奁供汾泽。","借秀色。","添春色。","借秀色。","添春色。","云幕华灯张绮席。","半醉客。","留醒客。","半醉客。","留醒客。","渐促膝倾鬟琴差拍。","问此夕。","知何夕。","问此夕。","知何夕。"],"p":"相思引"},{"id":"S00375","t":"天门谣","a":"贺铸","c":["牛渚天门险。","限南北、七雄豪占。","清雾敛。","与闲人登览。","待月上潮平波滟滟。","塞管轻吹新《阿滥》。","风满槛。","历历数、西州更点。"],"p":"天门谣"},{"id":"S00376","t":"献金杯・厌金杯","a":"贺铸","c":["风软香迟，花深漏短。","可怜宵、画堂春半。","碧纱窗影，卷帐蜡灯红，鸳枕畔。","密写乌丝一段。","采苹溪晚。","拾翠沙空，尽愁倚、梦云飞观。","木兰艇子，几日渡江来，心目断。","桃叶青山隔岸。"],"p":"献金杯・厌金杯"},{"id":"S00377","t":"清平乐","a":"贺铸","c":["阴晴未定。","薄日烘云影。","临水朱门花一径。","尽日鸟啼人静。","厌厌几许春情。","可怜老去兰成。","看取镊残双鬓，不随芳草重生。"],"p":"清平乐"},{"id":"S00378","t":"清平乐","a":"贺铸","c":["小桃初谢。","双燕还来也。","记得年时寒食下。","紫陌青门游冶。","楚城满目春华。","可堪游子思家。","惟有夜来归梦，不知身在天涯。"],"p":"清平乐"},{"id":"S00379","t":"摊破浣溪沙・山花子","a":"贺铸","c":["湖上秋深藕叶黄。","清霜销瘦损垂杨。","洲嘴嫩沙斜照暖，睡鸳鸯。","红粉莲娃何处在，西风不为管馀香。","今夜月明闻水调，断人肠。"],"p":"摊破浣溪沙・山花子"},{"id":"S00380","t":"摊破浣溪沙・山花子","a":"贺铸","c":["双凤箫声隔彩霞。","朱门深闭七香车。","何处探春寻旧约，谢娘家。","旖旎细风飘水麝，玲珑残雪浸山茶。","饮罢西厢帘影外，玉蟾斜。"],"p":"摊破浣溪沙・山花子"},{"id":"S00381","t":"惜双双・惜分飞","a":"贺铸","c":["皎镜平湖三十里。","碧玉山围四际。","莲荡香风里。","彩鸳鸯觉双飞起。","明月多情随舵尾。","偏照空床翠被。","回首笙歌地。","醉更衣处长相记。"],"p":"惜双双・惜分飞"},{"id":"S00382","t":"思越人・朝天子","a":"贺铸","c":["紫府东风放夜时。","步莲秾李伴人归。","五更钟动笙歌散，十里月明灯火稀。","香苒苒，梦依依。","天涯寒尽减春衣。","凤凰城阕知何处，寥落星河一雁飞。"],"p":"思越人・朝天子"},{"id":"S00383","t":"思越人・朝天子","a":"贺铸","c":["怊怅离亭断采襟。","碧云明月两关心。","几行书尾情何限，一尺裙腰瘦不禁。","遥夜半，曲房深。","有时昵语话如今。","侵窗冷雨灯生晕，泪湿罗笺楚调吟。"],"p":"思越人・朝天子"},{"id":"S00384","t":"鹤冲天","a":"贺铸","c":["冬冬鼓动，花外沈残漏。","华月万枝灯，还清昼。","广陌衣香度，飞盖影、相先后。","个处频回首。","锦房西去，期约武陵西口。","当时早恨欢难偶。","可堪流浪远，分携久。","小畹兰英在，轻付与、何人手。","不似长亭柳。","舞枫眠雨，伴我一春销瘦。"],"p":"鹤冲天"},{"id":"S00385","t":"小重山","a":"贺铸","c":["飘径梅英雪未融。","芳菲消息到，杏梢红。","隔年欢事水西东。","凝思久，不语坐书空。","回想夹城中。","采山箫鼓沸，绮罗丛。","钿轮珠网玉花骢。","香陌上，谁与斗春风。"],"p":"小重山"},{"id":"S00386","t":"六州歌头","a":"贺铸","c":["少年侠气，交结五都雄。","肝胆洞。","毛发耸。","立谈中。","死生同。","一诺千金重。","推翘勇。","衿豪踪。","轻盖拥。","聊飞鞚。","斗城东。","轰饮酒炉，春色浮寒瓮。","吸海垂虹。","闲呼鹰嗾犬，白羽摘雕弓。","狡穴俄空。","乐匆匆。","似黄粱梦。","辞丹凤。","明月共。","漾孤篷。","官冗从。","怀倥偬。","落尘笼。","薄书从。","鹖弁如云众。","共粗用。","忽奇功。","笳鼓动。","渔阳弄。","思悲翁。","不请长缨，系取天娇种。","剑吼西风。","恨登山临水，手寄七弦桐。","目送归鸿。"],"p":"六州歌头"},{"id":"S00387","t":"浣溪沙","a":"贺铸","c":["翠縠参差拂水风。","暖云如絮扑低空。","丽人波脸觉春融。","缨挂宝钗初促席，檀高微注玉杯红。","芳醪何似此情浓。"],"p":"浣溪沙"},{"id":"S00388","t":"浣溪沙","a":"贺铸","c":["云母窗前歇绣针。","低鬟凝思坐调琴。","玉纤纤按十三金。","归卧文园犹带酒，柳花飞度画堂阴。","只凭双燕话春心。"],"p":"浣溪沙"},{"id":"S00389","t":"浣溪沙","a":"贺铸","c":["叠鼓新歌百样娇。","铜丸玉腕促云谣。","揭帘飞瓦雹声焦。","九渠池边杨柳陌，香轮轧轧马箫箫。","细风妆面酒痕销。"],"p":"浣溪沙"},{"id":"S00390","t":"江城子","a":"贺铸","c":["麝熏微度绣芙蓉。","翠衾重。","画堂空。","前夜偷期，相见却匆匆。","心事两知何处问，依约是，梦中逢。","坐疑行听竹窗风。","出帘栊。","杳无踪。","已过黄昏，缠动寺楼钟。","暮雨不来春又去，花满地，月朦胧。"],"p":"江城子"},{"id":"S00391","t":"浪淘沙","a":"贺铸","c":["一叶忽惊秋。","分付东流。","殷勤为过白苹洲。","洲上小楼帘半卷，应认归舟。","回首恋朋游。","迹去心留。","歌尘萧散梦云收。","惟有尊前曾见月，相伴人愁。"],"p":"浪淘沙"},{"id":"S00392","t":"木兰花・玉楼春","a":"贺铸","c":["佩环声认腰肢软。","风里麝熏知近远。","此身常羡玉妆台，得见晓来梳画面。","回廊几步通深院。","一桁绣衣帘不卷。","酒阑歌罢欲黄昏，肠断归巢双燕燕。"],"p":"木兰花・玉楼春"},{"id":"S00393","t":"木兰花・玉楼春","a":"贺铸","c":["银黄雁柱香檀拨。","镂板三声催细抹。","舞腰轻怯绛裙长，羞按筑球花十八。","东城柳岸匆匆发。","画舫一篙烟水阔。","可怜单枕欲眠时，还见尊前前夜月。"],"p":"木兰花・玉楼春"},{"id":"S00394","t":"蝶恋花","a":"贺铸","c":["小院朱扉开一扇。","内样新妆，镜里分明见。","眉晕半深唇注浅。","朵云冠子偏宜面。","被掩芙蓉熏麝煎。","帘影沈沈，祗有双飞燕。","心事向人犹腼腆。","强来窗下寻针线。"],"p":"蝶恋花"},{"id":"S00395","t":"石州引・石州慢","a":"贺铸","c":["薄雨初寒，斜照弄晴，春意空阔。","长亭柳色缠黄，远客一枝先折。","烟横水际，映带几点归鸦，东风销尽龙沙雪。","还记初关来，恰而今时节。","将发。","画楼芳酒，红泪清歌，顿成清别。","已是经年，杳杳音尘多绝。","欲知方寸，共有几许清愁，芭蕉不展丁香结。","枉望断天涯，两厌厌风月。"],"p":"石州引・石州慢"},{"id":"S00396","t":"失调名","a":"贺铸","c":["罗帷映月，玉研生冰。"],"p":"失调名"},{"id":"S00397","t":"失调名","a":"贺铸","c":["风头梦、吹无迹。"],"p":"失调名"},{"id":"S00398","t":"减字木兰花","a":"贺铸","c":["簪花照镜。","客鬓萧萧都不整。","拟倩东□。","化作尊前如梦云。","风香月影。","信是瑶台清夜永。","深闭重门。","牵绊刘郎别后魂。"],"p":"减字木兰花"},{"id":"S00399","t":"凤栖梧・蝶恋花","a":"贺铸","c":["为问宛溪桥畔柳。","拂水倡条，几赠行人手。","一样叶眉偏解皱。","白绵飞尽因谁瘦。","今日离亭还对酒。","唱断青青，好去休回首。","美阴向人疏似旧。","何须更待秋风后。"],"p":"凤栖梧・蝶恋花"},{"id":"S00400","t":"小重山令・小重山","a":"姜夔","c":["人绕湘皋月坠时。","斜横花树小，浸愁漪。","一春幽事有谁知。","东风冷、香远茜裙归。","鸥去昔游非。","遥怜花可可，梦依依。","九疑云杳断魂啼。","相思血，都沁绿筠枝。"],"p":"小重山令・小重山"},{"id":"S00401","t":"江梅引・江城梅花引","a":"姜夔","c":["人间离别易多时。","见梅枝。","忽相思。","几度小窗，幽梦手同携。","今夜梦中无觅处，漫徘徊。","寒侵被、尚未知。","湿红恨墨浅封题。","宝筝空、无雁飞。","俊游巷陌，算空有、古木斜晖。","旧约扁舟，心事已成非。","歌罢淮南春草赋，又萋萋。","漂零客、泪满衣。"],"p":"江梅引・江城梅花引"},{"id":"S00402","t":"蓦山溪","a":"姜夔","c":["与鸥为客。","绿野留吟屐。","雨行柳垂阴，是当日、仙翁手植。","一亭寂寞。","烟外带愁横，荷苒苒，展凉云，横卧虹千尺。","才因老尽，秀句君休觅。","万绿正迷人，更愁入、山阳夜笛。","百年心事，惟有玉阑知，吟未了，放船回，月下空相忆。"],"p":"蓦山溪"},{"id":"S00403","t":"莺声绕红楼","a":"姜夔","c":["十亩梅花作雪飞。","冷香下、携手多时。","两年不到断桥西。","长笛为予吹。","人妒垂杨绿，春风为、染作仙衣。","垂杨却又妒腰枝。","近前舞丝丝。"],"p":"莺声绕红楼"},{"id":"S00404","t":"鬲溪梅令","a":"姜夔","c":["好花不与𣨼香人。","浪粼粼。","又恐春风归去绿成阴。","玉钿何处寻。","木兰双桨梦中云。","小横陈。","漫向孤山山下觅盈盈。","翠禽啼一春。"],"p":"鬲溪梅令"},{"id":"S00405","t":"阮郎归","a":"姜夔","c":["红云低压碧玻璃。","惺惚花上啼。","静看楼角拂长枝。","朝寒吹翠眉。","休涉笔，且裁诗。","年年风絮时。","绣衣夜半草符移。","月中双桨归。"],"p":"阮郎归"},{"id":"S00406","t":"阮郎归","a":"姜夔","c":["旌阳宫殿昔徘徊。","一坛云叶垂。","与君闲看壁间题。","夜凉笙鹤期。","茅店酒，寿君时。","老枫临路歧。","年年强健得追随。","名山游遍归。"],"p":"阮郎归"},{"id":"S00407","t":"好事近","a":"姜夔","c":["凉夜摘花钿，苒苒动摇云绿。","金络一团香露，正纱厨人独。","朝来碧缕放长穿，钗头挂层玉。","记得如今时候，正荔枝初熟。"],"p":"好事近"},{"id":"S00408","t":"点绛唇","a":"姜夔","c":["燕雁无心，太湖西畔随云去。","数峰清苦。","商略黄昏雨。","第四桥边，拟共天随住。","今何许。","凭栏怀古。","残柳参差舞。"],"p":"点绛唇"},{"id":"S00409","t":"点绛唇","a":"姜夔","c":["金谷人归，绿扬低扫吹笙道。","数声啼鸟。","也学相思调。","月落潮生，掇送刘郎老。","淮南好。","甚时重到。","陌上生春草。"],"p":"点绛唇"},{"id":"S00410","t":"虞美人","a":"姜夔","c":["西园曾为梅花醉。","叶翦春云细。","玉笙凉夜隔帘吹。","卧看花梢摇动、一枝枝。","娉娉袅袅教谁惜。","空压纱巾侧。","沈香亭北又青苔。","唯有当时蝴蝶、自飞来。"],"p":"虞美人"},{"id":"S00411","t":"虞美人","a":"姜夔","c":["摩挲紫盖峰头石。","上瞰苍崖立。","玉盘摇动半崖花。","花树扶蔬、一半白云遮。","盈盈相望无由摘。","惆怅归来屐。","而今仙迹杳难寻。","那日青楼、曾见似花人。"],"p":"虞美人"},{"id":"S00412","t":"忆王孙","a":"姜夔","c":["冷红叶叶下塘秋。","长与行云共一舟。","零落江南不自由。","两绸缪。","料得吟鸾夜夜愁。"],"p":"忆王孙"},{"id":"S00413","t":"少年游","a":"姜夔","c":["双螺未合，双蛾先敛，家在碧云西。","别母情怀，随郎滋味，桃叶渡江时。","扁舟载了，匆匆归去，今夜泊前溪。","杨柳津头，梨花墙外，心事两人知。"],"p":"少年游"},{"id":"S00414","t":"鹧鸪天","a":"姜夔","c":["京洛风流绝代人。","因何风絮落溪津。","笼鞋浅出鸦头袜，知是凌波漂渺身。","红乍笑，绿长嚬。","与谁同度可怜春。","鸳鸯独宿何曾惯，化作西楼一缕云。"],"p":"鹧鸪天"},{"id":"S00415","t":"鹧鸪天","a":"姜夔","c":["曾共君侯历聘来。","去年今日踏莓苔。","旌扬宅里疏疏磬。","挂𪨗枫前草草杯。","呼煮酒，摘青梅。","今年官事莫徘徊。","移家径入蓝田县，急急船头打鼓催。"],"p":"鹧鸪天"},{"id":"S00416","t":"鹧鸪天","a":"姜夔","c":["柏绿椒红事事新。","隔篱灯影贺年人。","三茅钟动西窗晓，诗鬓无端又一春。","慵对客，缓开门。","梅花闲伴老来身。","娇儿学作人间字，郁垒神荼写未真。"],"p":"鹧鸪天"},{"id":"S00417","t":"鹧鸪天","a":"姜夔","c":["巷陌风光纵赏时。","笼纱未出马先嘶。","白头居士无呵殿，只有乘肩小女随。","花满市，月侵衣。","少年情事老来悲。","沙河塘上春寒浅，看了游人缓缓归。"],"p":"鹧鸪天"},{"id":"S00418","t":"鹧鸪天","a":"姜夔","c":["忆昨天街预赏时。","柳悭梅小未教知。","而今正是欢游夕，却怕春寒自掩扉。","帘寂寂，月低低。","旧情惟有绛都词。","芙蓉影暗三更后，卧听邻娃笑语归。"],"p":"鹧鸪天"},{"id":"S00419","t":"鹧鸪天","a":"姜夔","c":["肥水东流无尽期。","当初不合种相思。","梦中未比丹青见，暗里忽惊山鸟啼。","春未绿，鬓先丝。","人间别久不成悲。","谁教岁岁红莲夜，两处沈吟各自知。"],"p":"鹧鸪天"},{"id":"S00420","t":"鹧鸪天","a":"姜夔","c":["辇路珠帘两行垂。","千枝银烛舞僛僛。","东风历历红楼下，谁识三生杜牧之。","欢正好，夜何其。","明朝春过小桃枝。","鼓声渐远游人散，惆怅归来有月知。"],"p":"鹧鸪天"},{"id":"S00421","t":"夜行船","a":"姜夔","c":["略彴横溪人不度。","听流澌、佩环无数。","屋角垂枝，船头生影，算唯有、春知处。","回首江南天欲暮。","折寒香、倩谁传语。","玉笛无声，诗人有句，花休道、轻分付。"],"p":"夜行船"},{"id":"S00422","t":"杏花天","a":"姜夔","c":["绿丝低拂鸳鸯浦。","想桃叶、当时唤渡。","又将愁眼与春风，待去。","倚兰桡、更少驻。","金陵路。","莺吟燕舞。","算潮水、知人最苦。","满汀芳草不成归，日暮。","更移舟、向甚处。"],"p":"杏花天"},{"id":"S00423","t":"醉吟商小品・小品","a":"姜夔","c":["又正是春归，细柳暗黄千缕。","暮鸦啼处。","梦逐金鞍去。","一点芳心休诉。","琵琶解语。"],"p":"醉吟商小品・小品"},{"id":"S00424","t":"玉梅令","a":"姜夔","c":["疏疏雪片。","散入溪南苑。","春寒锁、旧家亭馆。","有玉梅几树，背立怨东风，高花未吐，暗香已远。","公来领略，梅花能劝。","花长好、愿公更健。","便揉春为酒，翦雪作新诗，拚一日、绕花千转。"],"p":"玉梅令"},{"id":"S00425","t":"踏莎行","a":"姜夔","c":["燕燕轻盈，莺莺娇软。","分明又向华胥见。","夜长争得薄情知，春初早被相思染。","别后书辞，别时针线。","离魂暗逐郎行远。","淮南皓月冷千山，冥冥归去无人管。"],"p":"踏莎行"},{"id":"S00426","t":"诉衷情","a":"姜夔","c":["石榴一树浸溪红。","零落小桥东。","五日凄凉心事，山雨打船篷。","谙世味，楚人弓。","莫忡忡。","白头行客，不采苹花，孤负薰风。"],"p":"诉衷情"},{"id":"S00427","t":"浣溪沙","a":"姜夔","c":["著酒行行满袂风。","草枯霜鹘落晴空。","销魂都在夕阳中。","恨入四弦人欲老，梦寻千驿意难通。","当时何似莫匆匆。"],"p":"浣溪沙"},{"id":"S00428","t":"浣溪沙","a":"姜夔","c":["春点疏梅雨后枝。","翦灯心事峭寒时。","市桥携手步迟迟。","蜜炬来时人更好，玉笙吹彻夜何其。","东风落靥不成归。"],"p":"浣溪沙"},{"id":"S00429","t":"浣溪沙","a":"姜夔","c":["钗燕笼云晚不忺。","拟将裙带系郎船。","别离滋味又今年。","杨柳夜寒犹自舞，鸳鸯风急不成眠。","些儿闲事莫萦牵。"],"p":"浣溪沙"},{"id":"S00430","t":"倒犯","a":"吴文英","c":["茂苑、共莺花醉吟，岁华如许。","江湖夜雨。","传书问、雁多幽阻。","清溪上，惯来往扁舟、轻如羽。","到兴懒归来，玉冷耕云圃。","按琼箫，赋金缕。","回首词场，动地声名，春雷初启户。","枕水卧漱石，数间屋，梅一坞。","待共结、良朋侣。","载清尊、随花追野步。","要未若城南，分取溪隈住。","昼长看柳舞。"],"p":"倒犯"},{"id":"S00431","t":"花犯","a":"吴文英","c":["翦横枝，清溪分影，修然空镜晓。","小窗春到。","怜夜冷孀娥，相伴孤照。","古苔泪锁霜千点，苍华人共老。","料浅雪、黄昏驿路，飞香遗冻草。","行云梦中认琼娘，冰肌瘦，窈窕风前纤缟。","残醉醒，屏山外、翠禽声小。","寒泉贮、绀壶渐暖，年事对、青灯惊换了。","但恐舞、一帘胡蝶，玉龙吹又杳。"],"p":"花犯"},{"id":"S00432","t":"花犯","a":"吴文英","c":["小娉婷，清铅素靥，蜂黄暗偷晕。","翠翘敧鬓。","昨夜冷中庭，月下相认。","睡浓更苦凄风紧。","惊回心未稳。","送晓色、一壶葱蒨，才知花梦准。","湘娥化作此幽芳，凌波路，古岸云沙遗恨。","临砌影，寒香乱、冻梅藏韵。","熏炉畔、旋移傍枕，还又见、玉人垂绀鬒。","料唤赏、清华池馆，台杯须满引。"],"p":"花犯"},{"id":"S00433","t":"蝶恋花","a":"吴文英","c":["北斗秋横云髻影。","莺羽衣轻，腰减青丝剩。","一曲游仙闻玉磬。","月华深院人初定。","十二阑干和笑凭。","风露生寒，人在莲花顶。","睡重不知残酒醒。","红帘几度啼鸦暝。"],"p":"蝶恋花"},{"id":"S00434","t":"蝶恋花","a":"吴文英","c":["明月枝头香满路。","几日西风，落尽花如雨。","倒照秦眉天镜古。","秋明白鹭双飞处。","自摘霜葱宜荐俎。","可惜重阳，不把黄花与。","帽堕笑凭纤手取。","清歌莫送秋声去。"],"p":"蝶恋花"},{"id":"S00435","t":"浣溪沙","a":"吴文英","c":["新梦游仙驾紫鸿。","数家灯火灞桥东。","吹箫楼外冻云重。","石瘦溪根船宿处，月斜梅影晓寒中。","玉人无力倚东风。"],"p":"浣溪沙"},{"id":"S00436","t":"浣溪沙","a":"吴文英","c":["冰骨清寒瘦一枝。","玉人初上木兰时。","懒妆斜立澹春姿。","月落溪穷清影在，日长春去画帘垂。","五湖水色掩西施。"],"p":"浣溪沙"},{"id":"S00437","t":"浣溪沙","a":"吴文英","c":["千盖笼花斗胜春。","东风无力扫香尘。","尽沿高阁步红云。","闲里暗牵经岁恨，街头多认旧年人。","晚钟催散又黄昏。"],"p":"浣溪沙"},{"id":"S00438","t":"浣溪沙","a":"吴文英","c":["蝶粉蜂黄大小乔。","中庭寒尽雪微销。","一般清瘦各无聊。","窗下和香封远讯，墙头飞玉怨邻箫。","夜来风雨洗春娇。"],"p":"浣溪沙"},{"id":"S00439","t":"浣溪沙","a":"吴文英","c":["门隔花深梦旧游。","夕阳无语燕归愁。","玉纤香动小帘钩。","落絮无声春堕泪，行云有影月含羞。","东风临夜冷于秋。"],"p":"浣溪沙"},{"id":"S00440","t":"浣溪沙","a":"吴文英","c":["波面铜花冷不收。","玉人垂钓理纤钩。","月明池阁夜来秋。","江燕话归成晓别，水花红减似春休。","西风梧井叶先愁。"],"p":"浣溪沙"},{"id":"S00441","t":"浣溪沙","a":"吴文英","c":["门巷深深小画楼。","阑干曾识凭春愁。","新蓬遮却绣鸳游。","桃观日斜香掩户，苹溪风起水东流。","紫萸玉腕又逢秋。"],"p":"浣溪沙"},{"id":"S00442","t":"浣溪沙","a":"吴文英","c":["曲角深帘隐洞房。","正嫌玉骨易愁黄。","好花偏占一秋香。","夜气清时初傍枕，晓光分处未开窗。","可怜人似月中孀。"],"p":"浣溪沙"},{"id":"S00443","t":"玉楼春","a":"吴文英","c":["茸茸狸帽遮梅额。","金蝉罗翦胡衫窄。","乘肩争看小腰身，倦态强随闲鼓笛。","问称家住城东陌。","欲买千金应不惜。","归来困顿𣨼春眠，犹梦婆娑斜趁拍。"],"p":"玉楼春"},{"id":"S00444","t":"玉楼春","a":"吴文英","c":["华堂夜宴连清晓。","醉里笙歌云窈袅。","酿来千日酒初尝，过却重阳秋更好。","阿儿早晚成名了。","玉树阶前春满抱。","天边金镜不须磨，长与妆楼悬晚照。"],"p":"玉楼春"},{"id":"S00445","t":"点绛唇","a":"吴文英","c":["推枕南窗，拣花寒入单纱浅。","雨帘不卷。","空碍调雏燕。","一握柔葱，香染榴巾汗。","音尘断。","画罗闲扇。","山色天涯远。"],"p":"点绛唇"},{"id":"S00446","t":"点绛唇","a":"吴文英","c":["时霎清明，载花不过西园路。","嫩阴绿树。","正是春留处。","燕子重来，往事东流去。","征衫贮。","旧寒一缕。","泪湿风帘絮。"],"p":"点绛唇"},{"id":"S00447","t":"点绛唇","a":"吴文英","c":["卷尽愁云，素娥临夜新梳洗。","暗尘不起。","酥润凌波地。","辇路重来，仿佛灯前事。","情如水。","小楼熏被。","春梦笙歌里。"],"p":"点绛唇"},{"id":"S00448","t":"秋蕊香","a":"吴文英","c":["宝月惊尘堕晓。","愁锁空枝斜照。","古苔几点露萤小。","销减秋光旋少。","佩丸尚忆春酥袅。","故人老。","断香忍和泪痕扫。","魂返东篱梦窅。"],"p":"秋蕊香"},{"id":"S00449","t":"秋蕊香","a":"吴文英","c":["懒浴新凉睡早。","雪靥酒红微笑。","倚楼起把绣针小。","月冷波光梦觉。","怕闻井叶西风到。","恨多少。","粉河不语堕秋晓。","云雨人间未了。"],"p":"秋蕊香"},{"id":"S00450","t":"诉衷情","a":"吴文英","c":["阴阴绿润暗啼鸦。","陌上断香车。","红云深处春在，飞出建章花。","春此去，那天涯。","几烟沙。","忍教芳草，狼藉斜阳，人未归家。"],"p":"诉衷情"},{"id":"S00451","t":"诉衷情","a":"吴文英","c":["柳腰空舞翠裙烟。","尽日不成眠。","花尘浪卷清昼，渐变晚阴天。","吴社水，系游船。","又经年。","东风不管，燕子初来，一夜春寒。"],"p":"诉衷情"},{"id":"S00452","t":"诉衷情","a":"吴文英","c":["片云载雨过江鸥。","水色澹汀洲。","小莲玉惨红怨，翠被又经秋。","凉意思，到南楼。","小帘钩。","半窗灯晕，几叶芭蕉，客梦床头。"],"p":"诉衷情"},{"id":"S00453","t":"诉衷情","a":"吴文英","c":["西风吹鹤到人间。","凉月满缑山。","银河万里秋浪，重载客槎还。","河汉女，巧云鬟。","夜阑干。","钗头新约，针眼娇颦，楼上秋寒。"],"p":"诉衷情"},{"id":"S00454","t":"夜游宫","a":"吴文英","c":["窗外捎溪雨响。","映窗里、嚼花灯冷。","浑似潇湘系孤艇。","见幽仙，步凌波，月边影。","香苦欺寒劲。","牵梦绕、沧涛千顷。","梦觉新愁旧风景。","绀云敧，玉搔斜，酒初醒。"],"p":"夜游宫"},{"id":"S00455","t":"夜游宫","a":"吴文英","c":["春语莺迷翠柳，烟隔断、晴波远岫。","寒压重帘幔拖绣。","袖炉香，倩东风，与吹透。","花讯催时候。","旧相思、偏供闲昼。","春澹情浓半中酒。","玉痕销，似梅花，更清瘦。"],"p":"夜游宫"},{"id":"S00456","t":"醉桃源・阮郎归","a":"吴文英","c":["金丸一树带霜华。","银台摇艳霞。","烛阴树影两交加。","秋纱机上花。","飞醉笔，驻吟车。","香深小隐家。","明朝新梦付啼鸦。","歌阑月未斜。"],"p":"醉桃源・阮郎归"},{"id":"S00457","t":"醉桃源・阮郎归","a":"吴文英","c":["沙河塘上旧游嬉。","卢郎年少时。","一声长笛月中吹。","和云和雁飞。","惊物换，叹星移。","相看两鬓丝。","断肠吴苑草凄凄。","倚楼人未归。"],"p":"醉桃源・阮郎归"},{"id":"S00458","t":"醉桃源・阮郎归","a":"吴文英","c":["青春花姊不同时。","凄凉生较迟。","艳妆临水最相宜。","风来吹秀漪。","惊旧事，问长眉。","月明仙梦回。","凭阑人但觉秋肥。","花愁人不知。"],"p":"醉桃源・阮郎归"},{"id":"S00459","t":"醉桃源・阮郎归","a":"吴文英","c":["翠阴浓合晓莺堤。","春如日坠西。","画图新展远山齐。","花深十二梯。","风絮晚，醉魂迷。","隔城闻马嘶。","落红微沁绣鸳泥。","秋千教放低。"],"p":"醉桃源・阮郎归"},{"id":"S00460","t":"哨遍","a":"刘克庄","c":["胜处可宫，平处可田，泉土尤甘美。","深复深，路绝住人稀。","有人兮、盘旋于此。","送子归。","是他隐居求志。","是要明主媒当世。","嗟此意谁论，其言甚壮，孔颜犹有遗旨。","大丈夫之被遇于时。","入则坐庙朝出旗麾。","列屋名姬，夹道武夫，满前才子。","噫。","有命存焉，吾非恶此而逃之。","富贵人所欲，如之何、幸而致。","向茂树堪休，清泉可濯，谷中别有闲天地。","况脍细于丝，蕨甜似蜜，采于山，钓于水。","大丈夫不遇之所为。","唐处士、依稀是吾师。","觉山林、尊如朝市。","五侯门下宾客，扰扰趋形势。","嗟盘之乐，谁争子所，占断千秋万岁。","呼童秣马更膏车，便与君，从此逝矣。"],"p":"哨遍"},{"id":"S00461","t":"六州歌头","a":"刘克庄","c":["维摩病起，兀坐等枯株。","清晨里，谁来问，是文殊。","遣名姝。","夺尽群花色，浴才出，酲初解，千万态，娇无力，困相扶。","绝代佳人，不入金张室，却访吾庐。","对茶铛禅榻，笑杀此翁臞。","珠髻金壶。","始消渠。","忆承平日，繁华事，修成谱，写成图。","奇绝甚，欧公记，蔡公书。","古来无。","一自京华隔，问姚魏、竟何如。","多应是，彩云散，劫灰馀。","野鹿衔将花去，休回首、河洛丘墟。","漫伤春吊古，梦绕汉唐都。","歌罢欷歔。"],"p":"六州歌头"},{"id":"S00462","t":"水调歌头","a":"刘克庄","c":["敕使竟空反，公不出梅关。","当年玉座记忆，仄席问平安。","羽扇尉佗城上，野服仙游阁下，辽鹤几时还。","赖有蜀耆旧，健笔与书丹。","青油士，珠履客，各凋残。","四方蹙蹙靡骋，独此尚宽闲。","丞相祠堂何处，太傅石碑堕泪，木老瀑泉寒。","往者不可作，置酒且登山。"],"p":"水调歌头"},{"id":"S00463","t":"水调歌头","a":"刘克庄","c":["遣作岭头使，似戍玉门关。","来时送者，举酒珍重祝身安。","街畔小儿拍笑，马上是翁矍铄，头与璧俱还。","何处得仙诀，发白颊犹丹。","屋茅破，篱菊瘦，架签残。","老夫自计甚审，忙定不如闲。","客难扬雄拓落，友笑王良来往，面汗背芒寒。","再拜谢不敏，早晚乞还山。"],"p":"水调歌头"},{"id":"S00464","t":"水调歌头","a":"刘克庄","c":["老子颇更事，打透利名关。","百年扰扰于役，何异入槐安。","梦里偶然得意，醒后才堪发笑，蚁穴驾车还。","恰佩南柯印，彷佛毂曾丹。","客未散，日初昳，酒犹残。","向来幻境安在，回首总成闲。","莫问浮云起灭，且跨刚风游戏，露冷玉箫寒。","寄语抱朴子，候我石楼山。"],"p":"水调歌头"},{"id":"S00465","t":"水调歌头","a":"刘克庄","c":["半世惯歧路，不怕唱阳关。","朝来印绶解去，今夕枕初安。","莫是散场优孟，又似下棚傀儡，脱了戏衫还。","老去事多忘，公莫笑师丹。","笔端花，胸中锦，两消残。","江湖水草空旷，何必养天闲。","久苦诸君共事，更尽一杯别酒，风露夜深寒。","回首行乐地，明日隔云山。"],"p":"水调歌头"},{"id":"S00466","t":"水调歌头","a":"刘克庄","c":["落日几呼渡，佳夕每留关。","有时来照清浅，鬓云似潘安。","一曲亲蒙君赐，两岸更无人迹，惟见鹭飞还。","隙地欠栽接，蕉荔杂黄丹。","柳全疏，松尚幼，怕摧残。","旁人笑我痴计，管钥费防闲。","翁意在乎林壑，客亦知夫水月，满腹贮清寒。","赋咏差有愧，赤壁与滁山。"],"p":"水调歌头"},{"id":"S00467","t":"水调歌头","a":"刘克庄","c":["羯虏问周鼎，柱史出秦关。","苦求句漏，何意身世远差安。","不见跕鸢堕水，时有飞鸿遵渚，乐此久忘还。","采药寓言耳，胸次有灵丹。","钓游处，榕叶暗，荻花残。","自翁仙后千载，输与水鸥闲。","我读内篇未竟，忽被急符驱去，洞闭白云寒。","回首愧幽子，隐约海中山。"],"p":"水调歌头"},{"id":"S00468","t":"水调歌头","a":"刘克庄","c":["怪事广寒殿，此夕不开关。","林间乌鹊相贺，暂得一枝安。","只在浮云深处，谁驾长风挟取，明镜忽飞还。","玉兔呼不应，难觅臼中丹。","酒行深，歌听彻，笛吹残。","嫦娥老去孤另，离别匹如闲。","待得银盘擎出，只怕玉峰醉倒，衰病不禁寒。","卿去我欲睡，孤负此湖山。"],"p":"水调歌头"},{"id":"S00469","t":"水调歌头","a":"刘克庄","c":["老年有奇事，天放两中秋。","使君飞榭千尺，缥缈见麟洲。","景物东徐城上，岁月北征诗里，圆缺几时休。","俯仰慨今昔，惟酒可浇愁。","风露高，河汉澹，素光流。","贾胡野老相庆，四海十分收。","竞看姮娥金镜，争信仙人玉斧，费了一番修。","衰晚笔无力，谁伴赋黄楼。"],"p":"水调歌头"},{"id":"S00470","t":"水调歌头","a":"刘克庄","c":["岁晚太玄草，深悔赋长杨。","向来户外之屦，已饱各飞扬。","阁上青藜安在，院里金莲去矣，且爱短檠光。","衰懒倦宾客，谁访老任棠。","叹时人，怜黠小，笑鲐黄。","汝曹变灭臭腐，侬底愈芬香。","苦羡阿龙则甚，学取幼安亦可，坐穴几藜床。","零落雁行小，敢不举君觞。"],"p":"水调歌头"},{"id":"S00471","t":"沁园春","a":"刘克庄","c":["何处相逢，登宝钗楼，访铜雀台。","唤厨人斫就，东溟鲸脍，圉人呈罢，西极龙媒。","天下英雄，使君与操，馀子谁堪共酒杯。","车千两，载燕南赵北，剑客奇才。","饮酣画鼓如雷。","谁信被晨鸡轻唤回。","叹年光过尽，功名未立，书生老去，机会方来。","使李将军，遇高皇帝，万户侯何足道哉。","披衣起，但凄凉感旧，慷慨生哀。"],"p":"沁园春"},{"id":"S00472","t":"沁园春","a":"刘克庄","c":["岁暮天寒，一剑飘然，幅巾布裘。","尽缘云鸟道，跻攀绝顶，拍天鲸浸，笑傲中流。","畴昔奇君，紫髯铁面，生子当如孙仲谋。","争知道，向中年犹未，建节封侯。","南来万里何求。","因感慨桥公成远游。","叹名姬骏马，都成昨梦，只鸡斗酒，谁吊新丘。","天地无情，功名有命，千古英雄只么休。","平生客，独羊昙一个，洒泪西州。"],"p":"沁园春"},{"id":"S00473","t":"沁园春","a":"刘克庄","c":["我羡君归，一路秋风，芙蓉木犀。","想慈颜望久，灵乌乍噪，新眉画就，郎马频嘶。","忙脱征衫，快呼斗酒，细为家人说建溪。","争知道，这中年怀抱，最怕分携。","丈夫南北东西。","应笑杀离筵粉泪啼。","怅佳人来未，碧云冉冉，王孙去后，芳草萋萋。","明日相思，山重水复，古道人稀茅店鸡。","元龙老，有高楼百尺，谁共登梯。"],"p":"沁园春"},{"id":"S00474","t":"沁园春","a":"刘克庄","c":["一卷阴符，二石硬弓，百斤宝刀。","更玉花骢喷，鸣鞭电抹，乌丝阑展，醉墨龙跳。","牛角书生，虬髯豪客，谈笑皆堪折简招。","依稀记，曾请缨系粤，草檄征辽。","当年目视云霄。","谁信道凄凉今折腰。","怅燕然未勒，南归草草，长安不见，北望迢迢。","老去胸中，有些磊块，歌罢犹须著酒浇。","休休也，但帽边鬓改，镜里颜凋。"],"p":"沁园春"},{"id":"S00475","t":"沁园春","a":"刘克庄","c":["我梦见君，戴飞霞冠，著宫锦袍。","与牧之高会，齐山诗酒，谪仙同载，采石风涛。","万卷星罗，千篇电扫，肯学穷儿事楚骚。","掀髯啸，有鱼龙鼓舞，狐兔悲嗥。","英雄埋没蓬蒿。","谁摸索当年刘与曹。","叹事机易失，功名难偶，诛茅西崦，种秫东皋。","栅有鸡豚，庭无羔雁，道是先生索价高。","人间窄，待相期海上，共摘蟠桃。"],"p":"沁园春"},{"id":"S00476","t":"沁园春","a":"刘克庄","c":["有个头陀，形等枯株，心犹死灰。","幸春山笋贱，无人争吃，夜炉芋美，与客同煨。","何处旛花，忽相导引，莫是天宫迎赴斋。","又疑道，向毗耶城里，讲席初开。","这边尚自徘徊。","笑那里纷纷早见猜。","有尊神奋杵，拳粗似钵，名缁竖拂，喝猛如雷。","老子无能，山僧不会，谁误檀那举请哉。","山中去，便百千亿劫，休下山来。"],"p":"沁园春"},{"id":"S00477","t":"沁园春","a":"刘克庄","c":["我所思兮，延陵季子，别来九春。","笑是非浮论，白衣苍狗，文章定价，秋月华星。","独步岷峨，后身坡颍，何必荀家有二仁。","中朝里，看叔兮衮斧，伯也丝纶。","洛中曾识机云。","记玉立堂堂九尺身。","叹苕溪渔艇，幽人孤往，雁山马鬣，吊客谁经。","宣室厘残，玄都花谢，回首旧游存几人。","新腔美，堪洗空恩怨，唤起交情。"],"p":"沁园春"},{"id":"S00478","t":"沁园春","a":"刘克庄","c":["莫羡渠侬，白玉成楼，黄金筑台。","也不消颠怪，骑𬴊被发，谁能委曲，令鸠为媒。","鬓有二毛，袖闲双手，只了持螯与把杯。","公过矣，赏陈登豪气，杜牧粗才。","便烦问讯张雷。","甚斗宿无光剑不回。","想阁中鸣佩，时携客去，壁间悬榻，近有谁来。","撤我虎皮，让君牛耳，谁道两贤相厄哉。","中年后，向歌阑易感，乐极生哀。"],"p":"沁园春"},{"id":"S00479","t":"沁园春","a":"刘克庄","c":["辽鹤重来，不见繁华，只见凋残。","甚都无人咏，何郎诗句，也无人报，书记平安。","闾里俱非，江山略是，纵有高楼莫倚栏。","沈吟处，但萤飞草际，雁起芦间。","不辞露宿风餐。","怕万里归来双鬓斑。","算这边赢得，黑貂裘敞，那边输了，翡翠衾寒。","檄草流传，吟笺倚阁，开到琼花亦懒看。","君记取，向中州差乐，塞地无欢。"],"p":"沁园春"},{"id":"S00480","t":"沁园春","a":"刘克庄","c":["华发萧萧，归碧鸡坊，出金马门。","把一枝色笔，掷还郭璞，些儿残锦，回乞天孙。","永免朝参，更无宣锁，送老三家水竹村。","休休也，任巫阳来下，未易招魂。","茅檐安得庖阍。","倩便了沽来酒满樽。","叹角巾东路，吾寻初服，上书北阙，子漫危言。","漏院霜靴，火城雪辔，得似先生败絮温。","安危事，付布衣融泰，鼎足膺蕃。"],"p":"沁园春"},{"id":"S00481","t":"沁园春","a":"刘克庄","c":["载籍以来，于宇宙间，有功者谁。","自唐尧咨禹，水行由地，宗周微管，夏变为夷。","谢傅棋边，莱公骰畔，淝水澶渊送捷旗。","天不偶，生堂堂国老，真太平基。","雅怀厌倦台司。","新天子殷勤留帝师。","向朝堂衮绣，万羊非泰，湖山绦褐，两鹤相随。","寿过磻溪，德如淇澳，进了丹书作抑诗。","蒯缑客，愿年年岁岁，来献新词。"],"p":"沁园春"},{"id":"S00482","t":"沁园春","a":"刘克庄","c":["驯于蹇驴，清于赐驹，我行尔从。","幸柴车堪驾，何惭韩众，药苗可采，长伴庞公。","野涧泉甘，阳坡草暖，有柏叶松枝充短供。","修梦想，去游灵囿沼，入望夷宫。","与夸夺子争雄。","生与死未知谁手中。","况嗾獒者众，放麑人少，大将触网，小亦伤弓。","风月和柔，山林深密，折角何如且养茸。","二虫喜，各衔花拜跪，来寿樗翁。"],"p":"沁园春"},{"id":"S00483","t":"沁园春","a":"刘克庄","c":["剥啄谁欤，户外一宾，布衣麻鞋。","有舌端雄辨，机锋破的，袖中行卷，锦绣成堆。","阍启上宾，侬观诸老，个主人公喜挽推。","怎奈向，今十分衰飒，非昔形骸。","阍言宾怒如雷。","因底事朱门晏未开。","假使汝主公，做他将相，懒迎揖客，紧闭翘材。","病叟惭惶，尊官宁耐，待铁拐先生旋出来。","宾性急，怀生毛名纸，兴尽而回。"],"p":"沁园春"},{"id":"S00484","t":"沁园春","a":"刘克庄","c":["老子衰颓，晚与亲朋，约法三章。","有谈除目者，勒回车马，谈时事者，麾出门墙。","已挂衣冠，怕言轩冕，犯令先当举罚觞。","书尺里，但平安二字，多少深长。","溪翁苦未相忘。","我今有双鱼烦寄将。","道荒芜羞对，宫中莲烛，昏花难映，阁上藜光。","闻庙瑟音，识关雎乱，诗学专门尽不妨。","百年后，尚庶几申白，不数韦康。"],"p":"沁园春"},{"id":"S00485","t":"沁园春","a":"刘克庄","c":["天造梅花，有许孤高，有许芬芳。","似湘娥凝望，敛君山黛，明妃远嫁，作汉宫妆。","冷艳谁知，素标难亵，又似夷齐饿首阳。","幽雅意，纵写之缣楮，未得毫芒。","曾经诸老平章。","只一个孤山说影香。","便诏书存问，漫招处士，节旄落尽，早屈中郎。","日暮天寒，山空月堕，茅舍清于白玉堂。","宁淡杀，不敢凭羌笛，告诉凄凉。"],"p":"沁园春"},{"id":"S00486","t":"沁园春","a":"刘克庄","c":["畴昔遭逢，薰殿之琴，清庙之璋。","谢锦袍打扮，佯狂太白，黄冠结裹，老大知章。","种杏仙人，看桃君子，得似篱边嗅晚香。","从人笑，笑安车迎晚，只履归忙。","后身定作班扬。","彼撼树蚍蜉不自量。","偶有时戏笔，官奴藏去，有时醉坠，宗武扶将。","永别鹓鸾，已盟猿鹤，肯学周颙出草堂。","从人笑，我韩公齿豁，张镐眉苍。"],"p":"沁园春"},{"id":"S00487","t":"沁园春","a":"刘克庄","c":["惭愧清朝，罢贡包茅，住发牙璋。","便羊裘归去，难留严子，牛衣病卧，肯泣王章。","畴昔忧天，如今怀土，田舍鸡肥社酒香。","甘雨足，且免扶锄苦，免踏车忙。","先生少拟荀扬。","晚自觉才衰可斗量。","甚都无白凤，飞来玄草，亦无紫气，下烛干将。","待得新亭，倒持手版，何似抽还政事堂。","荣与辱，算到头由我，不属苍苍。"],"p":"沁园春"},{"id":"S00488","t":"沁园春","a":"刘克庄","c":["吉梦维何，男子之祥，载弄之璋。","嗟我辰安在，斯文后死，力侔元气，手抉天章。","学稼田荒，炼丹灶壤，稽首南华一瓣香。","休休也，免王良友笑，屑往来忙。","浮名斗挹箕扬。","世岂有明珠百斛量。","叹种来瑶草，年深未熟，挑成锦字，道远难将。","迁转不行，形容尽变，盍改称呼号瞎堂。","遗弓远，怆帝乡云白，禹会山苍。"],"p":"沁园春"},{"id":"S00489","t":"沁园春","a":"刘克庄","c":["余少之时，赋如仲宣，檄如孔璋。","也曾观万舞，铺陈商颂，曾闻九奏，制作尧章。","抖擞空囊，存留谏笏，犹带虚皇案畔香。","今归矣，省听鸡骑马，趁早朝忙。","榻前密启明扬。","宰物者方持玉尺量。","元未尝弃汝，自云耄及，无宁寿我，或者天将。","富有图书，贫无钗泽，不似安昌列后堂。","新腔好，任伊川看见，非亵穹苍。"],"p":"沁园春"},{"id":"S00490","t":"小重山","a":"岳飞","c":["昨夜寒蛩不住鸣。","惊回千里梦，已三更。","起来独自绕阶行。","人悄悄，帘外月胧明。","白首为功名。","旧山松竹老，阻归程。","欲将心事付瑶琴。","知音少，弦断有谁听。"],"p":"小重山"},{"id":"S00491","t":"满江红","a":"岳飞","c":["怒发冲冠，凭阑处、潇潇雨歇。","抬望眼、仰天长啸，壮怀激烈。","三十功名尘与土，八千里路云和月。","莫等闲、白了少年头，空悲切。","靖康耻，犹未雪。","臣子恨，何时灭。","驾长车踏破，贺兰山缺。","壮志饥餐胡虏肉，笑谈渴饮匈奴血。","待从头、收拾旧山河，朝天阙。"],"p":"满江红"},{"id":"S00492","t":"满江红","a":"岳飞","c":["遥望中原，荒烟外、许多城郭。","想当年、花遮柳护，凤楼龙阁。","万岁山前珠翠绕，蓬壶殿里笙歌作。","到而今、铁骑满郊畿，风尘恶。","兵安在，膏锋锷。","民安在，填沟壑。","叹江山如故，千村寥落。","何日请缨提锐旅，一鞭直渡清河洛。","却归来、再续汉阳游，骑黄鹤。"],"p":"满江红"},{"id":"S00493","t":"桂枝香","a":"王安石","c":["登临送目。","正故国晚秋，天气初肃。","千里澄江似练，翠峰如簇。","归帆去棹残阳里，背西风、酒旗斜矗。","彩舟云淡，星河鹭起，画图难足。","念往昔、繁华竞逐。","叹门外楼头，悲恨相续。","千古凭高，对此漫嗟荣辱。","六朝旧事随流水，但寒烟、芳草凝绿。","至今商女，时时犹唱，后庭遗曲。"],"p":"桂枝香"},{"id":"S00494","t":"甘露歌","a":"王安石","c":["折得一枝香在手。","人间应未有。","疑是经春雪未消。","今日是何朝。"],"p":"甘露歌"},{"id":"S00495","t":"甘露歌","a":"王安石","c":["尽日含毫难比兴。","都无色可并。","万里晴天何处来。","真是屑琼瑰。"],"p":"甘露歌"},{"id":"S00496","t":"甘露歌","a":"王安石","c":["天寒日暮山谷里。","的砾愁成水。","池上渐多枝上稀。","唯有故人知。"],"p":"甘露歌"},{"id":"S00497","t":"菩萨蛮","a":"王安石","c":["数家茅屋闲临水。","单衫短帽垂杨里。","今日是何朝。","看予度石桥。","梢梢新月偃。","午醉醒来晚。","何物最关情。","黄鹂三两声。"],"p":"菩萨蛮"},{"id":"S00498","t":"渔家傲","a":"王安石","c":["灯火已收正月半。","山南山北花撩乱。","闻说洊亭新水漫。","骑款段。","穿云入坞寻游伴。","却拂僧床褰素幔。","千岩万壑春风暖。","一弄松声悲急管。","吹梦断。","西看窗日犹嫌短。"],"p":"渔家傲"},{"id":"S00499","t":"渔家傲","a":"王安石","c":["平岸小桥千嶂抱。","柔蓝一水萦花草。","茅屋数间窗窈窕。","尘不到。","时时自有春风扫。","午枕觉来闻语鸟。","敧眠似听朝鸡早。","忽忆故人今总老。","贪梦好。","茫然忘了邯郸道。"],"p":"渔家傲"},{"id":"S00500","t":"雨霖铃","a":"王安石","c":["孜孜矻矻。","向无明里、强作窠窟。","浮名浮利何济，堪留恋处，轮回仓猝。","幸有明空妙觉，可弹指超出。","缘底事、抛了全潮，认一浮沤作瀛渤。","本源自性天真佛。","祗些些、妄想中埋没。","贪他眼花阳艳，谁信道、本来无物。","一旦茫然，终被阎罗老子相屈。","便纵有、千种机筹，怎免伊唐突。"],"p":"雨霖铃"},{"id":"S00501","t":"清平乐","a":"王安石","c":["云垂平野。","掩映竹篱茅舍。","阒寂幽居实潇洒。","是处绿娇红冶。","丈夫运用堂堂。","且莫五角六张。","若有一卮芳酒，逍遥自在无妨。"],"p":"清平乐"},{"id":"S00502","t":"浣溪沙","a":"王安石","c":["百亩中庭半是苔。","门前白道水萦回。","爱闲能有几人来。","小院回廊春寂寂，山桃溪杏两三栽。","为谁零落为谁开。"],"p":"浣溪沙"},{"id":"S00503","t":"诉衷情","a":"王安石","c":["常时黄色见眉间。","松桂我同攀。","每言天上辛苦，不肯饵金丹。","怜水静，爱云闲。","便忘还。","高歌一曲，岩谷迤逦，宛似商山。"],"p":"诉衷情"},{"id":"S00504","t":"诉衷情","a":"王安石","c":["练巾藜杖白云间。","有兴即跻攀。","追思往昔如梦，华毂也曾丹。","尘自扰，性长闲。","更无还。","达如周召，穷似丘轲，祗个山山。"],"p":"诉衷情"},{"id":"S00505","t":"诉衷情","a":"王安石","c":["茫然不肯住林间。","有处即追攀。","将他死语图度，怎得离真丹。","浆水价，匹如闲。","也须还。","何如直截，踢倒军持，赢取沩山。"],"p":"诉衷情"},{"id":"S00506","t":"诉衷情","a":"王安石","c":["营巢燕子逞翱翔。","微志在雕梁。","碧云举翮千里，其奈有鸾皇。","临济处，德山行。","果承当。","自时降住，一切天魔，扫地焚香。"],"p":"诉衷情"},{"id":"S00507","t":"诉衷情","a":"王安石","c":["莫言普化祗颠狂。","真解作津梁。","蓦然打个筋斗，直跳过羲皇。","临济处，德山行。","果承当。","将他建立，认作心诚，也是寻香。"],"p":"诉衷情"},{"id":"S00508","t":"南乡子","a":"王安石","c":["嗟见世间人。","但有纤毫即是尘。","不住旧时无相貌，沈沦。","祗为从来认识神。","作么有疏亲。","我自降魔转法轮。","不是摄心除妄想，求真。","幻化空身即法身。"],"p":"南乡子"},{"id":"S00509","t":"南乡子","a":"王安石","c":["自古帝王州。","郁郁葱葱佳气浮。","四百年来成一梦，堪愁。","晋代衣冠成古丘。","绕水恣行游。","上尽层城更上楼。","往事悠悠君莫问，回头。","槛外长江空自流。"],"p":"南乡子"},{"id":"S00510","t":"浪淘沙令","a":"王安石","c":["伊吕两衰翁。","历遍穷通。","一为钓叟一耕佣。","若使当时身不遇，老了英雄。","汤武偶相逢。","风虎云龙。","兴王祗在笑谈中。","直至如今千载后，谁与争功。"],"p":"浪淘沙令"},{"id":"S00511","t":"望江南・忆江南","a":"王安石","c":["归依众，梵行四威仪。","愿我遍游诸佛土。","十方贤圣不相离。","永灭世间痴。"],"p":"望江南・忆江南"},{"id":"S00512","t":"望江南・忆江南","a":"王安石","c":["归依法，法法不思议。","愿我六根常寂静，心如宝月映琉璃。","了法更无疑。"],"p":"望江南・忆江南"},{"id":"S00513","t":"望江南・忆江南","a":"王安石","c":["归依佛，弹指越三祗。","愿我速登无上觉，还如佛坐道场时。","能智又能悲。"],"p":"望江南・忆江南"},{"id":"S00514","t":"望江南・忆江南","a":"王安石","c":["三界里，有取总灾危。","普愿众生同我愿，能于空有善思惟。","三宝共住持。"],"p":"望江南・忆江南"},{"id":"S00515","t":"西江月","a":"王安石","c":["梅好惟嫌淡伫，天教薄与胭脂。","真妃初出华清池。","酒入琼姬半醉。","东阁诗情易动，高楼玉管休吹。","北人浑作杏花疑。","惟有青枝不似。"],"p":"西江月"},{"id":"S00516","t":"渔家傲","a":"王安石","c":["隔岸桃花红未半。","枝头已有蜂儿乱。","惆怅武陵人不管。","清梦断。","亭亭伫立春宵短。"],"p":"渔家傲"},{"id":"S00517","t":"清平乐","a":"王安石","c":["留春不住。","费尽莺儿语。","满地残红宫锦污。","昨夜南园风雨。","小怜初上琵琶。","晓来思绕天涯。","不肯画堂朱户，春风自在杨花。"],"p":"清平乐"},{"id":"S00518","t":"生查子","a":"王安石","c":["雨打江南树。","一夜花开无数。","绿叶渐成阴，下有游人归路。","与君相逢处。","不道春将暮。","把酒祝东风，且莫恁、匆匆去。"],"p":"生查子"},{"id":"S00519","t":"谒金门","a":"王安石","c":["春又老。","南陌酒香梅小。","遍地落花浑不扫。","梦回情意悄。","红笺寄与添烦恼。","细写相思多少。","醉后几行书字小。","泪痕都揾了。"],"p":"谒金门"},{"id":"S00520","t":"菩萨蛮","a":"王安石","c":["海棠乱发皆临水。","君知此处花何似。","凉月白纷纷。","香风隔岸闻。","啭枝黄鸟近。","隔岸声相应。","随意坐莓苔。","飘零酒一杯。"],"p":"菩萨蛮"},{"id":"S00521","t":"千秋岁引","a":"王安石","c":["别馆寒砧，孤城画角。","一派秋声入寥廓。","东归燕从海上去，南来雁向沙头落。","楚台风，庾楼月，宛如昨。","无奈被些名利缚。","无奈被他情担阁。","可惜风流总闲却。","当初漫留华表语，而今误我秦楼约。","梦阑时，酒醒后，思量著。"],"p":"千秋岁引"},{"id":"S00522","t":"失调名","a":"宋祁","c":["因为衔泥污锦衣。","垂下珠帘不敢归。"],"p":"失调名"},{"id":"S00523","t":"浪淘沙近・浪淘沙","a":"宋祁","c":["少年不管。","流光如箭。","因循不觉韶光换。","至如今，始惜月满、花满、酒满。","扁舟欲解垂杨岸。","尚同欢宴。","日斜歌阕将分散。","倚兰桡，望水远、天远、人远。"],"p":"浪淘沙近・浪淘沙"},{"id":"S00524","t":"蝶恋花","a":"宋祁","c":["雨过蒲萄新涨绿。","苍玉盘倾，堕碎珠千斛。","姬监拥前红簇簇。","温泉初试真妃浴。","驿使南来丹荔熟。","故翦轻绡，一色颁时服。","娇汗易晞凝醉玉。","青凉不用香绵扑。"],"p":"蝶恋花"},{"id":"S00525","t":"玉楼春","a":"宋祁","c":["东城渐觉风光好。","縠皱波纹迎客棹。","绿杨烟外晓寒轻，红杏枝头春意闹。","浮生长恨欢娱少。","肯爱千金轻一笑。","为君持酒劝斜阳，且向花间留晚照。"],"p":"玉楼春"},{"id":"S00526","t":"蝶恋花","a":"宋祁","c":["绣幕茫茫罗帐卷。","春睡腾腾，困入娇波慢。","隐隐枕痕留玉脸。","腻云斜溜钗头燕。","远梦无端欢又散。","泪落胭脂，界破蜂黄浅。","整了翠鬟匀了面。","芳心一寸情何限。"],"p":"蝶恋花"},{"id":"S00527","t":"鹧鸪天","a":"宋祁","c":["画毂雕鞍狭路逢。","一声肠断绣帘中。","身无彩凤双飞翼，心有灵犀一点通。","金作屋，玉为笼。","车如流水马游龙。","刘郎已恨蓬山远，更隔蓬山几万重。"],"p":"鹧鸪天"},{"id":"S00528","t":"好事近","a":"宋祁","c":["睡起玉屏风，吹去乱红犹落。","天气骤生轻暖，衬沈香帷箔。","珠帘约住海棠风，愁拖两眉角。","昨夜一庭明月，冷秋千红索。"],"p":"好事近"},{"id":"S00529","t":"酒泉子","a":"潘阆","c":["长忆钱塘，不是人寰是天上。","万家掩映翠微间。","处处水潺潺。","异花四季当窗放。","出入分明在屏障。","别来隋柳几经秋。","何日得重游。"],"p":"酒泉子"},{"id":"S00530","t":"酒泉子","a":"潘阆","c":["长忆钱塘，临水傍山三百寺。","僧房携杖遍曾游。","闲话觉忘忧。","栴檀楼阁云霞畔。","钟梵清宵彻天汉。","别来遥礼祗焚香。","便恐是西方。"],"p":"酒泉子"},{"id":"S00531","t":"酒泉子","a":"潘阆","c":["长忆西湖，湖上春来无限景。","吴姬个个是神仙。","兢泛木兰船。","楼台簇簇疑蓬岛。","野人祗合其中老。","别来已是二十年。","东望眼将穿。"],"p":"酒泉子"},{"id":"S00532","t":"酒泉子","a":"潘阆","c":["长忆西湖，尽日凭阑楼上望。","三三两两钓鱼舟。","岛屿正清秋。","笛声依约芦花里。","白鸟成行忽惊起。","别来闲整钓鱼竿。","思入水云寒。"],"p":"酒泉子"},{"id":"S00533","t":"酒泉子","a":"潘阆","c":["长忆孤山，山在湖心如黛簇。","僧房四面向湖开。","轻棹去还来。","芰荷香喷连云阁。","阁上清声檐下铎。","别来尘土污人衣。","空役梦魂飞。"],"p":"酒泉子"},{"id":"S00534","t":"酒泉子","a":"潘阆","c":["长忆西山，灵隐寺前三竺后。","冷泉亭上旧曾游。","三伏似清秋。","白猿时见攀高树。","长啸一声何处去。","别来几向画阑看。","终是欠峰峦。"],"p":"酒泉子"},{"id":"S00535","t":"酒泉子","a":"潘阆","c":["长忆高峰，峰上塔高尘世外。","昔年独上最高层。","月出见觚棱。","举头咫尺疑天汉。","星斗分明在身畔。","别来无翼可飞腾。","何日得重登。"],"p":"酒泉子"},{"id":"S00536","t":"酒泉子","a":"潘阆","c":["长忆吴山，山上森森吴相庙。","庙前江水怒为涛。","千古恨犹高。","寒鸦日暮鸣还聚。","时有阴云笼殿宇。","别来有负谒灵祠。","遥奠酒盈卮。"],"p":"酒泉子"},{"id":"S00537","t":"酒泉子","a":"潘阆","c":["长忆龙山，日月宫中谁得到。","宫中旦暮听潮声。","台殿竹风清。","门前岁岁生灵草。","人采食之多不老。","别来已白数茎头。","早晚却重游。"],"p":"酒泉子"},{"id":"S00538","t":"酒泉子","a":"潘阆","c":["长忆观潮，满郭人争江上望。","来疑沧海尽成空。","万面鼓声中。","弄涛儿向涛头立。","手把红旗旗不湿。","别来几向梦中看。","梦觉尚心寒。"],"p":"酒泉子"},{"id":"S00539","t":"扫市舞","a":"潘阆","c":["出砒霜，价钱可。","赢得拨灰兼弄火。","畅杀我。"],"p":"扫市舞"},{"id":"S00540","t":"水调歌头","a":"陈亮","c":["不见南师久，谩说北群空。","当场只手，毕竟还我万夫雄。","自笑堂堂汉使，得似洋洋河水，依旧只流东。","且复穹庐拜，会向藁街逢。","尧之都，舜之壤，禹之封。","于中应有，一个半个耻臣戎。","万里腥膻如许，千古英灵安在，磅礴几时通。","胡运何须问，赫日自当中。"],"p":"水调歌头"},{"id":"S00541","t":"念奴娇","a":"陈亮","c":["江南春色，算来是、多少胜游清赏。","妖冶廉纤，只做得，飞鸟向人偎傍。","地辟天开，精神朗慧，到底还京样。","人家小语，一声声近清唱。","因念旧日山城，个人如画，已作州中想。","邓禹笑人无限也，冷落不堪惆怅。","秋水双明，高山一弄，著我些悲壮。","南徐好住，片帆有分来往。"],"p":"念奴娇"},{"id":"S00542","t":"贺新郎","a":"陈亮","c":["修竹更深处。","映帘栊、清阴障日，坐来无暑。","水激泠泠如何许。","跳碎危栏玉树。","都不系、人间朝暮。","东阁少年今老矣，况樽中有酒嫌推去。","犹著我，明流语。","大家绿野陪容与。","算等闲、过了薰风，又还商素。","手弄柔条人健否，尤忆当时雅趣。","恩未报、恐成辜负。","举目江河休感涕，念有君如此何愁虏。","歌未罢，谁来舞。"],"p":"贺新郎"},{"id":"S00543","t":"满江红","a":"陈亮","c":["曾洗乾坤，问何事、雄图顿屈。","试著眼、阶除当下，又添英物。","北向争衡幽愤在，南来遗恨狂酋失。","算凄凉部曲几人存，三之一。","诸老尽，郎君出。","恩未报，家何恤。","念横飞直上，有时还戢。","笑我只知存饱暖，感君元不论阶级。","休更上百尺旧家楼，尘侵帙。"],"p":"满江红"},{"id":"S00544","t":"桂枝香","a":"陈亮","c":["天高气肃。","正月色分明，秋容新沐。","桂子初收，三十六宫都足。","不辞散落人间去，怕群花、自嫌凡俗。","向他秋晚，唤回春意，几曾幽独。","是天上、馀香剩馥。","怪一树香风，十里相续。","坐对花旁，但见色浮金粟。","芙蓉只解添秋思，况东篱、凄凉黄菊。","入时太浅，背时太远，爱寻高躅。"],"p":"桂枝香"},{"id":"S00545","t":"三部乐","a":"陈亮","c":["小屈穹庐，但二满三平，共劳均佚。","人中龙虎，本为明时而出。","只合是、端坐王朝，看指挥整办，扫荡飘忽。","也持汉节，聊过旧家宫室。","西风又还带暑，把征衫著上，有时披拂。","休将看花泪眼，闻弦□骨。","对遗民、有如皎日。","行万里、依然故物。","入奏几策，天下里、终定于一。"],"p":"三部乐"},{"id":"S00546","t":"水调歌头","a":"陈亮","c":["人物从来少，篱菊为谁黄。","去年今日，倚楼还是听行藏。","未觉霜风无赖，好在月华如水，心事楚天长。","讲论参洙泗，杯酒到虞唐。","人未醉，歌宛转，兴悠扬。","太平胸次，笑他磊磈欲成狂。","且向武夷深处，坐对云烟开敛，逸思如微茫。","我欲为君寿，何许得新腔。"],"p":"水调歌头"},{"id":"S00547","t":"念奴娇","a":"陈亮","c":["危楼远望，叹此意、今古几人曾会。","鬼设神施，浑认作、天限南疆北界。","一水横陈，莲岗三面，做出争雄势。","六朝何事，只成门户私计。","因笑王谢诸人，登高怀远，也学英雄涕。","凭却长江管不到，河洛腥膻无际。","正好长驱，不须反顾，寻取中流誓。","小儿破贼，势成宁问疆场。"],"p":"念奴娇"},{"id":"S00548","t":"贺新郎","a":"陈亮","c":["老去凭谁说。","看几番、神奇臭腐，夏裘冬葛。","父老长安今馀几，后死无仇可雪。","犹未燥、当时生发。","二十五弦多少恨，算世间、那有平分月。","胡妇弄，汉宫瑟。","树犹如此堪重别。","只使君、从来与我，话头多合。","行矣置之无足问，谁唤妍皮痴骨。","但莫使、伯牙弦绝。","九转丹砂牢拾取，管精金、只是寻常铁。","龙共虎，应声裂。"],"p":"贺新郎"},{"id":"S00549","t":"瑞云浓慢","a":"陈亮","c":["蔗浆酪粉，玉壶冰醑，朝罢更闻宣赐。","去天咫尺，下拜再三，幸今有母可遗。","年年此日，共道月入怀中最贵。","向暑天，正风云会遇，有恁嘉瑞。","鹤冲霄，鱼得水。","一超便、直入神仙地。","植根江表。","开拓两河，做得黑头公未。","骑鲸赤手，问如何、长鞭尺箠。","向来王谢风流，只今管是。"],"p":"瑞云浓慢"},{"id":"S00550","t":"阮郎归","a":"陈亮","c":["波光渺渺浸晴陂。","有亭湖岸西。","芰荷香拂柳丝垂。","升堂献寿卮。","红约腕，绿侵衣。","愿祝届期颐。","花间妙语欲无诗。","一年歌一词。"],"p":"阮郎归"},{"id":"S00551","t":"祝英台近","a":"陈亮","c":["驾扁舟，冲剧暑。","千里江上去。","夜宿晨兴，一一旧时路。","百年望了旬头，被人馋破，故纸里、是争雄处。","怎生诉。","欲待细与分疏，其如有凭据。","包裹生鱼，活底怎遭遇。","相逢樽酒何时，征衫容易，君去也、自家须住。"],"p":"祝英台近"},{"id":"S00552","t":"蝶恋花","a":"陈亮","c":["手拈黄花还自笑。","笑比渊明，莫也归来早。","随世功名浑草草。","五湖却共繁华老。","冷淡家生冤得道。","旖旎妖娆，春梦如今觉。","管个岁华须到了。","此花之后花应少。"],"p":"蝶恋花"},{"id":"S00553","t":"水调歌头","a":"陈亮","c":["人爱新来景，龙认旧时湫。","不论三伏，小住便觉凛生秋。","我自醉眠其上，任是水流其下，湍激若为收。","世事如斯去，不去为谁留。","本无心，随所寓，触虚舟。","东山始末，且向灵洞与沈浮。","料得神仙窟穴，争似提封万里，大小几琉球。","但有君才具，何用问时流。"],"p":"水调歌头"},{"id":"S00554","t":"念奴娇","a":"陈亮","c":["西风带暑，又还是、长途利牵名役。","我已无心，君因甚，更把青衫为客。","邂逅卑飞，几时高举，不露真消息。","大家行处，到头须管行得。","何处寻取狂徒，可能著意，更问渠侬骨。","天上人间，最好是、闹里一般岑寂。","瀛海无波，玉堂有路，稳著青霄翼。","归来何事，眼光依旧生碧。"],"p":"念奴娇"},{"id":"S00555","t":"卜算子","a":"陈亮","c":["悄静菊花天，洗尽梧桐雨。","倍九周遭烂熳开，祝寿当头取。","顶戴玉袍黄，叠秀金棱吐。","仙种花容晚节香，人愿争先睹。"],"p":"卜算子"},{"id":"S00556","t":"贺新郎","a":"陈亮","c":["离乱从头说。","爱吾民，金缯不爱，蔓藤累葛。","壮气尽消人脆好，冠盖阴山观雪。","亏杀我，一星星发。","涕出女吴成倒转，问鲁为齐弱何年月。","丘也幸，由之瑟。","斩新换出旗麾别。","把当时、一椿大义，拆开收合。","据地一呼吾往矣，万里摇肢动骨。","这话霸、又成痴绝。","天地洪炉谁扇𫖔，算于中、安得长坚铁。","淝水破，关东裂。"],"p":"贺新郎"},{"id":"S00557","t":"垂丝钓","a":"陈亮","c":["菊花细雨。","萧萧红蓼汀渚。","景物渐幽，风致如许。","秋未暮。","又值吾初度。","看天宇。","正澄清欲往，登高未也，红尘当面飞舞。","几人吊古。","乌帽牢收取。","短发还羞觑。","遐寿身、近五云深处。"],"p":"垂丝钓"},{"id":"S00558","t":"彩凤飞","a":"陈亮","c":["人立玉，天如水，特地如何撰。","海南沈烧著，欲寒犹暖。","算从头，有多少、厚德阴功，人家上，一一旧时香案。","□煞经惯。","小驻吾舟才尔，依然欢声满。","莫也教、公子王孙眼见。","这些儿、颖脱处，高出书卷。","经纶自入手，不了判断。"],"p":"彩凤飞"},{"id":"S00559","t":"鹧鸪天","a":"陈亮","c":["落魄行歌记昔游。","头颅如许尚何求。","心肝吐尽无馀事，口腹安然岂远谋。","才怕暑，又伤秋。","天涯梦断有书不。","大都眼孔新来浅，羡尔微官作计周。"],"p":"鹧鸪天"},{"id":"S00560","t":"谒金门","a":"陈亮","c":["新雨足。","洗尽山城袢褥。","见说好峰三十六。","峰峰如立玉。","四海英游追逐。","事业相时伸缩。","入境德星须做福。","只愁金诏趣。"],"p":"谒金门"},{"id":"S00561","t":"天仙子","a":"陈亮","c":["一夜秋光先著柳。","暑力平明羞失守。","西风不放入帘帏，饶永昼。","沈烟透。","半月十朝秋定否。","指点芙蕖凝伫久。","高处成莲深处藕。","百年长共月团圆，女进男，酒称寿。","一点浮云人似旧。"],"p":"天仙子"},{"id":"S00562","t":"水调歌头","a":"陈亮","c":["事业随人品，今古几麾旌。","向来谋国，万事尽出汝书生。","安识鲲鹏变化，九万里风在下，如许上南溟。","斥鷃旁边笑，河汉一头倾。","叹世间，多少恨，几时平。","霸图消歇，大家创见又成惊。","邂逅汉家龙种，正尔乌纱白纻，驰骛觉身轻。","樽酒从渠说，双眼为谁明。"],"p":"水调歌头"},{"id":"S00563","t":"洞仙歌","a":"陈亮","c":["秋容一洗，不受凡尘涴。","许大乾坤这回大。","向上头，些子是雕鹗抟空，篱底下，只有黄花几朵。","骑鲸汗慢，那得人同坐。","赤手丹心扑不破。","问唐虞、禹汤文武，多少功名，犹自是、一点浮云铲过。","且烧却、一瓣海南沈，任拈取、千年陆沈奇货。"],"p":"洞仙歌"},{"id":"S00564","t":"祝英台近","a":"陈亮","c":["嫩寒天，金气雨，揽断一秋事。","仝样霏微，远作小晴意。","世间万宝都成，些儿无欠，只待与、黄花为地。","好招致。","对此郁郁葱葱，新𥬠未成醉。","翻手为云，造物等儿戏。","也知富贵来时，一班呈露，便做出人中祥瑞。"],"p":"祝英台近"},{"id":"S00565","t":"踏莎行","a":"陈亮","c":["书册如仇，旧游浑讳。","有怀不断人应异。","千山上去梦魂轻，片帆似下蛮溪水。","已共酒杯，长坚海誓。","见君忽忘花前醉。","从来解事苦无多，不知解到毫芒未。"],"p":"踏莎行"},{"id":"S00566","t":"南乡子","a":"陈亮","c":["人物满东瓯。","别我江心识俊游。","北尽平芜南似画，中流。","谁系龙骧万斛舟。","去去几时休。","犹自潮上更来头。","醉墨淋漓人感旧，离愁。","一夜西风似夏不。"],"p":"南乡子"},{"id":"S00567","t":"三部乐","a":"陈亮","c":["入脚西风，渐去去来来，早三之一。","春花无数，毕竟何如秋实。","不须待、名品如麻，试为君屈指，是谁层出。","十朝半月，争看抟空霜鹘。","从来别真共假，任盘根错节，更饶仓卒。","还他济时好手，封侯奇骨。","没些儿、媻姗勃窣。","也不是、峥嵘突兀。","百二十岁，管做彻、元分人物。"],"p":"三部乐"},{"id":"S00568","t":"贺新郎","a":"陈亮","c":["话杀浑闲说。","不成教、齐民也解，为伊为葛。","樽酒相逢成二老，却忆去年风雪。","新著了、几茎华发。","百世寻人犹接踵，叹只今两地三人月。","写旧恨，向谁瑟。","男儿何用伤离别。","况古来、几番际会，风从云合。","千里情亲长晤对，妙体本心次骨。","卧百尺、高楼斗绝。","天下适安耕且老，看买犁卖剑平家铁。","壮士泪，肺肝裂。"],"p":"贺新郎"},{"id":"S00569","t":"点绛唇","a":"陈亮","c":["一夜相思，水边清浅横枝瘦。","小窗如昼。","情共香俱透。","清入梦魂，千里人长久。","君知否。","雨﹀人︽。","格调还依旧。"],"p":"点绛唇"},{"id":"S00570","t":"南歌子","a":"张孝祥","c":["人物羲皇上，诗名沈谢间。","漫郎元自谩为官。","醉眼瞢腾、只拟看湘山。","小隐今成趣，邻翁独往还。","野堂梅柳尚春寒。","且趁华灯、频泛酒船宽。"],"p":"南歌子"},{"id":"S00571","t":"霜天晓角","a":"张孝祥","c":["柳丝无力。","冉冉萦愁碧。","系我船儿不住，楚江上、晚风急。","棹歌休怨抑。","有人离恨极。","说与归期不远，刚不信、泪偷滴。"],"p":"霜天晓角"},{"id":"S00572","t":"生查子","a":"张孝祥","c":["远山眉黛横，媚柳开青眼。","楼阁断霞明，帘幕春寒浅。","杯延玉漏迟，烛怕金刀剪。","明月忽飞来，花影和帘卷。"],"p":"生查子"},{"id":"S00573","t":"长相思","a":"张孝祥","c":["小楼重。","下帘栊。","万点芳心绿间红。","秋千图画中。","草茸茸。","柳松松。","细卷玻璃水面风。","春寒依旧浓。"],"p":"长相思"},{"id":"S00574","t":"忆秦娥","a":"张孝祥","c":["元宵节。","凤楼相对鳌山结。","鳌山结。","香尘随步，柳梢微月。","多情又把珠帘揭。","游人不放笙歌歇。","笙歌歇。","晓烟轻散，帝城宫阕。"],"p":"忆秦娥"},{"id":"S00575","t":"苍梧谣・归字谣","a":"张孝祥","c":["归。","十万人家儿样啼。","公归去，何日是来时。"],"p":"苍梧谣・归字谣"},{"id":"S00576","t":"苍梧谣・归字谣","a":"张孝祥","c":["归。","猎猎薰风飐绣旗。","拦教住，重举送行杯。"],"p":"苍梧谣・归字谣"},{"id":"S00577","t":"苍梧谣・归字谣","a":"张孝祥","c":["归。","数得宣麻拜相时。","秋前后，公衮更莱衣。"],"p":"苍梧谣・归字谣"},{"id":"S00578","t":"水调歌头","a":"张孝祥","c":["天上掌纶手，阃外折冲才。","发踪指示，平荡全楚息氛埃。","缓带轻裘多暇，燕寝森严兵卫，香篆几徘徊。","襦绔见歌咏，桃李藉栽培。","紫泥封，天笔润，日边来。","趣装入觐，行矣归去作盐梅。","祖帐不须遮道，看取眉间一点，喜气入尊罍。","此去沙堤路，平步上三台。"],"p":"水调歌头"},{"id":"S00579","t":"水调歌头","a":"张孝祥","c":["客里送行客，常苦不胜情。","见公秣马东去，底事却欣欣。","不为青毡俯拾，自是公家旧物，何必更关心。","且喜谢安石，重起为苍生。","圣天子，方侧席，选豪英。","日边仍有知己，应剡荐章间。","好把文经武略，换取碧幢红旆，谈笑扫胡尘。","勋业在此举，莫厌短长亭。"],"p":"水调歌头"},{"id":"S00580","t":"木兰花・玉楼春","a":"张孝祥","c":["拥貔貅万骑，聚千里、铁衣寒。","正玉帐连云，油幢映日，飞箭天山。","锦城起方面重，对筹壶、尽日雅歌闲。","休遣沙场虏骑，尚馀匹马空还。","那看。","更值春残。","斟绿醑、对朱颜。","正宿雨催红，和风换翠，梅小香悭。","牙旗渐西去也，望梁州、故垒暮云间。","休使佳人敛黛，断肠低唱阳关。"],"p":"木兰花・玉楼春"},{"id":"S00581","t":"雨中花・夜行船","a":"张孝祥","c":["一舸凌风，斗酒酹江，翩然乘兴东游。","欲吐平生孤愤，壮气横秋。","浩荡锦囊诗卷，从容玉帐兵筹。","有当时桥下，取履仙翁，谈笑同舟。","先贤济世，偶耳功名，事成岂为封留。","何况我、君恩深重，欲报无由。","长望东南气王，从教西北云浮。","断鸿万里，不堪回首，赤县神州。"],"p":"雨中花・夜行船"},{"id":"S00582","t":"鹧鸪天","a":"张孝祥","c":["可意黄花人不知。","黄花标格世间稀。","园葵裛露迎朝日，槛菊迎霜媚夕霏。","芍药好，是金丝。","绿藤红刺引蔷薇。","姚家别有神仙品，似着天香染御衣。"],"p":"鹧鸪天"},{"id":"S00583","t":"眼儿媚","a":"张孝祥","c":["晓来江上荻花秋。","做弄个离愁。","半竿残日，两行珠泪，一叶扁舟。","须知此去应难遇，直待醉方休。","如今眼底，明朝心上，后日眉头。"],"p":"眼儿媚"},{"id":"S00584","t":"虞美人","a":"张孝祥","c":["清宫初入韶华管。","宫叶秋声满。","满庭芳草月婵娟。","想见明朝喜色、动天颜。","持杯满劝龙头客。","荣遇时难得。","词源三峡泻瞿塘。","便是醉中空去、也无妨。"],"p":"虞美人"},{"id":"S00585","t":"菩萨蛮","a":"张孝祥","c":["史君家枕吴波碧。","朱门铺手摇双戟。","也到岭边州。","真成汗漫游。","归期应不远。","趁得东江暖。","翁媪雪垂肩。","双双平地仙。"],"p":"菩萨蛮"},{"id":"S00586","t":"临江仙","a":"张孝祥","c":["罨画楼前初立马，隔帘笑语相亲。","铅华洗尽见天真。","衫儿轻罩雾，髻子直梳云。","翠叶银丝簪末利，樱桃澹住香唇。","见人不语解留人。","数杯愁里酒，两眼醉时春。"],"p":"临江仙"},{"id":"S00587","t":"浣溪沙","a":"张孝祥","c":["我是临川旧史君。","而今欲作岭南人。","重来辽鹤事犹新。","去路政长仍酷暑，主公交契更情亲。","横秋阁上晚风匀。"],"p":"浣溪沙"},{"id":"S00588","t":"浣溪沙","a":"张孝祥","c":["康乐亭前种此君。","重来风月苦留人。","儿童竹马笑谈新。","今代孟士仍好客，政成归去眷方新。","十眉环坐晚妆匀。"],"p":"浣溪沙"},{"id":"S00589","t":"西江月","a":"张孝祥","c":["十里轻红自笑，两山浓翠相呼。","意行着脚到精庐。","借我绳床小住。","解饮不妨文字，无心更狎鸥鱼。","一声长啸暮烟孤。","袖手西湖归去。"],"p":"西江月"},{"id":"S00590","t":"忆秦娥","a":"张孝祥","c":["天一角。","南枝向我情如昨。","情如昨。","水寒烟淡，雾轻云薄。","吹花嚼蕊愁无托。","年华冉冉惊离索。","惊离索。","倩春留住，莫教摇落。"],"p":"忆秦娥"},{"id":"S00591","t":"浣溪沙","a":"张孝祥","c":["湓浦从君已十年。","京江仍许借归船。","相逢此地有因缘。","十万貔貅环武帐，三千珠翠入歌筵。","功成去作地行仙。"],"p":"浣溪沙"},{"id":"S00592","t":"柳梢青","a":"张孝祥","c":["碧云风月无多。","莫被名缰利锁。","白玉为车，黄金作印，不恋休呵。","争如对酒当歌。","人是人非恁么。","年少甘罗，老成吕望，必竟如何。"],"p":"柳梢青"},{"id":"S00593","t":"卜算子","a":"张孝祥","c":["万里去担簦，谁识新丰旅。","好事些儿说与郎，奴是姮娥侣。","若到广寒宫，但道奴传语。","待我仙郎折桂枝，拣个高枝与。"],"p":"卜算子"},{"id":"S00594","t":"柳梢青","a":"张孝祥","c":["草底蛩吟。","烟横水际，月澹松阴。","荷动香浓，竹深凉早，销尽烦襟。","发稀浑不胜簪。","更客里、吴霜暗侵。","富贵功名，本来无意，何况如今。"],"p":"柳梢青"},{"id":"S00595","t":"瑞鹧鸪","a":"张孝祥","c":["香佩潜分紫绣囊。","野塘波急折鸳鸯。","春风灞岸空回首，落日西陵更断肠。","雪下哦诗怜谢女，花间为令胜潘郎。","从今千里同明月，再约圜时拜夜香。"],"p":"瑞鹧鸪"},{"id":"S00596","t":"青玉案","a":"张孝祥","c":["相春堂上闻莺语。","正花柳、芳菲处。","有底尊前欢且舞。","满堂宾客，紫泥丹诏，衮衮烟霄路。","君王天纵资仁武。","要尺箠、平骄虏。","思得英雄亲驾驭。","将军行矣，九重虚宁，谈笑清寰宇。"],"p":"青玉案"},{"id":"S00597","t":"念奴娇","a":"张孝祥","c":["海云四敛，太清楼、极目一天秋色。","明月飞来云雾尽，城郭山川历历。","良夜悠悠，西风袅袅，银汉冰轮侧。","云霓三弄，广寒宫殿长笛。","偏照紫府瑶台，香笼玉座，翠霭迷南北。","天上人间凝望处，应有乘风归客。","露滴金盘，凉生玉宇，满地新霜白。","壶中清赏，画檐高挂虚碧。"],"p":"念奴娇"},{"id":"S00598","t":"念奴娇","a":"张孝祥","c":["风帆更起，望一天秋色，离愁无数。","明日重阳尊酒里，谁与黄花为主。","别岸风烟，孤舟灯火，今夕知何处。","不如江月，照伊清夜同去。","船过采石江边，望夫山下，酌水应怀古。","德耀归来虽富贵，忍弃平生荆布。","默想音容，遥怜儿女，独立衡皋暮。","桐乡君子，念予憔悴如许。"],"p":"念奴娇"},{"id":"S00599","t":"蓦山溪","a":"张孝祥","c":["雄风豪雨，时节清明近。","帘幕起轻寒，暖红炉、笑翻灰烬。","阴藏迟日，欲验几多长，绣工慵，围棋倦，香篆频销印。","茂林芳径，绿变红添润。","桃杏意酣酣，占前头、一番花信。","华堂尊酒，但作艳阳歌，禽声喜，流云尽，明日春游俊。"],"p":"蓦山溪"},{"id":"S00600","t":"导引","a":"和岘","c":["气和玉烛，睿化著鸿明。","缇管一阳生。","郊禋盛礼燔柴毕，旋轸凤凰城。","森罗仪卫振华缨。","载路溢欢声。","皇图大业超前古，垂象泰阶平。","岁时丰衍，九土乐升平。","睹寰海澄清。","道高尧舜垂衣治，日月并文明。","嘉禾甘露登歌荐，云物焕祥经。","兢兢惕惕持谦德，未许禅云亭。"],"p":"导引"},{"id":"S00601","t":"六州","a":"和岘","c":["严夜警，铜莲漏迟迟。","清禁肃，森陛戟，羽卫俨皇闱。","角声励，钲鼓攸宜。","金管成雅奏，逐吹逶迤。","荐苍璧，郊祀神祗。","属景运纯禧。","京坻丰衍，群材乐育，诸侯述职，盛德服蛮夷。","殊祥萃，九苞丹凤来仪。","膏露降，和气洽，三秀焕灵芝。","鸿猷播，史册相辉。","张四维。","卜世永固丕基。","敷玄化，荡荡无为。","合尧舜文思。","混并寰宇，休牛归马，销金偃革，蹈咏庆昌期。"],"p":"六州"},{"id":"S00602","t":"十二时・忆少年","a":"和岘","c":["承宝运，驯致隆平。","鸿庆被寰瀛。","时清俗阜，治定功成。","遐迩咏由庚。","严郊祀，文物声明。","会天正、星拱奏严更。","布羽仪簪缨。","宸心虔洁，明德播惟馨。","动苍冥。","神降享精诚。","燔柴半，万乘移天仗，肃銮辂旋衡。","千官云拥，群后葵倾。","玉帛旅明庭。","韶濩荐，金奏谐声。","集休亨。","皇泽浃黎庶，普率洽恩荣。","仰钦元后，睿圣贯三灵。","万邦宁。","景贶福千龄。"],"p":"十二时・忆少年"},{"id":"S00603","t":"点绛唇","a":"王禹","c":["雨恨云愁，江南依旧称佳丽。","水村渔市。","一缕孤烟细。","天际征鸿，遥认行如缀。","平生事。","此时凝睇。","谁会凭阑意。"],"p":"点绛唇"},{"id":"S00604","t":"越江吟","a":"苏易简","c":["神仙神仙瑶池宴。","片片。","碧桃零落春风晚。","翠云开处，隐隐金舆挽。","玉麟背冷清风远。"],"p":"越江吟"},{"id":"S00605","t":"甘草子","a":"寇准","c":["春早。","柳丝无力，低拂清门道。","暖日笼啼鸟。","初坼桃花小。","遥望碧天净如扫。","曳一缕、轻烟缥缈。","堪惜流年谢芳草。","任玉壶倾倒。"],"p":"甘草子"},{"id":"S00606","t":"踏莎行","a":"寇准","c":["春色将阑，莺声渐老。","红英落尽青梅小。","画堂人静雨蒙蒙，屏山半掩馀香袅。","密约沈沈，离情杳杳。","菱花尘满慵将照。","倚楼无语欲销魂，长空黯淡连芳草。"],"p":"踏莎行"},{"id":"S00607","t":"阳关引","a":"寇准","c":["塞草烟光阔。","渭水波声咽。","春朝雨霁轻尘歇。","征鞍发。","指青青杨柳，又是轻攀折。","动黯然、知有后会甚时节。","更尽一杯酒，歌一阕。","叹人生，最难欢聚易离别。","且莫辞沉醉，听取阳关彻。","念故人、千里自此共明月。"],"p":"阳关引"},{"id":"S00608","t":"点绛唇","a":"寇准","c":["水陌轻寒，社公雨足东风慢。","定巢新燕。","湿雨穿花转。","象尺熏炉，拂晓停针线。","愁蛾浅。","飞红零乱。","侧卧珠帘卷。"],"p":"点绛唇"},{"id":"S00609","t":"木兰花・玉楼春","a":"钱惟演","c":["城上风光莺语乱。","城下烟波春拍岸。","绿杨芳草几时休，泪眼愁肠先已断。","情怀渐变成衰晚。","鸾鉴朱颜惊暗换。","昔年多病厌芳尊，今日芳尊惟恐浅。"],"p":"木兰花・玉楼春"},{"id":"S00610","t":"玉楼春","a":"钱惟演","c":["锦箨参差朱槛曲。","露濯文犀和粉绿。","未容浓翠伴桃红，已许纤枝留凤宿。","嫩似春荑明似玉。","一寸芳心谁管束。","劝君速吃莫踟蹰，看被南风吹作竹。"],"p":"玉楼春"},{"id":"S00611","t":"踏莎行","a":"陈尧佐","c":["二社良辰，千家庭院。","翩翩又见新来燕。","凤凰巢稳许为邻，潇湘烟暝来何晚。","乱入红楼，低飞绿岸。","画梁时拂歌尘散。","为谁归去为谁来，主人恩重珠帘卷。"],"p":"踏莎行"},{"id":"S00612","t":"凤栖梧・蝶恋花","a":"丁谓","c":["十二层楼春色早。","三殿笙歌，九陌风光好。","堤柳岸花连复道。","玉梯相对开蓬岛。","莺啭乔林鱼在藻。","太液微波，绿斗王孙草。","南阙万人瞻羽葆。","后天祝圣天难老。"],"p":"凤栖梧・蝶恋花"},{"id":"S00613","t":"凤栖梧・蝶恋花","a":"丁谓","c":["朱阙玉城通阆苑。","月桂星榆，春色无深浅。","潇瑟篌笙仙客宴。","蟠桃花满蓬莱殿。","九色明霞裁羽扇。","云雾为车，鸾鹤骖雕辇。","路指瑶池归去晚。","壶中日月如天远。"],"p":"凤栖梧・蝶恋花"},{"id":"S00614","t":"相思令・相思儿令","a":"林逋","c":["吴山青。","越山青。","两岸青山相对迎。","争忍有离情。","君泪盈。","妾泪盈。","罗带同心结未成。","江边潮已平。"],"p":"相思令・相思儿令"},{"id":"S00615","t":"点绛唇","a":"林逋","c":["金谷年年，乱生春色谁为主。","馀花落处。","满地和烟雨。","又是离歌，一阕长亭暮。","王孙去。","萋萋无数。","南北东西路。"],"p":"点绛唇"},{"id":"S00616","t":"霜天晓角","a":"林逋","c":["冰清霜洁。","昨夜梅花发。","甚处玉龙三弄，声摇动、枝头月。","梦绝。","金兽𦶟。","晓寒兰烬灭。","要卷珠帘清赏，且莫扫、阶前雪。"],"p":"霜天晓角"},{"id":"S00617","t":"瑞鹧鸪","a":"林逋","c":["众芳摇落独鲜妍。","占尽风情向小园。","疏影横斜水清浅，暗香浮动月黄昏。","寒禽欲下先偷眼，粉蝶如知合断魂。","幸有微吟可相狎，不须檀板共金尊。"],"p":"瑞鹧鸪"},{"id":"S00618","t":"少年游","a":"杨亿","c":["江南节物，水昏云淡，飞雪满前村。","千寻翠岭，一枝芳艳，迢递寄归人。","寿阳妆罢，冰姿玉态，的的写天真。","等闲风雨又纷纷。","更忍向、笛中闻。"],"p":"少年游"},{"id":"S00619","t":"生查子","a":"陈亚","c":["朝庭数擢贤，旋占凌霄路。","自是郁陶人，险难无移处。","也知没药疗饥寒，食薄何相误。","大幅纸连粘，甘草归田赋。"],"p":"生查子"},{"id":"S00620","t":"生查子","a":"陈亚","c":["相思意已深，白纸书难足。","字字苦参商，故要槟郎读。","分明记得约当归，远至樱桃熟。","何事菊花时，犹未回乡曲。"],"p":"生查子"},{"id":"S00621","t":"生查子","a":"陈亚","c":["小院雨馀凉，石竹风生砌。","罢扇尽从容，半下纱厨睡。","起来闲坐北亭中，滴尽真珠泪。","为念婿辛勤，去折蟾宫桂。"],"p":"生查子"},{"id":"S00622","t":"生查子","a":"陈亚","c":["浪荡去未来，踯躅花频换。","可惜石榴裙，兰麝香销半。","琵琶闲抱理相思，必拨朱弦断。","拟续断朱弦，待这冤家看。"],"p":"生查子"},{"id":"S00623","t":"喜迁莺","a":"夏竦","c":["霞散绮，月沈钩。","帘卷未央楼。","夜凉河汉截天流。","宫阙锁清秋。","瑶阶曙。","金盘露。","凤髓香和烟雾。","三千珠翠拥宸游。","水殿按《凉州》。"],"p":"喜迁莺"},{"id":"S00624","t":"鹧鸪天","a":"夏竦","c":["镇日无心扫黛眉。","临行愁见理征衣。","尊前只恐伤郎意，阁泪汪汪不敢垂。","停宝马，捧瑶卮。","相斟相劝忍分离。","不如饮待奴先醉，图得不知郎去时。"],"p":"鹧鸪天"},{"id":"S00625","t":"多丽","a":"聂冠卿","c":["想人生，美景良辰堪惜。","问其间、赏心乐事，就中难是并得。","况东城、凤台沙苑，泛晴波、浅照金碧。","露洗华桐，烟霏丝柳，绿阴摇曳，荡春一色。","画堂迥、玉簪琼佩，高会尽词客。","清欢久、重然绛蜡，别就瑶席。","有翩若轻鸿体态，暮为行雨标格。","逞朱唇、缓歌妖丽，似听流莺乱花隔。","慢舞萦回，娇鬟低亸，腰肢纤细困无力。","忍分散、彩云归后，何处更寻觅。","休辞醉，明月好花，莫谩轻掷。"],"p":"多丽"},{"id":"S00626","t":"望汉月・忆汉月","a":"李遵","c":["黄菊一丛临砌。","颗颗露珠装缀。","独教冷落向秋天，恨东君不曾留意。","雕阑新雨霁。","绿藓上，乱铺金蕊。","此花开后更无花，愿爱惜、莫同桃李。"],"p":"望汉月・忆汉月"},{"id":"S00627","t":"滴滴金","a":"李遵","c":["帝城五夜宴游歇。","残灯外、看残月。","都人犹在醉乡中，听更漏初彻。","行乐已成闲话说。","如春梦、觉时节。","大家同约探春行，问甚花先发。"],"p":"滴滴金"},{"id":"S00628","t":"剔银灯","a":"沈邈","c":["一夜隋河风劲。","霜湿水天如镜。","古柳堤长，寒烟不起，波上月无流影。","那堪频听。","疏星外、离鸿相应。","须信道、情多是病。","酒未到、愁肠还醒。","数叠兰衾，馀香未减，甚时枕鸳重并。","教伊须更。","将盟誓、后约言定。"],"p":"剔银灯"},{"id":"S00629","t":"剔银灯","a":"沈邈","c":["江上秋高霜早。","云静月华如扫。","候雁初飞，啼螀正苦，又是黄花衰草。","等闲临照。","潘郎鬓、星星易老。","那堪更、酒醒孤棹。","望千里、长安西笑。","臂上妆痕，胸前泪粉，暗惹离愁多少。","此情谁表。","除非是、重相见了。"],"p":"剔银灯"},{"id":"S00630","t":"长相思","a":"杨适1","c":["南山明。","北山明。","中有长亭号丈亭。","沙边供送迎。","东江清。","西江清。","海上潮来两岸平。","行人分棹行。"],"p":"长相思"},{"id":"S00631","t":"临江仙","a":"滕宗谅","c":["湖水连天天连水，秋来分外澄清。","君山自是小蓬瀛。","气蒸云梦泽，波撼岳阳城。","帝子有灵能鼓瑟，凄然依旧伤情。","微闻兰芝动芳馨。","曲终人不见，江上数峰青。"],"p":"临江仙"},{"id":"S00632","t":"满江红","a":"张","c":["无利无名，无荣无辱，无烦无恼。","夜灯前、独歌独酌，独吟独笑。","况值群山初雪满，又兼明月交光好。","便假饶百岁拟如何，从他老。","知富贵，谁能保。","知功业，何时了。","算箪瓢金玉，所争多少。","一瞬光阴何足道，但思行乐常不早。","待春来携酒𣨼东风，眠芳草。"],"p":"满江红"},{"id":"S00633","t":"离亭燕・离亭宴","a":"张","c":["一带江山如画。","风物向秋潇洒。","水浸碧天何处断，翠色冷光相射。","蓼岸荻花中，隐映竹篱茅舍。","天际客帆高挂。","门外酒旗低迓。","多少六朝兴废事，尽入渔樵闲话。","怅望倚危栏，红日无言西下。"],"p":"离亭燕・离亭宴"},{"id":"S00634","t":"水调歌头","a":"张","c":["雪月两相映，水石互悲鸣。","不知岩上枯木，今夜若为情。","应见尘中胶扰，便道山间空旷，与么了平生。","与么平生了，□水不流行。","起披衣，瞻碧汉，露华清。","寥寥千载，此事本分明。","若向乾坤识易，便信行藏无间，处处总圆成。","记取渊冰语，莫错定盘星。"],"p":"水调歌头"},{"id":"S00635","t":"水调歌头","a":"张","c":["雨后烟景绿，春水涨桃花。","系舟溪上，笋舆十里达平沙。","路转峰回胜处，无数青荧玉树，飘缈羽人家。","楼观倚空碧，水竹湛清华。","纵幽寻，携蜡屐，上苍霞。","古仙何在，空馀药灶委岩洼。","他日倘然归老，乞取一庵云卧，随分了生涯。","底用更辛苦，九转炼黄芽。"],"p":"水调歌头"},{"id":"S00636","t":"诉衷情","a":"王益","c":["烧残绛蜡泪成痕。","街鼓报黄昏。","碧云又阻来信，廊上月侵门。","愁永夜，拂香裀。","待谁温。","梦兰憔悴，掷果凄凉，两处销魂。"],"p":"诉衷情"},{"id":"S00637","t":"鹊桥仙","a":"石延年","c":["一分素景，千家新月，凉露楼台遍洗。","宝奁深夜结蛛丝，纴五孔、金针不寐。"],"p":"鹊桥仙"},{"id":"S00638","t":"燕归梁","a":"石延年","c":["芳草年年惹恨幽。","想前事悠悠。","伤春伤别几时休。","算从古、为风流。","春山总把，深匀翠黛，千叠在眉头。","不知供得几多愁。","更斜日、凭危楼。"],"p":"燕归梁"},{"id":"S00639","t":"迷仙引","a":"关咏","c":["春阴霁。","岸柳参差，袅袅金丝细。","画阁昼眠莺唤起。","烟光媚。","燕燕双高，引愁人如醉。","慵缓步，眉敛金铺倚。","嘉景易失，懊恼韶光改。","花空委。","忍厌厌地。","施朱粉，临鸾鉴，腻香销减摧桃李。","独自个凝睇。","暮云暗、遥山翠。","天色无情，四远低垂淡如水。","离恨托、征鸿寄。","旋娇波、暗落相思泪。","妆如洗。","向高楼、日日春风里。","悔凭阑、芳草人千里。"],"p":"迷仙引"},{"id":"S00640","t":"水调歌头","a":"刘潜","c":["六郡酒泉。"],"p":"水调歌头"},{"id":"S00641","t":"六州歌头","a":"刘潜","c":["秦亡草昧，刘项起吞并。","驱龙虎。","鞭寰宇。","斩长鲸。","扫欃枪。","血染彭门战。","视馀耳，皆鹰犬。","平祸乱。","归炎汉。","势奔倾。","兵散月明。","风急旌旗乱，刁斗三更。","命虞姬相对，泣听楚歌声。","玉帐魂惊。","泪盈盈。","恨花无主。","凝愁绪。","挥雪刃，掩泉扃。","时不利。","骓不逝。","困阴陵。","叱追兵。","喑呜摧天地，望归路，忍偷生。","功盖世。","成闲纪。","建遗灵。","江静水寒烟冷，波纹细、古木凋零。","遣行人到此，追念痛伤情。","胜负难凭。"],"p":"六州歌头"},{"id":"S00642","t":"水调歌头","a":"刘潜","c":["落日塞垣路，风劲戛貂裘。","翩翩数骑闲猎，深入黑山头。","极目平沙千里，惟见雕弓白羽，铁面骇骅骝。","隐隐望青冢，特地起闲愁。","汉天子，方鼎盛，四百州。","玉颜皓齿，深锁三十六宫秋。","堂有经纶贤相，边有纵横谋将，不作翠蛾羞。","戎虏和乐也，圣主永无忧。"],"p":"水调歌头"},{"id":"S00643","t":"蝶恋花","a":"李冠","c":["遥夜亭皋闲信步。","才过清明，渐觉伤春暮。","数点雨声风约住。","朦胧淡月云来去。","桃杏依稀香暗渡。","谁在秋千，笑里轻轻语。","一寸相思千万绪。","人间没个安排处。"],"p":"蝶恋花"},{"id":"S00644","t":"六州歌头","a":"李冠","c":["凄凉绣岭，宫殿倚山阿。","明皇帝。","曾游地。","锁烟萝。","郁嵯峨。","忆惜真妃子。","艳倾国，方姝丽。","朝复暮。","嫔嫱妒。","宠偏颇。","三尺玉泉新浴，莲羞吐、红浸秋波。","听花奴，敲羯鼓，酣奏鸣鼍。","体不胜罗。","舞婆娑。","正霓裳曳。","惊烽燧。","千万骑。","拥雕戈。","情宛转。","魂空乱。","蹙双蛾。","奈兵何。","痛惜三春暮，委妖丽，马嵬坡。","平寇乱。","回宸辇。","忍重过。","香瘗紫囊犹有，鸿都客、钿合应讹。","使行人到此，千古只伤歌。","事往愁多。"],"p":"六州歌头"},{"id":"S00645","t":"六州歌头","a":"李冠","c":["秦亡草昧，刘项起吞并。","鞭寰宇。","驱龙虎。","扫欃枪。","斩长鲸。","雪染中原战。","视馀耳，皆鹰犬。","平祸乱。","归炎汉。","势奔倾。","兵散月明。","风急旌旗乱，刁斗三更。","共虞姬相对，泣听楚歌声。","玉帐魂惊。","泪盈盈。","念花无主。","凝愁苦。","挥雪刃，掩泉扃。","时不利。","骓不逝。","困阴陵。","叱追兵。","呜喑摧天地，望归路，忍偷生。","功盖世，何处见遗灵。","江静水寒烟冷，波纹钿、古木凋零。","遣行人到此，追念益伤情。","胜负难凭。"],"p":"六州歌头"},{"id":"S00646","t":"蝶恋花","a":"李冠","c":["贴鬓香云双绾绿。","柳弱花娇，一点春心足。","不肯玉箫闲度曲。","恼人特把青蛾蹙。","静夜溪桥霜薄屋。","独影行歌，惊起双鸾宿。","愁破酒阑闺梦熟。","月斜窗外风敲竹。"],"p":"蝶恋花"},{"id":"S00647","t":"菩萨蛮","a":"谢绛","c":["娟娟侵鬓妆痕浅。","双眸相媚弯如翦。","一瞬百般宜。","无论笑与啼。","酒阑思翠被。","特故瞢腾地。","生怕促归轮。","微波先注人。"],"p":"菩萨蛮"},{"id":"S00648","t":"夜行船","a":"谢绛","c":["昨夜佳期初共。","鬓云低、翠翘金凤。","尊前和笑不成歌，意偷转、眼波微送。","草草不容成楚梦。","渐寒深、翠帘霜重。","相看送到断肠时，月西斜、画楼钟动。"],"p":"夜行船"},{"id":"S00649","t":"诉衷情","a":"谢绛","c":["银缸夜永影长孤。","香草续残炉。","倚屏脉脉无语，粉泪不成珠。","双粲枕，百娇壶。","忆当初。","君恩莫似，秋叶无情，欲向人疏。"],"p":"诉衷情"},{"id":"S00650","t":"木兰花令","a":"贾昌朝","c":["都城水绿嬉游处。","仙棹往来人笑语。","红随远浪泛桃花，雪散平堤飞柳絮。","东君欲共春归去。","一阵狂风和骤雨。","碧油红旆锦障泥，斜日画桥芳草路。"],"p":"木兰花令"},{"id":"S00651","t":"水调歌头","a":"尹洙","c":["万倾太湖上，朝暮浸寒光。","吴王去后，台榭千古锁悲凉。","谁信蓬山仙子，天与经纶才器，等闲厌名缰。","敛翼下霄汉，雅意在沧浪。","晚秋里，烟寂静，雨微凉。","危亭好景，佳树修竹绕回塘。","不用移舟酌酒，自有青山渌水，掩映似潇湘。","莫问平生意，别有好思量。"],"p":"水调歌头"},{"id":"S00652","t":"苏幕遮","a":"梅尧臣","c":["露堤平，烟墅杳。","乱碧萋萋，雨后江天晓。","独有庾郎年最少。","窣地春袍，嫩色宜相照。","接长亭，迷远道。","堪怨王孙，不记归期早。","落尽梨花春又了。","满地残阳，翠色和烟老。"],"p":"苏幕遮"},{"id":"S00653","t":"玉楼春","a":"梅尧臣","c":["天然不比花含粉。","约月眉黄春色嫩。","小桥低映欲迷人，闲倚东风无奈困。","烟姿最与章台近。","冉冉千丝谁结恨。","狂莺来往恋芳阴，不道风流真能尽。"],"p":"玉楼春"},{"id":"S00654","t":"江南好・忆江南","a":"叶清臣","c":["丞相有才裨造化，圣皇宽诏养疏顽。","赢取十年闲。"],"p":"江南好・忆江南"},{"id":"S00655","t":"贺圣朝","a":"叶清臣","c":["满斟绿醑留君住。","莫匆匆归去。","三分春色二分愁，更一分风雨。","花开花谢、都来几许。","且高歌休诉。","不知来岁牡丹时，再相逢何处。"],"p":"贺圣朝"},{"id":"S00656","t":"折红梅","a":"吴感","c":["喜冰澌初泮，微和渐入、东郊时节。","春消息，夜来顿觉，红梅数枝争发。","玉溪仙馆，不是个、寻常标格。","化工别与、一种风情，似匀点胭脂，染成香雪。","重吟细阅。","比繁杏夭桃，品格真别。","只愁共、彩云易散，冷落谢池风月。","凭谁向说。","三弄处、龙吟休咽。","大家留取，时倚阑干，闻有花堪折，劝君须折。"],"p":"折红梅"},{"id":"S00657","t":"映山红","a":"文彦博","c":["遂请后。","愿频醉、石楼溪口。"],"p":"映山红"},{"id":"S00658","t":"南乡子","a":"荣","c":["江上野梅芳。","粉色盈盈照路傍。","闲折一枝和雪嗅，思量。","似个人人玉体香。","特地起愁肠。","此恨谁人与寄将。","山馆寂寥天欲暮，凄凉。","人转迢迢路转长。"],"p":"南乡子"},{"id":"S00659","t":"定风波","a":"王琪","c":["把酒花前欲问天。","春来秋去苦茫然。","风雨满枝花满地。","何事。","却教纤草占流年。","试把钿筝重促柱。","无绪。","酒阑清泪滴朱弦。","赖有玉人相顾好。","轻笑。","却疑春色在婵娟。"],"p":"定风波"},{"id":"S00660","t":"祝英台・祝英台近","a":"王琪","c":["可堪妒柳羞花，下床都懒，便瘦也教春知道。"],"p":"祝英台・祝英台近"},{"id":"S00661","t":"望江南・忆江南","a":"王琪","c":["江南柳，烟穗拂人轻。","愁黛空长描不似，舞腰虽瘦学难成。","天意与风情。","攀折处，离恨几时平。","已纵柔条萦客棹，更飞狂絮扑旗亭。","三月乱莺声。"],"p":"望江南・忆江南"},{"id":"S00662","t":"望江南・忆江南","a":"王琪","c":["江南酒，何处味偏浓。","醉卧春风深巷里，晓寻香旆小桥东。","竹叶满金锺。","檀板醉，人面粉生红。","青杏黄梅朱阁上，鲥鱼苦笋玉盘中。","酩酊任愁攻。"],"p":"望江南・忆江南"},{"id":"S00663","t":"一络索・一落萦","a":"陈凤仪","c":["蜀江春色浓如雾。","拥双旌归去。","海棠也似别君难，一点点、啼红雨。","此去马蹄何处。","沙堤新路。","禁林赐宴赏花时，还忆著、西楼否。"],"p":"一络索・一落萦"},{"id":"S00664","t":"水调歌头","a":"苏舜钦","c":["潇洒太湖岸，淡伫洞庭山。","鱼龙隐处，烟雾深锁渺弥间。","方念陶朱张翰，忽有扁舟急桨，撇浪载鲈还。","落日暴风雨，归路绕汀湾。","丈夫志，当景盛，耻疏闲。","壮年何事憔悴，华发改朱颜。","拟借寒潭垂钓，又恐鸥鸟相猜，不肯傍青纶。","刺棹穿芦荻，无语看波澜。"],"p":"水调歌头"},{"id":"S00665","t":"永遇乐","a":"解","c":["风暖莺娇，露浓花重，天气和煦。","院落烟收，垂杨舞困，无奈堆金缕。","谁家巧纵，青楼弦管，惹起梦云情绪。","忆当时、纹衾粲枕，未尝暂孤鸳侣。","芳菲易老，故人难聚。","到此翻成轻误。","阆苑仙遥，蛮笺纵写、何计传深诉。","青山绿水，古今长在，惟有旧欢何处。","空赢得、斜阳暮草，淡烟细雨。"],"p":"永遇乐"},{"id":"S00666","t":"阳台梦","a":"解","c":["仙姿本寓。","十二峰前住。","千里行云行雨。","偶因鹤驭过巫阳。","邂逅他、楚襄王。","无端宋玉夸才赋。","诬诞人心素。","至今狂客到阳台。","也有痴心，望妾入、梦中来。"],"p":"阳台梦"},{"id":"S00667","t":"点绛唇","a":"韩琦","c":["病起恹恹，画堂花谢添憔悴。","乱红飘砌。","滴尽胭脂泪。","惆怅前春，谁向花前醉。","愁无际。","武陵回睇。","人远波空翠。"],"p":"点绛唇"},{"id":"S00668","t":"维扬好","a":"韩琦","c":["二十四桥千步柳，春风十里上珠帘。"],"p":"维扬好"},{"id":"S00669","t":"安阳好・忆江南","a":"韩琦","c":["安阳好，形势魏西州。","曼衍山川环故国，升平歌吹沸高楼。","和气镇飞浮。","笼画陌，乔木几春秋。","花外轩窗排远岫，竹间门巷带长流。","风物更清幽。"],"p":"安阳好・忆江南"},{"id":"S00670","t":"安阳好・忆江南","a":"韩琦","c":["安阳好，戟户使君宫。","白昼锦衣清宴处，铁楹丹榭画图中。","壁记旧三公。","棠讼悄，池馆北园通。","夏夜泉声来枕簟，春来花气透帘栊。","行乐兴何穷。"],"p":"安阳好・忆江南"},{"id":"S00671","t":"失调名","a":"沈唐","c":["不是这，下辈无礼，都缘是我，自家遭逢。"],"p":"失调名"},{"id":"S00672","t":"雨中花・夜行船","a":"沈唐","c":["有谁念我、如今霜鬓，远赴边堠。","……身在碧云西畔，情随陇水东流。"],"p":"雨中花・夜行船"},{"id":"S00673","t":"霜叶飞","a":"沈唐","c":["霜林凋晚，危楼迥，登临无限秋思。","望中闲想，洞庭波面，乱红初坠。","更萧索、风吹渭水。","长安飞舞千门里。","变景摧芳榭，唯有兰衰暮丛，菊残馀蕊。","回念花满华堂，美人一去，镇掩香闺经岁。","又观珠露，碎点苍苔，败梧飘砌。","谩赢得、相思泪眼，东君早作归来计。","便莫惜丹青手，重与芳菲，万红千翠。"],"p":"霜叶飞"},{"id":"S00674","t":"念奴娇","a":"沈唐","c":["杏花过雨，渐残红零落，胭脂颜色。","流水飘香人渐远，难托春心脉脉。","恨别王孙，墙阴目断，手把青梅摘。","金鞍何处，绿杨依旧南陌。","消散云雨须臾，多情因甚，有轻离轻拆。","燕语千般，争解说、些子伊家消息。","厚约深盟，除非重见，见了方端的。","而今无奈，寸肠千恨堆积。"],"p":"念奴娇"},{"id":"S00675","t":"鹤冲天","a":"杜安世","c":["清明天气。","永日愁如醉。","台榭绿阴浓，薰风细。","燕子巢方就，盆池小，新荷蔽。","恰是逍遥际。","单夹衣裳，半栊软玉肌体。","石榴美艳，一撮红绡比。","窗外数修篁，寒相倚。","有个关心处，难相见、空凝睇。","行坐深闺里。","懒更妆梳，自知新来憔悴。"],"p":"鹤冲天"},{"id":"S00676","t":"两同心","a":"杜安世","c":["巍巍剑外，寒霜覆林枝。","望衰柳、尚色依依。","暮天静、雁阵高飞。","入碧云际。","江山秋色，遣客心悲。","蜀道巇崄行迟。","瞻京都迢递。","听巴峡、数声猿啼。","惟独个、未有归计。","谩空怅望，每每无言，独对斜晖。"],"p":"两同心"},{"id":"S00677","t":"玉阑干","a":"杜安世","c":["珠帘怕卷春残景。","小雨牡丹零欲尽。","庭轩悄悄燕高空，风飘絮、绿苔侵径。","欲将幽恨传愁信。","想后期、无个凭定。","几回独睡不思量，还悠悠、梦里寻趁。"],"p":"玉阑干"},{"id":"S00678","t":"浣溪沙","a":"杜安世","c":["模样偏宜掌上怜。","云如双鬓玉如颜。","身材轻妙眼儿单。","幽会未成双怅望，深情欲诉两艰难。","空教魂梦到巫山。"],"p":"浣溪沙"},{"id":"S00679","t":"折新荷引・折新荷","a":"赵","c":["雨过回廊，圆荷嫩绿新抽。","越女轻盈，画桡稳泛兰舟。","芳容艳粉，红香透、脉脉娇羞。","菱歌隐隐渐遥，依约回眸。","堤上郎心，波间妆影迟留。","不觉归时，淡天碧衬蟾钩。","风蝉噪晚，馀霞际、几点沙鸥。","渔笛、不道有人，独倚危楼。"],"p":"折新荷引・折新荷"},{"id":"S00680","t":"夜行船","a":"赵","c":["今夜阴云初霁。","画帘外、月华如水。","露霭晴空，风吹高树，满院中秋意。","皎皎蟾光当此际。","怎奈何、不成况味。","莫近檐间，休来窗上，且放离人睡。"],"p":"夜行船"},{"id":"S00681","t":"阮郎归","a":"赵","c":["留连春意晚花稠。","云疏雨未收。","新荷池面叶齐抽。","凉天醉碧楼。","能达理，有何愁。","心宽万事休。","人生还似水中沤。","金尊尽更酬。"],"p":"阮郎归"},{"id":"S00682","t":"谒金门","a":"赵","c":["天色晚。","云外一筝斜雁。","独凭阑干秋满眼。","菊花寒尚浅。","叶落香沟红泛。","懒把新诗题怨。","何处笛声三弄断。","月迟帘未卷。"],"p":"谒金门"},{"id":"S00683","t":"梅花曲","a":"刘几","c":["汉宫中侍女，娇额半涂黄。","盈盈粉色凌时，寒玉体、先透薄妆。","好借月魂来，娉婷画烛旁。","惟恐随、阳春好梦去，所思飞扬。","宜向风亭把盏，酬孤艳，醉永夕何妨。","雪径蕊、真凝密，降回舆、认暗香。","不为藉我作和羹，肯放结子花狂。","向上林，留此占年芳。"],"p":"梅花曲"},{"id":"S00684","t":"梅花曲","a":"刘几","c":["结子非贪，有香不俗，宜当鼎鼐尝。","偶先红紫，度韶华、玉笛占年芳。","众花杂色满上林，未能教、腊雪埋藏。","却怕春风漏泄，一一尽天香。","不须更御铅黄。","知国色，禀自天真殊常。","只裁云缕，奈芳滑、玉体想仙妆。","少陵为尔东阁。","美艳激诗肠。","当已阴未雨春光。","无心赋海棠。"],"p":"梅花曲"},{"id":"S00685","t":"梅花曲","a":"刘几","c":["浅浅池塘。","深深庭院，复出短短垣墙。","年年为尔，若九真巡会、宝惜流芳。","向人自有，绵渺无言，深意深藏。","倾国倾城，天教与、抵死芳香。","袅须金色，轻危欲压，绰约冠中央。","蒂团红蜡，兰肌粉艳巧能妆。","婵娟一种风流，如雪如冰衣霓裳。","永日依倚，春风笑野棠。"],"p":"梅花曲"},{"id":"S00686","t":"花发状元红慢","a":"刘几","c":["三春向暮，万卉成阴、有嘉艳方坼。","娇姿嫩质。","冠群品，共赏倾城倾国。","上苑晴昼暄，千素万红尤奇特。","绮筵开，会咏歌才子，压倒元白。","别有芳幽苞小，步障华丝，绮轩油壁。","与紫鸳鸯、素蛱蝶。","自清旦、往往连夕。","巧莺喧翠管，娇燕语雕梁留客。","武陵人，念梦役意浓，堪遣情溺。"],"p":"花发状元红慢"},{"id":"S00687","t":"减字木兰花","a":"元绛","c":["绿杨阴下。","短帽轻衫行信马。","过尽春风。","踏尽青青打尽红。","舞鸾歌凤。","人面湖光红影动。","醉眼归时。","人在朱楼曲角西。"],"p":"减字木兰花"},{"id":"S00688","t":"映山红慢","a":"元绛","c":["谷雨风前，占淑景、名花独秀。","露国色仙姿，品流第一，春工成就。","罗帏护日金泥皱。","映霞腮动檀痕溜。","长记得天上，瑶池阆苑曾有。","千匝绕、红玉阑干，愁只恐、朝云难久。","须款折、绣囊剩戴，细把蜂须频嗅。","佳人再拜抬娇面，敛红巾、捧金杯酒。","献千千寿。","愿长恁、天香满袖。"],"p":"映山红慢"},{"id":"S00689","t":"渔家傲","a":"程师孟","c":["折柳赠君君且住。"],"p":"渔家傲"},{"id":"S00690","t":"望江南・忆江南","a":"陈朴","c":["中黄宝，须向胆中求。","春帝令行生万物，乾坤膝下与吾俦。","百脉自流通。","施造化，左右火双抽。","浩浩腾腾充宇宙，苦烟袅袅上环楼。","夫妇渐相谋。"],"p":"望江南・忆江南"},{"id":"S00691","t":"望江南・忆江南","a":"陈朴","c":["玄珠降，丹窟在中宫。","九候息调重九数，赤波忽迸太阳东。","心肾始交通。","逢六变，重六息阴功。","火自海门朝帝坐，水从莲沼佐丁公。","紫电透玲珑。"],"p":"望江南・忆江南"},{"id":"S00692","t":"望江南・忆江南","a":"陈朴","c":["毛发落，丹左运行阳。","胎色渐红阴渐小，推移岁运助干刚。","育火养中央。","成物象，五岳辨微茫。","出入尚迟形尚小，晨昏天籁奏笙簧。","常饮玉壶浆。"],"p":"望江南・忆江南"},{"id":"S00693","t":"望江南・忆江南","a":"陈朴","c":["丹往右，四转运行阴。","逢六闭藏阳户气，玉关泉透合丁壬。","龟戏任浮沉。","时出入，无碍贯他心。","游戏神通常出面，圆光周匝绕千寻。","寒暑不相侵。"],"p":"望江南・忆江南"},{"id":"S00694","t":"西江月","a":"张伯端","c":["内药还同外药，内通外亦须通。","丹头和合类相同。","温养两般作用。","内有天然真火，炉中赫赫长红。","外炉增减要勤功。","妙绝无过真种。"],"p":"西江月"},{"id":"S00695","t":"西江月","a":"张伯端","c":["此道至神至圣，忧君分薄难消。","调和铅汞不终朝。","早睹玄珠形兆。","志士若能修炼，何妨在市居朝。","工夫容易药非遥。","说破人须失笑。"],"p":"西江月"},{"id":"S00696","t":"西江月","a":"张伯端","c":["白虎首经至宝，华池神水真金。","故知上善利源深。","不比寻常药品。","若要修成九转，先须炼己持心。","依时采取定浮沈。","进火须防危甚。"],"p":"西江月"},{"id":"S00697","t":"西江月","a":"张伯端","c":["若要真铅留汞，亲中不离家臣。","木金间隔会无因。","须仗媒人勾引。","本性爱金顺义，金情恋木慈仁。","相吞相陷却相亲。","始觉男儿有孕。"],"p":"西江月"},{"id":"S00698","t":"凤栖梧・蝶恋花","a":"卢氏","c":["蜀道青天烟霭翳。","帝里繁华、迢递何时至。","回望锦川挥粉泪。","凤钗斜亸乌云腻。","钿带双垂金缕细。","玉珮玎珰，露滴寒如水。","从此鸾妆添远意。","画眉学得遥山翠。"],"p":"凤栖梧・蝶恋花"},{"id":"S00699","t":"家山好","a":"刘述","c":["挂冠归去旧烟萝。","闲身健，养天和。","功名富贵非由我，莫贪他。","这歧路、足风波。","水晶宫里家山好，物外胜游多。","晴溪短棹，时时醉唱里棱罗。","天公奈我何。"],"p":"家山好"},{"id":"S00700","t":"合宫歌","a":"赵祯","c":["缵重明。","端拱保凝命。","广大孝休德，永锡四海有庆。","觚坛寓礼正典名。","幔室雅奏，彩仗崇制定。","五位仿古甚盛。","蒿宫光符辰星。","高秋嘉时款芎灵。","交累圣。","上下来顾，寅畏歆纯诚。","三阶平。","金气肃，转和景。","翠葆御双观，巽风兑泽布令。","脂茶刬荡墨索清。","远迩向附，动植咸遂性。","表里穆悦，庶政醇𬪩，熙然胥庭。","唐舜华封祝，如南山寿永。","愿今广怀宁延，昌基扃。"],"p":"合宫歌"},{"id":"S00701","t":"沁园春","a":"王拱辰","c":["华发青云。"],"p":"沁园春"},{"id":"S00702","t":"好事近","a":"蔡襄","c":["瑞雪满京都，宫殿尽成银阙。","常对素光遥望，是江梅时节。","如今江上见寒梅，幽香自清绝。","重看落英残艳，想飘零如雪。"],"p":"好事近"},{"id":"S00703","t":"踏莎行","a":"韩绛","c":["嵩峤云高，洛川波暖。","举头乔木森无断。","□□□雨绝风尘，小桥频过春渠满。","□□离宫，□棱斗焕。","万家罗绮多游伴。","□□□□自风□，□□是处喧弦管。"],"p":"踏莎行"},{"id":"S00704","t":"菩萨蛮","a":"李师中","c":["子规啼破城楼月。","画船晓载笙歌发。","两岸荔枝红。","万家烟雨中。","佳人相对泣。","泪下罗衣湿。","从此信音稀。","岭南无雁飞。"],"p":"菩萨蛮"},{"id":"S00705","t":"喜迁莺","a":"蔡挺","c":["霜天清晓。","望紫塞古垒，寒云衰草。","汗马嘶风，边鸿翻月，垅上铁衣寒早。","剑歌骑曲悲壮，尽道君恩难报。","塞垣乐，尽双鞬锦带，山西年少。","谈笑。","刁斗静。","烽火一把，常送平安耗。","圣主忧边，威灵遐布，骄虏且宽天讨。","岁华向晚愁思，谁念玉关人老。","太平也，且欢娱，不惜金尊频倒。"],"p":"喜迁莺"},{"id":"S00706","t":"喜长新","a":"王益柔","c":["秋云朔吹晓徘徊。","雪照楼台。","梁王宴召有邹枚。","相如独逞雄才。","明烛薰炉香暖，深劝金杯。","庭前粉艳有寒梅。","一枝昨夜先开。"],"p":"喜长新"},{"id":"S00707","t":"西江月","a":"韩维","c":["早岁相期林下，高年同在尊前。","风花绣舞乍晴天。","绿蚁新浮酒面。","身外虚名电转，人间急景梭传。","当筵莫惜听朱弦。","一品归来强健。"],"p":"西江月"},{"id":"S00708","t":"踏莎行","a":"韩维","c":["归雁低空，游蜂趁暖。","凭高目向西云断。","具茨山外夕阳多，展江亭下春波满。","双桂情深，千花明焕。","良辰谁是同游伴。","辛夷花谢早梅开。","应须次第调弦管。"],"p":"踏莎行"},{"id":"S00709","t":"减字木兰花","a":"韩维","c":["和风动□。","□□新年□入手。","世事尘□。","□□□情近酒□。","水开湖□。","□□笙歌波面起。","相与排□。","□□□胜特地□。"],"p":"减字木兰花"},{"id":"S00710","t":"浪淘沙","a":"韩维","c":["饱食日□□。","□上危亭。","东风昨夜入□□。","□□雪晴云□□，□遍银屏。","回首叹劳生。","□鼎相承。","皇恩早晚□□□。","□□陂边垂钓手，不负幽情。"],"p":"浪淘沙"},{"id":"S00711","t":"赏南枝","a":"曾巩","c":["暮冬天地闭，正柔木冻折，瑞雪飘飞。","对景见南山，岭梅露、几点清雅容姿。","丹染萼、玉缀枝。","又岂是、一阳有私。","大抵是、化工独许，使占却先时。","霜威莫苦凌持。","此花根性，想群卉争知。","贵用在和羹，三春里、不管绿是红非。","攀赏处、宜酒卮。","醉拈嗅、幽香更奇。","倚阑干、仗何人去，嘱羌管休吹。"],"p":"赏南枝"},{"id":"S00712","t":"阮郎归","a":"司马光","c":["渔舟容易入春山。","仙家日月闲。","绮窗纱幌映朱颜。","相逢醉梦间。","松露冷，海霞殷。","匆匆整棹还。","落花寂寂水潺潺。","重寻此路难。"],"p":"阮郎归"},{"id":"S00713","t":"西江月","a":"司马光","c":["宝髻松松挽就，铅华淡淡妆成。","青烟翠雾罩轻盈。","飞絮游丝无定。","相见争如不见，有情何似无情。","笙歌散后酒初醒。","深院月斜人静。"],"p":"西江月"},{"id":"S00714","t":"锦堂春・锦堂春慢","a":"司马光","c":["红日迟迟，虚廊转影，槐阴迤逦西斜。","彩笔工夫，难状晚景烟霞。","蝶尚不知春去，漫绕幽砌寻花。","奈猛风过后，纵有残红，飞向谁家。","始知青鬓无价，叹飘零官路，荏苒年华。","今日笙歌丛里，特地咨嗟。","席上青衫湿透，算感旧、何止琵琶。","怎不教人易老，多少离愁，散在天涯。"],"p":"锦堂春・锦堂春慢"},{"id":"S00715","t":"临江仙","a":"苏氏","c":["一夜东风穿绣户，融融暖应佳时。","春来何处最先知。","平明堤上柳。","染遍郁金枝。","姊妹嬉游时节近，今朝应怨来迟。","凭谁说与到家期。","玉钗头上胜，留待远人归。"],"p":"临江仙"},{"id":"S00716","t":"更漏子","a":"苏氏","c":["小阑干，深院宇。","依旧当时别处。","朱户锁，玉楼空。","一帘霜日红。","弄珠江，何处是，望断碧云无际。","凝泪眼，出重城。","隔溪羌笛声。"],"p":"更漏子"},{"id":"S00717","t":"鹊桥仙","a":"苏氏","c":["星移斗转，玉蟾西下，渐觉东郊向晓。","马嘶人语隔霜林，望千里、长安古道。","珠宫姊妹，相逢方信，别后十分瘦了。","上林归去正花时，争奈向、花前又老。"],"p":"鹊桥仙"},{"id":"S00718","t":"踏莎行","a":"苏氏","c":["孤馆深沈，晓寒天气。","解鞍独自阑干倚。","暗香浮动月黄昏，落梅风送沾衣袂。","待写红笺，凭谁与寄。","先教觅取嬉游地。","到家正是早春时，小桃花下拼沈醉。"],"p":"踏莎行"},{"id":"S00719","t":"清平乐","a":"刘敞","c":["小山丛桂。","最有留人意。","拂叶攀花无限思。","雨湿浓香满袂。","别来过了秋光。","翠帘昨夜新霜。","多少月宫闲地，姮娥与借微芳。"],"p":"清平乐"},{"id":"S00720","t":"踏莎行","a":"刘敞","c":["蜡炬高高，龙烟细细。","玉楼十二门初闭。","疏帘不卷水晶寒，小屏半掩琉璃翠。","桃叶新声，榴花美味。","南山宾客东山妓。","利名不肯放人闲，忙中偷取工夫醉。"],"p":"踏莎行"},{"id":"S00721","t":"导引","a":"王","c":["忆玉清景，繁盛极当时。","千古事难追。","汉家别庙秋风起，空出奉宸衣。","三山浮海日晖晖。","羽盖共云飞。","灵宫旧是栖真处，还望玉舆归。"],"p":"导引"},{"id":"S00722","t":"发引","a":"王","c":["玉宸朝晚，忽掩赭黄衣。","愁雾锁金扉。","蓬莱待得仙丹至，人世已成非。","龙轩天仗转西畿。","旌旆入云飞。","望陵宫女垂红泪，不见翠舆归。"],"p":"发引"},{"id":"S00723","t":"发引","a":"王","c":["上林春晚，曾是奉宸游。","水殿戏龙舟。","玉箫吹断催仙驭，一去隔千秋。","游人重到曲江头。","事往涕难收。","空馀御幄传觞处，依旧水东流。"],"p":"发引"},{"id":"S00724","t":"倦寻芳慢・倦寻芳","a":"王","c":["露晞向晚，帘幕风轻，小院闲昼。","翠迳莺来，惊下乱红铺绣。","倚危墙，登高榭，海棠经雨胭脂透。","算韶华，又因循过了，清明时候。","倦游燕、风光满目，好景良辰，谁共携手。","恨被榆钱，买断两眉长斗。","忆高阳，人散后。","落花流水仍依旧。","这情怀，对东风、尽成消瘦。"],"p":"倦寻芳慢・倦寻芳"},{"id":"S00725","t":"凤箫吟・芳草","a":"韩缜","c":["锁离愁，连绵无际，来时陌上初熏。","绣帏人念远，暗垂珠泪，泣送征轮。","长亭长在眼，更重重、远水孤云。","但望极楼高，尽日目断王孙。","消魂。","池塘别后，曾行处、绿妒轻裙。","恁时携素手，乱花飞絮里，缓步香裀。","朱颜空自改，向年年、芳意长新。","遍绿野，嬉游醉眠，莫负青春。"],"p":"凤箫吟・芳草"},{"id":"S00726","t":"蝶恋花","a":"韩缜姬","c":["香作风光浓著露。","正恁双栖，又遣分飞去。","密诉东君应不许。","泪波一洒奴衷素。"],"p":"蝶恋花"},{"id":"S00727","t":"浪淘沙","a":"裴湘","c":["雁塞说并门。","郡枕西汾。","山形高下远相吞。","古寺楼台依碧嶂，烟景遥分。","晋庙锁溪云。","箫鼓仍存。","牛羊斜日自归村。","惟有故城禾黍地，前事消魂。"],"p":"浪淘沙"},{"id":"S00728","t":"浪淘沙","a":"裴湘","c":["万国仰神京。","礼乐纵横。","葱葱佳气锁龙城。","日御明堂天子圣，朝会簪缨。","九陌六街平。","万国充盈。","青楼弦管酒如渑。","别有隋堤烟柳暮，千古含情。"],"p":"浪淘沙"},{"id":"S00729","t":"花心动","a":"阮逸女","c":["仙苑春浓，小桃开，枝枝已堪攀折。","乍雨乍晴，轻暖轻寒，渐近赏花时节。","柳摇台榭东风软，帘栊静、幽禽调舌。","断魂远、闲寻翠径，顿成愁结。","此恨无人共说。","还立尽黄昏，寸心空切。","强整绣衾，独掩朱扉，簟枕为谁铺设。","夜长更漏传声远，纱窗映、银缸明灭。","梦回处，梅梢半笼淡月。"],"p":"花心动"},{"id":"S00730","t":"蝶恋花","a":"滕甫","c":["叶底无风池面静。","掬水佳人，拍破青铜镜。","残月朦胧花弄影。","新梳斜插乌云鬓。","拍索闷怀添酒兴。","旋撷园蔬，随分成盘饤。","说与翠微休急性。","功名富贵皆前定。"],"p":"蝶恋花"},{"id":"S00731","t":"蝶恋花","a":"滕甫","c":["昼永无人深院静。","一枕春醒，犹未忺临镜。","帘卷新蟾光射影。","速忙掠起蓬松鬓。","对景沈吟嗟没兴。","薄幸不来，空把杯盘饤。","休道妇人多水性。","今宵独自言无定。"],"p":"蝶恋花"},{"id":"S00732","t":"定风波","a":"吴氏1","c":["待得明年重把酒。","携手。","那知无雨又无风。"],"p":"定风波"},{"id":"S00733","t":"蜡梅香","a":"吴师孟","c":["锦里阳和，看万木凋时，早梅独秀。","珍馆琼楼畔，正降跗初吐，秾华将茂。","国艳天葩，真澹伫、雪肌清瘦。","似广寒宫，铅华未御，自然妆就。","凝睇倚朱阑，喷清香暗度，易袭襟袖。","好与花为主，宜秉烛、频观泛湘酎。","莫待南枝，随乐府、新声吹后。","对赏心人，良辰好景，须信难偶。"],"p":"蜡梅香"},{"id":"S00734","t":"阮郎归","a":"俞紫芝","c":["钓鱼船上谢三郎。","双鬓已苍苍。","蓑衣未必清贵，不肯换金章。","汀草畔，浦花旁。","静鸣榔。","自来好个，渔父家风，一片潇湘。"],"p":"阮郎归"},{"id":"S00735","t":"临江仙","a":"俞紫芝","c":["弄水亭前千万景，登临不忍空回。","水轻墨澹写蓬莱。","莫教世眼，容易洗尘埃。","收去雨昏都不见，展时还似云开。","先生高趣更多才。","人人尽道，小杜却重来。"],"p":"临江仙"},{"id":"S00736","t":"苏幕遮","a":"俞紫芝","c":["地锺灵，天应瑞。","簇簇香苞、团作真珠蕊。","玉宇瑶台分十二。","要伴姮娥，月里双双睡。","月如花，花似月。","花月生香，添此真奇异。","不许扬州夸间气。","昨夜春风，唤醒琼琼醉。"],"p":"苏幕遮"},{"id":"S00737","t":"失调名","a":"郑獬","c":["玉环妾意无渝。","问君心、朝槿何如。"],"p":"失调名"},{"id":"S00738","t":"好事近","a":"郑獬","c":["江上探春回，正值早梅时节。","两行小槽双凤，按凉州初彻。","谢娘扶下绣鞍来，红靴踏残雪。","归去不须银烛，有山头明月。"],"p":"好事近"},{"id":"S00739","t":"好事近","a":"郑獬","c":["把酒对江梅，花小未禁风力。","何计不教零落，为青春留得。","故人莫问在天涯，尊前苦相忆。","好把素香收取，寄江南消息。"],"p":"好事近"},{"id":"S00740","t":"渔家傲","a":"强至","c":["雪月照梅溪畔路。","幽姿背立无言语。","冷浸瘦枝清浅处。","香暗度。","妆成处士横斜句。","浑似玉人常淡伫。","菱花相对盈清楚。","谁解小图先画取。","天欲曙。","恐随月色云间去。"],"p":"渔家傲"},{"id":"S00741","t":"踏莎行","a":"沈注","c":["竹阁云深，巢虚人阒。","几年湖上音尘寂。","风流今有使君家，月明夜夜闻双笛。"],"p":"踏莎行"},{"id":"S00742","t":"望梅花","a":"蒲宗孟","c":["一阳初起。","暖力未胜寒气。","堪赏素华长独秀，不并开红抽紫。","青帝只应怜洁白，不使雷同众卉。","淡然难比。","粉蝶岂知芳蕊。","半夜卷帘如乍失，只在银蟾影里。","残雪枝头君认取，自有清香旖旎。"],"p":"望梅花"},{"id":"S00743","t":"减字木兰花","a":"陈汝羲","c":["纤纤素手。","盘里醉花新点就。","对叶双心。","别有东风意思深。","琼沾粉缀。","消得玉堂留客醉。","试嗅清芳。","别有红罗巧袖香。"],"p":"减字木兰花"},{"id":"S00744","t":"行香子","a":"汪辅之","c":["晚绿寒红。","芳意匆匆。","惜年华、今与谁同。","碧云零落，数字宾鸿。","看渚莲凋，宫扇旧，怨秋风。","流波坠叶，佳期何在，想天教、离恨无穷。","试将前事，闲倚梧桐。","有销魂处，明月夜，锦屏空。"],"p":"行香子"},{"id":"S00745","t":"鹧鸪天","a":"范纯仁","c":["腊后春前暖律催。","日和风软欲开梅。","公方结客寻佳景，我亦忘形趁酒杯。","添歌管，续尊罍。","更阑烛短未能回。","清欢莫待相期约，乘兴来时便可来。"],"p":"鹧鸪天"},{"id":"S00746","t":"雨中花・夜行船","a":"张才翁","c":["万缕青青，初眠官柳，向人犹未成阴。","据雕鞍马上，拥鼻微吟。","远宦情怀谁问，空嗟壮志销沈。","正好花时节，山城留滞、忍负归心。","别离万里，飘蓬无定，谁念会合难凭。","相聚里，休辞金盏，酒浅还深。","欲把春愁抖擞，春愁转更难禁。","乱山高处，凭阑垂袖，聊寄登临。"],"p":"雨中花・夜行船"},{"id":"S00747","t":"渔家傲","a":"寿涯禅师","c":["深愿弘慈无缝罅。","乘时走入众生界。","窈窕丰姿都没赛。","提鱼卖。","堪笑马郎来纳败。","清冷露湿金襽坏。","茜裙不把珠缨盖。","特地掀来呈捏怪。","牵人爱。","还尽许多菩萨债。"],"p":"渔家傲"},{"id":"S00748","t":"水龙吟","a":"章","c":["燕忙莺懒花残，正堤上、柳花飘坠。","轻飞点画青林，谁道全无才思。","闲趁游丝，静临深院，日长门闭。","傍珠帘散漫，垂垂欲下，依前被，风扶起。","兰帐玉人睡觉，怪春衣、雪粘琼缀。","绣床旋满，香球无数，才圆却碎。","时见蜂儿，仰粘轻粉，鱼吹池水。","望章台路杳，金鞍游荡，有盈盈泪。"],"p":"水龙吟"},{"id":"S00749","t":"声声令・胜胜令","a":"章","c":["帘移碎影，香褪衣襟。","旧家庭院嫩苔侵。","东风过尽，暮云锁，绿窗深。","怕对人、闲枕剩衾。","楼底轻阴。","春信断，怯登临。","断肠魂梦两沈沈。","花飞水远，便从今。","莫追寻。","又怎禁、蓦地上心。"],"p":"声声令・胜胜令"},{"id":"S00750","t":"渔父乐・渔歌子","a":"徐积","c":["水曲山隈四五家。","夕阳烟火隔芦花。","渔唱歇，醉眠斜。","纶竿蓑笠是生涯。"],"p":"渔父乐・渔歌子"},{"id":"S00751","t":"渔父乐・渔歌子","a":"徐积","c":["见说红尘罩九衢。","贪名逐利各区区。","论得失，问荣枯。","争似侬家占五湖。"],"p":"渔父乐・渔歌子"},{"id":"S00752","t":"渔父乐・渔歌子","a":"徐积","c":["讨得渔竿买得船。","归休何必待高年。","深浪里，乱云边。","只有逍遥是水仙。"],"p":"渔父乐・渔歌子"},{"id":"S00753","t":"渔父乐・渔歌子","a":"徐积","c":["饱则高歌醉即眠。","只知头白不知年。","江绕屋，水随船。","买得风光不著钱。"],"p":"渔父乐・渔歌子"},{"id":"S00754","t":"开元乐・三台","a":"沈括","c":["鹳鹊楼头日暖，蓬莱殿里花香。","草绿烟迷步辇，天高日近龙床。"],"p":"开元乐・三台"},{"id":"S00755","t":"开元乐・三台","a":"沈括","c":["楼上正临宫外，人间不见仙家。","寒食轻烟薄雾，满城明月梨花。"],"p":"开元乐・三台"},{"id":"S00756","t":"开元乐・三台","a":"沈括","c":["按舞骊山影里，回銮渭水光中。","玉笛一天明月，翠华满陌东风。"],"p":"开元乐・三台"},{"id":"S00757","t":"开元乐・三台","a":"沈括","c":["殿后春旗簇仗，楼前御队穿花。","一片红云闹处，外人遥认官家。"],"p":"开元乐・三台"},{"id":"S00758","t":"失调名","a":"范宽之","c":["谢娘栀子，贾妃萸佩。"],"p":"失调名"},{"id":"S00759","t":"黄鹤引","a":"方资","c":["生逢垂拱。","不识干戈免田陇。","士林书圃终年，庸非天宠。","才初阘茸。","老去支离何用。","浩然归弄。","似黄鹤、秋风相送。","尘事塞翁心，浮世庄生梦。","漾舟遥指烟波，群山森动。","神闲意耸。","回首利鞿名鞚。","此情谁共。","问几斛、淋浪春瓮。"],"p":"黄鹤引"},{"id":"S00760","t":"点绛唇","a":"王安国","c":["秋气微凉，梦回明月穿帘幕。","井梧萧索。","正绕南枝鹊。","宝瑟尘生，金雁空零落。","情无托。","鬓云慵掠。","不似君恩薄。"],"p":"点绛唇"},{"id":"S00761","t":"清平乐","a":"王安国","c":["留春不住。","费尽莺儿语。","满地残红宫锦污。","昨夜南园风雨。","小怜初上琵琶。","晓来思绕天涯。","不肯画堂朱户，春风自在梨花。"],"p":"清平乐"},{"id":"S00762","t":"减字木兰花","a":"王安国","c":["画桥流水。","雨湿落红飞不起。","月破黄昏。","帘里馀香马上闻。","徘徊不语。","今夜梦魂何处去。","不似垂杨。","犹解飞花入洞房。"],"p":"减字木兰花"},{"id":"S00763","t":"菩萨蛮","a":"孙洙","c":["楼头上有三冬鼓。","何须抵死催人去。","上马苦匆匆。","琵琶曲未终。","回头肠断处。","却更廉纤雨。","漫道玉为堂。","玉堂今夜长。"],"p":"菩萨蛮"},{"id":"S00764","t":"河满子","a":"孙洙","c":["怅望浮生急景，凄凉宝瑟馀音。","楚客多情偏怨别，碧山远水登临。","目送连天衰草，夜阑几处疏砧。","黄叶无风自落，秋云不雨长阴。","天若有情天亦老，摇摇幽恨难禁。","惆怅旧欢如梦，觉来无处追寻。"],"p":"河满子"},{"id":"S00765","t":"失调名","a":"李清臣","c":["杨花落。","燕子穿朱阁。","苦恨春醪如水薄。","闲愁无处著。","去年今日王陵舍，鼓角秋风。","千岁辽东。","回首人间万事空。"],"p":"失调名"},{"id":"S00766","t":"减字木兰花","a":"韦骧","c":["人生可意。","祗说功名贪富贵。","遇景开怀。","且尽生前有限杯。","韶华几许。","鹈鴂声残无觅处。","莫自因循。","一片花飞减却春。"],"p":"减字木兰花"},{"id":"S00767","t":"减字木兰花","a":"韦骧","c":["金貂贳酒。","乐事可为须趁手。","且醉青春。","白发何曾饶贵人。","凤笙鼍鼓。","况是桃花落红雨。","莫诉觥筹。","炊熟黄粱一梦休。"],"p":"减字木兰花"},{"id":"S00768","t":"减字木兰花","a":"韦骧","c":["鸾坡凤沼。","轩冕傥来何足道。","存养天真。","安用浮名绊此身。","劳生逸老。","摆脱纷华须是早。","解绶眠云。","林下何曾见一人。"],"p":"减字木兰花"},{"id":"S00769","t":"减字木兰花","a":"韦骧","c":["危楼引望。","天气犹寒花未放。","远思悠悠。","芳草何年恨即休。","仙踪何处。","此去蓬山多少路。","春霭腾腾。","更在瑶台十二层。"],"p":"减字木兰花"},{"id":"S00770","t":"渔家傲","a":"圆禅师","c":["本是潇湘一钓客。","自东自西自南北。","只把孤舟为屋宅。","无宽窄。","幕天席地人难测。","顷闻四海停戈革。","金门懒去投书册。","时向滩头歌月白。","真高格。","浮名浮利谁拘得。"],"p":"渔家傲"},{"id":"S00771","t":"满庭芳","a":"则禅师","c":["咄这牛儿，身强力健，几人能解牵骑。","为贪原上，嫩草绿离离。","只管寻芳逐翠，奔驰后、不顾倾危。","争知道，山遥水远，回首到家迟。","牧童，今有智，长绳牢把，短杖高提。","入泥入水，终是不生疲。","直待心调步稳，青松下、孤笛横吹。","当归去，人牛不见，正是月明时。"],"p":"满庭芳"},{"id":"S00772","t":"八声甘州","a":"陈偕","c":["芰荷风、涤面恰麦秋，应倒著春衣。","渡晓溪云湿，日流尘脚，露滉蛛丝。","调翼受风雏燕，弱不解争泥。","衬琅玕锦院，竹外蔷薇。","立久阑干凭暖，看行鱼吹沫，波晕平池。","藓痕斑础石，渐雨熟梅时。","傍短篱、成团粉蝶，掠野花、相逐□高低。","忘言处，徽弦乍拂，流水先知。"],"p":"八声甘州"},{"id":"S00773","t":"满庭芳","a":"陈偕","c":["岚影浮春，云容阁雨，澄泓碧展玻璃。","高低楼观，窗户舞涟漪。","别有轻盈水面，清讴起、舟叶如飞。","沙堤上，垂鞭信马，柳重绿交枝。","渐残红倒影，金波潋滟，弦管催归。","看飘香陈粉，满路扶携。","不尽湖边风月，孤山下、猿鸟须知。","东风里、年年此水，贮尽是和非。"],"p":"满庭芳"},{"id":"S00774","t":"满庭芳","a":"陈偕","c":["榆荚抛钱，桃英胎子，杨花已送春归。","未成萍叶，水面绿纹肥。","沙暖溪禽行哺，忘机处、雏母相随。","重帘静，铜壶昼歇，声度竹间棋。","人生如意少，乐随春减，恨为情离。","怕牵愁勾怨，渐近金徽。","浮世更相代谢，江头明月，渡口斜晖。","关情处，摩挲钓石，莫遣上苔衣。"],"p":"满庭芳"},{"id":"S00775","t":"忆黄梅","a":"王观","c":["枝上叶儿未展。","已有坠红千片。","春意怎生防，怎不怨。","被我安排，矮牙床斗帐，和娇艳。","移在花丛里面。","请君看。","惹清香，偎媚暖。","爱香爱暖金杯满。","问春怎管。","大家拼、便做东风，总吹交零乱。","犹肯自、输我鸳鸯一半。"],"p":"忆黄梅"},{"id":"S00776","t":"浪淘沙","a":"王观","c":["素手水晶盘。","垒起仙丸。","红绡剪碎却成团。","逗得安排金粟遍，何似鸡冠。","味胜玉浆寒。","只被宜酸。","莫将荔子一般看。","色淡香消僝僽损，才到长安。"],"p":"浪淘沙"},{"id":"S00777","t":"天香","a":"王观","c":["霜瓦鸳鸯，风帘翡翠，今年早是寒少。","矮钉明窗，侧开朱户，断莫乱教人到。","重阴未解，云共雪、商量不了。","青帐垂毡要密，红炉收围宜小。","呵梅弄妆试巧。","绣罗衣、瑞云芝草。","伴我语时同语，笑时同笑。","已被金尊劝倒。","又唱个新词故相恼。","尽道穷冬，元来恁好。"],"p":"天香"},{"id":"S00778","t":"卜算子","a":"王观","c":["水是眼波横，山是眉峰聚。","欲问行人去那边，眉眼盈盈处。","才始送春归，又送君归去。","若到江东赶上春，千万和春住。"],"p":"卜算子"},{"id":"S00779","t":"万年欢","a":"王安礼","c":["雅出群芳。","占春前信息，腊后风光。","野岸邮亭，繁似万点轻霜。","清浅溪流倒影，更黯淡、月色笼香。","浑疑是、姑射冰姿，寿阳粉面初妆。","多情对景易感，况淮天庾岭，迢递相望。","愁听龙吟凄绝，画角悲凉。","念昔因谁醉赏，向此际、空恼危肠。","终须待结实，恁时佳味堪尝。"],"p":"万年欢"},{"id":"S00780","t":"潇湘忆故人慢","a":"王安礼","c":["薰风微动，方樱桃弄色，萱草成窠。","翠帏敞轻罗。","试冰簟初展，几尺湘波。","疏帘广厦，寄潇洒、一枕南柯。","引多少、梦中归绪，洞庭雨棹烟蓑。","惊回处，闲昼永，但时时，燕雏莺友相过。","正绿影婆娑。","况庭有幽花，池有新荷。","青梅煮酒，幸随分、赢得高歌。","功名事、到头终在，岁华忍负清和。"],"p":"潇湘忆故人慢"},{"id":"S00781","t":"点绛唇","a":"王安礼","c":["春睡腾腾，觉来鸳被堆香暖。","起来慵懒。","触目情何限。","深院日斜，人静花阴转。","柔肠断。","凭高不见。","芳草连天远。"],"p":"点绛唇"},{"id":"S00782","t":"江神子・江城子","a":"张舜民","c":["七朝文物旧江山。","水如天。","莫凭栏。","千古斜阳，无处问长安。","更隔秦淮闻旧曲，秋已半，夜将阑。","争教潘鬓不生斑。","敛芳颜。","抹么弦。","须记琵琶，子细说因缘。","待得鸾胶肠已断，重别日，是何年。"],"p":"江神子・江城子"},{"id":"S00783","t":"朝中措","a":"张舜民","c":["三湘迁客思悠哉。","尊俎定常开。","云雨未消歌伴，山川忍对离杯。","他年来此，贤侯未去，忍话先回。","好在江南山色，恁时重上高台。"],"p":"朝中措"},{"id":"S00784","t":"卖花声","a":"张舜民","c":["木叶下君山。","空水漫漫。","十分斟酒敛芳颜。","不是渭城西去客，休唱阳关。","醉袖抚危栏。","天淡云闲。","何人此路得生还。","回首夕阳红尽处，应是长安。"],"p":"卖花声"},{"id":"S00785","t":"卖花声","a":"张舜民","c":["楼上久踟躇。","地远身孤。","拟将憔悴吊三闾。","自是长安日下影，流落江湖。","烂醉且消除。","不醉何如。","又看暝色满平芜。","试问寒沙新到雁，应有来书。"],"p":"卖花声"},{"id":"S00786","t":"江南好・忆江南","a":"曾布","c":["江南客，家有宁馨儿。","三世文章称大手，一门兄弟独良眉。","借甚众多推。","千里足，来自渥洼池。","莫倚善题鹦鹉赋，青山须待健时归。","不似傲当时。"],"p":"江南好・忆江南"},{"id":"S00787","t":"水调歌头","a":"曾布","c":["魏豪有冯燕，年少客幽并。","击球斗鸡为戏，游侠久知名。","因避仇、来东郡。","元戎留属中军。","直气凌貔虎，须臾叱咤风云。","凛凛坐中生。","偶乘佳兴。","轻裘锦带，东风跃马，往来寻访幽胜。","游冶出东城。","堤上莺花撩乱，香车宝马纵横。","草软平沙稳。","高楼两岸春风，语笑隔帘声。"],"p":"水调歌头"},{"id":"S00788","t":"水调歌头","a":"曾布","c":["袖笼鞭敲镫。","无语独闲行。","绿杨下、人初静。","烟澹夕阳明。","窈窕佳人，独立瑶阶，掷果潘郎，瞥见红颜横波盻，不胜娇软倚银屏。","曳红裳，频推朱户，半开还掩，似欲倚、咿哑声里，细说深情。","因遣林间青鸟，为言彼此心期，的的深相许，窃香解佩，绸缪相顾不胜情。"],"p":"水调歌头"},{"id":"S00789","t":"水调歌头","a":"曾布","c":["说良人滑将张婴。","从来嗜酒，还家镇长酩酊狂酲。","屋上鸣鸠空斗，梁间客燕相惊。","谁与花为主，兰房从此，朝云夕雨两牵萦。","似游丝飘荡，随风无定。","奈何岁华荏苒，欢计苦难凭。","唯见新恩缱绻，连枝并翼，香闺日日为郎，谁知松萝托蔓，一比一毫轻。"],"p":"水调歌头"},{"id":"S00790","t":"临江仙","a":"魏夫人","c":["庭院深深深几许，云窗雾阁春迟。","为谁憔悴损芳姿。","夜来清梦好，应是发南枝。","玉瘦檀轻无限恨，南楼羌管休吹。","浓香吹尽有谁知。","暖风迟日也，别到杏花肥。"],"p":"临江仙"},{"id":"S00791","t":"好事近","a":"魏夫人","c":["雨后晓寒轻，花外早莺啼歇。","愁听隔溪残漏，正一声凄咽。","不堪西望去程赊，离肠万回结。","不似海棠阴下，按凉州时节。"],"p":"好事近"},{"id":"S00792","t":"阮郎归","a":"魏夫人","c":["夕阳楼外落花飞。","晴空碧四垂。","去帆回首已天涯。","孤烟卷翠微。","楼上客，鬓成丝。","归来未有期。","断魂不忍下危梯。","桐阴月影移。"],"p":"阮郎归"},{"id":"S00793","t":"减字木兰花","a":"魏夫人","c":["西楼明月。","掩映梨花千树雪。","楼上人归。","愁听孤城一雁飞。","玉人何处。","又见江南春色暮。","芳信难寻。","去后桃花流水深。"],"p":"减字木兰花"},{"id":"S00794","t":"清平乐","a":"王仲甫","c":["黄金殿里。","烛影双龙戏。","劝得官家真个醉，进酒犹呼万岁。","锦裀舞彻凉州，君恩与整搔头。","一夜御前宣唤，六宫多少人愁。"],"p":"清平乐"},{"id":"S00795","t":"满朝欢","a":"王仲甫","c":["忆得延州，旧曾相见，东城近东下住。","被若著意引归家，放十分、以上抬举。","小样罗衫，淡红拂过，风流万般做处。","怕伊蓦地忆人时，梦中来、不要迷路。"],"p":"满朝欢"},{"id":"S00796","t":"丑奴儿・采桑子","a":"王仲甫","c":["牡丹不好长春好，有个因依。","一两枝儿。","但是风光总属伊。","当初祗为嫦娥种，月正明时。","教恁芳菲。","伴著团圆十二回。"],"p":"丑奴儿・采桑子"},{"id":"S00797","t":"永遇乐","a":"王仲甫","c":["风折新英，雨肥繁实，又还如豆。","玉核初成，红腮尚浅，齿软酸透。","粉墙低亚，佳人惊见，不管露沾襟袖。","一枝钗子未插，应把手挪频嗅。","相思病酒，只因思此，免使文君眉皱。","入鼎调羹，攀林止渴，功业还依旧。","看看飞燕，衔将春去，又将欲、黄昏时候。","争如向、金盘满捧，共君王对酒。"],"p":"永遇乐"},{"id":"S00798","t":"离亭燕・离亭宴","a":"孙浩然","c":["一带江山如画。","景物向秋潇洒。","水浸碧天何处断，霁色冷光相射。","橘树荻花洲，掩映竹篱茅舍。","天际客帆高挂。","烟外酒旗低亚。","多少六朝兴废事，尽入渔樵闲话。","怅望倚层楼，红日无言西下。"],"p":"离亭燕・离亭宴"},{"id":"S00799","t":"夜行船","a":"孙浩然","c":["何处采菱归暮。","隔宵烟、菱歌轻举。","白苹风起月华寒，影朦胧、半和梅雨。","脉脉相逢心似许。","扶兰棹、黯然凝伫。","遥指前村，隐隐烟树，含情背人归去。"],"p":"夜行船"},{"id":"S00800","t":"鹧鸪天","a":"王诜","c":["才子阴风度远关。","清愁曾向画图看。","山衔斗柄三星没，雪共月明千里寒。","新路陌，旧江干。","崎岖谁叹客程难。","临风更听昭华笛，簌簌梅花满地残。"],"p":"鹧鸪天"},{"id":"S00801","t":"花心动","a":"王诜","c":["春欲来时，看雪里、新梅品流珍绝。","气韵楚江，颜色中央，数朵巧熔香蜡。","嫩苞珠泪圆金烛，娇腮润、蜂房微缺。","画栏悄，佳人道妆，醉吟风月。","淡白轻红谩说。","算何事、东君用心偏别。","赋与异姿，添与清香，堪向苦寒时节。","但教开后金尊满，休惆怅、落时歌阙。","断肠也，繁枝为谁赠折。"],"p":"花心动"},{"id":"S00802","t":"落梅花・落梅","a":"王诜","c":["寿阳妆晚，慵匀素脸，经宵醉痕堪惜。","前村雪里，几枝初绽，□冰姿仙格。","忍被东风，乱飘满地，残英堆积。","可堪江上起离愁，凭谁说寄，肠断未归客。","流恨声传羌笛。","感行人、水亭山驿。","越溪信阻，仙乡路杳，但风流尘迹。","香艳浓时，东君吟赏，已成轻掷。","愿身长健，且凭阑，明年还放春消息。"],"p":"落梅花・落梅"},{"id":"S00803","t":"黄莺儿","a":"王诜","c":["多情春意忆时节。","北圃人来，传道江梅，依稀芳姿，数枝新发。","夸嫩脸著胭脂，腻滑凝香雪。","问伊还记年时，正好相看，因甚轻别。","情切。","往事散浮云，旧恨成华发。","算知空对，绮槛雕栏，孜孜望人攀折。","愁未见苦思量，待见重端叠。","愿与永仿高堂，云雨芳菲月。"],"p":"黄莺儿"},{"id":"S00804","t":"蓦山溪","a":"陈济翁","c":["去年今日，从驾游西苑。","彩仗压金波，看水戏、鱼龙曼衍。","宝津南殿，宴坐近天颜，金杯酒，君王劝。","头上宫花颤。","六军锦绣，万骑穿杨箭。","日暮翠华归，拥钧天、笙歌一片。","如今关外，千里未归人，前山雨，西楼晚。","望断思君眼。"],"p":"蓦山溪"},{"id":"S00805","t":"蓦山溪","a":"陈济翁","c":["薰风时候。","芍药披晴昼。","天上玉阑干，展一枰、天家锦绣。","汉宫唐殿。","嫔御逞妖娆，飞燕女，太真妃，一样新妆就。","黄金拈线，色与红芳斗。","谁把绛绡衣，误将他、胭脂渍透。","晚风生处，襟袖卷浓香，持玉斝，秉纱笼，倚醉听更漏。"],"p":"蓦山溪"},{"id":"S00806","t":"踏青游","a":"陈济翁","c":["濯锦江头，羞杀艳桃秾李。","纵赵昌、丹青难比。","晕轻红，留浅素，千娇百媚。","照绿水。","恰如下临鸾镜，妃子弄妆犹醉。","诗笔因循，不晓少陵深意。","但满眼、伤春珠泪。","燕来时，莺啼处，年年憔悴。","便除是。","秉烛凭阑吟赏，莫教夜深花睡。"],"p":"踏青游"},{"id":"S00807","t":"河传","a":"郭讵","c":["大官无闷。","刚被傍人、竟来相问。","又难为□□敷臣。","且只将、甘草论。","朴消大戟并银粉。","疏风紧。","甘草闲相混。","及至下来，转杀他人。","尔甘草、有一分。"],"p":"河传"},{"id":"S00808","t":"水龙吟","a":"李之仪","c":["晚来轻拂，游云尽卷，霁色寒相射。","银潢半掩，秋毫欲数，分明不夜。","玉琯传声，羽衣催舞，此欢难借。","凛清辉，但觉圆光照影，冰壶莹、真无价。","闻道水晶宫殿，蕙炉薰、珠帘高挂。","琼枝半倚，瑶觞更劝，莺娇燕姹。","目断魂飞，翠萦红绕，空吟小砑。","想归来醉里，鸾篦凤朵，倩何人卸。"],"p":"水龙吟"},{"id":"S00809","t":"蓦山溪","a":"李之仪","c":["神仙院宇，记得春归后。","蜂蝶不胜闲，惹残香、萦纡深透。","玉徽指稳，别是一般情，方永昼。","因谁瘦。","都为天然秀。","桐阴未减，独自携芳酎。","再弄想前欢，拊金樽、何时似旧。","凭谁说与，潘鬓转添霜，飞陇首。","云将皱。","应念相思久。"],"p":"蓦山溪"},{"id":"S00810","t":"蓦山溪","a":"李之仪","c":["金柔火老，欲避几无地。","谁借一檐风，锁幽香、愔愔清邃。","瑶阶珠砌，如膜遇金篦，流水外，落花前，岂是人能致。","擘鳞泛玉，笑语皆真类。","惆怅月边人，驾云𫐌、何方适意。","么弦咽处，空感旧时声，兰易歇，恨偏长，魂断成何事。"],"p":"蓦山溪"},{"id":"S00811","t":"蓦山溪","a":"李之仪","c":["蛾眉亭上，今日交冬至。","已报一阳生，更佳雪、因时呈瑞。","匀飞密舞，都是散天花，山不见，水如山，浑在冰壶里。","平生选胜，到此非容易。","弄月与燃犀，漫劳神、徒能惊世。","争如此际，天意巧相符，须痛饮，庆难逢，莫诉厌厌醉。"],"p":"蓦山溪"},{"id":"S00812","t":"失调名","a":"蔡确","c":["骊山宫中看乞巧，太液池边收曝衣。"],"p":"失调名"},{"id":"S00813","t":"惜黄花","a":"许将","c":["雁声晚断。","寒宵云卷。","正一枝开，风前看，月下见。","花占千花上，香笑千香浅。","化工与、最先裁翦。","谁把瑶林，闲抛江岸。","恁素英浓，芳心细，意何限。","不恨宫妆色，不怨吹羌管。","恨天远、恨春来晚。"],"p":"惜黄花"},{"id":"S00814","t":"临江仙","a":"许将","c":["圣主临轩亲策试，集英佳气葱葱。","鸣鞘声震未央宫。","卷帘龙影动，挥翰御烟浓。","上第归来何事好，迎人花面争红。","蓝袍香散六街风。","一鞭春色里，骄损玉花骢。"],"p":"临江仙"},{"id":"S00815","t":"临江仙","a":"郑无党","c":["不比寻常三五夜，万家齐望清辉。","烂银盘透碧琉璃。","莫辞终夕看，动是隔年期。","试问嫦娥还记否，玉人曾折高枝。","明年此夜再圆时。","合开东府宴，身在凤凰池。"],"p":"临江仙"},{"id":"S00816","t":"无愁可解","a":"陈","c":["光景百年，看便一世。","生来不识愁味。","问愁何处来，更开解个甚底。","万事从来风过耳。","何用不著心里。","你唤做、展却眉头，便是达者，也则恐未。","此理。","本不通言，何曾道、欢游胜如名利。","道即浑是错，不道如何即是。","这里元无我与你。","甚唤做、物情之外。","若须待醉了、方开解时，问无酒、怎生醉。"],"p":"无愁可解"},{"id":"S00817","t":"兰陵王","a":"陈","c":["角声切。","何处梅梢弄雪。","还乡梦，玉井楼前，千朵芙蕖插空碧。","邻翁问消息。","为说红尘倦客。","应怜笑、弓剑旌旗，底事留人未归得。","淮山旧相识。","记急处笙歌，静里锋镝。","隋堤杨柳犹春色。","嗟十载人事，几番棋局，青油年少已鬓白。","漫惆怅京国。","朱墨。","困无力。","似病鹤樊笼，老骥羁勒。","夕阳不系栖林翼。","待添竹东圃，种松西陌。","功名休问，吾老矣，付俊杰。"],"p":"兰陵王"},{"id":"S00818","t":"临江仙","a":"陈","c":["三十四年台榭，八千馀里江津。","去时杨柳正轻颦。","重来桃李少，不似旧时春。","风扫半空烟雨，玉虹翠浪如新。","可怜笳鼓送行人。","白头梳上见，归梦枕边频。"],"p":"临江仙"},{"id":"S00819","t":"哨遍","a":"陈","c":["多病倦游，在家又贫，毕竟如何是。","十万钱，骑鹤更扬州，是人间几曾有底。","算一生，大都能消几屐，劳神到老成何事。","趁齿落已双，发丝在两，归寻闲里滋味。","不见青云路有危机。","金缕歌声，渐变成悲。","待思大东门，忆鹤华亭，悔之晚矣。","休，归去来兮，北山幸有闲田地。","地瘠宜瓜菜，引泉凿成方沚。","这仲子蔬园，三公不换，况东陵自来瓜美。","间走马溪头，倚阑垂钓，解衣自濯清泚。","酿山泉、时复一中之。","琴横膝。","古淡无弦有音徽。","送归鸿、暮云千里。","蓬莱自古无路，玄圃何时到，只消曲几蒲团，镇日闲庐打眭。","这乾坤日月，更远游、问他王子。"],"p":"哨遍"},{"id":"S00820","t":"沁园春","a":"陈睦","c":["小雪初晴，画舫明月，强饮未眠。","念翠鬟双耸，舞衣半卷，琵琶催拍，促管危弦。","密意虽具，欢期难偶，遣我离情愁绪牵。","追思处，奈溪桥道窄，无计留连。","天天。","莫是前缘。","自别后、深诚谁为传。","想玉篦偷付，珠囊暗解，两心长在，须合金钿。","浅淡精神，温柔情性，记我疏狂应痛怜。","空肠断，奈衾寒漏永，终夜如年。"],"p":"沁园春"},{"id":"S00821","t":"清平乐","a":"陈睦","c":["鬓云斜坠。","莲步弯弯细。","笑脸双蛾生多媚。","百步兰麝香喷。","从前万种愁烦。","枕边未可明言。","好是蓝桥再渡，玉篦还胜金钿。"],"p":"清平乐"},{"id":"S00822","t":"玉楼春","a":"马成","c":["来时吴会犹残暑。","去日武林春已暮。","欲知遗爱感人深，洒泪多于江上雨。","欢情未举眉先聚。","别酒多斟君莫诉。","从今宁忍看西湖，抬眼尽成肠断处。"],"p":"玉楼春"},{"id":"S00823","t":"满江红","a":"李婴","c":["荆楚风烟，寂寞近、中秋时候。","露下冷、兰英将谢，苇花初秀。","归燕殷勤辞巷陌，鸣蛩凄楚来窗牖。","又谁念、江边有神仙，飘零久。","横琴膝，携筇手。","旷望眼，闲吟口。","任纷纷万事，到头何有。","君不见、凌烟冠剑客，何人气貌长依旧。","归去来、一曲为君吟，为君寿。"],"p":"满江红"},{"id":"S00824","t":"菩萨蛮","a":"王齐愈","c":["玉肌香衬冰丝縠。","縠丝冰衬香肌玉。","纤指拂眉尖。","尖眉拂指纤。","巧裁罗袜小。","小袜罗裁巧。","移步看尘飞。","飞尘看步移。"],"p":"菩萨蛮"},{"id":"S00825","t":"菩萨蛮","a":"王齐愈","c":["吼雷催雨飞沙走。","走沙飞雨催雷吼。","波涨泻倾河。","河倾泻涨波。","幌纱凉气爽。","爽气凉纱幌。","幽梦觉仙游。","游仙觉梦幽。"],"p":"菩萨蛮"},{"id":"S00826","t":"菩萨蛮","a":"王齐愈","c":["兽喷香缕飞长昼。","昼长飞缕香喷兽。","迎日喜葵倾。","倾葵喜日迎。","卷帘双舞燕。","燕舞双帘卷。","清簟枕钗横。","横钗枕簟清。"],"p":"菩萨蛮"},{"id":"S00827","t":"菩萨蛮","a":"王齐愈","c":["远香风递莲湖满。","满湖莲递风香远。","光鉴试新妆。","妆新试鉴光。","棹穿花处好。","好处花穿棹。","明月咏歌清。","清歌咏月明。"],"p":"菩萨蛮"},{"id":"S00828","t":"望江南・忆江南","a":"王齐叟","c":["居下位，常恐被人谗。","只是曾填青玉案，何曾敢作望江南。","请问马都监。"],"p":"望江南・忆江南"},{"id":"S00829","t":"失调名","a":"王齐叟","c":["蹙绣圈金，槃囊密约，未赴意先警。","欲罢还休，临行又怯，倚定画栏痴等。","帘风渐冷。","先自虑、春宵不永。","更那堪、斗转星移，尚在有无之境。","绿云满压蝤蛴领。","惭愧也、满怀香拥。","此际有谁知证。","但楼前明月，窗间花影。"],"p":"失调名"},{"id":"S00830","t":"点绛唇","a":"舒氏","c":["独自临池，闷来强把阑干凭。","旧愁新恨。","耗却年时兴。","鹭散鱼潜，烟敛风初定。","波心静。","照人如镜。","少个年时影。"],"p":"点绛唇"},{"id":"S00831","t":"满庭芳","a":"琴操","c":["山抹微云，天连衰草，画角声断斜阳。","暂停征辔，聊共饮离觞。","多少蓬莱旧侣，频回首、烟霭茫茫。","孤村里，寒鸦万点，流水绕红墙。","魂伤。","当此际，轻分罗带，暗解香囊。","谩赢得，青楼薄幸名狂。","此去何时见也，襟袖上、空有馀香。","伤心处，高城望断，灯火已昏黄。"],"p":"满庭芳"},{"id":"S00832","t":"卜算子","a":"琴操","c":["欲整别离情，怯对尊中酒。","野梵幽幽石上飘，搴落楼头柳。","不系黄金绶。","粉黛愁成垢。","春风三月有时阑，遮不尽、梨花丑。"],"p":"卜算子"},{"id":"S00833","t":"临江仙","a":"舒亶","c":["折柳门前鹦鹉绿，河梁小驻归船。","不堪华发对离筵。","孤村啼鴂日，深院落花天。","文采弟兄真叠玉，赤宵去路谁先。","明朝便恐各风烟。","江山如有恨，桃李自无言。"],"p":"临江仙"},{"id":"S00834","t":"点绛唇","a":"舒亶","c":["紫雾香浓，岁华风转花随辇。","洞天云暖。","一片笙歌远。","水殿龙舟，忆侍瑶池宴。","闲庭院。","梦回春半。","雪鬓无人见。"],"p":"点绛唇"},{"id":"S00835","t":"散天花","a":"舒亶","c":["云断长空叶落秋。","寒江烟浪静，月随舟。","西风偏解送离愁。","声声南去雁，下汀洲。","无奈多情去复留。","骊歌齐唱罢，泪争流。","悠悠别恨几时休。","不堪残酒醒，凭危楼。"],"p":"散天花"},{"id":"S00836","t":"醉花阴","a":"舒亶","c":["露芽初破云腴细。","玉纤纤亲试。","香雪透金瓶，无限仙风，月下人微醉。","相如消渴无佳思。","了知君此意。","不信老卢郎，花底春寒，赢得空无睡。"],"p":"醉花阴"},{"id":"S00837","t":"导引","a":"范祖禹","c":["思齐文母，盛烈对皇天。","演宝祚千年。","卿云复旦治功全。","厌人世登仙。","龙舆忽掩三川。","彩仗属车旋。","维清象舞告英宣。","入诗颂歌弦。"],"p":"导引"},{"id":"S00838","t":"六州","a":"范祖禹","c":["太平功。","拥佑帝尧聪。","歌九德，偃五戎。","寰海被祥风。","车书万里文轨同。","自南北西东。","耕田凿井，戏垂髫华发，跻仁寿域变时雍。","大明方天中。","弃养东朝苦匆匆。","玉座如存，永隔慈容。","恨难穷。","崇庆空。","飙轮仙驭无踪。","超宇宙，驾云龙。","袆翟掩轩宫。","柏城王气长郁葱。","温洛照寒崧。","光灵在上，徽音流千古，昭如日月丽层穹。","太任家邦隆。","彤史青编永垂鸿。","清庙笙镛。","奏假钦崇。"],"p":"六州"},{"id":"S00839","t":"十二时・忆少年","a":"范祖禹","c":["转招摇。","厚陵回望，双阙起岧峣。","晓日丽谯。","金爵上干霄。","风雨阕，夜宫闭，不重朝。","奉鸾镳渐遥。","玉京知何处，飞英衔恤，乱絮缠悲，春路迢迢。","缥缈哀音，发龙笳凤箫。","光景同，惨淡度岩邑，指河桥。","马萧萧。","络绎星轺。","拂天容卫，江海上寒潮。","万国魂销。","追昔御东朝。","开钿扇，垂珠箔，侍珰貂。","宝香烧。","散飘。","开仁寿域，神孙高拱，昆仑渤澥，玉烛方调。","一旦宫车晚，旋归泬寥。","九载初，如梦次，功得琼瑶。"],"p":"十二时・忆少年"},{"id":"S00840","t":"虞神歌","a":"范祖禹","c":["驾玉龙。","设初虞祭终。","前旌举，天回洛水，路转崧峰。","瞻寥廓，烟霏冲融。","窅无踪。","震地鼓吹悲雄。","谁何羽卫重。","拂云旗帜眩青红。","来渐东。","清尘洒道，修职百神恭。","回首苍茫醅雾雨吹风。","掩泉宫。","□□□□□□□□□寰畿入，山川改容。","鼓钟临近次，千官望拜，涕泪衡从。","人如堵，晨光葱茏。","阙穹隆。","驰道禁水相通。","当年游幸空。","皇仪事毕泣重瞳。","哀未穷。","巍巍馀烈，辉映简编中。","亿万斯年，覆载同功。"],"p":"虞神歌"},{"id":"S00841","t":"千秋岁","a":"孔平仲","c":["春风湖外。","红杏花初退。","孤馆静，愁肠碎。","泪馀痕在枕，别久香销带。","新睡起。","小园戏蝶飞成对。","惆怅人谁会。","随处聊倾盖。","情暂遣，心何在。","锦书消息断，玉漏花阴改。","迟日暮，仙山杳杳空云海。"],"p":"千秋岁"},{"id":"S00842","t":"满庭芳","a":"了元","c":["鳞甲何多，羽毛无数，悟来佛性皆同。","世人何事，刚爱口头浓。","痛把群生割剖，刀头转、鲜血飞红。","□□□，零炮碎炙，不忍见渠侬。","喉咙。","才咽罢，龙肝凤髓，毕竟无踪。","谩赢得、生前夭寿多凶。","奉劝世人省悟，休恣意、激恼阎翁。","轮回转，本来面目，改换片时中。"],"p":"满庭芳"},{"id":"S00843","t":"极相思令・极相思","a":"太尉夫人","c":["柳烟霁色方春。","花露逼金茎。","秋千院落，海棠渐老，才过清明。","嫩玉腕托香脂脸，相傅粉、更与谁情。","秋波绽处，相思泪迸，天阻深诚。"],"p":"极相思令・极相思"},{"id":"S00844","t":"醉翁操","a":"郭祥正","c":["冷冷潺潺。","寒泉。","泻云间。","如弹。","醉翁洗心逃区寰。","自期猿鹤俱闲。","情未阑。","日暮造深原。","异芳谁与搴。","忘还。","琼楼玉阙，归去何年。","遗风馀思，犹有猿吟鹤怨。","花落溪边。","萧然。","莺语林中清圆。","空山。","春又残。","客怀文章仙。","度曲响涓涓。","清商回征星斗寒。"],"p":"醉翁操"},{"id":"S00845","t":"望江南・忆江南","a":"董","c":["缥缈烟中渔父桨，坡陀山上使君衙。"],"p":"望江南・忆江南"},{"id":"S00846","t":"望江南・忆江南","a":"董","c":["六月凉窗凉衽袖，二苏辞翰照青冥。"],"p":"望江南・忆江南"},{"id":"S00847","t":"绛都春","a":"丁仙现","c":["融和又报。","乍瑞霭霁色，皇州春早。","翠幰竞飞，玉勒争驰都门道。","鳌山彩结蓬莱岛。","向晚色、双龙衔照。","绛绡楼上，彤芝盖底，仰瞻天表。","缥缈。","风传帝乐，庆三殿共赏，群仙同到。","迤逦御香，飘满人间闻嬉笑。","须臾一点星球小。","渐隐隐、鸣鞘声杳。","游人月下归来，洞天未晓。"],"p":"绛都春"},{"id":"S00848","t":"减字木兰花","a":"刘泾","c":["凭谁妙笔。","横扫素缣三百尺。","天下应无。","此是钱塘湖上图。","一般奇绝。","云淡天高秋夜月。","费尽丹青。","只这些儿画不成。"],"p":"减字木兰花"},{"id":"S00849","t":"夏初临","a":"刘泾","c":["泛水新荷，舞风轻燕，园林夏日初长。","庭树阴浓，雏莺学弄新簧。","小桥飞如横塘。","跨青苹、绿藻幽香。","朱阑斜倚，霜纨未摇，衣袂先凉。","歌欢稀遇，怨别多同，路遥水远，烟淡梅黄。","轻衫短帽，相携洞府流觞。","况有红妆。","醉归来、宝蜡成行。","拂牙床。","纱厨半开，月在回廊。"],"p":"夏初临"},{"id":"S00850","t":"桂枝香","a":"黄裳","c":["人烟一簇。","正寄演，客飞升，翠微麓。","楼阁参差，下瞰水天红绿。","腰间剑去人安在，记千年、寸阴何速。","山趋三岸，潭吞二水，岁丰人足。","是处有、雕阑送目。","更无限笙歌，芳酝初熟。","休诧滕王看处，落霞孤鹜。","雨中尤爱烟波上，见渔舟、来去相逐。","数声歌向芦花，还疑是湘灵曲。"],"p":"桂枝香"},{"id":"S00851","t":"桂枝香","a":"黄裳","c":["插云翠壁。","为送目，入遥空，见山色。","金鼎丹成去也，晋朝高客。","百花岩下遗孙在，赋何人、离尘风骨。","翠微缘近，希夷志远，洞天踪迹。","近剑有、为龙信息。","怪潭上灵光，雷电相击。","尤好风波乍霁，鹭汀斜日。","倚栏白尽行人鬓，但沈沈、群岫凝碧。","利名休事蝇头，飞舠送君南北。"],"p":"桂枝香"},{"id":"S00852","t":"新荷叶","a":"黄裳","c":["落日衔山，行云载雨俄鸣。","一顷新荷，坐间疑是秋声。","烟波醉客，见快哉、风恼娉婷。","香和清点，为人吹在衣襟。","珠佩欢言，放船且向前汀。","绿伞红幢，自从天汉相迎。","飞鸥独落，芦边对、几朵繁英。","侑觞人唱，乍闻应似湘灵。"],"p":"新荷叶"},{"id":"S00853","t":"渔家傲","a":"黄裳","c":["多幸春来云雨少。","且教月与花相照。","清色真香庭院悄。","前事杳。","还嗟此景何时了。","莫道难逢开口笑。","夜游须趁人年少。","光泛雕栏寒料峭。","迂步绕。","不劳秉烛壶天晓。"],"p":"渔家傲"},{"id":"S00854","t":"蓦山溪","a":"葛胜仲","c":["出门西笑。","千里长安道。","不用引离声，便登荣、十洲三岛。","画船珠箔，苹末水风凉，随柳岸，楚台人，景与人俱好。","应嗟见晚，玉殿生清晓。","正是妙年时，步承明、谋身须早。","轺车肤使，新逐凯歌回，恩绋重，彩衣轻，嘉庆知多少。"],"p":"蓦山溪"},{"id":"S00855","t":"西江月","a":"葛胜仲","c":["艳曲醉歌金缕，朱门高耸铜环。","中天楼观共跻攀。","飞絮落花春晚。","低映绿阴朱户，斜拖素练沧湾。","银钩华榜五云间。","奕奕蛟龙字绾。"],"p":"西江月"},{"id":"S00856","t":"西江月","a":"葛胜仲","c":["靺鞨斜红带柳，琉璃涨绿平桥。","人在花月见新妖。","不数江南苏小。","恨寄飞花蔌蔌，情随流水迢迢。","鲤鱼风送木兰桡。","回棹荒鸡报晓。"],"p":"西江月"},{"id":"S00857","t":"西江月","a":"葛胜仲","c":["清樾已生昼寂，孤花尚表春馀。","象床筠簟燕堂虚。","初过晚凉微雨。","圭璧新来北苑，鲈鱼未减东吴。","捧觞红袖透香肤。","不浥翔龙烟缕。"],"p":"西江月"},{"id":"S00858","t":"临江仙","a":"米友仁","c":["昨夜扁舟沙外舣，淮山微雨初晴。","断云飞过月还明。","一天风露重，人在玉壶清。","水际不知何许是，遥林□辨微青。","醉迷归梦强□凌。","谁言东去雁，解寄此时情。"],"p":"临江仙"},{"id":"S00859","t":"小重山","a":"米友仁","c":["醉倚朱阑一解衣。","碧云迷望眼，断虹低。","近来休说带宽围。","人千里，还是燕双飞。","深院日初迟。","绮窗帘幕静，恨生眉。","不堪虚度是花时。","鸿来速，争解寄相思。"],"p":"小重山"},{"id":"S00860","t":"减字木兰花","a":"米友仁","c":["柳塘微雨。","两两飞鸥来复去。","倚遍重阑。","人在碧云山外山。","一春离怨。","日照绮窗长几线。","酒病情魔。","两事春来无奈何。"],"p":"减字木兰花"},{"id":"S00861","t":"点绛唇","a":"米友仁","c":["浩渺湖天，酒浮黄菊携佳侣。","澹烟疏雨。","去鲁方怀土。","倾盖相逢，引满哦奇语。","山围处。","兕觥频举。","不醉君无去。"],"p":"点绛唇"},{"id":"S00862","t":"念奴娇","a":"曾纡","c":["片帆暮落，正前村梅蕊，愁人如雪。","东陌西溪长记得，疏影横斜时节。","六出冰姿，玉人微步，笑里轻轻折。","兰房沈醉，暗香曾共私窃。","回头万水千山，一枝重见处，离肠千结。","料想临鸾消瘦损，时把啼红偷浥。","怎得伊来，许多幽恨，共拈青梢说。","如今千里，断魂空对明月。"],"p":"念奴娇"},{"id":"S00863","t":"上林春・一落萦","a":"曾纡","c":["东苑梅繁，豪健放乐，醉倒花前狂客。","靓妆微步，攀条弄粉，凌波遍寻青陌。","暗香堕靥。","更飘近、雾鬟蝉额。","倒金荷、念流光易失，幽姿堪惜。","惜花心、未甘鬓白。","南枝上、又见寻芳消息。","旧游回首，前欢如梦，谁知等闲抛掷。","稠红乱蕊，漫开遍、楚江南北。","独销魂，念谁寄、故园春色。"],"p":"上林春・一落萦"},{"id":"S00864","t":"秋霁","a":"曾纡","c":["木落山明，暮江碧，楼倚太虚寥廓。","素手飞觞，钗头笑取，金英满浮桑落。","鬓云慢约。","酒红拂破香腮薄。","细细酌。","帘外任教、月转画阑角。","当年快意登临，异乡节物，难禁离索。","故人远、凌波何在，惟有残英共寂寞。","愁到断肠无处著。","寄寒香与，凭渠问讯佳时，弄粉吹花，为谁梳掠。"],"p":"秋霁"},{"id":"S00865","t":"念奴娇","a":"曾纡","c":["江城春晚，正海棠临水，嫣然幽独。","秀色天姿真富贵，何必金盘华屋。","月下无人，雨中有泪，绝艳仍清淑。","丰肌得酒，嫩红微透轻縠。","晓日雾霭林深，佳人春睡思，朦胧初足。","笑出疏篱，端可厌，桃李漫山粗俗。","衔子飞来，鸿鹄何在，千里移西蜀。","明朝酒醒，乱红那忍轻触。"],"p":"念奴娇"},{"id":"S00866","t":"失调名","a":"秦湛","c":["藕叶清香胜花气。"],"p":"失调名"},{"id":"S00867","t":"卜算子","a":"秦湛","c":["春透水波明，寒峭花枝瘦。","极目烟中百尺楼，人在楼中否。","四和袅金凫，双陆思纤手。","拟倩东风浣此情，情更浓于酒。"],"p":"卜算子"},{"id":"S00868","t":"木兰花慢","a":"范周","c":["美兰堂昼永，晏清暑、晚迎凉。","控水槛风帘，千花竞拥，一朵偏双。","银塘。","尽倾醉眼，讶湘娥、倦倚两霓裳。","依约凝情鉴里，并头宫面高妆。","莲房。","露脸盈盈，无语处、恨何长。","有翡翠怜红，鸳鸯妒影，俱断柔肠。","凄凉。","芰荷暮雨，褪娇红、换紫结秋房。","堪把丹青对写，凤池归去携将。"],"p":"木兰花慢"},{"id":"S00869","t":"宝鼎现","a":"范周","c":["夕阳西下，暮霭红隘，香风罗绮。","乘丽景、华灯争放，浓焰烧空连锦砌。","睹皓月、浸严城如画，花影寒笼绛蕊。","渐掩映、芙蓉万顷，迤逦齐开秋水。","太守无限行歌意。","拥麾幢、光动珠翠。","倾万井、歌台舞榭，瞻望朱轮骈鼓吹。","控宝马、耀貔貅千骑。","银烛交光数里。","似乱簇、寒星万点，拥入蓬壶影里。","宴阁多才，环艳粉、瑶簪珠履。","恐看看、丹诏催奉，宸游燕侍。","便趁早、占通宵醉。","缓引笙歌妓。","任画角、吹老寒梅，月落西楼十二。"],"p":"宝鼎现"},{"id":"S00870","t":"秦楼月・忆秦娥","a":"吴则礼","c":["怅离阕。","淮南三度梅花发。","梅花发。","片帆西去，落英如雪。","新秦古塞人华发。","一樽别酒君听说。","君听说。","胡笳征雁，陇云沙月。"],"p":"秦楼月・忆秦娥"},{"id":"S00871","t":"江楼令","a":"吴则礼","c":["凭栏试觅红楼句，听考考、城头暮鼓。","数骑翩翩度孤戍。","尽雕弓白羽。","平生正被儒冠误。","待闲看、将军射虎。","朱槛潇潇过微雨。","送斜阳西去。"],"p":"江楼令"},{"id":"S00872","t":"虞美人","a":"吴则礼","c":["真香秀色盈盈女。","一笑重阳雨。","不应解怯晚丛寒。","眼底轻罗小扇、且团团。","吴云楚燕浑依旧。","更把金英嗅。","鲜鲜未恨出闺迟。","自许平生孤韵、与秋期。"],"p":"虞美人"},{"id":"S00873","t":"虞美人","a":"吴则礼","c":["夜寒闲倚西楼月。","消尽江南雪。","东风明日木兰船。","想见阳关声彻、雁连天。","斜斜洲渚溶溶水。","端负青春醉。","平安小字几时回。","空有暗香疏影、陇头梅。"],"p":"虞美人"},{"id":"S00874","t":"八声甘州","a":"向子𬤇","c":["扫长空、万里静无云，飞镜上天东。","欲骑鲸与问，一株丹桂，几度秋风。","取水珠宫贝阙，聊为洗尘容。","莫放素娥去，清影方中。","玄魄犹馀半壁，便笙篁万籁，尊俎千峰。","况十分端正，更鼓舞衰翁。","恨人生、时乎不再，未转头、欢事已沈空。","多酌我，岁华好处，浩意无穷。"],"p":"八声甘州"},{"id":"S00875","t":"水调歌头","a":"向子𬤇","c":["闰馀有何好，一年两中秋。","补天修月人去，千古想风流。","少日南昌幕下，更得洪徐苏李，快意作清游。","送日眺西岭，得月上东楼。","四十载，两人在，总白头。","谁知沧海成陆，萍迹落南州。","忍问神京何在，幸有芗林秋露，芳气袭衣裘。","断送馀生事，惟酒可忘忧。"],"p":"水调歌头"},{"id":"S00876","t":"水调歌头","a":"向子𬤇","c":["我生六十四，四度闰中秋。","碧天千里如水，明月更如流。","照我洛滨诗伯，携手仙卿廛隐，阆苑与同游。","人醉玉相倚，不肯下琼楼。","芗林老，章江上，几回头。","剩欲控鹤瀛海，聊下越王州。","直入白云深处，细酌仙人九酝，香雾尽侵裘。","共看一笑粲，以写我心忧。"],"p":"水调歌头"},{"id":"S00877","t":"水调歌头","a":"向子𬤇","c":["飘飘任公子，爽气欲横秋。","向日携诗过我，知不是凡流。","筑室清江西畔，巧占一川佳处，胜士日追游。","邀我出门去，柱月上新楼。","烂银盘，从树杪，出云头。","好是风流从事，同醉入青州。","须信人生如幻，七十古来稀有，销得几狐裘。","谁似芗林老，无喜亦无忧。"],"p":"水调歌头"},{"id":"S00878","t":"水调歌头","a":"刘望之","c":["劝子一杯酒，清泪不须流。","人间千古，俯仰如梦说扬州。","何况楚王台畔，为雨为云无限，人事付轻沤。","聚散随来去，天地有虚舟。","谪仙人，解金龟，换美酒。","载与君游，流水曲觞且赓酬。","麾盖飞迎过霭，江滨响振歌喉，拚醉又何求。","三万六千日，日日此优游。"],"p":"水调歌头"},{"id":"S00879","t":"鹊桥仙","a":"刘望之","c":["只应将巧畀人间，定却向、人间乞取。"],"p":"鹊桥仙"},{"id":"S00880","t":"如梦令","a":"刘望之","c":["休絮。","休絮。","我自明朝归去。"],"p":"如梦令"},{"id":"S00881","t":"渔父词・渔父","a":"法常","c":["此事楞严常露布。","梅华雪月交光处。","一笑寥寥空万古。","风瓯语。","迥然银汉横天宇。","蝶梦南华方栩栩。","斑斑谁跨丰干虎。","而今忘却来时路。","江山暮。","天涯目送鸿飞去。"],"p":"渔父词・渔父"},{"id":"S00882","t":"念奴娇","a":"陆淞","c":["黄橙紫蟹，映金壶潋滟，新醅浮绿。","共赏西楼今夜月，极目云无一粟。","挥麈高谈，倚栏长啸，下视鳞鳞屋。","轰然何处，瑞龙声喷蕲竹。","何况露白风清，银河澈汉，仿佛如悬瀑。","此景古今如有价，岂惜明珠千斛。","灏气盈襟，冷风入袖，只欲骑鸿鹄。","广寒宫殿，看人颜似冰玉。"],"p":"念奴娇"},{"id":"S00883","t":"瑞鹤仙","a":"陆淞","c":["脸霞红印枕。","睡觉来、冠儿还是不整。","屏间麝煤冷。","但眉峰压翠，泪珠弹粉。","堂深昼永。","燕交飞、风帘露井。","恨无人，与说相思，近日带围宽尽。","重省。","残灯朱幌，淡月纱窗，那时风景。","阳台路迥。","云雨梦，便无准。","待归来，先指花梢教看，却把心期细问。","问因循、过了青春，怎生意稳。"],"p":"瑞鹤仙"},{"id":"S00884","t":"卜算子","a":"卓世清","c":["流水一湾西。","晚坐孤亭静。","不见高人跨鹤归，风竹摇清影。","往古与来今，休用重重省。","十里梅花雪正晴，月挂遥山冷。"],"p":"卜算子"},{"id":"S00885","t":"浣溪沙","a":"李结","c":["花圃萦回曲径通。","小亭风卷绣帘重。","秋千闲倚画桥东。","双蝶舞馀红便旋，交莺啼处绿葱珑。","远山眉黛晚来浓。"],"p":"浣溪沙"},{"id":"S00886","t":"西江月","a":"李结","c":["若将花卉论行藏。","盍在凌烟阁上。"],"p":"西江月"},{"id":"S00887","t":"水调歌头","a":"向滈","c":["短棹舣湍石，华月满汀洲。","应知孤客无寐，特地照离忧。","谁念姮娥单枕，寂寞广寒宫殿，亦自□□□。","□□□□□，□□□□□。","□怜我，尘满袖，雪盈头。","两乡千里萦恨，何事不归休。","遥想闺中今夜，夜久寒生玉臂，犹自倚高楼。","别泪入湘水，归梦绕鄜州。"],"p":"水调歌头"},{"id":"S00888","t":"摊破丑奴儿・采桑子","a":"向滈","c":["自笑好痴迷。","只为俺、忒�沙�儿。","近来都得傍人道，帖儿上面，言儿语子，那底都是虚脾。","楼上等多时。","两地里、人马都饥。","低低说与当直底，轿儿抬转，喝声靠里，看俺么、裸而归。"],"p":"摊破丑奴儿・采桑子"},{"id":"S00889","t":"如梦令","a":"向滈","c":["楼上千峰翠𪩘。","楼下一湾清浅。","宝簟酒醒时，枕上月华如练。","留恋。","留恋。","明日水村烟岸。"],"p":"如梦令"},{"id":"S00890","t":"如梦令","a":"向滈","c":["谁伴明窗独坐。","和我影儿两个。","灯烬欲眠时，影也把人抛躲。","无那。","无那。","好个恓惶的我。"],"p":"如梦令"},{"id":"S00891","t":"念奴娇","a":"向","c":["霜威凄紧，政悲风摇落，千山群木。","十里清香方盛赏，岩桂娇黄姹绿。","九畹衰丛，东篱落蕊，到此成粗俗。","孤标高远，淡然还媚幽独。","憔悴诗老多情，问佳人底事，幽居空谷。","日暮天寒垂翠袖，愁倚萧萧修竹。","林下神情，月边风露，不向雕栏曲。","殷勤惟有，篆烟留得馀馥。"],"p":"念奴娇"},{"id":"S00892","t":"满庭芳","a":"向","c":["玉粉匀梅，曲尘浮柳，画檐迟日融融。","金猊喷麝，庭户转香风。","好是闲居戏彩，寿觞举、和满春容。","须知道，闺门孕秀，佳气在帘栊。","无穷。","观盛事，年年此会，拚醉金锺。","又何须、西池高宴仙宫。","尽把乔松□寿，兼大国、秦虢重封。","那堪更，门阑多喜，女婿近乘龙。"],"p":"满庭芳"},{"id":"S00893","t":"青玉案","a":"向","c":["别时抆泪花无语。","但一味、教郎住。","此日扁舟游远浦。","雨晴云树。","月斜烟树。","目断家何许。","红笺不寄相思句。","人在潇湘雁回处。","屈指归期秋已暮。","万千里路。","两三头绪。","恨不飞将去。"],"p":"青玉案"},{"id":"S00894","t":"青玉案","a":"向","c":["多情赋得相思分。","便揽断、愁和闷。","万种千般说不尽。","吃他圈柜，被他拖逗，便佛也、须教恨。","传消寄息无凭信。","水远山遥怎生奔。","梦也而今难得近。","伊还知道，为伊成病，便死也、谁能问。"],"p":"青玉案"},{"id":"S00895","t":"念奴娇","a":"程大昌","c":["冰容玉格，笑桃杏、非是闺帏装束。","待要舒华那更管，朔气凝波僵木。","五鬣山松，万年宫树，仅仅存馀绿。","一枝寄赠，教渠知道春复。","宁解车马成蹊，高标宜雪月，仍便溪谷。","纵有知闻，谁办得、驾野凌寒秉烛。","尽更荒闲，终难掩抑，风里香千斛。","林坰兴尽，此时鼎味翻足。"],"p":"念奴娇"},{"id":"S00896","t":"浣溪沙","a":"程大昌","c":["干处缁尘湿处泥。","天嫌世路净无时。","皓然岩谷总凝脂。","清夜月明人访戴，玉山顶上玉舟移。","一蓑渔画更能奇。"],"p":"浣溪沙"},{"id":"S00897","t":"浣溪沙","a":"程大昌","c":["兽炭香红漫应时。","遮寒姝丽自成围。","销金暖帐四边垂。","报道黑风飞柳絮，齐翻白雪侑羔卮。","那家斟唱□□词。"],"p":"浣溪沙"},{"id":"S00898","t":"浣溪沙","a":"程大昌","c":["翦水飞花也大奇。","熬波出素料同机。","会心一笑撒盐诗。","谁拥醴酏夸岁瑞，恨无坚白怨朝曦。","闭门高卧有人饥。"],"p":"浣溪沙"},{"id":"S00899","t":"水调歌头","a":"范成大","c":["元日至人日，未有不阴时。","新年叶气，无处人物不熙熙。","万岁声从天下，一札恩随春到，光采动天鸡。","寿域遍寰海，直过雪山西。","忆曾预，宣玉册，捧金卮。","如今万里，魂梦空绕五云飞。","想见大庭宫馆，重起三山楼观，双指赭黄衣。","此会古无有，何止古来稀。"],"p":"水调歌头"},{"id":"S00900","t":"浣溪沙","a":"范成大","c":["十里西畴熟稻香。","槿花篱落竹丝长。","垂垂山果挂青黄。","浓雾知秋晨气润，薄云遮日午阴凉。","不须飞盖护戎装。"],"p":"浣溪沙"},{"id":"S00901","t":"破阵子","a":"范成大","c":["漂泊天隅佳节，追随花下群贤。","只欠山阴修禊帖，却比兰亭有管弦。","舞裙香未湔。","泪竹斑中宿雨，折桐雪里蛮烟。","唤起杜陵饥客恨，人在长安曲水边。","碧云千叠山。"],"p":"破阵子"},{"id":"S00902","t":"鹧鸪天","a":"范成大","c":["楼观青红倚快晴。","惊看陆地涌蓬瀛。","南园花影笙歌地，东岭松风鼓角声。","山绕水，水萦城。","柳边沙外古今情。","坐中更有挥豪客，一段风流画不成。"],"p":"鹧鸪天"},{"id":"S00903","t":"贺新郎","a":"游次公","c":["暖霭浮晴篽。","锁垂杨、龙池罩阁，万丝千缕。","池上晓光分宿雾，日近群芳易吐。","寻并蒂、阑干凝伫。","不信钗头飞凤去，但宝刀、被妾还留住。","天一笑，万花妒。","阿娇正好金屋贮。","甚西风、易得萧疏，扇鸾尘土。","一自昭阳扃玉户，墙角土花无数。","况多病、情伤幽素。","别殿时闻箫鼓奏，望红云、冉冉知何处。","天尺五，去无路。"],"p":"贺新郎"},{"id":"S00904","t":"卜算子","a":"游次公","c":["风雨送人来，风雨留人住。","草草杯柈话别离，风雨催人去。","泪眼不曾晴，眉黛愁还聚。","明日相思莫上楼，楼上多风雨。"],"p":"卜算子"},{"id":"S00905","t":"满江红","a":"游次公","c":["云接苍梧，山莽莽、春浮泽国。","江水涨、洞庭相近，渐近空阔。","江燕飘飘身似梦，江花草草春如客。","望渔春、樵市隔平林，寒烟色。","方寸乱，成丝结。","离别近，先愁绝。","便满篷风雨，橹声孤急。","白发论心湖海暮，清樽照影苍浪窄。","看明年、天际下归舟，应先识。"],"p":"满江红"},{"id":"S00906","t":"贺新郎","a":"游次公","c":["斗柄回秋律。","素蟾飞、冰霜万里，满川金碧。","得月偏多何处是，惟有桥南第一。","正野迥、西风寒寂。","丹桂婆娑疏影在，想微瑕、未累千金璧。","河汉远，澹无迹。","知君有句酬佳夕。","尽高歌、胡床自倚，露漙珠溢。","坐到参横星欲暗，隐隐天低似笠。","但络纬、悲啼催织。","吟咏凄凉翻有恨，谅知音、人远空追忆。","谁为置，郑庄驿。"],"p":"贺新郎"},{"id":"S00907","t":"满江红","a":"赵老","c":["见说春时，新波涨、二川溶溢。","今底事、沙痕犹褪，石渠悭碧。","人意不须长作解，兴来便向杯中觅。","纵茂林修竹记山阴，千年一。","薰吹动，春工毕。","桥上景，壶中日。","况梅肥笋嫩，雨微鱼出。","只恐延英催入觐，不教绿野长均逸。","任多情、胡蝶满园飞，狂踪迹。"],"p":"满江红"},{"id":"S00908","t":"满江红","a":"赵老","c":["西郭园林，湖光净、暮寒清溢。","明月上，近环山翠，远摇天碧。","粉泽兰膏违俗尚，岩花磴蔓从谁觅。","问近来、铛脚许何人，吾其一。","欢乐事，休教毕。","经后夜，思前日。","想无心不竞，水流云出。","物外烟霞供啸咏，个中鱼鸟同休逸。","又何须、浮海访三山，寻仙迹。"],"p":"满江红"},{"id":"S00909","t":"满江红","a":"赵老","c":["潇洒星郎，吹绿鬓、胜游霞举。","秋又半，月磨云翳，籁传风语。","太一青黎光对射，中流荡漾莲舟舞。","戏人间、今夜水精宫，前无古。","吾家是，蓬山侣。","歌舞袖，苹花渚。","拟问津斜汉，乘槎南浦。","谒帝通明今得便，素娥拍手心先许。","笑画阑、三十六宫秋，花如土。"],"p":"满江红"},{"id":"S00910","t":"念奴娇","a":"赵老","c":["冰蟾驾月，荡寒光、不见层波层碧。","几岁中秋争得似，云卷秋声寂寂。","多谢星郎，来陪贤令，快赏鳌峰极。","广寒宫近，素娥不靳馀力。","夜久露落琼浆，神京归路，有云翘前迹。","当日仙人曾驭气，只学神交龟息。","今夜清尊，一齐分付，稳是乘槎客。","天津重到，霓裳何似闻笛。"],"p":"念奴娇"},{"id":"S00911","t":"鹧鸪天","a":"赵磻老","c":["白日青天一旦明。","旧时勋业此时情。","延英再许裴公对，商鼎须调传说羹。","千万载，辅宗祊。","挚天八柱愈峥嵘。","将军犁却龙庭后，岁傍鳌山奏太平。"],"p":"鹧鸪天"},{"id":"S00912","t":"浣溪沙","a":"赵磻老","c":["懒画娥眉倦整冠。","笋苞来点镜中鬟。","承恩容易报恩难。","鬒发未饶青箬笠，素鳞行簇水晶盘。","流觞元自不相干。"],"p":"浣溪沙"},{"id":"S00913","t":"瑞鹧鸪","a":"尤袤","c":["梁溪西畔小桥东。","落叶纷纷水映空。","五夜客愁花片里，一年春事角声中。","歌残玉树人何在，舞破山香曲未终。","却忆孤山醉归路，马蹄香雪衬东风。"],"p":"瑞鹧鸪"},{"id":"S00914","t":"瑞鹧鸪","a":"尤袤","c":["两行芳蕊傍溪阴。","一笑嫣然抵万金。","火齐照林光灼灼，彤霞射水影沈沈。","晓妆无力胭脂重，春醉方酣酒晕深。","定自格高难著句，不应工部总无心。"],"p":"瑞鹧鸪"},{"id":"S00915","t":"忆少年","a":"谢懋","c":["池塘绿遍，王孙芳草，依依斜日。","游丝卷晴昼，系东风无力。","蝶趁幽香蜂酿蜜。","秋千外、卧红堆碧。","心情费消遣，更梨花寒食。"],"p":"忆少年"},{"id":"S00916","t":"石州引・石州慢","a":"谢懋","c":["日脚斜明，秋色半阴，人意凄楚。","飞雪特地凝愁，做弄晚来微雨。","谁家别院，舞困几叶霜红，西风送客闻砧杵。","鞭马出都门，正潮平洲渚。","无语。","匆匆短棹，满载离愁，片帆高举。","京洛红尘，因念几年羁旅。","浅颦轻笑，旧时风月逢迎，别来谁画双眉妩。","回首一销凝，望归鸿容与。"],"p":"石州引・石州慢"},{"id":"S00917","t":"洞仙歌","a":"谢懋","c":["愁边雨细。","漠漠天如醉。","摇扬游丝晚风外。","酿轻寒、和暝色，花柳难胜，春自老，谁管啼红敛翠。","关情潜入夜，斜湿帘栊，几处挑灯耿无寐。","念阳台、当日事，好伴云来，因个甚、不入襄王梦里。","便添起、寒潮卷长江，又恐是离人，断肠清泪。"],"p":"洞仙歌"},{"id":"S00918","t":"杏花天","a":"谢懋","c":["海棠枝上东风软。","荡霁色、烟光弄暖。","双双燕子归来晚。","零落红香过半。","琵琶泪揾青衫浅。","念事与、危肠易断。","馀酲未解扶头懒。","屏里潇湘梦远。"],"p":"杏花天"},{"id":"S00919","t":"相见欢","a":"王质","c":["霜花零落全稀。","不成飞。","寒水溶溶漾漾、软琉璃。","红未涌，青已露，白都晞。","□□□□沙暖、戏凫鹥。"],"p":"相见欢"},{"id":"S00920","t":"长相思","a":"王质","c":["红疏疏，紫疏疏。","可惜飘零著地铺。","春残心转孤。","莺相呼。","燕相呼。","楼下垂杨遮得乌。","倚阑人已无。"],"p":"长相思"},{"id":"S00921","t":"长相思","a":"王质","c":["山青青。","水青青。","两岸萧萧芦荻林。","水深村又深。","风泠泠。","露泠泠。","一叶扁舟深处横。","垂杨鸥不惊。"],"p":"长相思"},{"id":"S00922","t":"生查子","a":"王质","c":["见汝小溪湾，修竹连疏影。","林杪动风声，惊下毵毵粉。","见汝大江郊，高浪摇枯本。","飞雪密封枝，直到斜阳醒。"],"p":"生查子"},{"id":"S00923","t":"瑞鹧鸪","a":"郭世模","c":["倾城一笑得留人。","舞罢娇娥敛黛愁。","明月宝鞲金洛臂，翠琼花珥碧搔头。","晴云片雪腰支袅，晚吹微波眼色秋。","清露亭皋芳草绿，轻绡软挂玉帘钩。"],"p":"瑞鹧鸪"},{"id":"S00924","t":"瑞鹤仙","a":"郭世模","c":["云阶连月地。","记旧游、身在温柔乡里。","花阴透窗绮。","罗衾拥残梦，流莺惊起。","银瓶水沸。","待梳妆、屏风共倚。","看情眉恨眼，宿粉剩香，乱愁无际。","长记。","多情消减，宋玉连墙，茂陵同里。","离怀似水。","天涯路，叹愁悴。","想鸳机织锦，鸾台窥镜，秦丝幽怨未已。","好归去、共把琴书，倚娇扶醉。"],"p":"瑞鹤仙"},{"id":"S00925","t":"朝中措","a":"郭世模","c":["青灯听雨夜荒凉。","归梦苦难长。","坐想玉奁鸳锦，空馀臂粉衣香。","枕边共语，窗前执手，帘外啼妆。","也是平生薄幸，须还几度思量。"],"p":"朝中措"},{"id":"S00926","t":"南歌子","a":"郭世模","c":["玉盏浮琼蚁，金奁吐翠虬。","醉乡归路接温柔。","暗卜幽期低约、笑藏阄。","索去眉先锁，将言泪已流。","小窗移火更迟留。","自剔灯花油涴、玉搔头。"],"p":"南歌子"},{"id":"S00927","t":"木兰花・玉楼春","a":"黄仁荣","c":["监郡风流欢洽。"],"p":"木兰花・玉楼春"},{"id":"S00928","t":"失调名","a":"许左之","c":["谁知花有主。","误入花深处。","放直下、酒杯干、便归去。"],"p":"失调名"},{"id":"S00929","t":"失调名","a":"许左之","c":["忆你当初，惜我不去。","伤我如今，留你不住。"],"p":"失调名"},{"id":"S00930","t":"念奴娇","a":"黄谈","c":["午风清暑，过西湖隐约，曾游堤路。","云径烟扉人境绝，真是珠宫玄圃。","倦倚阑干，笑呼艇子，同入荷花去。","一杯相属，恍然身在何许。","休怪梦入巫云，凌波罗袜，我在迷湘浦。","缥缈惊鸿飞燕举，却怨严城钟鼓。","百斛明珠，千金骏马，豪气今犹故。","归来清晓，幅巾犹带香露。"],"p":"念奴娇"},{"id":"S00931","t":"水龙吟","a":"阎苍舒","c":["少年闻说京华，上元景色烘晴昼。","朱轮画毂，雕鞍玉勒，九衢争骤。","春满鳌山，夜沈陆海，一天星斗。","正红球过了，鸣鞘声断，迥鸾驭、钧天奏。","谁料此生亲到，十五年、都城如旧。","而今但有，伤心烟雾，萦愁杨柳。","宝箓宫前，绛霄楼下，不堪回首。","愿皇图早复，端门灯火，照人还又。"],"p":"水龙吟"},{"id":"S00932","t":"柳梢青","a":"崔敦礼","c":["惊世文章，门户照人，外家衣钵。","多谢温存，相期宅相，此恩难说。","今朝祝寿樽前，共拜舞、诸孙下列。","但愿从今，一年强似，一年时节。"],"p":"柳梢青"},{"id":"S00933","t":"西江月","a":"崔敦礼","c":["暖日江南梅柳，春风堂上笙歌。","满斟醽醁笑声哗。","再拜千年寿嘏。","清健非缘服玉，红颜不是苍霞。","仙姿福禄自无涯。","要看沧溟绿野。"],"p":"西江月"},{"id":"S00934","t":"鹧鸪天","a":"崔敦礼","c":["本是瑶台月里仙。","笑麾鸾鹤住人间。","蟠桃一熟三千岁，剩对春风日月闲。","缡绶结，彩衣斑。","孙枝相应傍门阑。","年年同上长生酒，得见沧溟几度干。"],"p":"鹧鸪天"},{"id":"S00935","t":"鹧鸪天","a":"崔敦礼","c":["王母瑶池景物鲜。","蟠桃华宝不知年。","天教把定春风笑，来作人间长寿仙。","披蕊芨，诵云篇。","朝朝香火篆炉烟。","只将清静为真乐，合住春秋岁八千。"],"p":"鹧鸪天"},{"id":"S00936","t":"诉衷情","a":"陈造","c":["今朝人自藕州来。","花意尚迟迥。","几时画船同载，云锦照樽罍。","铃斋外，已全开。","是谁催，诗仙住处，和气回春，羯鼓如雷。"],"p":"诉衷情"},{"id":"S00937","t":"蝶恋花","a":"陈造","c":["山立翠屏开几面。","画舸经行，蒲葺□□岸。","想过溪门帆影转。","湖光忽作浮天远。","诗卷来时春晼晚。","愁把钓游，佳处寻思遍。","不许冷官人所贱。","拘缠自叹冰蚕茧。"],"p":"蝶恋花"},{"id":"S00938","t":"洞仙歌","a":"陈造","c":["蝶狂风闹，不到凝香地。","谁见飞琼巧梳洗。","厌孤标冷艳，不入时宜，银烛底，酒沁冰肌未睡。","东君怜索寞，分寄寒斋，闹耐残醒嗅芳蕊。","费西湖东阁，多少诗愁，援采笔、重与江梅品第。","算肯容、丹杏接仙游，又却要蕊宫，侍香扶醉。"],"p":"洞仙歌"},{"id":"S00939","t":"水调歌头","a":"陈造","c":["胜日探梅去，邂逅得奇观。","南枝的皪，陡觉品俗又香悭。","曾是瑶妃清瘦，帝与金丹换骨，酒韵上韶颜。","百叠侈罗袂，小立耐春寒。","凝香地，古仙伯，玉尘间。","烦公持并三友，秀色更堪飡。","定笑芙蓉骚客，认作东风桃杏，醉眼自相谩。","相见落诗笔，字字漱龙阑。"],"p":"水调歌头"},{"id":"S00940","t":"鹧鸪天","a":"黄定","c":["间世文章万选钱。","清时平步八花砖。","大开紫府瑶池宴，正是橙黄橘绿天。","金烛里，玉堂前。","翰林元是武夷仙。","雍容草罢明堂诏，留取天香馥寿筵。"],"p":"鹧鸪天"},{"id":"S00941","t":"念奴娇","a":"王自中","c":["扁舟夜泛，向子陵台下，偃帆收橹。","水阔风摇舟不定。","依约月华新吐。","细酌清泉，痛浇尘臆，唤起先生语。","当年纶钓，为谁高卧烟渚。","还念古往今来，功名可共，能几人光武。","一旦星文惊四海，从此故人何许。","到底轩裳，不如蓑笠，久矣心相与。","天低云淡，浩然吾欲高举。"],"p":"念奴娇"},{"id":"S00942","t":"水调歌头","a":"李处全","c":["金节照南国，画戟壮陪都。","严谯古角霜晓，雄胜压全吴。","葱倩采香古径，缥缈折梅新奏，春事早关渠。","谁识使君意，行乐与民俱。","披绣幌，薰宝篆，引琼酥。","黄堂富暇，宾幕谈笑足欢娱。","看取十行丹诏，遥指五云深处，归路接亨衢。","玉佩映鸳缀，不老奉轩虞。"],"p":"水调歌头"},{"id":"S00943","t":"水调歌头","a":"李处全","c":["上马趣携酒，送客古朱方。","秋风斜日山际，低草见牛羊。","酩酊不知更漏，但见横江白露，清映月如霜。","平睨广寒殿，谁说路歧长。","醉还醒，时起舞，念吾乡。","江山尔尔，回首千载几兴亡。","一笑书生事业，谁信管城居士，不换碧油幢。","好在中冷水，击楫奏伊凉。"],"p":"水调歌头"},{"id":"S00944","t":"水调歌头","a":"李处全","c":["明月浸瑶碧，河汉水交流。","偏来照我，知我白发不胜愁。","客里山中三载，枕上人间一梦，曾忆到瀛洲。","矫首蓬壶路，两腋已飕飕。","记扁舟，浮震泽，趁中秋。","垂虹亭上，与客千里快凝眸。","看剑引杯狂醉，饮水曲肱高卧，鹏鷃已同游。","起舞三人耳，横笛唤沙鸥。"],"p":"水调歌头"},{"id":"S00945","t":"水调歌头","a":"李处全","c":["落日暝云合，客子意如何。","定知今日，封六巽二弄干戈。","四望际天空阔，一叶凌涛掀舞，壮志未消磨。","为向吴儿道，听我扣舷歌。","我常欲，利剑戟，斩蛟鼍。","胡尘未扫，指挥壮士挽天河。","谁料半生忧患，成就如今老态，白发逐年多。","对此貌无恐，心亦畏风波。"],"p":"水调歌头"},{"id":"S00946","t":"鹧鸪天","a":"韩淲","c":["静乐堂中禅悦身。","相家庆袭两家春。","瑶池云气冲霄鹤，兰砌风标瑞世麟。","华屋邃，宝杯新。","年年秋与月常明。","笙箫且奏长生曲，宣劝还看送喜频。"],"p":"鹧鸪天"},{"id":"S00947","t":"忆秦娥","a":"韩淲","c":["香滴滴。","肌肤冰雪娇无力。","娇无力。","秋风凉冷，有谁消得。","洗妆不奈云鬟侧。","璧堂珠院空相忆。","空相忆。","轻颦浅笑，小梅标格。"],"p":"忆秦娥"},{"id":"S00948","t":"朝中措","a":"韩淲","c":["熏风两节照稽山。","三百里湖间。","镜上谁为贺老，棹船能伴官闲。","今年寿日，不妨吟啸，还上清班。","为寄长生新曲，齐眉想见酡颜。"],"p":"朝中措"},{"id":"S00949","t":"醉落魄・一斛珠","a":"韩淲","c":["风高木落。","壮心万里空回薄。","振衣待把尘埃濯。","声里斜阳，孤起戍楼角。","人生谁会谁为错。","年来但觉多离索。","黄花照地浑开却。","华发如斯，同和醉落魄。"],"p":"醉落魄・一斛珠"},{"id":"S00950","t":"瑞鹧鸪","a":"李廷忠","c":["洛浦风光烂漫时。","千金开宴醉为期。","花方著雨犹含笑，蝶不禁寒总是痴。","香腮擎吐浓华艳，不随桃李竞春菲。","东君自有回天力，看把花枝带月归。"],"p":"瑞鹧鸪"},{"id":"S00951","t":"生查子","a":"李廷忠","c":["玉女翠帷熏，香粉开妆面。","不是占春迟，羞被群花见。","纤手折柔条，绛雪飞千片。","流入紫金卮，未许停歌扇。"],"p":"生查子"},{"id":"S00952","t":"水龙吟","a":"李廷忠","c":["风流最数宣城，奇山秀水神仙府。","琴高台畔，花姑坛上，鸾翔凤舞。","春度玉墀，月升金掌，荣分铜虎。","想少陵，知有异人间出，三百载、留佳句。","岁岁椒盘柏斝，到明朝、又还重举。","阳和散作，千岩瑞雪，两溪甘雨。","汲取恩波，酿成禄酒，庆公初度。","有东风传报，都人已为，筑沙堤路。"],"p":"水龙吟"},{"id":"S00953","t":"沁园春","a":"李廷忠","c":["幕府增辉，前度刘郎，又还到来。","看芙蓉池畔，神凝秋水，绮罗丛里，欢动春雷。","彩笔新题，金钗半醉，当日英雄安在哉。","开筵处，是真仙福地，不著纤埃。","堪怜倦客情怀。","听吹竹弹丝金奏谐。","有黄花插鬓，何妨敧帽，绿橙醒酒，莫惜空罍。","坐上疏狂，帘间姝丽，应想横波一笑回。","停杯久，待娇歌缓劝，归骑休催。"],"p":"沁园春"},{"id":"S00954","t":"一落索","a":"方千里","c":["心抵江莲长苦。","凌波人去。","厌厌消瘦不胜衣，恨清泪、多于雨。","旧曲慵歌琼树。","谁传香素。","碧溪流水过楼前，问红叶、来何处。"],"p":"一落索"},{"id":"S00955","t":"垂丝钓","a":"方千里","c":["锦鳞绣羽。","难传愁态颦妩。","岸草际天，云影垂絮。","人何许。","谩并栏倚柱。","烟光暮。","怅榆钱满路。","送春𣨼酒。","欢期幽会希遇。","彩箫凤侣。","回首分携处。","双脸吹愁雨。","无限语。","再见时记否。"],"p":"垂丝钓"},{"id":"S00956","t":"满庭芳","a":"方千里","c":["山色澄秋，水光融日，浮萍飘碎还圆。","数行征雁，分破白鸥烟，高下回塘暗谷，写幽思、终日溅溅。","闲凝望，残霞暝霭，何处一渔船。","江南，思旧隐，筠轩野径，茅舍疏椽。","惯携壶花下，敧帽风前。","想像渊明旧节，琴中趣、何必疏弦。","归欤计，不将五斗，输与北窗眠。"],"p":"满庭芳"},{"id":"S00957","t":"隔浦莲・隔浦莲近拍","a":"方千里","c":["垂杨烟湿嫩葆。","别屿环清窈。","绀影浮新涨，夷犹终日鱼鸟，花妥庭下草。","鸣蝉闹。","暗绿藏台沼。","野轩小。","敧眠断梦，闲书风叶颠倒。","诗怀酒思，悔费十年昏晓。","投老红尘倦再到。","愁觉。","悠然心寄天表。"],"p":"隔浦莲・隔浦莲近拍"},{"id":"S00958","t":"沁园春","a":"吴泳","c":["𫛸鴂鸣兮，卉木萋止，维暮之春。","笑憨翁渐老，年加三豆，呆郎多事，诗记三星。","六十有三，高吟勇退，只有尧夫范景仁。","从今去，且亭前放鹤，溪上垂纶。","交亲。","散落如云。","仅留得尊前康健身。","有一编书传，一囊诗稿，一枰棋谱，一卷茶经。","红杏尚书，碧桃学士，看了虚名都赚人。","成何事，独青山有趣，白发无情。"],"p":"沁园春"},{"id":"S00959","t":"摸鱼儿","a":"吴泳","c":["甚一般、化工模子。","铸成一个拙底。","生来不向春头上，却跨暮春婪尾。","蓦省记。","早冉冉花阴，НН循除水。","虽然恁地。","但笑咏春风，闲推鸣瑟，别自有真意。","从前看，三十七年都未。","醉生声利场里。","浮云破处窗涵月，唤得自家醒起。","别料理。","那玉燕石麟，不当真符瑞。","彻头地位。","也须是长年，闻些好语，作个标月指。"],"p":"摸鱼儿"},{"id":"S00960","t":"沁园春","a":"吴泳","c":["春事阑斑，桐花烂漫，不堪凤栖。","叹交枰世道，容容是福，危航宦海，了了成痴。","邵子豪情，乐天狂态，六十六年才觉非。","溪山畔，要看承风月，舍我其谁。","文章高下随时。","料织锦应须用锦机。","愧老无健笔，高凌月胁，病无佳句，下解人颐。","君昔东坡，我今韩愈，造化一炉如小儿。","都休管，看龟翻荷露，燕落芹泥。"],"p":"沁园春"},{"id":"S00961","t":"满江红","a":"吴泳","c":["手摘桐花，怅还是、春风婪尾。","按锦瑟、一弦一柱，又添一岁。","紫马西来疑是梦，朱衣双引浑如醉。","较香山、七十欠三年，吾衰矣。","红袖却，青尊止。","檀板住，琼杯废。","淡香凝一室，自观生意。","事业不堪霜满镜，文章底用花如绮。","笑江滨、游女尚高歌，滕王记。"],"p":"满江红"},{"id":"S00962","t":"虞美人","a":"张景修","c":["春风曾见桃花面。","重见胜初见。","两枝独占小春开。","应怪刘郎迷路、又重来。","旁人应笑髯公老。","独爱花枝好。","世间好景不长圆。","莫放笙歌归院、且尊前。"],"p":"虞美人"},{"id":"S00963","t":"选冠子","a":"张景修","c":["嫩水挼蓝，遥堤映翠，半雨半烟桥畔。","鸣禽弄舌，蔓草萦心，偏称谢家池馆。","红粉墙头，柳摇金缕，纤柔舞腰低软。","被和风、搭在阑干，终日绣帘谁卷。","春易老，细叶舒眉，轻花吐絮，渐觉绿阴垂暖。","章台系马，灞水维舟，追念凤城人远。","惆怅阳关故国，杯酒飘零，惹人肠断。","恨青青客舍，江头风笛，乱云空晚。"],"p":"选冠子"},{"id":"S00964","t":"青玉案","a":"黄大临","c":["行人欲上来时路。","破晓雾、轻寒去。","隔叶子规声暗度。","十分酒满，舞裀歌袖，沾夜无寻处。","故人近送旌旗暮。","但听阳关第三句。","欲断离肠馀几许。","满天星月，看人憔悴，烛泪垂如雨。"],"p":"青玉案"},{"id":"S00965","t":"青玉案","a":"黄大临","c":["千锋百嶂宜州路。","天黯淡、知人去。","晓别吾家黄叔度。","弟兄华发，远山修水，异日同归处。","樽罍饮散长亭暮。","别语缠绵不成句。","已断离肠能几许。","水村山馆，夜阑无寐，听尽空阶雨。"],"p":"青玉案"},{"id":"S00966","t":"七娘子","a":"黄大临","c":["画堂银烛明如昼。","见林宗、巾垫羞蓬首。","针指花枝，线赊罗袖。","须臾两带还依旧。","劝君倒戴休令后。","也不须、更漉渊明酒。","宝箧深藏，浓香熏透。","为经十指如葱手。"],"p":"七娘子"},{"id":"S00967","t":"瑶台第一层","a":"赵仲御","c":["嶰管声催。","人报道、嫦娥步月来。","凤灯鸾矩，寒轻廉箔，光泛楼台。","万年春未老，更帝乡日月蓬莱。","从仙仗，看星河银界，锦绣天街。","欢陪。","千官万骑，九霄人在五云堆。","紫袍光里，星球宛转，花影徘徊。","未央宫漏水，散异香、龙阙崔嵬。","翠舆回。","奏仙歌韶吹，宝殿尊罍。"],"p":"瑶台第一层"},{"id":"S00968","t":"蓦山溪","a":"仲殊","c":["清江平淡，疏雨和烟染。","春在广寒宫，付江梅、先开素艳。","年年第一，相见越溪东，云体态，雪精神，不把年华占。","山亭水榭，别恨多销黯。","又是主人来，更不辜、香心一点。","题诗才思，清似玉壶冰，轻回顾，落尊前，桃杏声华减。"],"p":"蓦山溪"},{"id":"S00969","t":"鹊踏枝・蝶恋花","a":"仲殊","c":["斜日平山寒已薄。","雪过松梢，犹有残英落。","晚色际天天似幕。","一尊先与东风约。","邀得红梅同宴乐。","酒面融春，春满纤纤萼。","客意为伊浑忘却。","归船且傍花阴泊。"],"p":"鹊踏枝・蝶恋花"},{"id":"S00970","t":"点绛唇","a":"仲殊","c":["春遇瑶池，长空飞下残英片。","素光围练。","寒透笙歌院。","莫把寿阳，妆信传书箭。","掩香面。","汉宫寻遍。","月里还相见。"],"p":"点绛唇"},{"id":"S00971","t":"南歌子","a":"仲殊","c":["十里青山远，潮平陆带沙。","数声啼鸟怨年华。","又是凄凉时候、在天涯。","白露收残暑，清风衬晚霞。","绿杨堤畔闹荷花。","记得年时沽酒、那人家。"],"p":"南歌子"},{"id":"S00972","t":"如梦令","a":"吕本中","c":["海雁桥边春苦。","几见落花飞絮。","重到柳行西，懒问画楼何处。","凝伫。","凝伫。","十顷荷花风雨。"],"p":"如梦令"},{"id":"S00973","t":"宣州竹・虞美人","a":"吕本中","c":["小溪篷底湖风重。","吹破凝酥动。","一枝斜映庾门深。","冷淡无言香泛、月华清。","已经轻瘦谁为共。","魂绕徐熙□。","耻同桃李困春容。","肯向毫端开发、两云中。"],"p":"宣州竹・虞美人"},{"id":"S00974","t":"采桑子","a":"吕本中","c":["恨君不似江楼月，南北东西。","只有相随无别离。","恨君却似江楼月，暂满还亏。","暂满还亏。","待得团团是几时。"],"p":"采桑子"},{"id":"S00975","t":"采桑子","a":"吕本中","c":["乱红夭绿风吹尽，小市疏楼。","细雨轻鸥。","总向离人恨里收。","年年春好年年病，妾自西游。","水自东流。","不似残花一样愁。"],"p":"采桑子"},{"id":"S00976","t":"临江仙","a":"毕良史","c":["霜月穿帘乍白，苹风入坐偏凉。","麾灯促席诧时光。","桃花歌扇小，杨柳舞衫长。","别乘平分风月，词人剩引觥觞。","莫将幽恨搅刚肠。","尽添金掌露，频注玉猊香。"],"p":"临江仙"},{"id":"S00977","t":"好事近","a":"毕良史","c":["高会罢飞觞。","方锦再移珍席。","雷鼎乍烹甘液，试问侯苍璧。","翠虬宝钏捧殷勤，明灭粲金碧。","宾主放怀谈笑，满华堂春色。"],"p":"好事近"},{"id":"S00978","t":"小重山","a":"沈晦","c":["湖上秋来莲荡空。","年华都付与，木芙蓉。","采菱舟子两相逢。","双媚靥，一笑与谁浓。","斜日落溟蒙。","鸳鸯飞起处，水无踪。","望湖楼上两三峰。","人不见，林外数声钟。"],"p":"小重山"},{"id":"S00979","t":"点绛唇","a":"郭章","c":["翠柏丹崖，碧云深锁神仙府。","势盘龙虎。","楼观雄中土。","我欲停时，又恐斜阳暮。","黄尘路。","客怀良苦。","满目西山雨。"],"p":"点绛唇"},{"id":"S00980","t":"酹江月・念奴娇","a":"胡世将","c":["神州沈陆，问谁是、一范一韩人物。","北望长安应不见，抛却关西半壁。","塞马晨嘶，胡笳夕引，赢得头如雪。","三秦往事，只数汉家三杰。","试看百二山河，奈君门万里，六师不发。","阃外何人回首处，铁骑千群都灭。","拜将台敧，怀贤阁杳，空指冲冠发。","阑干拍遍，独对中天明月。"],"p":"酹江月・念奴娇"},{"id":"S00981","t":"蝶恋花","a":"赵鼎","c":["一朵江梅春带雪。","玉软云娇，姑射肌肤洁。","照影凌波微步怯。","暗香浮动黄昏月。","谩道广平心似铁。","词赋风流，不尽愁千结。","望断江南音信绝。","陇头行客空情切。"],"p":"蝶恋花"},{"id":"S00982","t":"蝶恋花","a":"赵鼎","c":["尽日东风吹绿树。","向晚轻寒，数点催花雨。","年少凄凉天付与。","更堪春思萦离绪。","临水高楼携酒处。","曾倚哀弦，歌断黄金缕。","楼下水流何处去。","凭栏目送苍烟暮。"],"p":"蝶恋花"},{"id":"S00983","t":"虞美人","a":"赵鼎","c":["魂消目断关山路。","曾送雕鞍去。","而今留滞古陪京。","还是一尊芳酒、送君行。","吾庐好在条山曲。","三径应芜没。","诛茅为我补东篱。","会待新春残腊、也来归。"],"p":"虞美人"},{"id":"S00984","t":"怨春风・一斛珠","a":"赵鼎","c":["宝鉴菱花莹。","孤鸾慵照影。","鱼书蝶梦两浮沉，恨恨恨。","结尽丁香，瘦如杨柳，雨疏云冷。","宿醉厌厌病。","罗巾空泪粉。","欲将远意托湘弦，闷闷闷。","香絮悠悠，画帘悄悄，日长春困。"],"p":"怨春风・一斛珠"},{"id":"S00985","t":"青玉案","a":"蒋璨","c":["三年枕上吴中路。","遣黄耳、随君去。","欲过松江呼小渡。","莫惊鸥鹭，四桥都是，老子经行处。","辋川图上看春暮。","长忆高人右丞句。","作个归期天未许。","春衫犹是，小蛮针线，曾湿西湖雨。"],"p":"青玉案"},{"id":"S00986","t":"汉宫春","a":"李邴","c":["潇洒江梅，向竹梢疏处，横两三枝。","东君也不爱惜，雪压霜欺。","无情燕子，怕春寒、轻失花期。","却是有，年年塞雁，归来曾见开时。","清浅小溪如练，问玉堂何似，茅舍疏篱。","伤心故人去后，冷落新诗。","微云淡月，对江天、分付他谁。","空自忆，清香未减，风流不在人知。"],"p":"汉宫春"},{"id":"S00987","t":"洞仙歌","a":"李邴","c":["一团娇软，是将春揉做，撩乱随风到何处。","自长亭、人去后，烟草萋迷，归来了、装点离愁无数。","飘扬无个事，刚被萦牵，长是黄昏怕微雨。","记那回，深院静，帘幕低垂，花阴下、霎时留住。","又只恐、伊家太轻狂，蓦地和春，带将归去。"],"p":"洞仙歌"},{"id":"S00988","t":"玉蝴蝶","a":"李邴","c":["壮岁分符方面，惠风草偃，禾稼春融。","报政朝天，归去稳步鳌宫。","望尧斝、九重绛阙，颁汉诏、五色芝封。","湛恩浓。","锦衣槐里，重继三公。","雍容。","临歧祖帐，绮罗环列，冠盖云丛。","满城桃李，尽将芳意谢东风。","柳烟轻、万条离恨，花露重、千点啼红。","莫匆匆。","且陪珠履，同醉金锺。"],"p":"玉蝴蝶"},{"id":"S00989","t":"念奴娇","a":"李邴","c":["素光练净，映秋山、隐隐修眉横绿。","𫛛鹊楼高天似水，碧瓦寒生银粟。","千丈斜晖，奔云涌雾，飞过卢仝屋。","更无尘气，满庭风碎梧竹。","谁念鹤发仙翁，当年曾共赏，紫岩飞瀑。","对影三人聊痛饮，一洗离愁千斛。","斗转参横，翩然归去，万里骑黄鹄。","满川霜晓，叫云吹断横玉。"],"p":"念奴娇"},{"id":"S00990","t":"上西平・金人捧露盘","a":"张元干","c":["卧扁舟，闻寒雨，数佳期。","又还是、轻误仙姿。","小楼梦冷，觉来应恨我归迟。","鬓云松处，枕檀斜、露泣花枝。","名利空萦系，添憔悴，谩孤恓。","得见了、说与教知。","偎香倚暖，夜炉围定酒温时。","任他飞雪洒江天，莫下层梯。"],"p":"上西平・金人捧露盘"},{"id":"S00991","t":"春光好","a":"张元干","c":["花恨雨，柳嫌风。","客愁浓。","坐久霜刀飞碎雪，一尊同。","劳烦玉指春葱。","未放箸、金盘已空。","更与个中寻尺素，两情通。"],"p":"春光好"},{"id":"S00992","t":"春光好","a":"张元干","c":["寒食近，踏青时。","画堂西。","可是春来偏倦绣，乍生儿。","香绵轻拂胭脂。","加文褓、初试班衣。","诮没功夫存问我，且怜伊。"],"p":"春光好"},{"id":"S00993","t":"清平乐","a":"张元干","c":["乱山深处。","雪拥溪桥路。","晓日乍明催客去。","惊起玉鸦翻树。","翠衾香暖檀灰。","一枝想见疏梅。","凭仗东风说与，画眉人共春回。"],"p":"清平乐"},{"id":"S00994","t":"瑞鹧鸪","a":"邓肃","c":["北书一纸惨天容。","花柳春风不敢秾。","未学宣尼歌凤德，姑从阮籍哭途穷。","此身已落千山外，旧事回思一梦中。","何日中兴烦吉甫，洗开阴翳放晴空。"],"p":"瑞鹧鸪"},{"id":"S00995","t":"临江仙","a":"邓肃","c":["带雨梨花看上马，问人底事匆匆。","于飞有愿恨难从。","大鹏抟九万，鹦鹉锁金笼。","忽忽便为千里隔，危岑已接高穹。","回头那忍问前踪。","家留烟雨外，人在斗牛中。"],"p":"临江仙"},{"id":"S00996","t":"临江仙","a":"邓肃","c":["百尺危楼初过雨，清风凛作轻寒。","一声渔笛在云端。","黄昏帘幕卷，新月半阑干。","青翼不来音信断，云窗杳隔三山。","何当携手便骖鸾。","今宵同胜景，玉斝不留残。"],"p":"临江仙"},{"id":"S00997","t":"临江仙","a":"邓肃","c":["春雪一瓯扶醉玉，翩翩两腋生风。","柳腰无力𣨼云踪。","陈郎投辖意，分袂忍匆匆。","白玉琢杯龙麝泛，瀼瀼天酒争浓。","何妨一饮上青骢。","晴空行夜月，缓辔水晶宫。"],"p":"临江仙"},{"id":"S00998","t":"水调歌头","a":"林淳","c":["湖波涨新绿，环绕越王山。","棠斋清昼馀暇，赢得静中观。","四面屏围碧玉，十里障开云锦，冰鉴倒晴澜。","目送孤鸿远，心与白鸥闲。","隘游人，喧鼓吹，杂歌欢。","晓天澄霁，花羞柳妒怯春寒。","好在风光满眼，只恐阳春有脚，催诏下天关。","剩写鹅溪幅，归去凤池看。"],"p":"水调歌头"},{"id":"S00999","t":"水调歌头","a":"林淳","c":["疏水绕城郭，农利遍三山。","使君重本，雅志初不在游观。","化出玉壶境界，挥洒锦囊词翰，笔下涌波澜。","天巧无馀蕴，意匠自舒闲。","拥鳌头，民同乐，颂声欢。","养花天气，云柔烟腻护朝寒。","桃李满城阴合，杨柳绕堤绿暗，幽鸟语间关。","似诉风光好，留与后人看。"],"p":"水调歌头"},{"id":"S01000","t":"水调歌头","a":"林淳","c":["螺水亘千古，鳌顶冠三山。","年丰帅阃尘静，栏槛纵遐观。","四望潮登浦溆，万顷绿浮原野，堤岸溢波澜。","畎浍皆沾足，日永桔槔闲。","肆华筵，鱼鸟乐，众宾欢。","良辰好景，年年莫放此盟寒。","且念新湖遗爱，莫作故园遐想，到处是乡关。","勋业知非晚，聊把镜频看。"],"p":"水调歌头"},{"id":"S01001","t":"菩萨蛮","a":"林淳","c":["鹅溪净称烟笼月。","澄心白称光浮雪。","净白两俱宜。","天然浓淡枝。","花光神意远。","吮墨含毫浅。","依约有香来。","春风随手开。"],"p":"菩萨蛮"},{"id":"S01002","t":"洞仙歌","a":"廖行之","c":["虞弦挥按，甫奏熏风曲。","两两尧蓂长新绿。","揖鳌峰、连雁峤，𫐖轕圆融，总里许、北郭门围全属。","年年才见夏，喜溢枌榆，龙穴霏烟霭晴谷。","向氤氲和气里，岁奉瑶觞，试屈指、几阅梅林初熟。","待一品官高见玄孙，算八十彩衣，更饶遐福。"],"p":"洞仙歌"},{"id":"S01003","t":"念奴娇","a":"廖行之","c":["薰风庭院，报槐阴拥翠，池波凝绿。","瑞气葱葱浮燕寝，羽仗霓旌相属。","𬸚𬸦开祥，长庚入梦，诧列仙图箓。","林泉高迈，肯应轩冕尘俗。","好是妙舞清歌，浮瓜沈李，荐杯中醽醁。","鹊尾炉生香篆细，又作如何祈祝。","试问蓬莱，丹崖胜处，几摘蟠桃熟。","东方何在，凛然能继高躅。"],"p":"念奴娇"},{"id":"S01004","t":"贺新郎","a":"廖行之","c":["玉宇□蓬户。","渺凉声、箾椮梧井，乱零枫浦。","得得西山朝来爽，碧瘦千崖万树。","清兴在、烟霞深处。","拄笏风流今谁是，但闻鸡、夜半犹狂舞。","试举看，渠多许。","青云万里君夷路。","肯区区、辀张兔穴，沈迷金坞。","流水高山真难料，休把朱弦浪抚。","任展转、翻云覆雨。","且对佳时随意乐，更从今、莫问惊人句。","算万事，总天赋。"],"p":"贺新郎"},{"id":"S01005","t":"贺新郎","a":"廖行之","c":["修月三千户。","拥冰轮、同游碧落，问津牛浦。","上界真仙多才思，乞与瑶阶玉树。","渺万里、人间何处。","云叶依依分清荫，忆当时、掩映霓裳舞。","算万木，宁如许。","年年萧爽幽岩路。","倚西风、吹香金粟，超然云坞。","一洗纷纷凡花尽，堪写清商对抚。","为豁散、蛮烟瘴雨。","脱俗高标谁能领，向骚人、正欠题新句。","须大手，与君赋。"],"p":"贺新郎"},{"id":"S01006","t":"醉落魄・一斛珠","a":"京镗","c":["芳尘休扑。","名花唤我相追逐。","浅妆不比梅敧竹。","深注朱颜，娇面称红烛。","阿娇合贮黄金屋。","是谁却遣来空谷。","酡颜遍倚阑干曲。","一段风流，不枉到西蜀。"],"p":"醉落魄・一斛珠"},{"id":"S01007","t":"好事近","a":"京镗","c":["急雨逐骄阳，洗出长空新月。","更对银河风露，觉今宵都别。","不须乞巧拜中庭，枉共天孙说。","且信平生拙极，耐岁寒霜雪。"],"p":"好事近"},{"id":"S01008","t":"好事近","a":"京镗","c":["杰阁耸层霄，几度晓风残月。","同是鹓行旧侣，慰十年离别。","一杯相属莫留残，试倚阑干说。","趁取簪花绿鬓，未骎骎如雪。"],"p":"好事近"},{"id":"S01009","t":"定风波","a":"京镗","c":["何必穿针上彩楼。","剖瓜插竹诉穷愁。","闻道天孙相会处，银汉无津，不待泛兰舟。","动是隔年寻素约，何似，每逢清梦且嬉游。","但得举杯开笑口，对月临风，总胜鹊桥秋。"],"p":"定风波"},{"id":"S01010","t":"蝶恋花","a":"张震","c":["梅子初青春已暮。","芳草连云，绿遍西池路。","小院绣垂帘半举。","衔泥紫燕双飞去。","人在赤阑桥畔住。","不解伤春，还解相思否。","清梦欲寻犹间阻。","沙窗一夜萧萧雨。"],"p":"蝶恋花"},{"id":"S01011","t":"鹧鸪天","a":"张震","c":["宽尽香罗金缕衣。","心情不似旧家时。","万丝柳暗才飞絮，一点梅酸已着枝。","金底背，玉东西。","前欢赢得两相思。","伤心不及风前燕，犹解穿帘度幕飞。"],"p":"鹧鸪天"},{"id":"S01012","t":"鹧鸪天","a":"张震","c":["横素桥边景最佳。","绿波清浅见琼沙。","衔泥燕子迎风絮，得食鱼儿趁浪花。","春已暮，日初斜。","画船箫鼓是谁家。","兰桡欲去空留恋，醉倚阑干看晚霞。"],"p":"鹧鸪天"},{"id":"S01013","t":"蓦山溪","a":"张震","c":["青梅如豆，断送春归去。","小绿间长红，看几处、云歌柳舞。","偎花识面，对月共论心，携素手，采香游，踏遍西池路。","水边朱户。","曾记销魂处。","小立背秋千，空怅望、娉婷韵度。","杨花扑面，香糁一帘风，情脉脉，酒厌厌，回首斜阳暮。"],"p":"蓦山溪"},{"id":"S01014","t":"蝶恋花","a":"王炎2","c":["纤手行杯红玉润。","满眼花枝，雨过胭脂嫩。","新月一眉生浅晕。","酒阑无奈添春困。","唤起醉魂君不问。","憔悴颜容，羞与花相近。","人自无情花有韵。","风光易老何须恨。"],"p":"蝶恋花"},{"id":"S01015","t":"蝶恋花","a":"王炎2","c":["柳暗西湖春欲暮。","无数青丝，不系行人住。","一点心情千万绪。","落花寂寂风吹雨。","唤起声中人独睡。","千里明驼，不踏山间路。","谩道遣愁除是醉。","醉还易醒愁难去。"],"p":"蝶恋花"},{"id":"S01016","t":"点绛唇","a":"王炎2","c":["雨湿东风，谁家燕子穿庭户。","孤村薄暮。","花落春归去。","浪走天涯，归思萦心绪。","家何处。","乱山无数。","不记来时路。"],"p":"点绛唇"},{"id":"S01017","t":"水调歌头","a":"王炎2","c":["江月冷如水，江水碧于空。","晚来一霎过雨，为我洗秋容。","悄悄四山人静，凛凛三更露下，天阔叫孤鸿。","唤醒蓬窗梦，身在水晶宫。","揖湘妃，招月娣，御清风。","素琴韵远，不觉醉眼杏花红。","禹穴骑鲸仙去，东海钓鳌人远，此意与谁同。","倚柁一长啸，出壑舞鱼龙。"],"p":"水调歌头"},{"id":"S01018","t":"摸鱼子","a":"张炎","c":["向天涯、水流云散，依依往事非旧。","西湖见说鸥飞去，知有海翁来否。","风雨后。","甚客里逢春，尚记花间酒。","空嗟皓首。","对茂苑残红，携歌占地，相趁小垂手。","归时候。","花径青红尚有。","好游何事诗瘦。","龟蒙未肯寻幽兴，曾恋志和渔叟。","吟啸久。","爱如此清奇，岁晚忘年友。","呼船渡口。","叹西出阳关，故人何处，愁在渭城柳。"],"p":"摸鱼子"},{"id":"S01019","t":"南乡子","a":"张炎","c":["风月似孤山。","千树斜横水一环。","天与清香心独领，怡颜。","冰雪中间屋数间。","庭户隔尘寰。","自有云封底用关。","却笑桃源深处隐，跻攀。","引得渔翁见不难。"],"p":"南乡子"},{"id":"S01020","t":"南楼令・唐多令","a":"张炎","c":["一见又天涯。","人生可叹嗟。","想难忘、江上琵琶。","诗酒一瓢风雨外，都莫问，是谁家。","怜我鬓先华。","何愁归路赊。","向西湖、重隐烟霞。","说与山童休放鹤，最零落，是梅花。"],"p":"南楼令・唐多令"},{"id":"S01021","t":"醉落魄・一斛珠","a":"张炎","c":["镂花镌叶。","满枝风露和香撷。","引将芳思归吟箧。","梦与魂同，闲了弄香蝶。","小楼帘卷歌声歇。","幽篁独处泉呜咽。","短笺空在愁难说。","霜角寒梅，吹碎半江月。"],"p":"醉落魄・一斛珠"},{"id":"S01022","t":"菩萨蛮","a":"陈义","c":["天生体态腰肢细。","新词唱彻歌声利。","出口便清奇。","扬尘簌簌飞。","主人恩义重。","宴出红妆宠。","便要赏新荷。","时光也不多。"],"p":"菩萨蛮"},{"id":"S01023","t":"菩萨蛮","a":"陈义","c":["去年共饮菖蒲酒。","今年却向僧房守。","好事更多磨。","教人没奈何。","主人恩义重。","知我心头痛。","待要赏新荷。","争知疾愈么。"],"p":"菩萨蛮"},{"id":"S01024","t":"菩萨蛮","a":"陈义","c":["平生只被今朝误。","今朝却把平生补。","重午一年期。","斋僧只待时。","主人恩义重。","两载蒙恩宠。","清净得为僧。","幽闲度此生。"],"p":"菩萨蛮"},{"id":"S01025","t":"菩萨蛮","a":"陈义","c":["包中香黍分边角。","彩丝剪就交绒索。","樽俎泛菖蒲。","年年五月初。","主人恩义重。","对景承欢宠。","何日玩山家。","葵蒿三四花。"],"p":"菩萨蛮"},{"id":"S01026","t":"满庭芳","a":"梅娇","c":["一种阳和，玉英初纵，雪天分外精神。","冰肌肉骨，别是一家春。","楼上笛声三弄，百花都未知音。","明窗畔，临风对月，曾结岁寒盟。","笑杏花何太晚，迟疑不发，等待春深。","只宜远望，举目似烧林。","丽质芳姿虽好，一时取媚东君。","争如我，青青结子，金鼎内调羹。"],"p":"满庭芳"},{"id":"S01027","t":"满庭芳","a":"杏俏","c":["景傍清明，日和风暖，数枝浓淡胭脂。","春来早起，惟我独芳菲。","门外几番雨过，似佳人、细腻香肌。","堪赏处，玉楼人醉，斜插满头归。","梅花何太早，消疏骨肉，叶密花稀。","不逢媚景，开后甚孤栖。","恐怕百花笑你，甘心受、雪压霜欺。","争如我，年年得意，占断踏青时。"],"p":"满庭芳"},{"id":"S01028","t":"飞龙宴","a":"苏小娘","c":["炎炎暑气时，流光闪烁，闲扃深院。","水阁凉亭，半开帘幕遥观。","灼灼榴花吐艳。","细雨洒、小荷香浅。","树影竹影，清凉潇洒，枕簟摇纨扇。","堪叹浮世忙如箭。","对良辰欢乐，莫辞频劝。","遇酒逢歌，恣情遂意迷恋。","须信人生聚散。","奈区区、利牵名绊。","少年未倦。","良天皓月金尊满。"],"p":"飞龙宴"},{"id":"S01029","t":"踏莎行","a":"张魁","c":["凤髻堆鸦，香酥莹腻。","雨中花占街前地。","弓鞋湿透立多时，无人为问深深意。","眉上新愁，手中文字。","如何不倩鳞鸿去。","想伊只诉薄情人，官中不管闲公事。"],"p":"踏莎行"},{"id":"S01030","t":"声声慢","a":"张枢密","c":["星冠懒带，鹤氅慵披，色心顿起兰房。","离了三清归去，作个新郎。","良宵自有佳景，更烧甚、清香德香。","瑶台上，便玉皇亲诏，也则寻常。","常观里、孤孤令令，争如赴鸳闱，夜夜成双。","救苦天尊，你且远离他方。","更深酒阑歌罢，𣨼玉人、云雨交相。","问则甚，咱门这里拜章。"],"p":"声声慢"},{"id":"S01031","t":"踏莎行","a":"申二官人","c":["葱草身才、灯心脚手。","闲时与蝶花间走。","有时跌倒屋檐头，蜘蛛网里翻筋斗。","水马驰来，藕丝缠就。","鹅毛般上三杯酒。","等闲试把秤儿秤，平盘分上何曾有。"],"p":"踏莎行"},{"id":"S01032","t":"失调名","a":"杨岛仙","c":["待得团圆时候，樽前问这时节。"],"p":"失调名"},{"id":"S01033","t":"失调名","a":"吴德远","c":["过平康巷陌绮罗丛。","赢得佳人，妙舞艳歌，争劝金锺。"],"p":"失调名"},{"id":"S01034","t":"失调名","a":"连静女","c":["朦胧月影，黯淡花阴，独立等多时。","只恐冤家误约，又怕他、侧近人知。","千回作念，万般思忆，心下暗猜疑。","蓦地偷来厮见，抱著郎、语颤声低。","轻移莲步，暗褪罗裳，携手过廊西。","已是更阑人静，粉郎恣意怜伊。","霎时云雨，半晌欢娱，依旧两分飞。","去也回眸告道，待等奴、兜上鞋儿。"],"p":"失调名"},{"id":"S01035","t":"武陵春","a":"连静女","c":["人道有情须有梦，无梦岂无情。","夜夜相思直到明。","有梦怎生成。","伊若忽然来梦里，邻笛又还惊。","笛里声声不忍听。","浑是断肠声。"],"p":"武陵春"},{"id":"S01036","t":"生查子","a":"楚娘","c":["去年梅雪天，千里人归远。","今岁雪梅天，千里人追怨。","铁石作心肠，铁石刚犹软。","江海比君恩，江海深犹浅。"],"p":"生查子"},{"id":"S01037","t":"南歌子","a":"谢福娘","c":["闲傍药栏西。","正是春光三月时。","深紫浅红光照眼，依稀。","有似西施醉枕敧。","摘放胆瓶儿。","冷艳幽光映酒卮。","曾记古人题品语，祆知。","今夜花王得艳妻。"],"p":"南歌子"},{"id":"S01038","t":"南歌子","a":"张时","c":["暖日未斜西。","正是迷花𣨼酒时。","红药雕阑呈冷艳，依稀。","花重枝柔压半敧。","相对耍猴儿。","一捻幽芳劝酒卮。","魏紫姚黄来觑着，方知。","准拟今宵醉伴妻。"],"p":"南歌子"},{"id":"S01039","t":"人月圆","a":"双渐","c":["碧纱低映秦娥面，咫尺暗香浓。","瑶池春晚，长天共恨，烟锁芙蓉。","夭桃再赏，流莺声巧，不待春工。","樽前潜想，樱桃破处，得似香红。"],"p":"人月圆"},{"id":"S01040","t":"鹧鸪天","a":"黄夫人","c":["先自春光似酒浓。","时听莺语透帘栊。","小桥杨柳飘香絮，山寺绯桃散落红。","莺渐老，蝶西东。","春归难觅恨无穷。","侵阶草色迷朝雨，满地梨花逐晓风。"],"p":"鹧鸪天"},{"id":"S01041","t":"醉亭楼","a":"刘使君","c":["平生性格，随分好些春色。","沉醉恋花陌。","虽然年老心未老，满头花压巾帽侧。","鬓如霜，须似雪，自嗟恻。","几个相知劝我染，几个相知劝我摘。","染摘有何益。","当初怕成短命鬼，如今已过中年客。","且留些，妆晚景，尽教白。"],"p":"醉亭楼"},{"id":"S01042","t":"浣溪沙","a":"李氏2","c":["无力蔷薇带雨低。","多情蝴蝶趁花飞。","流水飘香乳燕啼。","南浦魂销春不管，东阳衣减镜仙知。","小楼今夜月依依。"],"p":"浣溪沙"},{"id":"S01043","t":"失调名","a":"朱希真","c":["苦汝临期话别，与君挽手叮咛。","归期誓约十馀朝，去后又经三四月，鱼沉雁杳，空倚著六曲阑干。","凤只鸾孤，谩独宿半床衾枕。","欲寄花牌传密意，奈无黄耳堪凭。","待修锦字诉离情。"],"p":"失调名"},{"id":"S01044","t":"采桑子","a":"朱希真","c":["王孙去后无芳草，绿遍书阶。","尘满妆台。","粉面羞搽泪满腮。","教我甚情怀。","去时梅蕊全然少，等到花开花已成梅。","梅子青青又待黄。","兀自未归来。"],"p":"采桑子"},{"id":"S01045","t":"一翦梅","a":"张幼谦","c":["同年同日又同窗。","不似鸾凰。","谁似鸾凰。","石榴树下事匆忙。","惊散鸳鸯。","拆散鸳鸯。","一年不到读书堂。","教不思量。","怎不思量。","朝朝暮暮只烧香。","有分成双。","愿早成双。"],"p":"一翦梅"},{"id":"S01046","t":"长相思","a":"张幼谦","c":["天有神。","地有神。","海誓山盟字字真。","如今墨尚新。","过一春。","又一春。","不解金钱变作银。","如何忘却人。"],"p":"长相思"},{"id":"S01047","t":"卜算子","a":"张幼谦","c":["去时不由人，归怎由人也。","罗带同心结到成，底事教┾舍。","心是十分真，情没些儿假。","若道归迟打棹篦，甘受三千下。"],"p":"卜算子"},{"id":"S01048","t":"卜算子","a":"罗惜惜","c":["幸得那人归，怎便教来也。","一日相思十二辰，真是情难舍。","本是好因缘，又怕因缘假。","若是教随别个人，相见黄泉下。"],"p":"卜算子"},{"id":"S01049","t":"应景乐","a":"萧回","c":["金陵故国。","极目长江浩渺，千重隔。","山无际，临湍怒涛碛。","俯春城苇寂。","芳昼迤逦，一簇烟村将晚，严光旧台侧。","何处倦游客。","对此景惹起离怀，顿觉旧日意，魂黯愁积。","幽恨绵绵，何计消溺。","回首洛城东，千里暮云碧。"],"p":"应景乐"},{"id":"S01050","t":"阮郎归","a":"春娘","c":["胡虏中原乱似麻。","此景依稀似永嘉。","丁珠片玉落泥沙。","何时返翠华。","呈祥鸾凤失仙槎。","因循离恨加。","前生应是负偿他。","思量无岸涯。"],"p":"阮郎归"},{"id":"S01051","t":"西江月","a":"张生2","c":["一望朱楼巧小，四边绣幕低垂。","个人活脱似杨妃。","倚遍阑干十二。","最苦两双情眼，难禁四只愁眉。","无言回首日沉西。","不道一声安置。"],"p":"西江月"},{"id":"S01052","t":"小重山","a":"张生2","c":["杏火无烟烧断肠。","织成春恨切，柳丝长。","当时谁是种花郎。","却不教，柳近杏花傍。","柳道不须忙。","春深须是有，絮飞扬。","等闲扑着杏腮香。","恁时节，选甚隔池塘。"],"p":"小重山"},{"id":"S01053","t":"西江月","a":"郑云娘","c":["一片冰轮皎洁，十分桂魄婆娑。","不施方便是何如。","莫是嫦娥妒我。","虽则清光可爱，奈缘好事多磨。","仗谁传与片云呵。","遮取霎时则个。"],"p":"西江月"},{"id":"S01054","t":"减字木兰花","a":"吕岩","c":["暂游大庾。","白鹤飞来谁共语。","岭畔人家。","曾见寒梅几度花。","春来春去。","人在落花流水处。","花满前溪。","藏尽神仙人不知。"],"p":"减字木兰花"},{"id":"S01055","t":"渔家傲","a":"吕岩","c":["二月江南山水路。","李花零落春无主。","一个鱼儿无觅处。","风和雨。","玉龙生甲归天去。"],"p":"渔家傲"},{"id":"S01056","t":"望江南・忆江南","a":"吕岩","c":["瑶池上，瑞雾霭群仙。","素练金童锵凤板，青衣玉女啸鸾笙。","身在大罗天。","沉醉处，缥缈玉京山。","唱彻步虚清燕罢，不知今夕是何年。","海水又桑田。"],"p":"望江南・忆江南"},{"id":"S01057","t":"梧桐影","a":"吕岩","c":["落日斜，西风冷。","幽人今夜来不来，教人立尽梧桐影。"],"p":"梧桐影"},{"id":"S01058","t":"失调名","a":"海哥","c":["海哥风措。","被渔人、下网打住。","将在帝城中，每日教言语。","甚时节、放我归去。","龙王传语。","这里思量你。","千回万度。","螃蟹最恓惶，鲇鱼尤忧虑。"],"p":"失调名"},{"id":"S01059","t":"八声甘州","a":"何仙姑","c":["千门万户，尽七颠八倒，掘地寻天。","真个玄妙，返作笑胡言。","无为大道人行少，向捏怪途中有万千。","伤感。","蜣转却做灵丹。","无奈伤嗟最苦，又不知端的，枉弃了家缘。","时间清净，岂解汞收铅。","心思意想，何曾遣暂合眼。","阴魔作睡缠。","展转。","越思深返作仇冤。","谁信无中生有，有中生无，万派归源。"],"p":"八声甘州"},{"id":"S01060","t":"蝶恋花","a":"宋媛","c":["云破蟾光穿晓户。","敧枕凄凉，多少伤心处。","惟有相思情最苦。","檀郎咫尺千山阻。","莫学飞花兼落絮。","摇荡春风，迤逦抛人去。","结尽寸肠千万缕。","如今认得先辜负。"],"p":"蝶恋花"},{"id":"S01061","t":"阮郎归","a":"宋媛","c":["东风成阵送春归。","庭花高下飞。","柔条缭绕入帘帏。","斑斑装舞衣。","云鬓乱，坐偷啼。","郎来何负期。","人生恰似这芳菲。","芳菲能几时。"],"p":"阮郎归"},{"id":"S01062","t":"清平乐令・清平乐","a":"吴城小龙女","c":["帘卷曲栏独倚。","江展暮天无际。","泪眼不曾晴，家在吴头楚尾。","数点雪花乱委。","扑漉沙鸥惊起。","诗句欲成时，没入苍烟丛里。"],"p":"清平乐令・清平乐"},{"id":"S01063","t":"望江南・忆江南","a":"蔡真人","c":["阑干曲，红扬绣帘旌。","花嫩不禁纤手捻，被风吹去意还惊。","眉黛蹙山青。","铿铁板，闲引步虚声。","尘世无人知此曲，却骑黄鹤上瑶京。","风冷月华清。"],"p":"望江南・忆江南"},{"id":"S01064","t":"烛影摇红","a":"懒堂女子","c":["绿净湖光，浅寒先到芙蓉岛。","谢池幽梦属才郎，几度生春草。","尘世多情易老。","更那堪、秋风袅袅。","晓来羞对，香芷汀洲，枯荷池沼。","恨锁横波，远山浅黛无人扫。","湘江人去叹无依，此意从谁表。","喜趁良宵月皎。","况难逢、人间两好。","莫辞沉醉，醉入屏山，只愁天晓。"],"p":"烛影摇红"},{"id":"S01065","t":"惜奴娇","a":"巫山神女","c":["瑶阙琼宫，高枕巫山十二。","睹瞿塘、千载滟滟云涛沸。","异景无穷好，闲吟满酌金卮。","忆前时。","楚襄王，曾来梦中相会。","吾正鬓乱钗横，敛霞衣云缕。","向前低揖。","问我仙职。","桃杏遍开，绿草萋萋铺地。","燕子来时，向巫山、朝朝行雨暮行云，有闲时，只恁画堂高枕。"],"p":"惜奴娇"},{"id":"S01066","t":"惜奴娇","a":"巫山神女","c":["绕绕云梯，上彻青霄霞外。","与诸仙同饮，镇长春醉。","虎啸猿吟，碧桃香异风飘细。","希奇。","想人间难识，这般滋味。","姮娥奏乐箫韶，有仙音异品，自然清脆。","遏住行云不敢飞。","空凝滞。","好是波澜澄湛，一溪香水。"],"p":"惜奴娇"},{"id":"S01067","t":"惜奴娇","a":"巫山神女","c":["山染青螺缥渺，人间难陟。","有珍珠光照，昼夜无休息。","仙景无极。","欲言时。","汝等何知。","且修心，要观游，亦非。","大段难易。","下俯浮生，尚自争名逐利。","岂不省，来岁扰扰兵戈起。","天惨云愁，念时衰如何是。","使我辈、终日蓬宫下泪。"],"p":"惜奴娇"},{"id":"S01068","t":"惜奴娇","a":"巫山神女","c":["再启诸公，百岁还如电急。","高名显位瞬息尔。","泛水轻沤，霎那间、难久立。","画烛当风里。","安能久之。","速往茅峰割爱，休名避世。","等功成、须有上真相引指。","放死求生，施良药、功无比。","千万记。","此个奇方第一。"],"p":"惜奴娇"},{"id":"S01069","t":"浪淘沙","a":"玉英","c":["塞上早春时。","暖律犹微。","柳舒金线拂回堤。","料得江乡应更好，开尽梅溪。","昼漏渐迟迟。","愁损仙机。","几回无语敛双眉。","凭遍阑干十二曲，日下楼西。"],"p":"浪淘沙"},{"id":"S01070","t":"白苎","a":"紫姑","c":["绣帘垂，画堂悄，寒风淅沥。","遥天万里，黯淡同云幂幂。","渐纷纷、六花零乱散空碧。","姑射宴瑶池，把碎玉、零珠抛掷。","林峦望中，高下琼瑶一白。","严子陵钓台迷踪迹。","追惜。","燕然画角，宝钥珊瑚，是时丞相，虚作银城换得。","当此际、偏宜访袁安宅。","醺醺醉了，任他金钗舞困，玉壶频侧。","又是东君，暗遣花神，先报南国。","昨夜江梅，漏泄春消息。"],"p":"白苎"},{"id":"S01071","t":"瑞鹤仙","a":"紫姑","c":["睹娇红细捻。","是西子、当日留心千叶。","西都竞栽接。","赏园林台榭，何妨日涉。","轻罗慢褶。","费多少、阳和调燮。","向晓来、露浥芳苞，一点醉红潮颊。","双靥。","姚黄国艳，魏紫天香，倚风羞怯。","云鬓试插。","引动狂蜂浪蝶。","况东君开宴，赏心乐事，莫惜献酬频叠。","看相将，红药翻阶，尚馀侍妾。"],"p":"瑞鹤仙"},{"id":"S01072","t":"望江南・忆江南","a":"清源真君","c":["才举意，玄象照离宫。","坎女离男金水火，几多铁骑漫英雄。","最苦是云中。","辽阳鹤，惊起老苍龙。","四海九州沾惠泽，狼烟影里弄清风。","堪作主人公。"],"p":"望江南・忆江南"},{"id":"S01073","t":"木兰花・玉楼春","a":"李季萼","c":["东风忽起黄昏雨。","红紫飘残香满路。","凭阑空有惜春心，浓绿满枝无处诉。","春光背我堂堂去。","纵有黄金难买住。","欲将春去问残花，花亦不言春已暮。"],"p":"木兰花・玉楼春"},{"id":"S01074","t":"天仙子","a":"随车娘子","c":["别酒未斟心先醉。","忽听阳关辞故里。","扬鞭勒马到皇都，三题尽，当际会。","稳跳龙门三级水。","天意令吾先送喜。","不审君侯知得未。","蔡邕博识爨桐声，君背负，只此是。","酒满金杯来劝你。"],"p":"天仙子"},{"id":"S01075","t":"杨柳枝","a":"玉真","c":["已谢芳华更不留。","几经秋。","故宫台榭只荒邱。","忍回头。","塞外风霜家万里，望中愁。","楚魂湘血恨悠悠。","此生休。"],"p":"杨柳枝"},{"id":"S01076","t":"忆少年","a":"乩仙","c":["凄凉天气，凄凉院落，凄凉时候。","孤鸿叫斜月，伴寒灯残漏。","落尽梧桐秋影瘦。","菱鉴古、画眉难就。","重阳又近也，对黄花依旧。"],"p":"忆少年"},{"id":"S01077","t":"鹊桥仙","a":"乩仙","c":["鸾舆初驾，牛车齐发，隐隐鹊桥咿轧。","尤云𣨼雨正欢浓，但只怕、来朝初八。","霞垂彩幔，月明银烛，馥郁香喷金鸭。","年年此际一相逢，未审是、甚时结煞。"],"p":"鹊桥仙"},{"id":"S01078","t":"千金意","a":"琴精","c":["音音音。","音音你负心。","你真负心。","孤负我到如今。","记的年时，低低唱、浅浅斟。","一曲值千金。","如今寂寞古墙阴。","秋风荒草白云深。","断桥流水何处寻。","凄凄切切，冷冷清清，教奴怎禁。"],"p":"千金意"},{"id":"S01079","t":"浣溪沙","a":"珍娘","c":["溪雾溪烟溪景新。","溶溶春水浸春云。","碧琉璃底静无尘。","风扬游丝随蝶翅，雨飘飞絮湿鸳唇。","桃花片片送残春。"],"p":"浣溪沙"},{"id":"S01080","t":"青玉案","a":"刘清之","c":["江南十月春风早。","见枝上、梅英小。","爱日初升清雾晓。","绣筵中启，星图高挂，膝下斑衣绕。","今年献寿多欢笑。","弄玉新将二雏好。","此曲尊前何所祷。","十分康乐，十分强健，一树庄椿老。"],"p":"青玉案"},{"id":"S01081","t":"鹧鸪天","a":"刘清之","c":["柳色青青罩翠烟。","花光灼灼映临川。","欲知窈窕呈祥日，恰近清明淑景天。","浮瑞霭，庆真仙。","不须男女祝椿年。","异时早约西王母，剩折蟠桃荐寿筵。"],"p":"鹧鸪天"},{"id":"S01082","t":"玉交枝・忆秦娥","a":"刘焘","c":["念谁伴、茜裙翠袖。"],"p":"玉交枝・忆秦娥"},{"id":"S01083","t":"花心动","a":"刘焘","c":["偏忆江南，有尘表丰神，世外标格。","低傍小桥，斜山疏篱，似向陇头曾识。","暗香孤韵冰雪里，初不怕、春寒要勒。","问桃杏贤瞒，怎生向前争得。","省共萧娘笑摘。","玉纤映琼枝，照人一色。","澹粉晕酥，多少工夫，到得寿阳宫额。","再三留待东君看，管都将、别花不惜。","但只恐、南楼又三弄笛。"],"p":"花心动"},{"id":"S01084","t":"八宝妆","a":"刘焘","c":["门掩黄昏，画堂人寂，暮雨乍收残暑。","帘卷疏星门户悄，隐隐严城钟鼓。","空街烟暝半开，斜日朦胧，银河澄淡风凄楚。","还是凤楼人远，桃源无路。","惆怅夜久星繁，碧空望断，玉箫声在何处。","念谁伴、茜裙翠袖，共携手、瑶台归去。","对修竹、森森院宇。","曲屏香暖凝沈炷。","问对酒当歌，情怀记得刘郎否。"],"p":"八宝妆"},{"id":"S01085","t":"转调满庭芳・满庭芳","a":"刘焘","c":["风急霜浓，天低云淡，过来孤雁声切。","雁儿且住，略听自家说。","你是离群到此，我共那人才相别。","松江岸，黄芦影里，天更待飞雪。","声声肠欲断，和我也、泪珠点点成血。","一江流水，流也呜咽。","告你高飞远举，前程事、永没磨折。","须知道、飘零聚散，终有见时节。"],"p":"转调满庭芳・满庭芳"},{"id":"S01086","t":"失调名","a":"田为","c":["映竹园啼乌。"],"p":"失调名"},{"id":"S01087","t":"南柯子・南歌子","a":"田为","c":["梦怕愁时断，春从醉里回。","凄凉怀抱向谁开。","些子清明时候、被莺催。","柳外都成絮，栏边半是苔。","多情帘燕独徘徊。","依旧满身花雨、又归来。"],"p":"南柯子・南歌子"},{"id":"S01088","t":"南柯子・南歌子","a":"田为","c":["团玉梅梢重，香罗芰扇低。","帘风不动蝶交飞。","一样绿阴庭院、锁斜晖。","对月怀歌扇，因风念舞衣。","何须惆怅惜芳菲。","┾却一年憔悴、待春归。"],"p":"南柯子・南歌子"},{"id":"S01089","t":"念奴娇","a":"田为","c":["嫩冰未白，被霜风换却，满院秋色。","小阁深沈围坐促，初拥红炉宜窄。","帘密收香，窗明迟夜，砚冷凝新滴。","无人知道，个中多少岑寂。","翻念一枕高唐，当年仙梦觉，难寻消息。","睡起微醒衣袖重，不管腰支犹索。","旋暖银簧，时添酥字，笋玉寒无力。","如今肠断，暮云依旧凝碧。"],"p":"念奴娇"},{"id":"S01090","t":"沁园春","a":"崔中","c":["自己阳生，正是中虚，静极动时。","默地雷微震，冲开玉户，天心朗彻，放下帘帏。","真火冲融，灵泉复凑，不昧谷神何险危。","自然妙，若三川龙跃，九万鹏飞。","中中二土成圭。","意眷恋浓如母护儿。","这恍惚真容，不空不色，窈冥妙象，无识无知。","命住丹圆，全真体道，夺志精修休自迟。","收功了，把三才全理，一贯全归。"],"p":"沁园春"},{"id":"S01091","t":"满庭芳","a":"何锄翁","c":["二气旋还，三宫升降，往来于是无穷。","透关神水，铅汞过三峰。","返复周流八脉，戊己炼、阴虎阳龙。","凝情处，金光朗朗，身外见形容。","灵光，真造化，天机深远，推测难通。","算利名酒色，恰似秋风。","大道玄炉进火，三田内养出神功。","功成后，金书来诏，平步赴瑶宫。"],"p":"满庭芳"},{"id":"S01092","t":"醉落魄・一斛珠","a":"无名氏","c":["红牙板歇。","韶声断、六么初彻。","小槽酒滴真珠竭。","紫玉瓯圆，浅浪泛春雪。","香芽嫩蕊清心骨。","醉中襟量与天阔。","夜阑似觉归仙阙。","走马章台，踏碎满街月。"],"p":"醉落魄・一斛珠"},{"id":"S01093","t":"满江红","a":"无名氏","c":["浪蕊浮花，当不住、晚风吹了。","微雨过，池塘飞絮，一帘晴画。","寂寂山光春似梦，依依草色熏如酒。","近新来、怕上小红楼，凭阑眺。","心事阻，诗情少。","东皇去，良辰杳。","想故园闲趣，水村烟柳。","此日鹃声天不管，当年燕子人何有。","叹江南、离别酒初醒，频回首。"],"p":"满江红"},{"id":"S01094","t":"西江月","a":"无名氏","c":["三级掀腾波浪，一堂庆会风云。","快乘霹雳化龙门。","头角人中有分。","谁状个中佳致，须还笔扫千军。","是他画手亦通神。","同向来春夺迅。"],"p":"西江月"},{"id":"S01095","t":"西江月","a":"无名氏","c":["身禀五行正气，此心如鉴光明。","不从龟鹤问年龄。","万物有衰有盛。","多谢道人著眼，我于身世常轻。","任从性巧与心灵，此事从来分定。"],"p":"西江月"},{"id":"S01096","t":"沁园春","a":"衣白山人","c":["一粒金丹，大如黍米，定中降胎。","运阴阳根本，东龙西虎，结凝金水，择地深栽。","九载无亏，三田功满，卦气周圆炉鼎开。","偷元化，用自然宗祖，全在灵台。","真才。","休恋尘埃。","况颖悟明堂婴未孩。","幸淮滨相遇，灵丹付了，亲留玄旨，期进仙阶。","此去何时，水云高会，更上烟霞岐路哉。","人间世，任王侯贵显，同委蒿莱。"],"p":"沁园春"},{"id":"S01097","t":"贺新郎","a":"熊禾","c":["旧事凭谁诉。","记锦宫、初试浓妆，前身天女。","玉辇行春娇侍夜，浴殿温泉轻注。","一点点、猩红啼吐。","绣屋篝香春睡足，细温存，怕遣惊风雨。","春孟散，暗凝伫。","韶华寂寞今何许。","想故宫、柳亦凝愁，倚栏停舞。","欲趁啼鹃归月下，可奈川回山阻。","倩万里、鹄来衔子。","工部无诗虽结恨，道无香、更恨痴人语。","拌绝艳，付黄土。"],"p":"贺新郎"},{"id":"S01098","t":"婆罗门引","a":"熊禾","c":["秋宵倦起，起来风露湿人衣。","休休未是早行时。","旋摘青蔬炊饭，暖酒就炉围。","值青山有意，且把诗题。","兴阑便归，忽邂逅、故人期。","道是游山正叔，消息曾知。","茶烟午灶，听击棹、歌声笑语迟。","云霭散、皓月呈辉。"],"p":"婆罗门引"},{"id":"S01099","t":"沁园春","a":"熊禾","c":["自笑生身，历事以来，垂六十年。","今浮沈闾里，半非识面，交游朋友，各已华颠。","富贵不来，少年已去，空见悠悠岁月迁。","虽然是，壮心一点，犹自依然。","新阳又长天边。","人指似山间诗酒仙。","算胸次崔嵬，不胜百榼，笔端枯槁，难足千篇。","隐几杖藜，相耕听诵，聊看诸郎相后先。","馀何事，但读书煮茗，日晏高眠。"],"p":"沁园春"},{"id":"S01100","t":"满庭芳","a":"熊禾","c":["斗转旋霄，梧飘金井，洞天秋气方新。","幔亭仙子，飞佩下瑶京。","霞袂霓裳缥缈，冰肌莹、月作精神。","云璈动，琼仙歌舞，共庆捧瑶觥。","蟾宫，人未老，纵横礼乐，谈笑功句名。","从今去，有多少、富贵光荣。","且听宾云奏曲，千秋岁、更引清声。","齐眉处，朱颜绿鬓，相与共长生。"],"p":"满庭芳"},{"id":"S01101","t":"水调歌头","a":"叶梦得","c":["何处难忘酒，朱夏日偏长。","湖山地胜潇湘，十里芰荷香。","柳外新蝉惊晚，楼上疏帘垂翠，簟枕晚生凉。","纨扇摇霜月，曲水泛流觞。","流年去，今古梦，几千场。","虚名浮利，输却几许好时光。","幸有碧云深处，存取朱颜绿鬓，流落又何妨。","莫厌人世间，频入醉中乡。","蔺卿全璧我蹉跎。"],"p":"水调歌头"},{"id":"S01102","t":"贺新郎","a":"叶梦得","c":["睡起啼莺语。","掩青苔、房栊向晚，乱红无数。","吹尽残花无人见，惟有垂杨自舞。","渐暖霭、初回轻暑。","宝扇重寻明月影，暗尘侵、尚有乘鸾女。","惊旧恨，遽如许。","江南梦断横江渚。","浪黏天、葡萄涨绿，半空烟雨。","无限楼前沧波意，谁采苹花寄取。","但怅望、兰舟容与。","万里云帆何时到，送孤鸿、目断千山阻。","谁为我，唱金缕。"],"p":"贺新郎"},{"id":"S01103","t":"水调歌头","a":"叶梦得","c":["渺渺楚天阔，秋水去无穷。","两淮不辨牛马，轻浪舞回风。","独倚高台一笑，圉圉游鱼来往，还戏此波中。","危栏对千里，落日照澄空。","子非我，安知我，意真同。","鹏飞鲲化何有，沧海漫冲融。","堪笑磻溪遣老，白首直钩溪畔，岁晚忽衰翁。","功业竟安在，徒自兆非熊。"],"p":"水调歌头"},{"id":"S01104","t":"水调歌头","a":"叶梦得","c":["霜降碧天静，秋事促西风。","寒声隐地，初听中夜入梧桐。","起瞰高城回望，寥落关河千里，一醉与君同。","叠鼓闹清晓，飞骑引雕弓。","岁将晚，客争笑，问衰翁。","平生豪气安在，沈领为谁雄。","何似当筵虎士，挥手弦声响处，双雁落遥空。","老矣真堪愧，回首望云中。"],"p":"水调歌头"},{"id":"S01105","t":"南乡子","a":"黄叔达","c":["落帽晚风回。","又报黄花一番开。","扶杖老人心未老，堪咍。","漫有才情付与谁。","芳意正徘徊。","传与西风且慢吹。","明日馀尊还共倒，重来。","未必秋香一夜衰。"],"p":"南乡子"},{"id":"S01106","t":"惜花容","a":"盼盼","c":["少年看花双鬓绿。","走马章台管弦逐。","而今老更惜花深，终日看花看不足。","坐中美女颜如玉。","为我一歌金缕曲。","归时压得帽檐敧，头上春风红蔌蔌。"],"p":"惜花容"},{"id":"S01107","t":"绿头鸭・多丽","a":"晁端礼","c":["锦堂深，兽炉轻喷沈烟。","紫檀槽、金泥花面，美人斜抱当筵。","挂罗绶、素肌莹玉，近鸾翅、云鬓梳蝉。","玉笋轻拢，龙香细抹，凤凰飞出四条弦。","碎牙板、烦襟消尽，秋气满庭轩。","今宵月，依稀向人，欲斗婵娟。","变新声、能翻往事，眼前风景依然。","路漫漫、汉妃出塞，夜悄悄、商妇移船。","马上愁思，江边怨感，分明都向曲中传。","困无力、劝人金盏，须要倒垂莲。","拼沈醉，身世恍然，一梦游仙。"],"p":"绿头鸭・多丽"},{"id":"S01108","t":"绿头鸭・多丽","a":"晁端礼","c":["晚云收，淡天一片琉璃。","烂银盘、来从海底，皓色千里澄辉。","莹无尘、素娥淡伫，静可数、丹桂参差。","玉露初零，金风未凛，一年无似此佳时。","露坐久，疏莹时度，乌鹊正南飞。","瑶台冷，栏干凭暖，玉下迟迟。","念佳人，音尘别后，对此应解相思。","最关情、漏声正永，暗断肠、花影偷移。","料得来宵，清光未减，阴晴天气又争知。","共凝恋、如今别后，还是隔年期。","人强健，清尊素影，长愿相随。"],"p":"绿头鸭・多丽"},{"id":"S01109","t":"望海潮","a":"晁端礼","c":["高阳方面，河间都会，三关地最称雄。","粉堞万层，金城百雉，楼横一带长虹。","烟素敛晴空。","正望迷平野，目断飞鸿。","易水风烟，范阳山色有无中。","安边暂倚元戎。","看纶巾对酒，羽扇摇风。","金勒少年，吴钩壮士，宁论卫霍前功。","乃眷在清衷。","恐凤池虚久，归去匆匆。","幸有佳人锦瑟，玉笋且轻拢。"],"p":"望海潮"},{"id":"S01110","t":"水龙吟","a":"晁端礼","c":["夜来深雪前村路，应是早梅初绽。","故人赠我，江头春信，南枝向暖。","疏影横斜，暗香浮动，月明溪浅。","向亭边驿畔，行人立马，频回首、空肠断。","别有玉溪仙馆。","寿阳人、初匀妆面。","天教占了，百花头上，和羹未晚。","最是关情处，高楼上、一声羌管。","仗谁人向道，何如留取，倚朱栏看。"],"p":"水龙吟"},{"id":"S01111","t":"好事近","a":"曾肇","c":["岁晚凤山阴，看尽楚天冰雪。","不待牡丹时候，又使人轻别。","如今归去老江南，扁舟载风月。","不似画梁双燕，有重来时节。"],"p":"好事近"},{"id":"S01112","t":"调笑转踏・调笑令","a":"郑仅","c":["归去。","携笼女。","南陌柔桑三月暮。","使君春思如飞絮。","五马徘徊频驻。","蚕饥日晚空留顾。","笑指秦楼归去。"],"p":"调笑转踏・调笑令"},{"id":"S01113","t":"调笑转踏・调笑令","a":"郑仅","c":["双桨。","小舟荡。","唤取莫愁迎叠浪。","武陵豪客青楼上。","不道风高江广。","千金难买倾城样。","那听绕梁清唱。"],"p":"调笑转踏・调笑令"},{"id":"S01114","t":"调笑转踏・调笑令","a":"郑仅","c":["草草。","最年少。","袖户银屏人窈窕。","瑶琴暗写相思调。","一曲关心多少。","临邛客舍成都道。","苦恨相逢不早。"],"p":"调笑转踏・调笑令"},{"id":"S01115","t":"调笑转踏・调笑令","a":"郑仅","c":["烟暖。","武陵晚。","洞里春长花烂熳。","红英满地溪流浅。","渐听云中鸡犬。","刘朗迷路香风远。","误到蓬莱仙馆。"],"p":"调笑转踏・调笑令"},{"id":"S01116","t":"西江月","a":"蔡京","c":["八十一年住世，四千里外无家。","如今流落向天涯。","梦到瑶池阙下。","玉殿五回命相，彤庭几度宣麻。","止因贪此恋荣华。","便有如今事也。"],"p":"西江月"},{"id":"S01117","t":"西江月","a":"苏琼","c":["韩愈文章盖世，谢安情性风流。","良辰美景在西楼。","敢劝一卮芳酒。","记得南宫高第，弟兄争占鳌头。","金炉玉殿瑞烟浮。","高占甲科第九。"],"p":"西江月"},{"id":"S01118","t":"茶瓶儿","a":"李元膺","c":["去年相逢深院宇。","海棠下、曾歌金缕。","歌罢花如雨。","翠罗衫上，点点红无数。","今岁重寻携手处。","空物事、人非春暮。","回首青门路。","乱红飞絮，相逐东风去。"],"p":"茶瓶儿"},{"id":"S01119","t":"洞仙歌","a":"李元膺","c":["廉纤细雨，𣨼东风如困。","萦断千丝为谁恨。","向楚宫一梦，千古悲凉，无处问。","愁到而今未尽。","分明都是泪，泣柳沾花，常与骚人伴孤闷。","记当年，得意处，酒力方融，怯轻寒、玉炉香润。","又岂识、情怀苦难禁，对点滴檐声，夜寒灯晕。"],"p":"洞仙歌"},{"id":"S01120","t":"洞仙歌","a":"李元膺","c":["雪云散尽，放晓晴池院。","杨柳于人便青眼。","更风流多处，一点梅心、相映远。","约略嚬轻笑浅。","一年春好处，不在浓芳，小艳疏香最娇软。","到清明时候，百紫千红花正乱。","已失春风一半。","蚤占取韶光，共追游，但莫管春寒，醉红自暖。"],"p":"洞仙歌"},{"id":"S01121","t":"蓦山溪","a":"李元膺","c":["溪堂欢燕。","惯捧玻璃盏。","今日祖西城，更忍把、一杯重劝。","别离情味，自古不堪秋，催泪雨，湿西风，肠共危弦断。","夕阳去路，五马旌旗乱。","便是古都春，应醉恋，曲江池馆。","须知别后，叠翠倚阑情，青嶂晚，碧云深，日近长安远。"],"p":"蓦山溪"},{"id":"S01122","t":"调笑令","a":"吕南公","c":["行客。","行客。","身世东西南北。","家林迢递不归。","岁时悲盛泪垂。","垂泪。","垂泪。","两鬓与霜相似。"],"p":"调笑令"},{"id":"S01123","t":"调笑令","a":"吕南公","c":["华草。","华草。","秀发乘春更好。","深心密竹纷纷。","妖韶随处动人。","人动。","人动。","王孙公子情重。"],"p":"调笑令"},{"id":"S01124","t":"瑶台第一层","a":"赵顼","c":["西母池边宴罢，赠南枝、步玉霄。","绪风和扇，冰华发秀，雪质孤高。","汉陂呈练影，问是谁、独立江皋。","便凝望、壶中珪璧，天下琼瑶。","清标。","曾陪胜赏，坐望愁、解使尘消。","况双成与乳丹点染，都付香梢。","寿妆酥冷，郢韵佩举，麝卷云绡。","乐逍遥。","凤凰台畔，取次忆吹箫。"],"p":"瑶台第一层"},{"id":"S01125","t":"临江仙","a":"吕希纯","c":["□□□□□□□，□□□□□□。","莫交闲虑到心头。","有来忧不得，无后不须忧。","□□□□□□□，□□□□□□。","万般希望不如休。","无来求不得，有后不须求。"],"p":"临江仙"},{"id":"S01126","t":"蜡梅香","a":"喻陟","c":["晓日初长，正锦里轻阴，小寒天气。","未报春消息，早瘦梅先发，浅苞纤蕊。","揾玉匀香，天赋与，风流标致。","问陇头人，音容万里。","待凭谁寄。","一样晓妆新，倚朱楼凝盼，素英如坠。","映月临风处，度几声羌管，愁生乡思。","电转光阴，须信道、飘零容易。","且频欢赏，柔芳正好，满簪同醉。"],"p":"蜡梅香"},{"id":"S01127","t":"渔家傲","a":"朱服","c":["小雨廉纤风细细。","万家杨柳轻烟里。","恋树湿花飞不起。","愁无比。","和春付与西流水。","九十光阴能有几。","金龟解尽留无计。","寄语东城沽酒市。","拼一醉。","而今乐事他年泪。"],"p":"渔家傲"},{"id":"S01128","t":"无闷","a":"丁注","c":["风急还收，云冻又开，海阔无人翦水。","算六出工夫，怎教容易。","刚被郢歌楚舞。","镇独向，尊前夸轻细。","想谢庭诗咏，梁园赋赏，未成欢计。","天意。","是则是。","便下得控持，柳梢梅蕊。","又争奈、看看渐回春意。","好趁东君未觉，预先把、园林都装缀。","看是处，玉树琼枝，胜却万红千翠。"],"p":"无闷"},{"id":"S01129","t":"宝鼎现","a":"刘弇","c":["浓阴堆积，回野空旷，将回微煦。","还是觉、早梅依旧，清艳枝枝攒晓树。","弄霁影、尽脂凝香蒂，琼削纤葩竞吐。","对几处园林，芳菲消息，都因传去。","取次台榭，等闲院落，偏宜独擅芳步。","长恁恐、寿阳妆面，姑射冰肤成暗妒。","笑杏坞、共桃蹊夸丽，一霎狂风骤雨。","又争似、年年此际，先得东皇为主。","好似雪里精神，曾解恼、游人吟顾。","想当时折赠，端的凭谁付与。","荡醉目、恨同云阻。","画角声将暮。","想异时成实，和羹止渴，还应得路。"],"p":"宝鼎现"},{"id":"S01130","t":"洞仙歌","a":"刘弇","c":["凄凉楚弄，行客肠曾断。","涛卷秋容暗淮甸。","去年时、还是今日孤舟，烟浪里，身与江云共远。","别来丹枕梦，几过沧洲，皓月而今为谁满。","薄幸苦无端，误却婵娟，有人在、玉楼天半。","最不愤、西风破帆来，甚时节，收拾望中心眼。"],"p":"洞仙歌"},{"id":"S01131","t":"金明春・金明池","a":"刘弇","c":["宝历延洪，昌辰开泰，崧岳储灵特异。","贤才并、□时间出，尽一一惊人绝艺。","捧乡书、气格飘飘，似阆苑神仙，参差相继。","纵子墨文章，相如才调，骤觉雷声平地。","太守宾兴当此际。","正瑞霭寒轻，虚堂风细。","舞腰旋、飞尘仿佛，歌管递、清声嘹唳。","况相将、桂籍荣登，对酒面鳞红，何妨沈醉。","但管取明年，宫花重戴，共赏金明春意。"],"p":"金明春・金明池"},{"id":"S01132","t":"内家娇","a":"刘弇","c":["绰约群芳里，阳和意，偏向一枝浓。","南国骤惊，动人奇艳，未饶西洛，百本千丛。","斩新弄，晓来无比格，半坼断肠红。","三月洞天，又还疑是，赋情楚客，窥见墙东。","朱阑干、遍倚生愁，怕无计、奈雨禁风。","别有瑞烟幕幕，时与遮笼。","便纵使当日，文忠品第，赵昌模写，难更形容。","应念故园桃李，羞怨春工。"],"p":"内家娇"},{"id":"S01133","t":"青门饮","a":"时彦","c":["胡马嘶风，汉旗翻雪，彤云又吐，一竿残照。","古木连空，乱山无数，行尽暮沙衰草。","星斗横幽馆，夜无眠、灯花空老。","雾浓香鸭，冰凝泪烛，霜天难晓。","长记晓妆才了，一杯未尽，离怀多少。","醉里秋波，梦中朝雨，都是醒时烦恼。","料有牵情处，忍思量、耳边曾道。","甚时跃马归来，认得迎门轻笑。"],"p":"青门饮"},{"id":"S01134","t":"瑶池宴令・越江吟","a":"廖正一","c":["飞花成阵。","春心困。","寸寸。","别肠多少愁闷。","无人问。","偷啼自揾。","残妆粉。","抱瑶琴、寻出新韵。","玉纤趁。","南风未解幽愠。","低云鬓。","眉峰敛晕。","娇和恨。"],"p":"瑶池宴令・越江吟"},{"id":"S01135","t":"失调名","a":"董武子","c":["畴昔寻芳秘殿西。","日压金铺，宫柳垂垂。"],"p":"失调名"},{"id":"S01136","t":"醉落魄・一斛珠","a":"哑女","c":["风波未息。","虚名浮利终无益。","不如早去备蓑笠。","高卧烟霞，千古企难及。","君今既已装行色。","定应雁塔题名籍。","他年若到南雄驿。","玉石休分，徒累卞和泣。"],"p":"醉落魄・一斛珠"},{"id":"S01137","t":"西江月","a":"米芾","c":["溪面荷香粲粲，林端远岫青青。","楚天秋色太多情。","云卷烟收风定。","夜静冰娥欲上，梦回醉眼初醒。","玉瓶未耻有新声。","一曲请君来听。"],"p":"西江月"},{"id":"S01138","t":"菩萨蛮","a":"米芾","c":["蒹葭风外烟笼柳。","数叠遥山眉黛秀。","微雨过江来。","烦襟为一开。","沙边临望处。","紫燕双飞语。","举酒送飞云。","夜凉愁梦频。"],"p":"菩萨蛮"},{"id":"S01139","t":"水调歌头","a":"米芾","c":["砧声送风急，蟋蟀思高秋。","我来对景，不学宋玉解悲愁。","收拾凄凉兴况，分付尊中醽醁，倍觉不胜幽。","自有多情处，明月挂南楼。","怅襟怀，横玉笛，韵悠悠。","清时良夜，借我此地倒金瓯。","可爱一天风物，遍倚阑干十二，宇宙若萍浮。","醉困不知醒，敧枕卧江流。"],"p":"水调歌头"},{"id":"S01140","t":"渔家傲","a":"米芾","c":["昔日丹阳行乐里。","紫金浮玉临无地。","宝阁化成弥勒世。","龙宫对。","时时更有天花坠。","浩渺一天秋水至。","鲸鲵鼓鬣连山沸。","员峤岱舆更赑屃。","无根蒂。","莫教龙伯邦人戏。"],"p":"渔家傲"},{"id":"S01141","t":"望云涯引","a":"李甲","c":["秋容江上，岸花老，苹洲白。","露湿蒹葭，浦屿渐增寒色。","闲渔唱晚，鹜雁惊飞处，映远碛。","数点轻帆，送天际归客。","凤台人散，漫回首。","沈消息。","素鲤无凭，楼上暮云凝碧。","时向西风下，认远笛。","宋玉悲怀，未信金樽消得。"],"p":"望云涯引"},{"id":"S01142","t":"吊严陵","a":"李甲","c":["蕙兰香泛，孤屿潮平，惊鸥散雪。","迤逦点破，澄江秋色。","暝霭向敛，疏雨乍收，染出蓝峰千尺。","渔舍孤烟锁寒碛。","画鹢翠帆旋解，轻舣晴霞岸侧。","正念往悲酸，怀乡惨切。","何处引羌笛。","追惜。","当时富春佳地，严光钓址空遗迹。","华星沈后，扁舟泛去，萧洒闲名图籍。","离觞吊终寓目，意断魂消泪滴。","渐洞天晚，回首暮云千古碧。"],"p":"吊严陵"},{"id":"S01143","t":"梦玉人引","a":"李甲","c":["渐东风暖，陇梅残，霁云碧。","嫩草柔条，又回江城春色。","乍促银签，便篆香纹蜡有馀迹。","愁梦相兼，尽日高无力。","这些离恨，依然是、酒醒又如织。","料伊怀情，也应向人端的。","何故近日，全然无消息。","问伊看，伊教人到此，如何休得。"],"p":"梦玉人引"},{"id":"S01144","t":"过秦楼","a":"李甲","c":["卖酒炉边，寻芳原上，乱花飞絮悠悠。","已蝶稀莺散，便拟把长绳、系日无由。","谩道草忘忧。","也徒将，酒解闲愁。","正江南春尽，行人千里，苹满汀洲。","有翠红径里，盈盈似簇，芳茵禊饮，时笑时讴。","当暖风迟景，任相将永日，烂熳狂游。","谁信盛狂中，有离情、忽到心头。","向尊前拟问，双燕来时，曾过秦楼。"],"p":"过秦楼"},{"id":"S01145","t":"蝶恋花","a":"赵令畤","c":["丽质仙娥生月殿。","谪向人间，未免凡情乱。","宋玉墙东流美盼。","乱花深处曾相见。","密意浓欢方有便。","不奈浮名，旋遣轻分散。","最恨多才情太浅。","等闲不念离人怨。"],"p":"蝶恋花"},{"id":"S01146","t":"蝶恋花","a":"赵令畤","c":["锦额重帘深几许。","绣履弯弯，未省离朱户。","强出娇羞都不语。","绛绡频掩酥胸素。","黛浅愁红妆淡伫。","怨绝情凝，不肯聊回顾。","媚脸未匀新泪污。","梅英犹带春朝露。"],"p":"蝶恋花"},{"id":"S01147","t":"蝶恋花","a":"赵令畤","c":["懊恼娇痴情未惯。","不道看看，役得人肠断。","万语千言都不管。","兰房跬步如天远。","废寝忘餐思想遍。","赖有青鸾，不必凭鱼雁。","密写香笺论缱绻。","春词一纸芳心乱。"],"p":"蝶恋花"},{"id":"S01148","t":"蝶恋花","a":"赵令畤","c":["庭院黄昏春雨霁。","一缕深心，百种成牵系。","青翼蓦然来报喜。","鱼笺微谕相容意。","待月西厢人不寐。","帘影摇光，朱户犹慵闭。","花动拂墙红萼坠。","分明疑是情人至。"],"p":"蝶恋花"},{"id":"S01149","t":"水龙吟","a":"晁补之","c":["水晶宫绕千家，卞山倒影双溪里。","白苹洲渚，诗成春晚，当年此地。","行遍瑶台，弄英携手，月婵娟际。","算多情小杜，风流未睹，空肠断、枝间子。","一似君恩赐与，贺家湖、千峰凝翠。","黄粱未熟，红旌已远，南柯旧事。","常恐重来，夜阑相对，也疑非是。","向松陵回首，平芜尽处，在青山外。"],"p":"水龙吟"},{"id":"S01150","t":"八声甘州","a":"晁补之","c":["谓东坡、未老赋归来，天未遣公归。","向西湖两处秋波一种，飞蔼澄辉。","又拥竹西歌吹，僧老木兰非。","一笑千秋事，浮世危机。","应倚平山栏槛，是醉翁饮处，江雨霏霏。","送孤鸿相接，今古眼中稀。","念平生、相从江海，任飘蓬、不遣此心违。","登临事，更何须惜，吹帽淋衣。"],"p":"八声甘州"},{"id":"S01151","t":"八声甘州","a":"晁补之","c":["谓东风、定是海冬来，海上最春先。","乍微阳破腊，梅心已省，柳意都远。","雪后南山耸翠，平野欲生烟。","记得相逢日，如上林边。","莫叹春光易老，算今年春老，还有明年。","叹人生难得，常好是朱颜。","有随轩、金钗十二，为醉娇、一曲踏珠筵。","功名事，算何如此，花下尊前。"],"p":"八声甘州"},{"id":"S01152","t":"满庭芳","a":"晁补之","c":["鸥起苹中，鱼惊荷底，画船天上来时。","翠湾红渚，宛似武陵迷。","更晚青山更好，孤云带、远雨丝垂。","清歌里，金尊未掩，谁使动分携。","竹林、高晋软，阿咸潇散，犹愧风期。","便弃官终隐，钓叟苔矶。","纵是鸣鸿云外，应念我、垂翼低飞。","新词好，他年认取，天际片帆归。"],"p":"满庭芳"},{"id":"S01153","t":"菩萨蛮","a":"陈师道","c":["行云过尽星河烂。","炉烟未断蛛丝满。","想得两眉颦。","停针忆远人。","河桥知有路。","不解留郎住。","天上隔年期。","人间长别离。"],"p":"菩萨蛮"},{"id":"S01154","t":"菩萨蛮","a":"陈师道","c":["东风乌鹊西飞燕。","盈盈一水经年见。","急雨洗香车。","天回河汉斜。","离愁千载上。","相远长相望。","终不似人间。","回头万里山。"],"p":"菩萨蛮"},{"id":"S01155","t":"菩萨蛮","a":"陈师道","c":["绮楼小小穿针女。","秋光点点蛛丝雨。","今夕是何宵。","龙车乌鹊桥。","经年谋一笑。","岂解令人巧。","不用问如何。","人间巧更多。"],"p":"菩萨蛮"},{"id":"S01156","t":"菩萨蛮","a":"陈师道","c":["银潢清浅填乌鹊。","画檐急雨长河落。","初月未成圆。","明星惜此筵。","愁来无断绝。","岁岁年年别。","不用泪红滋。","年年岁岁期。"],"p":"菩萨蛮"},{"id":"S01157","t":"减字木兰花","a":"青幕子妇","c":["清词丽句。","永叔子瞻曾独步。","似恁文章。","写得出来当甚强。"],"p":"减字木兰花"},{"id":"S01158","t":"减字木兰花","a":"张耒","c":["个人风味。","只有江梅些子似。","每到开时。","满眼清愁只自知。","霞裾仙珮。","姑射神人风露态。","蜂蝶休忙。","不与春风一点香。"],"p":"减字木兰花"},{"id":"S01159","t":"鹧鸪天","a":"张耒","c":["倾盖相逢汝水滨。","须知见面过闻名。","马头虽去无千里，酒盏才倾且百分。","嗟得失，一微尘。","莫教冰炭损精神。","北扉西禁须公等，金榜当年第一人。"],"p":"鹧鸪天"},{"id":"S01160","t":"满庭芳","a":"张耒","c":["裂楮裁筠，虚明潇洒，制成方丈屠苏。","草团蒲坐，中置一山炉。","拙似春林鸠宿，易于□、秋野鹑居。","谁相对，时烦孟妇，石鼎煮寒蔬。","嗟吁。","人生随分足，风云际会，漫付伸舒。","且偷取闲时，向此踌躇。","谩取黄金建厦，繁华梦、毕竟空虚。","争如且、寒村厨火，汤饼一斋盂。"],"p":"满庭芳"},{"id":"S01161","t":"风流子","a":"张耒","c":["木叶亭皋下，重阳近，又是捣衣秋。","奈愁入庾肠，老侵潘鬓，谩簪黄菊，花也应羞。","楚天晚，白苹烟尽处，红蓼水边头。","芳草有情，夕阳无语，雁横南浦，人倚西楼。","玉容，知安否，香笺共锦字，两处悠悠。","空恨碧云离合，青鸟沈浮。","向风前懊恼，芳心一点，寸眉两叶，禁甚闲愁。","情到不堪言处，分付东流。"],"p":"风流子"},{"id":"S01162","t":"临江仙","a":"侯蒙","c":["未遇行藏谁肯信，如今方表名踪。","无端良匠画形容。","当风轻借力，一举入高空。","才得吹嘘身渐稳，只疑远赴蟾宫。","雨馀时候夕阳红。","几人平地上，看我碧霄中。"],"p":"临江仙"},{"id":"S01163","t":"减字木兰花","a":"陈瓘","c":["世间拘碍。","人不堪时渠不改。","古有斯人。","千载谁能继后尘。","春风入手。","乐事自应随处有。","与众熙怡。","何似幽居独乐时。"],"p":"减字木兰花"},{"id":"S01164","t":"减字木兰花","a":"陈瓘","c":["结庐人境。","万事醉来都不醒。","鸟倦云飞。","两得无心总是归。","古人逝矣。","旧日南窗何处是。","莫负青春。","即是升平寄傲人。"],"p":"减字木兰花"},{"id":"S01165","t":"满庭芳","a":"陈瓘","c":["槁木形骸，浮云身世，一年两到京华。","又还乘兴，闲看洛阳花。","闻道鞓红最好，春归后、终委泥沙。","忘言处，花开花谢，不似我生涯。","年华。","留不住，饥飡困寝，触处为家。","这一轮明月，本自无瑕。","随分冬裘夏葛，都不会、赤水黄芽。","谁知我，春风一拐，谈笑有丹砂。"],"p":"满庭芳"},{"id":"S01166","t":"卜算子","a":"陈瓘","c":["身如一叶舟，万事潮头起。","水长船高一任伊，来往洪涛里。","潮落又潮生，今古长如此。","后夜开尊独酌时，月满人千里。"],"p":"卜算子"},{"id":"S01167","t":"满庭芳","a":"刘山老","c":["跛子年来，形容何似，俨然一部髭须。","世间许大，拐上做工夫。","选甚南州北县，逢著处、酒满葫芦。","醺醺醉，不知明日，何处度朝晡。","洛阳，花看了，归来帝里，一事全无。","又还与瓠羹，再作门徒。","蓦地思量下水，浪网上、芦席横铺。","呵呵笑，睢阳门外，有个大南湖。"],"p":"满庭芳"},{"id":"S01168","t":"望江南・忆江南","a":"邵伯温","c":["百尺长藤垂到地，千株乔木密参天。","只在郡城边。"],"p":"望江南・忆江南"},{"id":"S01169","t":"调笑・调笑令","a":"邵伯温","c":["翻翻绣袖上红茵。","舞姬犹是旧精神。","坐中莫怪无欢意，我与将军是故人。"],"p":"调笑・调笑令"},{"id":"S01170","t":"渔家傲","a":"净端","c":["斗转星移天渐晓。","蓦然听得鹈鹕叫。","山寺钟声人浩浩。","木鱼噪。","渡船过岸行官道。","轻舟再奈长江讨。","重添香饵为钩钓。","钓得锦鳞船里跳。","呵呵笑。","思量天下渔家好。"],"p":"渔家傲"},{"id":"S01171","t":"渔家傲","a":"净端","c":["浪静西溪澄似练。","片帆高挂乘风便。","始向波心通一线。","群鱼见。","当头谁敢先吞咽。","闪烁锦鳞如闪电。","灵光今古应无变。","爱是憎非都已遣。","回头转。","一轮明月升苍弁。"],"p":"渔家傲"},{"id":"S01172","t":"渔家傲","a":"净端","c":["七宝池中堪下钓。","八功德水烟波渺。","池底金沙齐布了。","羡鱼鸟。","周回旋绕为阶道。","白鹤孔雀鹦鹉噪。","弥陀接引毫光照。","不是修行何得到。","一般好。","西方净土无烦恼。"],"p":"渔家傲"},{"id":"S01173","t":"渔家傲","a":"净端","c":["一只孤舟巡海岸。","盘陀石上垂钩线。","钓得锦鳞鲜又健。","堪爱羡。","龙王见了将珠换。","钓罢归来莲苑看。","满堂尽是真罗汉。","便𦶟名香三五片。","梵□献。","原来佛不夺众生愿。"],"p":"渔家傲"},{"id":"S01174","t":"菩萨蛮","a":"李","c":["城阴犹有松间雪。","松间暗淡城头月。","月下几枝梅。","为谁今夜开。","尊前簪素发。","自拥繁枝折。","疑是在瑶台。","宝灯携手来。"],"p":"菩萨蛮"},{"id":"S01175","t":"虞美人令・虞美人","a":"李","c":["玉阑干外清江浦。","渺渺天涯雨。","好风如扇雨如帘。","时见岸花汀草、涨痕添。","青林枕上关山路。","卧想乘鸾处。","碧芜千里信悠悠。","惟有霎时凉梦、到南州。"],"p":"虞美人令・虞美人"},{"id":"S01176","t":"品令","a":"李","c":["唱歌须是，玉人檀口，皓齿冰肤。","意传心事，语娇声颤，字如贯珠。","老翁虽是解歌，无奈雪鬓霜须。","大家且道，是伊模样，怎如念奴。"],"p":"品令"},{"id":"S01177","t":"清平乐","a":"李","c":["落梅呜咽。","暗淡城头月。","吹满江山惊梦蝶。","唤起画楼伤别。","帘风轻触银钩。","梧桐玉露新秋。","底事琐窗深夜，素娥常伴人愁。"],"p":"清平乐"},{"id":"S01178","t":"水龙吟","a":"孔夷","c":["岁穷风雪瓢零，望迷万里云垂冻。","红绡碎翦，凝酥繁缀，烟深霜重。","疏影沈波，暗香和月，横斜浮动。","怅别来，欲把芳菲寄远，还羌管、吹三弄。","寂寞玉人睡起，污残妆、不胜姣凤。","盈盈山馆，纷纷客路，相思谁共。","才与风流，赋称清艳，多情唯宋。","算襄王，枉被梨花瘦损，又成春梦。"],"p":"水龙吟"},{"id":"S01179","t":"南浦","a":"孔夷","c":["风悲画角，听单于、三弄落谯门。","投宿骎骎征骑，飞雪满孤村。","酒市渐闲灯火，正敲窗、乱叶舞纷纷。","送数声惊雁，下离烟水，嘹唳度寒云。","好在半胧溪月，到如今、无处不销魂。","故国梅花归梦，愁损绿罗裙。","为问暗香闲艳，也相思、万点付啼痕。","算翠屏应是，两眉馀恨倚黄昏。"],"p":"南浦"},{"id":"S01180","t":"惜馀春慢・选冠子","a":"孔夷","c":["弄月馀花，团风轻絮，露湿池堂春草。","莺莺恋友，燕燕将雏，惆怅睡残清晓。","还似初相见时，携手旗亭，酒香梅小。","向登临长是，伤春滋味，泪弹多少。","因甚却、轻许风流，终非长久，又说分飞烦恼。","罗衣瘦损，绣被香消，那更乱红如扫。","门外无穷路岐，天若有情，和天须老。","念高唐归梦，凄凉何处，水流云绕。"],"p":"惜馀春慢・选冠子"},{"id":"S01181","t":"鼓笛慢・水龙吟","a":"孔矩","c":["数枝凌雪乘冰，嫩英半吐琼酥点。","南州故苑，何郎遗咏，风台月观。","疏影横斜，暗香浮动，水寒云晚。","笑浮花浪蕊，娇春万里，空零落、愁莺燕。","游子寂寥暮景，向天边、几回相见。","玉人纤手，殷勤攀赠，欲行微盼。","越使归来，汉宫妆罢，昭华流怨。","念湘江梦杳，窗前疑是，此情何限。"],"p":"鼓笛慢・水龙吟"},{"id":"S01182","t":"鹧鸪天","a":"孔矩","c":["却月凌风度雪清。","何郎高咏照花明。","一枝弄碧传幽信，半额涂黄拾晚荣。","春思淡，暗香轻。","江南雨冷若为情。","犹胜远隔潇湘水，忽到窗前梦不成。"],"p":"鹧鸪天"},{"id":"S01183","t":"渔家傲","a":"邹浩","c":["慧眼舒光无不见。","尘中一一藏经卷。","闻说大千摊已遍。","门方便。","法轮尽向毫端转。","月挂烛笼知再见。","西方可履休回盼。","要与老岑同掣电。","酬所愿。","欣逢十二观音面。"],"p":"渔家傲"},{"id":"S01184","t":"临江仙","a":"邹浩","c":["有个头陀修苦行，头上头发毵毵。","身披一副醦裙衫。","紧缠双脚，苦苦要游南。","闻说度牒朝夕到，并除颔下髭髯。","钵中无粥住无庵。","摩登伽处，只恐却重参。"],"p":"临江仙"},{"id":"S01185","t":"失调名","a":"曾诞","c":["草草山林职事，厌厌罢相情怀。"],"p":"失调名"},{"id":"S01186","t":"风流子","a":"李坦然","c":["东君虽不语，年华事、今岁恰如期。","向寒雨望中，晓霜清处，领些春意，开两三枝。","又不是、山桃红锦烂，溪柳绿摇丝。","别是一般，孤高风韵，绛裁纤萼，冰剪芳蕤。","清香还有意，轻飘度勾引，几句新诗。","须是放怀追赏，莫恁轻离。","更嫦娥为爱，寒光满地，故移疏影，来伴南枝。","谁道寿阳妆浅，偏入时宜。"],"p":"风流子"},{"id":"S01187","t":"感皇恩","a":"阮阅","c":["芝检下中天，春寒犹浅。","馀闰银蟾许重看。","满城灯火，又遍高楼深院。","宝鞍催绣毂，香风软。","憔悴慢翁，萧条古县。","随分良辰试开宴。","且倾芳酒，共听新声弦管。","夜阑人未散，更筹转。"],"p":"感皇恩"},{"id":"S01188","t":"踏莎行","a":"阮阅","c":["驿使初回，新阳才报。","时和倍觉青春早。","华灯和月拥朱轓，花间万点寒星小。","团扇歌清，重裀舞妙。","游人只恐归来悄。","明年亲侍辇舆行，未应肯记濡须好。"],"p":"踏莎行"},{"id":"S01189","t":"减字木兰花","a":"阮阅","c":["晓云舒瑞。","寒影初回长日至。","罗袜新成。","更有何人继后尘。","绮窗寒浅。","尽道朝来添一线。","秉烛须游。","已减铜壶昨夜筹。"],"p":"减字木兰花"},{"id":"S01190","t":"锦堂春・锦堂春慢","a":"阮阅","c":["江入重关，山围翠𪩘，湖边自古巢阳。","正梅残林坞，冰泮池塘。","闻道当年父老，记梅福、曾隐南昌。","有长堤万柳，映□参差，尽是甘棠。","共夸金斗。"],"p":"锦堂春・锦堂春慢"},{"id":"S01191","t":"失调名","a":"赵企","c":["闻道南丹风土美。","流出溅溅五溪水。","威仪尽识汉君臣，衣冠已变□番子。","凯歌还、欢声载路。","一曲春风里。","不日万年觞，猺人北面朝天子。"],"p":"失调名"},{"id":"S01192","t":"感皇恩","a":"赵企","c":["骑马踏红尘，长安重到。","人面依前似花好。","旧欢才展，又被新愁分了。","未成云雨梦，巫山晓。","千里断肠，关山古道。","回首高城似天杳。","满怀离恨，付与落花啼鸟。","故人何处也，青春老。"],"p":"感皇恩"},{"id":"S01193","t":"步蟾宫","a":"汪存","c":["玉京此去春犹浅。","正雪絮、马头零乱。","姮娥剪就绿云裳，待来步蟾宫与换。","明年二月桃花岸。","棹双浆、浪平烟暖。","扬州十里小红楼，尽卷上珠帘一半。"],"p":"步蟾宫"},{"id":"S01194","t":"蝶恋花","a":"谢逸","c":["豆蔻梢头春色浅。","新试纱衣，拂袖东风软。","红日三竿帘幕卷。","画楼影里双飞燕。","拢鬓步摇青玉碾。","缺样花枝，叶叶蜂儿颤。","独倚阑干凝望远。","一川烟草平如剪。"],"p":"蝶恋花"},{"id":"S01195","t":"踏莎行","a":"谢逸","c":["柳絮风轻，梨花雨细。","春阴院落帘垂地。","碧溪影里小桥横，青帘市上孤烟起。","镜约关情，琴心破睡。","轻寒漠漠侵鸳被。","酒醒霞散脸边红，梦回山蹙眉间翠。"],"p":"踏莎行"},{"id":"S01196","t":"菩萨蛮","a":"谢逸","c":["暄风迟日春光闹。","蒲萄水绿摇轻棹。","两岸草烟低。","青山啼子规。","归来愁未寝。","黛浅眉痕沁。","花影转廊腰。","红添酒面潮。"],"p":"菩萨蛮"},{"id":"S01197","t":"菩萨蛮","a":"谢逸","c":["縠纹波面浮㶉𫛶。","蒲芽出水参差碧。","满院落梅香。","柳梢初弄黄。","衣轻红袖皱。","春困花枝瘦。","睡起玉钗横。","隔帘闻晓莺。"],"p":"菩萨蛮"},{"id":"S01198","t":"减字木兰花","a":"夏倪","c":["江涵晓日。","荡漾波光摇桨入。","笑指浯溪。","漫叟雄文锁翠微。","休嗟不偶。","归到中州何处有。","独立风烟。","湘水浯台总接天。"],"p":"减字木兰花"},{"id":"S01199","t":"汉宫春","a":"晁冲之","c":["黯黯离怀，向东门系马，南浦移舟。","薰风乱飞燕子，时下轻鸥。","无情渭水，问谁教、日日东流。","常是送、行人去后，烟波一向离愁。","回首旧游如梦，记踏青𣨼饮，拾翠狂游。","无端彩云易散，覆水难收。","风流未老，拚千金，重入扬州。","应又是、当年载酒，依前名占青楼。"],"p":"汉宫春"},{"id":"S01200","t":"玉蝴蝶","a":"晁冲之","c":["目断江南千里，灞桥一望，烟水微茫。","尽锁重门，人去暗度流光。","雨轻轻，梨花院落，风淡淡、杨柳池塘。","恨偏长。","佩沈湘浦，云散高唐。","清狂。","重来一梦，手搓梅子，煮酒初尝。","寂寞经春，小桥依旧燕飞忙。","玉钩栏、凭多渐暖，金缕枕、别久犹香。","最难忘。","看花南陌，待月西厢。"],"p":"玉蝴蝶"}];
